WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[9906] = { title = "Message in a Battle", description = "Ogres are moved by one thing: Might. If we expose ourselves to them as being weak, they will take advantage of that weakness and wipe us out.\n\nGarrosh might be ready to lie down and let the ogre dogs take our lands but I am not! I need you to deliver a message to the Boulderfist, {name}. The only type of message that they are capable of understanding: Brutality.\n\nTravel to the Burning Blade Ruins, southeast of here and show them the might of the Mag'har.\n\nAnd {name}, check in with the others before leaving.", objectives = "Jorin Deadeye at Garadar in Nagrand has asked that you slay 8 Boulderfist Crushers and 8 Boulderfist Mystics.", completion = "Our task is not yet finished. There are more that must be taught a lesson!" }
WordHunterWoW_QuestEN[9907] = { title = "An Audacious Advance", description = "Directly west of here you will find the Halaani Basin. Within the basin are the twin clefts of Nagrand: Northwind and Southwind. Boulderfist shock troops use the clefts to hide their ogre mounds.\n\nI need you to track down those troops and kill all that you encounter in the name of Mag'har.", objectives = "Jorin Deadeye at Garadar in Nagrand has asked that you slay 10 Boulderfist Warriors and 10 Boulderfist Mages.", completion = "If this does not freeze the blood in their veins, nothing will. You have done the Mag'har justice, <name>. And for justice, Mag'har rewards greatly." }
WordHunterWoW_QuestEN[9908] = { title = "Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin", description = "", objectives = "" }
WordHunterWoW_QuestEN[9909] = { title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin", description = "", objectives = "" }
WordHunterWoW_QuestEN[9910] = { title = "Standards and Practices", description = "If you're venturing into the Burning Blade Ruins, I have a task for you. Take these Mag'har battle standards and place them at three distinct locations in the ogre compound. An area of high visibility is recommended. Look for the gigantic flaming pyres on the upper levels. Place a standard near the first, second, and third Burning Blade pyres.\n\nThe standard will leave a lasting impression upon any ogres who may have missed the battle.", objectives = "Elkay'gan the Mystic at Garadar in Nagrand wants you to use the Mag'har Battle Standard at the First Burning Blade Pyre, Second Burning Blade Pyre, and Third Burning Blade Pyre. Return the left-over Mag'har Battle Standards to him when you are finished.", progress = "Respect from fear! It is as good as any other kind.", completion = "Perhaps you would like another task? A more delicate matter, eh?" }
WordHunterWoW_QuestEN[9911] = { title = "The Count of the Marshes", description = "This bloody mandible comes from an unbelievably large creature. The nether ray that it belonged to has to be the largest ever seen in Zangarmarsh. Judging from the condition of the mandible, the count must've abandoned a diet of carrion in favor of living flesh.\n\nSurely the Cenarion Expedition would be interested in such a specimen. Watcher Leesa'oh has a small camp to the west of Quagg Ridge.", objectives = "Bring \"Count\" Ungula's Mandible to Watcher Leesa'oh at the Cenarion Outpost in Zangarmarsh.", progress = "<The watcher blinks several times in surprise.>\n\nWhere did you get that... thing?", completion = "Are you sure that's real? I mean, I knew there was large wildlife in the marsh, but there are giant creatures and then there are GIANT bugs.\n\nCome to think of it, the sporelings did mention a story about a fearsome nether ray that used to terrorize them before the boglord incursion.\n\nWhat if the stories are true? Oh, dear. I'd better take that for safekeeping. The expedition will want to know about this." }
WordHunterWoW_QuestEN[9912] = { title = "The Cenarion Expedition", description = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.", objectives = "Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", completion = "Welcome to Cenarion Refuge, <name>.  I hope you've come to aid us in our mission.  We've much work ahead of us." }
WordHunterWoW_QuestEN[9913] = { title = "The Consortium Needs You!", description = "My organization, the Consortium, is looking for a few resourceful individuals just like yourself.  You'll be hard pressed to find ethereals more honest, hard-working or pleasant to be around than us.\n\nAll we require is loyalty, dedication and a reasonable amount of moral flexibility.  If you're interested, speak to Gezhe, our ground operations leader.  You will find him at Aeris Landing, north of Oshu'gun.", objectives = "Report to Gezhe at Aeris Landing in Nagrand.", completion = "Are you ready to get to work, <race>?  I think I've got the perfect task for you." }
WordHunterWoW_QuestEN[9914] = { title = "A Head Full of Ivory", description = "Ivory is a much sought after prize.  I have many customers lined up in far off places to purchase it.\n\nI could be convinced to let you in on a cut of the profits.\n\nThe wild elekk roaming Nagrand have the high quality of tusks that I'm after.  Steer clear of the bull elekk; their ivory isn't in the condition that I desire.\n\nOh and don't worry, it's not poaching; I have an understanding with both the orcs and the draenei.\n\nDo you and I have an understanding?", objectives = "Collect 3 Pair of Ivory Tusks and return them to Shadrek at Aeris Landing in Nagrand.", progress = "It's ivory that I'm after, not excuses.  Of course, if you'd rather, we can renegotiate your percentage of the profits.  I doubt that you'd be pleased with the result.", completion = "Never doubted you for a second, friend.  Most of those look like fine specimens, if a bit dirty and scratched up.  Still, I think they're worth the value we agreed upon previously.\n\nI hope that we can continue to do business in the future." }
WordHunterWoW_QuestEN[9915] = { title = "More Heads Full of Ivory", description = "", objectives = "I still have a need for more pairs of ivory tusks from the wild elekk that roam this land.  Unfortunately, my budget will no longer handle your cut of the profits.  If you continue to provide me what I need, however, you will be ingratiating yourself with the Consortium.", progress = "I still have a need for more pairs of ivory tusks from the wild elekk that roam this land.  Unfortunately, my budget will no longer handle your cut of the profits.  If you continue to provide me what I need, however, you will be ingratiating yourself with the Consortium.", completion = "Excellent, more fine tusk specimens, though some look a bit dingy.\n\nYou have the far-reaching gratitude of the Consortium, <name>." }
WordHunterWoW_QuestEN[9916] = { title = "Bleeding Hollow Supply Crates", description = "The Boulderfist have moved the supplies they stole from our village to the twin clefts of Nagrand, found west of here in the Halaani Basin.\n\nWhile you are in the area, keep your eye out for the supply crates. If we can get those back, it would ease much of the burden that has fallen upon the matrons of Garadar.", objectives = "Elkay'gan the Mystic at Garadar in Nagrand wants you to recover 10 Bleeding Hollow Supply Crates.", progress = "The children might be able to go a day without feeling hunger pangs.", completion = "Most of our possessions were destroyed or stolen in the attacks. I cannot offer you much, but there are some items that you may find useful..." }
WordHunterWoW_QuestEN[9917] = { title = "Do My Eyes Deceive Me", description = "Do my eyes deceive me or is there an ogre hunting party over yonder? What could ogres be doing this far from their mound? I don't like this one bit, stranger. First Murkbloods and now ogres. We just don't have the manpower to handle all of these threats to our land.\n\nCould you investigate the ogre presence to the east for us? Their forward camp is about 200 paces east of here. You'll know you're at the right place if you see the Boulderfist hunters. Kill them to find the plans!", objectives = "Huntress Bintook at Telaar in Nagrand wants you to recover Boulderfist Plans.", progress = "Have you found any new information?", completion = "<Bintook reads the plans.>\n\nBY THE LIGHT! Their penmanship is atrocious. From what I can gather, they're either planning to \"eat the blue skins and take their village\" or bake a blueberry pie. It really could go either way. We must get to the bottom of this!" }
WordHunterWoW_QuestEN[9918] = { title = "Not On My Watch!", description = "The battle plans were written up by an ogre lieutenant. His name is either Dump or Lump.\n\n<Bintook turns the parchment sideways and cocks her head.>\n\nIt could also be Billy.\n\nAnyhow, I think you should go back out there and have a word with Billy or Lump or Dumpy or whatever! Try to approach him diplomatically. If that doesn't work, try using some muscle.", objectives = "Huntress Bintook at Telaar in Nagrand wants you to speak to Lump. Return to Huntress Bintook when you have gathered the information that she requested.", completion = "Oh my! This is a small scouting and hunting party? You must tell Mo'mor what you have discovered." }
WordHunterWoW_QuestEN[9919] = { title = "Sporeggar", description = "You're a kind {race}, {name}.  Not like some of the others I've met.\n\nYou should meet the rest of my people; they'll be very grateful for your help.  Take these spore sacs to my leader, Msshi'fn.  You will find him in Sporeggar, north of here.", objectives = "Go to Sporeggar in Zangarmarsh, north of the Spawning Glen, and deliver the Salvaged Spore Sacs to Msshi'fn.", progress = "You've something to show me, <name>?", completion = "You've helped protect the next generation of sporelings, <race>.  We can only repay you by welcoming you into our homes.  Stay for a bit and meet the other sporelings.  They will have many questions, I hope you don't mind." }
WordHunterWoW_QuestEN[9920] = { title = "Mo'mor the Breaker", description = "You must seek out Mo'mor immediately! You will find him in the center of Telaar, by the fountain. Tell him exactly what the ogre told you.", objectives = "Huntress Bintook at Telaar in Nagrand wants you to speak to Mo'mor the Breaker.", completion = "<Mo'mor looks perplexed.>\n\nSo, a new tribe of ogres is forcing the Boulderfist further and further south. This is quite troubling. We must first deal with the situation closest to home..." }
WordHunterWoW_QuestEN[9921] = { title = "The Ruins of Burning Blade", description = "These ogre hunting parties are a precursor to invasion. We must strike at them before they have a chance to amass an army big enough to take over our town.\n\nYou're going to need to get your hands dirty, {race}.\n\nThe largest collection of Boulderfist in this region can be found at the Burning Blade Ruins, almost directly east of Telaar, near the border of Terokkar. Go there and show the Boulderfist that Telaar will not bend to their will!", objectives = "Mo'mor the Breaker at Telaar in Nagrand wants you to kill 8 Boulderfist Crushers and 8 Boulderfist Mystics.", completion = "Excellent. Did you happen to locate this Lantresor creature that the stupid one's letter mentioned?\n\nRegardless, we must press on. I have gotten reports of more ogre activity that must be dealt with at once!" }
WordHunterWoW_QuestEN[9922] = { title = "The Twin Clefts of Nagrand", description = "You made a strong showing, {name}. Are you ready for more?\n\nI have received reports of a large contingent of Boulderfist ogres hidden in the twin clefts of Nagrand, northwest of here in the Halaani Basin.\n\nVenture forth to the clefts and deal with the remaining Boulderfist ogres.", objectives = "Mo'mor the Breaker at Telaar in Nagrand has asked that you slay 10 Boulderfist Warriors and 10 Boulderfist Mages.", completion = "Excellent work! I am currently researching the Warmaul tribe that the Boulderfist lieutenant mentioned. Now the tasks you have performed must be tested." }
WordHunterWoW_QuestEN[9923] = { title = "HELP!", description = "HELP! They're gonna eat me! I just know it!\n\nFind the key, I know it has to be on one of these ogres.\n\nIf you get me out of here, my father will reward you handsomely! He's the leader of Telaar, Arechron.\n", objectives = "Find the Boulderfist Key and Free Corki. Speak with Arechron in Telaar should you succeed.", completion = "I'm really sorry about this, <race>. He's always getting himself into trouble. I just wish I could put a leash on him..." }
WordHunterWoW_QuestEN[9924] = { title = "Corki's Gone Missing Again!", description = "<Arechron sighs.>\n\nThis is so embarrassing. Do you remember my boy, Corki? You rescued him from the Burning Blade Ruins recently. Well, his curiosity has gotten the best of him once more. He told me that he was going to investigate the Boulderfist menace for 'uncle' Mo'mor and ran off to the ogre mounds in the Halaani Basin, north of here.\n\nDo you think you could track him down? I would be eternally grateful.\n", objectives = "Arechron at Telaar has asked that you find and free Corki.", completion = "Thank you so much, <name>. His mother will deal with him from now on." }
WordHunterWoW_QuestEN[9925] = { title = "Matters of Security", description = "Gezhe chose to base our operations as close to Oshu'gun as possible, without any regard for the safety of our crew.  Why?  Because he projected a ten percent increase in productivity by setting up shop here instead of in the mountains to the south.\n\nNever mind the crazed voidspawn wandering all of ten feet away from us.  That would be the security officer's problem, not Gezhe's.\n\nKill some voidspawn for me and I'll pay you a tenth of our security budget.  Don't get excited, it's not much of a budget.", objectives = "Zerid at Aeris Landing in Nagrand wants you to kill 8 Voidspawn near Oshu'gun.", completion = "You bring a smile to my face, <name>.  Or you would, rather, if I had a face.\n\nKeep it up and you and I are going to be the best of friends." }
WordHunterWoW_QuestEN[9926] = { title = "FLAG Shadow Council/Warmaul Questline", description = "", objectives = "" }
WordHunterWoW_QuestEN[9927] = { title = "Ruthless Cunning", description = "<Lantresor hands you a pack full of banners.>\n\nThese are Warmaul ogre banners that I recently acquired.\n\nI want you to travel to Kil'sorrow Fortress, directly south of here, and kill as many of the Kil'sorrow filth as you can find. Drive a Warmaul ogre banner through the heart of each fallen Kil'sorrow soldier. Return to me when you have completed this task and the other that this plan requires.", objectives = "Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to drive 10 Warmaul Ogre Banners through the bodies of Kil'sorrow members at Kil'sorrow Fortress.\n\nReturn any unused Warmaul Ogre Banners.", progress = "<Lantresor's eyes open in bewilderment.>\n\nIs it done?", completion = "Can you imagine their puzzlement over what is happening, <race>? This will be glorious." }
WordHunterWoW_QuestEN[9928] = { title = "Armaments for Deception", description = "You will need to steal Kil'sorrow armaments from Kil'sorrow Fortress if my plan is to work.\n\nSearch the fortress for crates of Kil'sorrow armaments. Bring whatever you can find to me.\n\nKil'sorrow Fortress is located directly south and a little to the west of the Burning Blade Ruins.", objectives = "Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to collect 10 Kil'sorrow Armaments.", progress = "We will ignite a hatred heretofore unseen between the two clans!", completion = "Excellent! Our next target will be the Laughing Skull Ruins." }
WordHunterWoW_QuestEN[9929] = { title = "The Missing Merchant", description = "I don't suppose you've been here long enough to know Dugar, have you? He's a merchant with contacts among the various factions in Shattrath.\n\nDon't ask me how he does it, but he manages to trade with them for some of the goods our quartermasters can't provide.\n\nHe set out for Shattrath three days ago and hasn't returned. He's normally able to make the entire trip in less than that. If you're going to be traveling in the forest, would you keep an eye out for him?You will receive:", objectives = "Travel northwest along the road toward Shattrath and search for evidence of what happened to Dugar.I don't suppose you've been here long enough to know Dugar, have you? He's a merchant with contacts among the various factions in Shattrath.\n\nDon't ask me how he does it, but he manages to trade with them for some of the goods our quartermasters can't provide.\n\nHe set out for Shattrath three days ago and hasn't returned. He's normally able to make the entire trip in less than that. If you're going to be traveling in the forest, would you keep an eye out for him?You will receive:" }
WordHunterWoW_QuestEN[9930] = { title = "The Missing Merchant", description = "I don't suppose you've been here long enough to know Deirom, have you? He's a merchant with contacts among the various factions in Shattrath.\n\nDon't ask me how he does it, but he manages to trade with them for some of the goods our quartermasters can't provide.\n\nHe set out for Shattrath three days ago and hasn't returned. He's normally able to make the entire trip in less than that. Keep an eye out for him and report anything you find to the mercenary captain, Thander.You will receive:", objectives = "Travel northwest along the road toward Shattrath and search for evidence of what happened to Deirom.I don't suppose you've been here long enough to know Deirom, have you? He's a merchant with contacts among the various factions in Shattrath.\n\nDon't ask me how he does it, but he manages to trade with them for some of the goods our quartermasters can't provide.\n\nHe set out for Shattrath three days ago and hasn't returned. He's normally able to make the entire trip in less than that. Keep an eye out for him and report anything you find to the mercenary captain, Thander.You will receive:" }
WordHunterWoW_QuestEN[9931] = { title = "Returning the Favor", description = "Now you must plant the seed of war in the fat, useless heads of the Warmaul. To the northwest, near the mountains, you will find the Laughing Skull Ruins.\n\n<Lantresor points into the crate of armaments you brought him.>\n\nDo you recognize those banners? They are Kil'sorrow banners. I want you to take a stack of Kil'sorrow banners and plant them on the corpses of Warmaul ogres. Remember, northwest is where you will find the ogres.", objectives = "Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to drive 10 Kil'sorrow Banners through the bodies of Warmaul ogres at the Laughing Skull Ruins.\n\nReturn any unused Kil'sorrow Banners.", progress = "Can you predict what will happen next?", completion = "The plan is perfect, <name>. I am already seeing the fruits of your labor." }
WordHunterWoW_QuestEN[9932] = { title = "Body of Evidence", description = "Your rampage through Kil'sorrow Fortress has provided us with a special opportunity. We have enough bodies to make it appear as if a great battle has taken place.\n\nTravel to the Laughing Skull Ruins and find the Laughing Skull Courtyard. There should be a blazing pyre in the courtyard. Make sure the area is secure and then use this blanket to send up smoke signals. When my ogres see the smoke, they will sneak in and plant the bodies of slain Kil'sorrow soldiers.\n\nThat should be the final straw!", objectives = "Lantresor of the Blade at the Burning Blade Ruins in Nagrand wants you to use the Damp Woolen Blanket at the Blazing Warmaul Pyre in the Laughing Skull Courtyard to signal his ogres.", progress = "Do you now understand why you could never win a war against me?", completion = "I must admit, I have not felt this alive in decades. You have performed well, <name>." }
WordHunterWoW_QuestEN[9933] = { title = "Message to Telaar", description = "<Lantresor points to an unmarked crate.>\n\nTake it. It is my offering to your people. You have single-handedly saved my clan from extermination.\n\nYou may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.\n\n<Lantresor bows.>\n", objectives = "Take the Burning Blade Peace Offering to Arechron at Telaar in Nagrand.", progress = "Peace you say?", completion = "Please, <name>, take from the peace offering whatever it is that you may desire. After all, without your efforts, this would not have been possible." }
WordHunterWoW_QuestEN[9934] = { title = "Message to Garadar", description = "<Lantresor points to an unmarked crate.>\n\nTake it. It is my offering to your people. You have single-handedly saved my clan from extermination.\n\nYou may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.\n\n<Lantresor bows.>", objectives = "Take the Burning Blade Peace Offering to Garrosh at Garadar.", progress = "<Garrosh seems unmoved by the offering.>", completion = "<Garrosh kicks the crate aside.>\n\nYou waste your time, <race>. Take whatever you desire from the crate. I nor Garadar have any need for these useless trinkets." }
WordHunterWoW_QuestEN[9935] = { title = "WANTED: Giselda the Crone", description = "Wanted: Dead or Alive\n\nGiselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.\n\nKnown to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of Terokkar.\n\nLarge gold reward to be dispensed by Warden Bullrok at Garadar to anyone able to bring Giselda to justice.", objectives = "Slay Giselda the Crone and any combination of 10 Kil'sorrow Agents. Return to Warden Bullrok at Garadar should you complete this task.", completion = "The crone has been slain! This is wonderful news, <name>. Here is your reward." }
WordHunterWoW_QuestEN[9936] = { title = "WANTED: Giselda the Crone", description = "Wanted: Dead or Alive\n\nGiselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.\n\nKnown to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of Terokkar.\n\nLarge gold reward to be dispensed by Warden Moi'bff Jill at Telaar to anyone able to bring Giselda to justice.", objectives = "Slay Giselda the Crone and any combination of 10 Kil'sorrow Agents. Return to Warden Moi'bff Jill at Telaar should you complete this task.", completion = "The crone has been slain! This is wonderful news, <name>. Here is your reward." }
WordHunterWoW_QuestEN[9937] = { title = "WANTED: Durn the Hungerer", description = "You have destroyed two of the biggest threats in Nagrand, {name}. Are you ready to take on the scourge of the Spirit Fields?\n\nDurn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, far southwest of here, near Oshu'gun, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.\n", objectives = "Slay Durn the Hungerer. Return to Warden Bullrok if you manage to complete this task.", completion = "Durn's murderous grip has been loosed! Nagrand has a brighter tomorrow because of you, hero. Well done!" }
WordHunterWoW_QuestEN[9938] = { title = "WANTED: Durn the Hungerer", description = "You have destroyed two of the biggest threats in Nagrand, {name}. Are you ready to take on the scourge of the Spirit Fields?\n\nDurn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, west of here, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.", objectives = "Slay Durn the Hungerer. Return to Warden Moi'bff Jill if you manage to complete this task.", completion = "Durn's murderous grip has been loosed! Nagrand has a brighter tomorrow because of you, hero. Well done!" }
WordHunterWoW_QuestEN[9939] = { title = "WANTED: Zorbo the Advisor", description = "Wanted: Dead or Alive\n\nZorbo the Advisor, wanted for numerous planned attacks on Garadar. Along with his reavers and shaman, Zorbo has slain countless orcs. Consider Zorbo as armed, dangerous, and merciless.\n\nZorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand.\n\nReward for Zorbo the Advisor's death or capture to be dispensed by Warden Bullrok at Garadar. ", objectives = "Slay Zorbo the Advisor, 5 Warmaul Shaman and 5 Warmaul Reavers. Return to Warden Bullrok if you manage to complete this task.", completion = "This is a great victory for the people of Garadar! Well done, <name>!" }
WordHunterWoW_QuestEN[9940] = { title = "WANTED: Zorbo the Advisor", description = "Wanted: Dead or Alive\n\nZorbo the Advisor, wanted for numerous planned attacks on Telaar. Along with his reavers and shaman, Zorbo has slain countless Broken. Consider Zorbo as armed, dangerous, and merciless.\n\nZorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand.\n\nReward for Zorbo the Advisor's death or capture to be dispensed by Warden Moi'bff Jill at Telaar.", objectives = "Slay Zorbo the Advisor, 5 Warmaul Shaman and 5 Warmaul Reavers. Return to Warden Moi'bff Jill if you manage to complete this task.", completion = "This is a great victory for the people of Telaar! Well done, <name>!" }
WordHunterWoW_QuestEN[9941] = { title = "Tracking Down the Culprits", description = "The arakkoa tracks, accompanied by a pair of shallow ruts, lead north across the road. It seems the arakkoa dragged something away from the site of the battle, perhaps toward a nearby settlement.\n\nWhile the broken cart shows signs of a struggle, there's little information about Deirom's fate. Follow the arakkoa tracks north and continue your search for the merchant. If he was captured alive, there may still be a chance to rescue him.You will receive:", objectives = "Continue your search for signs of Deirom in the Arakkoa settlement north of the broken cart.The arakkoa tracks, accompanied by a pair of shallow ruts, lead north across the road. It seems the arakkoa dragged something away from the site of the battle, perhaps toward a nearby settlement.\n\nWhile the broken cart shows signs of a struggle, there's little information about Deirom's fate. Follow the arakkoa tracks north and continue your search for the merchant. If he was captured alive, there may still be a chance to rescue him.You will receive:" }
WordHunterWoW_QuestEN[9942] = { title = "Tracking Down the Culprits", description = "The arakkoa tracks, accompanied by a pair of shallow ruts, lead north across the road. It seems the arakkoa dragged something away from the site of the battle, perhaps toward a nearby settlement.\n\nWhile the broken cart shows signs of a struggle, there's little information about Dugar's fate. Follow the arakkoa tracks north and continue your search for the merchant. If he was captured alive, there may still be a chance to rescue him.You will receive:", objectives = "Continue your search for signs of Dugar in the Arakkoa settlement north of the broken cart.The arakkoa tracks, accompanied by a pair of shallow ruts, lead north across the road. It seems the arakkoa dragged something away from the site of the battle, perhaps toward a nearby settlement.\n\nWhile the broken cart shows signs of a struggle, there's little information about Dugar's fate. Follow the arakkoa tracks north and continue your search for the merchant. If he was captured alive, there may still be a chance to rescue him.You will receive:" }
WordHunterWoW_QuestEN[9943] = { title = "Return to Thander", description = "Deirom's cargo doesn't seem to have been harmed or even opened. The cargo clearly seemed of interest to them, but it seems their prisoner was more important. What the arakkoa hoped to gain from attacking and kidnapping Deirom remains unclear, but the merchant is certainly not being held here. \n\nWithout any further clues as to how to continue your search, you decide it might be a good time to report your findings to Thander.You will receive:", objectives = "Return to Thander at the Allerian Stronghold with news of your findings.Deirom's cargo doesn't seem to have been harmed or even opened. The cargo clearly seemed of interest to them, but it seems their prisoner was more important. What the arakkoa hoped to gain from attacking and kidnapping Deirom remains unclear, but the merchant is certainly not being held here. \n\nWithout any further clues as to how to continue your search, you decide it might be a good time to report your findings to Thander.You will receive:" }
WordHunterWoW_QuestEN[9944] = { title = "Missing Mag'hari Procession", description = "Greatmother says that we must press on and serve our people. She says that we must serve as an example for Garrosh - to show that life goes on.\n\nI have so many matters to attend to here, especially with Greatmother having taken ill. Would you honor the Mag'har by helping one of their matrons?\n\nSeveral days ago we sent a funeral procession to the Ancestral Grounds and they have yet to return. Will you go search for them? They took the western road out of Garadar. Follow it around and avoid Halaa.", objectives = "Search for the missing Mag'hari procession.", completion = "Thirty orcs, <race>! Of those original thirty, only Ungriz and I remain. We found the young orc, Saurfang, nearly dead near Sunspring. Apparently he was here for another reason..." }
WordHunterWoW_QuestEN[9945] = { title = "War on the Warmaul", description = "We were en route to the Ancestral Grounds when we were ambushed by Warmaul. They came from all sides, killing several of the procession guards and many of the others. They even desecrated the remains of the elder in the wagon.\n\nAnd for what? So they could humiliate us and display their power. Not even Boulderfist would have sunk so low.\n\nI am a spiritual orc, {name}, but even I have limitations. Find the attackers at Warmaul Hill to the northwest and destroy them!", objectives = "Elder Yorley at the Mag'hari Procession in Nagrand has asked that you slay 8 Warmaul Brutes and 8 Warmaul Warlocks.", completion = "It is a good start, but their leader must be dealt with for your actions to have any lasting impact." }
WordHunterWoW_QuestEN[9946] = { title = "Cho'war the Pillager", description = "Have you ever seen an ogre king, {race}? Few have and lived to tell the tale. Unfortunately, that is exactly what we are dealing with here.\n\nThe leader of these barbarians is an ogre named Cho'war. Rumor has it that Cho'war was the ogre responsible for forcing the gronn out of the cave. Cho'war then declared himself king and dissolved the ogre clans that served under the gronn. Thus, Warmaul was born.\n\nFind Cho'war deep in the caves of Warmaul Hill. Slay him and bring me his head.", objectives = "Elder Yorley at the Mag'hari Procession in Nagrand has asked that you slay Cho'war the Pillager and retrieve the Head of Cho'war.", progress = "He will undoubtedly be heavily guarded.", completion = "This head will be posted at the gates of Garadar for all to see. The ogres will think twice before interrupting sacred Mag'hari rituals." }
WordHunterWoW_QuestEN[9947] = { title = "Return to Rokag", description = "Dugar's cargo doesn't seem to have been harmed or even opened. The cargo clearly seemed of interest to them, but it seems their prisoner was more important. What the arakkoa hoped to gain from attacking and kidnapping Dugar remains unclear, but the merchant is certainly not being held here. \n\nWithout any further clues as to how to continue your search, you decide it might be a good time to report your findings to Rokag.You will receive:", objectives = "Return to Rokag at Stonebreaker Hold with news of your findings.Dugar's cargo doesn't seem to have been harmed or even opened. The cargo clearly seemed of interest to them, but it seems their prisoner was more important. What the arakkoa hoped to gain from attacking and kidnapping Dugar remains unclear, but the merchant is certainly not being held here. \n\nWithout any further clues as to how to continue your search, you decide it might be a good time to report your findings to Rokag.You will receive:" }
WordHunterWoW_QuestEN[9948] = { title = "Finding the Survivors", description = "If I know anything about ogres, it's that they like their food fresh. This means that the Mag'har that they captured are more than likely being kept alive until they are ready to serve. It's a sickening thought, I know, but one that we must use to our advantage.\n\nVenture to Warmaul Hill and search for Mag'har prisoners. If you find prisoners, then you will find keys to their cages on the nearby Warmaul ogres.\n\nKill ogres for their keys and release the prisoners.", objectives = "Elder Ungriz at the Mag'hari Procession in Nagrand has asked that you free 5 Mag'har Prisoners.", completion = "You have done what none thought was possible and brought back our missing brothers and sisters. You are a hero to the Mag'har, <name>. All will know your name and the deeds that you have performed for us." }
WordHunterWoW_QuestEN[9949] = { title = "A Bird's-Eye View", description = "With no further information to go on, we're in a difficult situation. I'm not going to give up on finding and rescuing Deirom. His abduction isn't an accident, <name>.\n\nThe arakkoa are up to something, but what is it they're planning?\n\nAndarl, over in the mage tower, knows something of their peculiar magic. With the right tools, he can scare up some new information for us. He'll need the \"eye\" crystals from each of the arakkoa towns north of the Bone Wastes - Veil Skith, Veil Reskk, and Veil Shienor.You will receive:", objectives = "Bring the Eye of Veil Skith, the Eye of Veil Shienor, and the Eye of Veil Reskk to Andarl at the Allerian Stronghold." }
WordHunterWoW_QuestEN[9950] = { title = "A Bird's-Eye View", description = "With no further information to go on, we're in a difficult situation. I'm not going to give up on finding and rescuing Dugar. His abduction isn't an accident, <name>.\n\nThe arakkoa are up to something, but what is it they're planning?\n\nKurgatok the warlock knows something of their peculiar magic. With the right tools, he can scare up some new information for us. He'll need the \"eye\" crystals from each of the arakkoa towns north of the Bone Wastes - Veil Skith, Veil Reskk, and Veil Shienor.You will receive:", objectives = "Bring the Eye of Veil Skith, the Eye of Veil Shienor, and the Eye of Veil Reskk to Kurgatok at Stonebreaker Hold." }
WordHunterWoW_QuestEN[9951] = { title = "It's Watching You!", description = "Quick, hide!  The eyes of Naphthal'ar are upon you... upon us all!\n\nI dare not go to the top of the tower to speak with it, but you... you look as if you might know the right words to say.  Just be careful, it doesn't like jokes and will not suffer fools easily.\n\nIf you can, convince it to come down for tea.  But, by all means, get it to stop staring at me!", objectives = "Kill Naphthal'ar and then return to Warden Treelos at the Cenarion Thicket in Terokkar Forest.", progress = "We should never have invited them to dinner.  That much is certain!\n\nOr, at least, we should have insisted upon a couple of courses before the dessert that they brought.", completion = "It's for the best, really.  If it cannot civilly accept an invitation then it has no business attending.\n\n<Warden Treelos looks momentarily confused.>\n\nWho are you and what are you doing here?  You must get out of here quickly before it is too late!" }
WordHunterWoW_QuestEN[9952] = { title = "Prospector Balmoral", description = "So Andarl is certain Deirom is being held in Veil Shalas? That's the largest of the arakkoa settlements that we know of.\n\nVeil Shalas is in the far south of the forest, close to the eastern rim of the Bone Wastes. Unfortunately, I don't have much information on it, but there is an Explorers' League member camped down there who may be able to help you. Prospector Balmoral's camp is perched on the very edge of the land to the southwest of Veil Shalas. Consult him before making any move against the arakkoa.You will receive:", objectives = "Locate and speak with Prospector Balmoral.So Andarl is certain Deirom is being held in Veil Shalas? That's the largest of the arakkoa settlements that we know of.\n\nVeil Shalas is in the far south of the forest, close to the eastern rim of the Bone Wastes. Unfortunately, I don't have much information on it, but there is an Explorers' League member camped down there who may be able to help you. Prospector Balmoral's camp is perched on the very edge of the land to the southwest of Veil Shalas. Consult him before making any move against the arakkoa.You will receive:" }
WordHunterWoW_QuestEN[9953] = { title = "Lookout Nodak", description = "So Kurgatok is certain Dugar is being held in Veil Shalas? That's the largest of the arakkoa settlements that we know of.\n\nVeil Shalas is in the far south of the forest, close to the eastern rim of the Bone Wastes. Unfortunately, I don't have much information on it, but we have a scout camped down there who may be able to help you. Lookout Nodak's camp is perched on the very edge of the land to the southwest of Veil Shalas. Consult him before making any move against the arakkoa.You will receive:", objectives = "Locate and speak with Lookout Nodak.So Kurgatok is certain Dugar is being held in Veil Shalas? That's the largest of the arakkoa settlements that we know of.\n\nVeil Shalas is in the far south of the forest, close to the eastern rim of the Bone Wastes. Unfortunately, I don't have much information on it, but we have a scout camped down there who may be able to help you. Lookout Nodak's camp is perched on the very edge of the land to the southwest of Veil Shalas. Consult him before making any move against the arakkoa.You will receive:" }
WordHunterWoW_QuestEN[9954] = { title = "Corki's Ransom", description = "<Arechron shows you a grime covered letter.>\n\nI just received this letter. It's from a clan of ogres known as Warmaul that rule the northwestern lands of Nagrand. It says that they have Corki and if we don't cooperate, they're going to eat him. Admittedly, Corki is a moron, but he's still my blood. Will you rescue him, {name}?\n\nI presume that he's locked up in a cage somewhere on Warmaul Hill. That should be your first stop.", objectives = "Arechron wants you to find Corki at Warmaul Hill.", completion = "They've got me locked up good this time, <name>. The Warmaul king, Cho'war, has the key." }
WordHunterWoW_QuestEN[9955] = { title = "Cho'war the Pillager", description = "They call him Cho'war the Pillager, {name}. He's the ogre that forced out the gronn that used to rule over these ogres. You better believe he's powerful!\n\nThe chef said that Cho'war lives in the big cave - wherever that may be... Get that key and get me out of here! If we live through this, my father will no doubt give you the big reward! As soon as I'm free, seek him out.", objectives = "Corki wants you to get Cho'war's Key so that you can free him from his cage. Return to Arechron at Telaar should you manage this task.", completion = "Thank you, <name>. Corki's been sent away to live among the night elves in Blade's Edge. Hopefully they'll be able to keep him out of trouble.\n\nAbout that reward..." }
WordHunterWoW_QuestEN[9956] = { title = "The Ravaged Caravan", description = "I was part of a caravan taking supplies to the Orebor Harborage in Zangarmarsh. As we were nearing the border of the marsh, we were jumped by a vicious squad of Warmaul ogres. They killed the others and took me prisoner, along with all of our supplies.\n\nThankfully, they neglected to place a backing on my cage. When they fell asleep, I made my escape.\n\nIt's too late for my comrades but we could really use the supplies they stole. Warmaul Hill is in the northwestern mountains of Nagrand.", objectives = "Huntress Kima at Telaar in Nagrand wants you to recover 10 Telaar Supply Crates.", progress = "I feel so stupid. Arechron's son, Corki, asked me what happened and I told him. Now he's gone missing again!", completion = "Amazing! How did you manage to carry all of that back by yourself?" }
WordHunterWoW_QuestEN[9957] = { title = "What's Wrong at Cenarion Thicket?", description = "We haven't heard from the druids at the Cenarion Thicket of Terokkar Forest in quite some time.\n\n{name}, I'd like for you to go down there and check in with them to see what's happening.  There are several ways to get there, but the fastest is to head south along the path, and then take the road that branches east from Shattrath City once you're in the forest.", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", completion = "I'm glad that the refuge sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?" }
WordHunterWoW_QuestEN[9958] = { title = "Scouting the Defenses", description = "In my time out here, I've had a few interactions with the arakkoa, none of them friendly. They seem very territorial, but I suppose we're the same way, aren't we?\n\nThe arakkoa wield a kind of primal magic unknown to us on Azeroth and have used it to weave defenses for Veil Shalas. Before moving against them, it would be prudent to scout out their defenses so we know what we're up against.You will receive:", objectives = "Approach Veil Shalas and observe the town's defenses." }
WordHunterWoW_QuestEN[9959] = { title = "Scouting the Defenses", description = "In my time out here, I've had a few interactions with the arakkoa, none of them friendly. They seem very territorial, but I suppose we're the same way, aren't we? Not even the ancestors recorded any encounters with the bird-men.\n\nThe arakkoa wield a kind of primal magic unknown to our seers and have used it to weave defenses for Veil Shalas. Before moving against them, it would be wise to scout out their defenses so we know what we're up against.You will receive:", objectives = "Approach Veil Shalas and learn about the magic defending the settlement." }
WordHunterWoW_QuestEN[9960] = { title = "What's Wrong at Cenarion Thicket?", description = "Hey there, {class}.  We haven't heard from the druids of the Cenarion Thicket in quite some time.\n\nI want you to go over there and check to see what's happening.  You can find it by heading northwest through the forest.", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", completion = "I'm glad that Stonebreaker Hold sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?" }
WordHunterWoW_QuestEN[9961] = { title = "What's Wrong at Cenarion Thicket?", description = "{class}, I have urgent business for you.  We haven't heard from the druids of the Cenarion Thicket in quite some time.  This is unusual as we usually hear from them at least once every few days.\n\nI want you to go up there and make sure that they're alright.  You can find the thicket by heading northwest through the forest.", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", completion = "I'm glad that Allerian Stronghold sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?" }
WordHunterWoW_QuestEN[9962] = { title = "The Ring of Blood: Brokentoe", description = "So are you ready for your first battle? If you are, let me know and I'll get things started. All you have to do is go wait in the Ring of Blood for your opponent to arrive.\n\nThis fight is against Brokentoe, a ferocious clefthoof.\n\nGood luck! I hope you brought friends.\n\nAnd remember, the fight's over when either you or your opponent are lying face down on the arena floor.\n", objectives = "Defeat Brokentoe. Should you win, speak with Wodin the Troll-Servant to collect your reward.", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "Hrm, not bad. Not bad at all... You've got potential, kid. Here's a little gold to line your pockets with..." }
WordHunterWoW_QuestEN[9963] = { title = "Seeking Help from the Source", description = "The wards you encountered are powerful magic, indeed. The techniques employed by the arakkoa are so far beyond our understanding that we can only hope to find a counter with their help.\n\nI know what's going through your mind. Why would an enemy help us to overcome their defenses? The answer is that they wouldn't, of course. Have you heard the tales of a crazy old arakkoa sage named Kokorek? They say he's hiding in Veil Lithic on the western edge of the Bone Wastes, waiting for the return of a lost age.You will receive:", objectives = "Find Kokorek in Veil Lithic and speak with him.The wards you encountered are powerful magic, indeed. The techniques employed by the arakkoa are so far beyond our understanding that we can only hope to find a counter with their help.\n\nI know what's going through your mind. Why would an enemy help us to overcome their defenses? The answer is that they wouldn't, of course. Have you heard the tales of a crazy old arakkoa sage named Kokorek? They say he's hiding in Veil Lithic on the western edge of the Bone Wastes, waiting for the return of a lost age.You will receive:" }
WordHunterWoW_QuestEN[9964] = { title = "Seeking Help from the Source", description = "The wards you encountered are powerful magic, indeed. The techniques employed by the arakkoa are so far beyond our understanding that we can only hope to find a counter with their help.\n\nI know what's going through your mind. Why would an enemy help us to overcome their defenses? The answer is that they wouldn't, of course. Have you heard the tales of a crazy old arakkoa sage named Kokorek? They say he's hiding in Veil Lithic on the western edge of the Bone Wastes, waiting for the return of a lost age.You will receive:", objectives = "Find Kokorek in Veil Lithic and speak with him.The wards you encountered are powerful magic, indeed. The techniques employed by the arakkoa are so far beyond our understanding that we can only hope to find a counter with their help.\n\nI know what's going through your mind. Why would an enemy help us to overcome their defenses? The answer is that they wouldn't, of course. Have you heard the tales of a crazy old arakkoa sage named Kokorek? They say he's hiding in Veil Lithic on the western edge of the Bone Wastes, waiting for the return of a lost age.You will receive:" }
WordHunterWoW_QuestEN[9965] = { title = "A Show of Good Faith", description = "I'd like to propose something of a trade: demonstrate your good intentions by helping me resolve a little problem, and I'll help you rescue your comrade.\n\nThe ogres are an ancient enemy of my people, and lately they have begun to filter back into our forest from the grasslands of Nagrand.\n\nOne particular ogre, Mug'gok, is quite an adventurous fellow, but none too bright. He goes back and forth between causing trouble for his friends at the Bleeding Hollow Ruins and trying to provoke us.You will receive:", objectives = "Bring Mug'gok's Head to Kokorek in Veil Lithic." }
WordHunterWoW_QuestEN[9966] = { title = "A Show of Good Faith", description = "I'd like to propose something of a trade: demonstrate your good intentions by helping me resolve a little problem, and I'll help you rescue your comrade.\n\nThe ogres are an ancient enemy of my people, and lately they have begun to filter back into our forest from the grasslands of Nagrand.\n\nOne particular ogre, Mug'gok, is quite an adventurous fellow, but none too bright. He goes back and forth between causing trouble for his friends at the Bleeding Hollow Ruins and trying to provoke us.You will receive:", objectives = "Bring Mug'gok's Head to Kokorek in Veil Lithic." }
WordHunterWoW_QuestEN[9967] = { title = "The Ring of Blood: The Blue Brothers", description = "This next battle involves a duo - twin brothers to be precise. They call themselves the \"Blue Brothers.\"\n\nIt's not too late to chicken out, {name}. I'd certainly understand.\n\nBut if you're ready for some action, step in the Ring of Blood and wait for the Murkblood twins to arrive.\n\nLast one standing is the winner!", objectives = "Defeat the Murkblood Twins that call themselves the Blue Brothers. Should you win, speak with Wodin the Troll-Servant to collect your reward.", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "I'll admit that I didn't think you had a prayer, <name>! That was amazing! So how 'bout another fight? Gurgthock's got the perfect match lined up." }
WordHunterWoW_QuestEN[9968] = { title = "Strange Energy", description = "Something strange has changed the teromoths of the thicket.\n\nWhere once there was a diversity of life in there, now only the teromoths remain.  And while before they were at peace, now they are agitated and will not hesitate to attack you should you get close.\n\nI need to compare the vicious ones to the normal.  Collect for me a number of samples from both.  You'll find the unaffected teromoths both to the south and the north.\n\nI'm certain this is related to whatever killed all of the druids.", objectives = "Collect 4 Teromoth Samples and 4 Vicious Teromoth Samples. Then return to Earthbinder Tavgren just outside of the Cenarion Thicket in Terokkar Forest.", progress = "Do you have my samples?", completion = "Odd.  The samples from the vicious teromoths are infused with what feels to me to be pure mana.\n\nIt would seem that whatever caused all of this death also left behind that strong field of residual energy.  But for some reason the teromoths were not killed by it; instead being driven into an agitated state.\n\nIt seems apparent that this strange energy is the by-product of whatever attacked the thicket." }
WordHunterWoW_QuestEN[9969] = { title = "The Final Reagents", description = "I can create an item that will neutralize the ward spells protecting Veil Shalas, but be warned, <name>. The magic will only work as long as your friend is held captive. I will not give you a means to attack my people at will.\n\nI have most of the materials I require to create the charm, but there are a couple that I'm going to need you to gather before I can finish the work. I'll need some warp hunter essence and a handful of Terokkar chokeberries. Both can be found in the area around the veil.You will receive:", objectives = "Bring 5 Warp Hunter Essences and 30 Terokkar Chokeberries to Kokorek in Veil Lithic." }
WordHunterWoW_QuestEN[9970] = { title = "The Ring of Blood: Rokdar the Sundered Lord", description = "This fight is gonna be painful, {name}. Do you have any friends that are brave enough to help you out? The ogres managed to get a giant from Blade's Edge named Rokdar! Trust me, you're gonna need friends, he seems unbeatable! He's hard as a rock - literally!\n\nIf you still want to fight him, step into the Ring of Blood and he will come.", objectives = "Defeat Rokdar the Sundered Lord. Should you win, speak with Wodin the Troll-Servant to collect your reward.", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "You've got the ogres sweatin', kid! Here's a little something extra this time - don't use 'em all in one place.\n\nAre you ready for another fight? Gurgthock's bettin' the bank on you!" }
WordHunterWoW_QuestEN[9971] = { title = "Clues in the Thicket", description = "I have no idea what killed all of the druids here.  I've been away for a couple of days on a survey of the Bone Wastes to the south.\n\nPlease, you must help me to uncover what's behind this horrible tragedy.  Go into the thicket and look for a clue that might reveal something to us.  When I was in there briefly, I could have sworn I saw a dead Broken and a strange object next to him.\n\n And don't worry about Treelos - he might have been driven insane by what happened, but I think he's mostly harmless.", objectives = "Investigate the Strange Object next to the Broken Corpse to determine what might have befallen the Cenarion Thicket. Then return to Earthbinder Tavgren just outside the thicket in Terokkar Forest.", completion = "So, I was right.  That was the corpse of one of the Broken?  And you can confirm that there was a strange object on the ground next to him?\n\nThis doesn't make any sense.  What would one of the Broken be doing here?  And what is that thing it had with him?\n\nIs it what caused all of this death?" }
WordHunterWoW_QuestEN[9972] = { title = "The Ring of Blood: Skra'gath", description = "You're murderin' 'em out there, kid! They got a ringer for the next match. They say he's a void lord or something... No way do they want you up against their champion. Did you here that palooka, Mogor, yapping at you? The bets are through the roof!\n\nGet in that ring and take this one out fast!", objectives = "Defeat Skra'gath. Should you win, speak with Wodin the Troll-Servant to collect your reward.", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "KID! KID THIS IS IT! The next fight is the big one! The championship!\n\nOk, keep it cool. We don't want the ogres to know that we got anything going on. I get a cut of all this, after all." }
WordHunterWoW_QuestEN[9973] = { title = "The Ring of Blood: The Warmaul Champion", description = "They had to ship the champion in from the Blade's Edge gladiator pits. He was training on mountain giants - three at a time.\n\nIf you win this one, you become the new champion. What do you think your odds are, kid? Do you have a shot? Just give me the word and I'll bet the house on you.\n\nNow get in there and win!", objectives = "Defeat the Warmaul Champion. Should you win, speak with Wodin the Troll-Servant to collect your reward.", completion = "Oh boy. Mogor has invoked his right of battle as hero of the Warmaul. You have to fight him!\n\nNobody ever said the Warmaul were good sports... erm... ogres." }
WordHunterWoW_QuestEN[9974] = { title = "The Final Reagents", description = "I can create an item that will neutralize the ward spells protecting Veil Shalas, but be warned, <name>. The magic will only work as long as your friend is held captive. I will not give you a means to attack my people at will.\n\nI have most of the materials I require to create the charm, but there are a couple that I'm going to need you to gather before I can finish the work. I'll need some warp hunter essence and a handful of Terokkar chokeberries. Both can be found in the area around the veil.You will receive:", objectives = "Bring 5 Warp Hunter Essences and 30 Terokkar Chokeberries to Kokorek at Veil Lithic." }
WordHunterWoW_QuestEN[9975] = { title = "Primal Magic", description = "I've stored the spell inside this talisman. Unleash it while standing near the totems that guard the approach to Veil Shalas. It should be sufficient to unravel the wards.\n\n<You mention that the figure in the talisman doesn't especially resemble an arakkoa.>\n\nMy people weren't always as they appear now. We were once magnificent creatures, but we... we made many ill-advised choices and failed in our sacred task. It cost us our beauty, our power, and very nearly our lives. Do not repeat our mistakes, <name>.You will receive:", objectives = "Use Kokorek's Talisman near the totems that guard the path to Veil Shalas, then speak with Prospector Balmoral." }
WordHunterWoW_QuestEN[9976] = { title = "Primal Magic", description = "I've stored the spell inside this talisman. Unleash it while standing near the totems that guard the approach to Veil Shalas. It should be sufficient to unravel the wards.\n\n<You mention that the figure in the talisman doesn't especially resemble an arakkoa.>\n\nMy people weren't always as they appear now. We were once magnificent creatures, but we... we made many ill-advised choices and failed in our sacred task. It cost us our beauty, our power, and very nearly our lives. Do not repeat our mistakes, <name>.You will receive:", objectives = "Use Kokorek's Talisman near the totems that guard the path to Veil Shalas, then speak with Lookout Nodak." }
WordHunterWoW_QuestEN[9977] = { title = "The Ring of Blood: The Final Challenge", description = "<Gurgthock is counting his massive pile of gold.>\n\nYou've made me a lot of money, kid. If you can defeat Mogor, I promise to make it worth your while. All that pain you suffered in the Ring of Blood is gonna end up paying off.\n\nNow get in there and show these ogres what you're made of!", objectives = "Defeat Mogor, Hero of the Warmaul. Should you win, speak with Wodin the Troll-Servant to collect your reward.", progress = "The fight's over when you or your opponent are dead on the floor.", completion = "Gurgthock told you he'd make it worth your while, kid. Take your pick!" }
WordHunterWoW_QuestEN[9978] = { title = "By Any Means Necessary", description = "I don't know what to make of all of this, but I do know how we can find more clues.\n\nEmpoor is a Broken merchant that traffics in all sorts of goods and information.  If you were to persuade him to talk, I'm sure he might have something interesting to say.\n\nHe travels the road here between Tuurem and Shattrath.  Watch out, though -- he travels with a bodyguard.", objectives = "Find Empoor on the road between Tuurem and Shattrath City in Terokkar Forest. Convince him to tell you what he knows.", completion = "Fine, fine... I'll tell you what I know, but it's not much!" }
WordHunterWoW_QuestEN[9979] = { title = "Wind Trader Lathrai", description = "I was asked to pick up and deliver some boxes of goods from an ethereal in Shattrath City.\n\nLast I saw him, he was standing outside of the World's End Tavern in Lower City.  His name is Wind Trader Lathrai, and that's all that I know!\n\nWant more answers, go talk with him!", objectives = "Speak with Wind Trader Lathrai near the World's End Tavern in the Lower City section of Shattrath City.", completion = "Yes?  How may I help you today, <race>?" }
WordHunterWoW_QuestEN[9980] = { title = "Rescue Deirom!", description = "Make your way to Veil Shalas with all haste, <name>! Time is of the essence here. If the arakkoa discover what you've done to their defenses, they may attempt to move Deirom, or even kill him.\n\nIf you can, bring a friend or two with you. It's likely to be rough there. The bird-men have gone to great lengths to secure their prisoner and they're not likely to give him up easily. After you've found Deirom and dealt with his captor, return to the Allerian Stronghold and notify Thander.You will receive:", objectives = "Venture into Veil Shalas, kill Luanga, and free Deirom. Report to Lady Dena Kennedy at the Allerian Stronghold when you have completed your mission." }
WordHunterWoW_QuestEN[9981] = { title = "Rescue Dugar!", description = "Make your way to Veil Shalas with all haste, <name>! Time is of the essence here. If the arakkoa discover what you've done to their defenses, they may attempt to move Dugar, or even kill him.\n\nIf you can, bring a friend or two with you. It's likely to be rough there. The bird-men have gone to great lengths to secure their prisoner and they're not likely to give him up easily. After you've found Dugar and dealt with his captor, return to Stonebreaker Hold and notify Rokag.You will receive:", objectives = "Venture into Veil Shalas, kill Luanga, and free Dugar. Report to Rokag at Stonebreaker Hold when you have completed your mission." }
WordHunterWoW_QuestEN[9982] = { title = "He Called Himself Altruis...", description = "A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand.\n\nHe claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons?\n\nBefore he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.", objectives = "If you are looking to fight the Burning Legion, find Altruis the Sufferer in western Nagrand.", completion = "Does my appearance startle you? Do you know what I am?" }
WordHunterWoW_QuestEN[9983] = { title = "He Called Himself Altruis...", description = "A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand.\n\nHe claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons?\n\nBefore he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.", objectives = "If you are looking to fight the Burning Legion, find Altruis the Sufferer in western Nagrand.", completion = "Does my appearance startle you? Do you know what I am?" }
WordHunterWoW_QuestEN[9984] = { title = "Host of the Hidden City", description = "Although you cannot read the strange script on the scroll, the ornate seal at the bottom of the document implies that it was drafted by an arakkoa of high standing. Luanga may have masterminded the capture and interrogation of Deirom, but it seems he was taking orders from someone else.\n\nYou remember Thander mentioning that Andarl has studied the arakkoa. Perhaps he can decipher the scroll's contents.", objectives = "Take Luanga's Orders to Andarl at the Allerian Stronghold in Terokkar Forest." }
WordHunterWoW_QuestEN[9985] = { title = "Host of the Hidden City", description = "Although you cannot read the strange script on the scroll, the ornate seal at the bottom of the document implies that it was drafted by an arakkoa of high standing. Luanga may have masterminded the capture and interrogation of Dugar, but it seems he was taking orders from someone else.\n\nYou remember Rokag mentioning that Kurgatok has studied the arakkoa. Perhaps he can decipher the scroll's contents.", objectives = "Bring Luanga's Orders to Kurgatok at Stonebreaker Hold in Terokkar Forest." }
WordHunterWoW_QuestEN[9986] = { title = "Stymying the Arakkoa", description = "We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers.\n\nMy scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil Shienor, and Veil Skith and kill them. ", objectives = "Kill Ashkaz in Veil Reskk, Ayit in Veil Shienor, and Urdak in Veil Skith and return to Thander at the Allerian Stronghold.", completion = "Well done, <name>. We have enough to worry about without wondering when the arakkoa will accost our merchants and messengers again." }
WordHunterWoW_QuestEN[9987] = { title = "Stymying the Arakkoa", description = "We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers.\n\nMy scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil Shienor, and Veil Skith and kill them. ", objectives = "Kill Ashkaz in Veil Reskk, Ayit in Veil Shienor, and Urdak in Veil Skith and return to Rokag at Stonebreaker Hold.", completion = "Well done, <name>. We have enough to worry about without wondering when the arakkoa will accost our merchants and messengers again." }
WordHunterWoW_QuestEN[9988] = { title = "A Dandy's Best Friend", description = "Don't let Thander and company fool you. They may look like a band of fearsome warriors, but underneath all that steel, they're nothing more than a troop of dandies!\n\nAnd they won't be seen in public without their hats. They're extravagant affairs made from felt and fur, complete with the gaudiest feathers you've ever seen.\n\nThe most desirable feathers come from any of the arakkoa, of course, and my supply is running low. I'll gladly pay you if you'll collect them for me.", objectives = "Bring 30 Arakkoa Feathers to Ros'eleth in the Allerian Stronghold." }
WordHunterWoW_QuestEN[9989] = { title = "Alien Spirits", description = "When I first came to Outland, and opened my ears to the voices of its spirits, I was amazed at what I heard. In time, I also came to notice which spirits I couldn't hear.\n\nFor all my attempts, I have never been able to make contact with the spirit of an arakkoa ancestor. Their magic is fundamentally different from ours, but I'm not convinced that their spirits are beyond my reach.\n\nBring me feathers from many arakkoa; perhaps having some token from them will provide the link I need.", objectives = "Bring 30 Arakkoa Feathers to Malukaz at Stonebreaker Hold." }
WordHunterWoW_QuestEN[9990] = { title = "Investigate Tuurem", description = "You know, come to think of it, I do recall selling several boxes of strange and exotic engineering parts to Empoor about a month ago.  I'm not sure what they'd be used for, but I know that they were delivered to Tuurem.\n\nPerhaps one or more of those boxes is still there?", objectives = "Find the Sealed Box and then deliver it to Earthbinder Tavgren just outside of the Cenarion Thicket in Terokkar Forest.", progress = "What news do you bring, <name>?", completion = "Ethereals?  Goods delivered to Tuurem?  Exotic engineering parts?  And a blood elf getting ready to deliver this last box to Firewing Point?\n\nWhat does all of this mean?!  How does it relate to what happened to the druids in the Cenarion Thicket?\n\nI think we should have a look inside that box." }
WordHunterWoW_QuestEN[9991] = { title = "Survey the Land", description = "To be my eyes will require some diligence on your part. Nethrandamus will take you through the Legion camps, but you must catalog everything that you see. Even the smallest detail that you may think to be inconsequential could be useful for our purposes.\n\nPrimarily, I want you to note what structures are in the camps and what comprises the camps' defenses.\n\nNethrandamus is ready when you are, {name}. Do not be afraid, he will keep you safe from harm.\n", objectives = "Sit back and enjoy the ride. Speak to Altruis when the survey is complete.", progress = "Never flown on the back of a nether drake, eh?", completion = "Excellent work, <name>! We now have a point from which we can plan our counter-attack." }
WordHunterWoW_QuestEN[9992] = { title = "Olemba Seeds", description = "Aren't the trees in the forest beautiful? I've often wondered if they would survive on Azeroth.\n\nI'm hesitant to send back seedlings, though. It's a rough trip and they're much harder to transport than something like a sack of seeds. The seeds are stored in tough cones that fall from the tree's branches once they've reached maturity.\n\nIf you come upon some of those cones in your travels, would you mind bringing some of the seeds back to me?", objectives = "Gather 30 Olemba Seeds and return them to Ros'eleth in the Allerian Stronghold.", progress = "I've started a seed collection, but I'm going to need some help before I have enough to send back to the park in Stormwind.", completion = "Thank you for bringing these seeds. I've almost got enough to send back the first batch!" }
WordHunterWoW_QuestEN[9993] = { title = "Olemba Seed Oil", description = "The oily seeds from the forest's olemba trees could prove very valuable. I'd like to gather a larger quantity of them, press them for their oil, and then see what I can do with it.\n\nJust think, there's a whole forest full of trees out there, producing a lot of seeds that go to waste. I don't care if it turns out to be cooking oil, lamp oil, or weapon oil, I won't let it go to waste!\n\nBring me any of the seeds that you happen to gather from the olemba cones. They're all over the place.", objectives = "Bring 30 Olemba Seeds to Rakoria in Stonebreaker Hold.", progress = "Do you have any seeds for me?", completion = "That's a good start, but we're going to need more than that if we're to press a respectable amount of oil!" }
WordHunterWoW_QuestEN[9994] = { title = "What Are These Things?", description = "I don't know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!\n\n{name}, I think you should take this box of parts to Jenai Starwhisper at the Allerian Stronghold to the southeast.  She may have some idea of what these are.", objectives = "Deliver the Box of Parts to Jenai Starwhisper at the Allerian Stronghold in Terokkar Forest.", progress = "You look concerned.  What is it, <class>?", completion = "Oh no!  That's horrible news!  I can't believe that all but two of our Cenarion friends are dead.\n\nAlright, let me have a look at those parts.  I'm just hoping they aren't what I suspect that they might be.\n\nYes, as I feared, I believe these are bomb parts.  Our eyes and ears in Shattrath City have been feeding us information about some of the ethereals importing proscribed goods from other dimensions that they're in contact with." }
WordHunterWoW_QuestEN[9995] = { title = "What Are These Things?", description = "I don't know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!\n\n{name}, I think you should take this box of parts to Tooki at Stonebreaker Hold to the southeast.  He may have some idea of what these are.", objectives = "Deliver the Box of Parts to Tooki at Stonebreaker Hold in Terokkar Forest.", progress = "You look concerned.  What is it, <class>?", completion = "Oh no!  That's horrible news!  I can't believe that all but two of our Cenarion friends are dead.\n\nAlright, let me have a look at those parts.  I'm just hoping they aren't what I suspect that they might be." }
WordHunterWoW_QuestEN[9996] = { title = "Attack on Firewing Point", description = "We know that the blood elves of Firewing Point are working for Kael'thas and Illidan.  And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon.\n\nWhatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers.\n\nThe Firewing blood elves need to be taken out!  Head up to Firewing Point to the north and see to it.", objectives = "Kill 10 Firewing Defenders, 10 Firewing Bloodwarders, and 10 Firewing Warlocks. Then report back to Lieutenant Meridian at the Allerian Post in Terokkar Forest.", completion = "That's a good start, but based on what you witnessed there in the courtyard, as well as intelligence that I've received, we have a far more pressing matter at hand!" }
WordHunterWoW_QuestEN[9997] = { title = "Attack on Firewing Point", description = "We know that the blood elves of Firewing Point are working for Kael'thas and Illidan.  And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon.\n\nWhatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers.\n\nThe Firewing blood elves need to be taken out!  Head over to Firewing Point to the northeast and see to it.", objectives = "Kill 10 Firewing Defenders, 10 Firewing Bloodwarders, and 10 Firewing Warlocks. Then report back to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest.", completion = "That's a good start, but based on what you witnessed there in the courtyard, as well as intelligence that I've received, we have a far more pressing matter at hand!" }
WordHunterWoW_QuestEN[9998] = { title = "Unruly Neighbors", description = "The recent arrival of the fel orcs at the ruins to the east both puzzles and troubles Thander. They wasted no time in starting to construct fortifications and repair the buildings.\n\nThe construction goes on day and night, {name}. I've dispatched one of my most reliable agents to keep watch, but we can ill afford to delay action. Move against their workers, then seek out Theloria Shadecloak at the Allerian Post to the north of the Bonechewer Ruins. She'll give you further instructions.", objectives = "Kill 12 Warped Peons and then report to Theloria Shadecloak at the Allerian Post.", progress = "I take it Bertelm sent you to hamper the efforts of their peons?", completion = "<The high elf nods.>\n\nIt's a good start, but Bertelm was right to send you to me. I've made a discovery that may help explain the fel orc presence here." }
WordHunterWoW_QuestEN[9999] = { title = "Buying Time", description = "As long as the transporters stand, nothing we do to the forge camps will have any permanence. We must find a way to destroy the Legion structures.\n\nI need time to devise a plan of attack. If you can keep their engineers and tinkerers busy, it would greatly slow down their progress, buying me the time I need.", objectives = "Altruis the Sufferer in western Nagrand has asked that you kill 2 Felguard Legionnaires, 3 Mo'arg Engineers and 8 Gan'arg Tinkerers.", progress = "Back so soon?", completion = "It is as I suspected. There are no conventional means of destroying fel steel. All is not lost, however..." }
WordHunterWoW_QuestEN[10000] = { title = "An Unwelcome Presence", description = "Our forces at Thrallmar thought they had the fel orcs contained in the Hellfire Citadel area, but the recent arrivals at the ruins to the east say otherwise.\n\nWe can't permit them to gain a foothold here. Rokag has dispatched Shadowstalker Kaide to the ruins to keep an eye on them, but we have to do something to keep them from digging in.\n\nGo to the ruins, decimate their peons, and then look for Kaide in the trees to the north. He'll tell you where to go from there.", objectives = "Kill 12 Warped Peons and then report to Shadowstalker Kaide.", completion = "Stopping the fel orcs is going to take more than merely harassing their workers, I'm afraid. I've made a discovery that's shed some light on the reason for their presence here and it's reinforced my belief that we must act quickly." }
WordHunterWoW_QuestEN[10001] = { title = "The Master Planner", description = "All forge camps have a master planner. The master planner dictates what types of structures are present at a forge camp and how each structure is situated. Moreover, this information is kept on a set of blueprints that the planner carries around on their person.\n\nWe need the master planner's blueprints. Armed with such exacting information, we could persuade an acquaintance of mine to lend some assistance.\n\nFind the mo'arg master planner and take his blueprints. He will be stationed behind the forges.", objectives = "Altruis the Sufferer in western Nagrand has asked that you recover the Master Planner's Blueprints.", progress = "Avoid the overseers at all costs. They must not be let on to your presence. The results could be disastrous!", completion = "My acquaintance will hopefully know of a way to destroy the camps. He was a Legion engineer, after all..." }
WordHunterWoW_QuestEN[10002] = { title = "The Firewing Liaison", description = "Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.\n", objectives = "Locate and slay Lisaile Fireweaver, then return to Theloria Shadecloak.", completion = "<Theloria nods at you.>\n\nWell done. We have bought ourselves a little time. The blood elves will grow curious about what happened to their friend. Hopefully, by that time, we will have a better understanding of their intentions." }
WordHunterWoW_QuestEN[10003] = { title = "The Firewing Liaison", description = "Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.", objectives = "Locate and slay Lisaile Fireweaver, then return to Shadowstalker Kaide.", completion = "<Kaide nods at you.>\n\nWell done. We have bought ourselves a little time. The blood elves will grow curious about what happened to their friend. Hopefully, by that time, we will have a better understanding of their intentions.\n\nWhen the time is right, I will inform Rogak of our progress." }
WordHunterWoW_QuestEN[10004] = { title = "Patience and Understanding", description = "Take the blueprints and travel to Shattrath City in the Terokkar Forest. Once at Shattrath, go to the Lower City and look for a mo'arg by the name Sal'salabim. He'll probably be at the bar, drinking away his sorrows.\n\nBy the way, you may need to convince him to lend his assistance. Try to approach him with patience and understanding. If that does not work, use your fists.", objectives = "Altruis the Sufferer in western Nagrand wants you to take the Master Planner's Blueprints to Sal'salabim in Shattrath City and convince him to help you.", progress = "<Sal'salabim rubs his head.>\n\n[Demonic] Ik il romath sardon.", completion = "Calm down, bright eyes! Sal'salabim will help." }
WordHunterWoW_QuestEN[10005] = { title = "Letting Earthbinder Tavgren Know", description = "{name}, after you're done celebrating here, I think that you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want to know what really happened out there.", objectives = "Speak with Earthbinder Tavgren just outside the Cenarion Thicket in Terokkar Forest.", completion = "A bomb utilizing pure mana that can take out whole towns!  But why?  Why would the blood elves create such a thing and use it on us?  The Cenarion Thicket was a place of peace and repose.\n\nWhatever the reason, it must be locked inside the head of Warden Treelos, and I have no idea how to cure him.  Perhaps his mind will heal in time?\n\nRegardless, I want to thank you for helping me to figure out what happened.  I can only hope that this tragedy will never befall anyone else ever again!" }
WordHunterWoW_QuestEN[10006] = { title = "Letting Earthbinder Tavgren Know", description = "{name}, I think that after you're done celebrating here, you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want to know what really happened out there.", objectives = "Speak with Earthbinder Tavgren just outside the Cenarion Thicket in Terokkar Forest.", completion = "A bomb utilizing pure mana that can take out whole towns!  But why?  Why would the blood elves create such a thing and use it on us?  The Cenarion Thicket was a place of peace and repose.\n\nWhatever the reason, it must be locked inside the head of Warden Treelos, and I have no idea how to cure him.  Perhaps his mind will heal in time?\n\nRegardless, I want to thank you for helping me to figure out what happened.  I can only hope that this tragedy will never befall anyone else ever again!" }
WordHunterWoW_QuestEN[10007] = { title = "Thinning the Ranks", description = "Knowing Thander and Bertelm, they won't tolerate such a large buildup of hostile forces on our doorstep. Asking them to dispatch members of the garrison to participate in an attack on the camp isn't an option either. It would just leave us too vulnerable to attack.\n\nIt falls to us to do what we can to diminish the threat the fel orc buildup poses. Kill what you can of their forces and I will look for ways to stall any reinforcements.", objectives = "Kill 10 Bonechewer Devastators and 6 Bonechewer Backbreakers and return to Theloria Shadecloak.", completion = "Things are starting to look up. I think if we can prevent the fel orcs from reinforcing their fellows here, we can keep this post under control." }
WordHunterWoW_QuestEN[10008] = { title = "What Happens in Terokkar Stays in Terokkar", description = "If word reaches Thrallmar that they've failed to contain the fel orcs, we're going to be receiving a lot of company down here. Frankly, I'm not sure I want all that attention, so we're going to keep this little problem under wraps, got it?\n\nIf we can inflict enough casualties on the fel orcs, chances are their presence will never come to the attention of anyone outside Stonebreaker. So, let's end it now.\n\nWade in there, swing your weapon, wave your hands, or whatever it is you do - just kill fel orcs.", objectives = "Shadowstalker Kaide wants you to kill 10 Bonechewer Devastators and 6 Bonechewer Backbreakers.", completion = "I know you're well-traveled, but understand, <name>, that some stories are best left where they happened. Do we understand each other?" }
WordHunterWoW_QuestEN[10009] = { title = "Crackin' Some Skulls", description = "<Sal'salabim laughs.>\n\nThis Sal'salabim design.\n\n<Sal'salabim points to the architecture and formations on the blueprints.>\n\nLook at towers. Demon hunter no can see, yes? Poor, poor Altruis. He cry if he had eyes, yes?\n\nYes, Sal'salabim help but first you help Sal'salabim.\n\n<Sal'salabim gives you a ledger.>\n\nThese creatures owe Sal'salabim golds. Many golds. Go collect for Sal'salabim and come back. They no give you Sal'salabim gold easy. Have to fight, but you strong. You defeat Sal'salabim!", objectives = "Sal'salabim at Shattrath City wants you to recover Raliq's Debt, Coosh'coosh's Debt and Floon's Debt.", progress = "You no come back without Sal'salabim golds!", completion = "Now, deal is deal but when Sal'salabim tell you, you not be mad, yes?" }
WordHunterWoW_QuestEN[10010] = { title = "It's Just That Easy?", description = "<Sal'salabim points to the blueprint.>\n\nYou see where fel cannons are?\n\n<Sal'salabim draws an arrow denoting a change of direction.>\n\nYou turn fel cannon around and use on structures.\n\nWait! Don't be mad! One thing you not know. Overseers have key to turn cannons. You need key first! One from each overseer!\n\nNot so easy, eh?\n\nTake information back to Altruis.\n", objectives = "Sal'salabim at Shattrath City wants you to return to Altruis the Sufferer in western Nagrand.", completion = "Of course! We will use their own weapons against them!" }
WordHunterWoW_QuestEN[10011] = { title = "Forge Camp: Annihilated", description = "Gather your courage, {name}. You will need it if you are to face an overseer.\n\nOnce you are ready, find and kill the overseers at each camp. Take their keys and use them to turn and fire the fel cannons upon the camps. Return to me once the camps are destroyed.", objectives = "Altruis the Sufferer in western Nagrand has asked that you Destroy Forge Camp: Hate and Destroy Forge Camp: Fear.", progress = "Is it done?", completion = "We are victorious! The Legion's advances have been halted!\n\nI offer you a choice of rewards for your heroic deeds!" }
WordHunterWoW_QuestEN[10012] = { title = "Fel Orc Plans", description = "The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy would the two forces be working together? Bertelm might have some insight into this odd alliance. You decide to make your way back to the Allerian Stronghold and show him the map.", objectives = "Bring the Fel Orc Plans to Bertelm at the Allerian Stronghold in Terokkar Forest.", progress = "What is it you have there, <name>?", completion = "<Bertelm takes the plans from you and looks them over.>\n\nIf you hadn't brought this map, I'd say you were out of your mind, but here it is, plain as day. Not only are the fel orcs here to serve the blood elves, but it appears, they've been ordered to keep us occupied.\n\nThis map raises more questions than it answers, but it gives us a better idea of what we're facing here." }
WordHunterWoW_QuestEN[10013] = { title = "An Unseen Hand", description = "The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy would the two forces be working together? Rokag might have some insight into this odd alliance. You decide to make your way back to Stonebreaker Hold and show him the map.", objectives = "Bring the Fel Orc Plans to Rokag at Stonebreaker Hold in Terokkar Forest.", progress = "What is it you have there, <name>?", completion = "<Rokag takes the plans from you and looks them over.>\n\nSo Kaide was right! Those fel orc scum are up to something. I never would've guessed they were colluding with the blood elves, though.\n\nAccording to this map, the fel orcs are to keep us busy... but why? This is disturbing news, <name>. You were correct in bringing it to me right away." }
WordHunterWoW_QuestEN[10014] = { title = "The Firewing Point Project", description = "As I was saying, we've just received some further intel and there's a much larger problem at hand.\n\nThe blood elves are hard at work on the construction of a second bomb at Firewing Point.  I cannot stress strongly enough the implications of them completing and using such a device on the Allerian Stronghold!\n\nMy scouts tell me that they are guarding the codes to the device in the four smaller buildings ringing the central courtyard.  Get in there and retrieve those codes before it's too late!You will receive:", objectives = "Steal the four Mana Bomb Code Sheets and deliver them to Lieutenant Meridian at the Allerian Post in Terokkar Forest." }
WordHunterWoW_QuestEN[10015] = { title = "The Firewing Point Project", description = "As I was saying, we've just received some further intel and there's a much larger problem at hand.\n\nThe blood elves are hard at work on the construction of a second bomb at Firewing Point.  I cannot stress strongly enough the implications of them completing and using such a device on Stonebreaker Hold!\n\nMy scouts tell me that they are guarding the codes to the device in the four smaller buildings ringing the central courtyard.  Get in there and retrieve those codes before it's too late!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Steal the four Mana Bomb Code Sheets and deliver them to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest." }
WordHunterWoW_QuestEN[10016] = { title = "Timber Worg Tails", description = "Have you come across the timber worgs in your travels? I've had the opportunity to observe them while mapping some of the northern reaches of the forest. I wouldn't recommend getting close to them unless you're prepared for combat.\n\nThey have no fear of us and won't hesitate to defend their territory.\n\nIt's fitting that such a creature would have a magnificent tail. I've been trying to collect enough of them to trim a new cloak, but the worgs have a habit of evading my snares. Will you help?", objectives = "Bertelm at the Allerian Stronghold wants you to bring him 12 Timber Worg Tails. The tails can come from either Timber Worgs or Timber Worg Alphas.", progress = "I see you've managed to survive the rigors of the forest. Have you brought any tails for my cloak?", completion = "Ah, well done, friend. These are finer than I thought they'd be. They'll make a fine cloak.\n\n<Bertelm glances toward the inn.>\n\nYes, a fine cloak it shall be." }
WordHunterWoW_QuestEN[10017] = { title = "Strained Supplies", description = "More and more refugees come through the gates of Shattrath City each day.  Some have sustained such injuries, it's a real wonder they made it here.\n\nI can deal with most of the conventional injuries; my training as an Aldor healer has prepared me for that.  Poison wounds are more problematic as my anti-venom supplies have begun to run low.\n\nBring me venom sacs from the local dreadfang spiders so I can produce more antidotes.  You'll find a pocket of the spiders in the southeastern region of Terokkar.", objectives = "Bring 8 Dreadfang Venom Sacs to Sha'nir in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you obtained the venom sacs, <name>?  These refugees can't wait much longer.", completion = "You have my thanks, <name>.  The Aldor will hear of your actions." }
WordHunterWoW_QuestEN[10018] = { title = "Vestments of the Wolf Spirit", description = "Generations ago, when orc clans still called Terokkar Forest home, the wolf spirit played an important role in their lives. When the orcs departed, they had no longer had any need for the spirit and they left it behind.\n\nIn time, the spirit grew lonely and it too left the forest.\n\nI believe I can bring the wolf spirit back to his ancestral home, just as we orcs have returned. The ritual will require me to create vestments from the pelts of the wolves of the forest to guide the spirit back to its home.", objectives = "Bring 12 Timber Worg Pelts to Malukaz at Stonebreaker Hold.", progress = "Were you able to find all the pelts that I need?", completion = "These are perfect, <name>! I could not have asked for better." }
WordHunterWoW_QuestEN[10019] = { title = "More Venom Sacs", description = "", objectives = "Many refugees still need treatment for their poisonous wounds.  Have you brought more venom sacs for me to use, <name>?", progress = "Many refugees still need treatment for their poisonous wounds.  Have you brought more venom sacs for me to use, <name>?", completion = "You have my thanks, <name>.  The naaru have extended their protection to these unfortunate souls; it would be a shame if they made it to Shattrath and perished to previous wounds." }
WordHunterWoW_QuestEN[10020] = { title = "A Cure for Zahlia", description = "The woman to my right suffered a severe injury to the head.  She survived, but lost her eyesight.\n\nA traditional cure used among my people requires the blood of a very old basilisk.\n\nUnfortunately, due to poaching from various groups, Terokkar basilisks don't tend to live very long.\n\nThere is one basilisk whose name I've known since I was a youngling.  It is known only as \"Stonegazer\" and it's rumored to live east of here, near the land's edge.\n\nBring me its blood so that Zahlia may see once again.", objectives = "Bring Stonegazer's Blood to Sha'nir in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you obtained the blood, <name>?  Without it, Zahlia may never see her son again.", completion = "Thank you, <name>.  Caring for those in need is a difficult task, but in time I've discovered that it is its own reward." }
WordHunterWoW_QuestEN[10021] = { title = "Restoring the Light", description = "Much of this region was inhabited by draenei long ago.  We Aldor were charged with the safeguarding of our holy sites and altars.  Many of them have since been destroyed or taken over by our enemies.\n\nTo the east of here there is an arakkoa outpost.  It was purposefully built on the location of three of our sacred altars. The arakkoa use their foul magic to warp and defile the innate power of our shrines.\n\nTake this to the arakkoa outpost and use it to cleanse the three altars.", objectives = "Ishanah wants you to go to the Arakkoa outpost east of Shattrath City and use the Blessed Vial to cleanse the Eastern Altar, the Western Altar and the Northern Altar.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed your task, <name>?", completion = "You have my thanks, <name>.  We are keepers of the light and cannot forsake our responsibilities, even in the most difficult of times." }
WordHunterWoW_QuestEN[10022] = { title = "The Elusive Ironjaw", description = "Now that I have the fur I'll need for the trim, I've been thinking that the pelt of a particular wolf would make a good hood for my cloak. Imagine seeing your enemy clad in the pelt of the most cunning predator in the forest!\n\nI've tried trapping old Ironjaw without success. I've tried cornering him, outsmarting him, and baiting him. None of it has worked.\n\nHe stalks the northeastern reaches of the forest, and I'd gladly reward you if you could succeed where I have failed.", objectives = "Bring Ironjaw's Pelt to Bertelm at the Allerian Stronghold.", progress = "Has old Ironjaw gotten the better of you, too, friend? Or have you managed to outsmart the old fellow?", completion = "I bow to your skills, <name>. You have proven yourself the superior hunter.\n\nI won't forget your help in making this cloak. It will truly be a one-of-a-kind piece and I'll wear it proudly." }
WordHunterWoW_QuestEN[10023] = { title = "Patriarch Ironjaw", description = "You've done well in gathering the first pelts.\n\nThe final piece of the vestments requires a pelt unlike any other. There is one particular wolf, an old and cunning one, that has earned his place as the patriarch of the forest wolves. He is known among them as Ironjaw, the mighty hunter.\n\nIn my visions, I have seen him wandering the northeastern region of the forest. Including his pelt in the vestments will surely light the wolf spirit's path.\n\nDo not mourn Ironjaw. He will be well honored.", objectives = "Bring Ironjaw's Pelt to Malukaz at Stonebreaker Hold.", progress = "The spirit awaits, <name>. Have you the pelt of the wolf patriarch?", completion = "The pelt is even more magnificent than I had hoped! This is a good omen, <name>, and the spirits will favor you for your contribution to this ceremony.\n\nI have fashioned a helmet for you from the remaining pelts, <name>. It identifies you as a mighty hunter and an ally of the great wolf spirit of Terokkar Forest." }
WordHunterWoW_QuestEN[10024] = { title = "Voren'thal's Visions", description = "Our leader, Voren'thal the Seer, was once a close advisor to Kael'thas.  His prophetic visions warned him that Kael's path would lead to the destruction of our race.\n\nThe visions are usually vague and unfocused, but our alchemists have devised an elixir to help him focus his clairvoyance.  Unfortunately, this elixir calls for a rare ingredient: basilisk eyes.  My usual source, this pathetic ethereal, has failed me.\n\nSeek the dampscale basilisks in the rocky regions of Terokkar and bring me their eyes.", objectives = "Bring 8 Dampscale Basilisk Eyes to Arcanist Adyria in Shattrath City.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Have you obtained the basilisk eyes for Voren'thal's elixir?", completion = "These are all in excellent state, <name>.  Carry on and you will soon count the Scryers as your friends." }
WordHunterWoW_QuestEN[10025] = { title = "More Basilisk Eyes", description = "", objectives = "It takes many basilisk eyes to make even a small dose of Voren'thal's elixir.  Bringing me more would certainly incur the Scryers' favor.", progress = "It takes many basilisk eyes to make even a small dose of Voren'thal's elixir.  Bringing me more would certainly incur the Scryers' favor.", completion = "I thank you, <name>.  Voren'thal's visions might one day decide the fate of our race.  It would behoove us to do our best to ensure that those visions are as accurate as possible." }
WordHunterWoW_QuestEN[10026] = { title = "Magical Disturbances", description = "It's embarrassing to admit this, but something has happened to me here in Terokkar Forest that hasn't occurred since my apprentice days.\n\nOccasionally, my spells will fizzle when I know I've done everything correctly. I almost drove myself crazy the first time it happened.\n\nI think I've found the cause. The forest is full of creatures called warp stalkers, demonic creatures with an affinity for magic and a habit of disturbing magical flows. The best way to deal with them is simply to kill them.", objectives = "Andarl at the Allerian Stronghold wants you to kill 10 Warp Stalkers.", completion = "<Andarl dabs at his forehead with the sleeve of his robe.>\n\nThank goodness. I was beginning to wonder if the things had displaced the rest of the forest's creatures." }
WordHunterWoW_QuestEN[10027] = { title = "Magical Disturbances", description = "There's nothing more annoying than preparing to cast a spell, only to have it interrupted by some unseen force. After the fourth time, I knew it couldn't be coincidence and I sent Keb'ezil out to investigate.\n\nI guarantee you'll never encounter an imp that talks back more than Keb.\n\nAnyway, he managed to find the source of the problem, a pesky creature known as a warp stalker. They have a habit of disturbing the magical energy wherever they blink into existence. I've had enough of their interference.", objectives = "Kill 10 Warp Stalkers and return to Kurgatok at Stonebreaker Hold.", completion = "Keb'ezil is relieved that you've taken care of that little problem, aren't you, Keb?\n\n<The imp ignores its master, presumably out of indignation.>\n\nYou'll have to forgive his bad manners. You know how demons can be..." }
WordHunterWoW_QuestEN[10028] = { title = "Vessels of Power", description = "Amid the ruins of Tuurem are a number of vessels containing raw, magical energy. We are fortunate that the Broken who have overrun the city are ignorant to the resource in their midst, but we cannot assume they will remain so forever.\n\nWith those vessels and their power in hand, the scattered survivors of my people can resist the lure of demonic magic. Every quel'dorei we can save from our prince's folly is one more that can help us regain our lost glory. Bring me these vessels, {class}.", objectives = "Bring 8 Draenei Vessels to Ros'eleth at the Allerian Stronghold.", progress = "Were you able to find any intact vessels?", completion = "I hope these aren't the only intact vessels in the city. This is a good start, but I suspect we'll need many more than this." }
WordHunterWoW_QuestEN[10029] = { title = "The Spirits Are Calling", description = "The spirits of the dead in the Bone Wastes have been calling out to me and they are in pain!\n\n<class>, you must journey to the Bone Wastes to the south and find my assistant, Soolaveen with the Refugee Caravan.  He must be feeling it too, and will need your assistance to help put the spirits there to rest.\n\nIf you hurry, you may catch them.  I know that they were going to stop for a while in the northern portion of the Bone Wastes before continuing south to Auchindoun.Upon completion of this quest you will gain:", objectives = "Anchorite Lyteera wants you to locate her assistant, Soolaveen at the Refugee Caravan in the Bone Wastes of Terokkar Forest.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.\n\nProvided item:" }
WordHunterWoW_QuestEN[10030] = { title = "Recover the Bones", description = "The bones of the dead draenei litter the Bone Wastes from the explosion of Auchindoun.  Their spirits are restless, and cannot move on to the next life.\n\n{class}, you must help me to recover their bones and take them to their final resting place!  Only then will they be at peace; only then will they know comfort.\n\nGather up the restless bones with care and deliver them to Ramdor the Mad at Auchindoun in the center of the Bone Wastes.  Despite his name, he will know how to care for them.", objectives = "Collect 10 Restless Bones. Deliver them to Ramdor the Mad, just off the western side of the Ring of Observance in Auchindoun, which is in the middle of the Bone Wastes of Terokkar Forest.", progress = "What's this?  Who are you?", completion = "Great, just what I needed... more bones.\n\n<Ramdor sighs.>\n\nYes, yes, I will see to it that these remains of our honored ancestors are given a proper burial, have no fear.\n\nThere is something else that you can do if you're truly interested in aiding the dead." }
WordHunterWoW_QuestEN[10031] = { title = "Helping the Lost Find Their Way", description = "Many spirits of the draenei were corrupted by the explosion of Auchindoun.  Now they wander the wastes in torment.\n\n{name}, I beseech you to put them to rest.  Destroy the lost spirits and broken skeletons that haunt the Bone Wastes beyond Auchindoun's walls.\n\nWhat?  You think leaving them to wander in blind agony would be better?\n\nAfterward, return to Soolaveen at the Refugee Caravan and tell him of that which you have done.", objectives = "Destroy 10 Lost Spirits and 10 Broken Skeletons, and then speak with Soolaveen at the Refugee Caravan in the Bone Wastes of Terokkar Forest.", completion = "You have done that which needed doing and there is nothing to forgive.  Though it saddens me to hear that they were corrupted into a horrible undeath, through your actions you have put them to rest.\n\nThank you for setting them free, <name>.  You must accept a humble token of my regard for you and your selflessness." }
WordHunterWoW_QuestEN[10032] = { title = "Artifacts from Tuurem", description = "Have you ever noticed the behavior of the Lost Ones in Tuurem? They wander the ruins, searching for surviving scraps of anything made by the draenei.\n\nTheir Broken masters know better. They've left their former lives and identities behind and become something completely different.\n\nI believe we can use the Lost Ones' compulsion to our benefit and gather old draenei relics from them. Why risk life and limb battling the Broken, when we can profit from picking our targets wisely?", objectives = "Gather 6 Tuurem Artifacts from Tuurem Scavengers and Tuurem Hunters and bring them to Rakoria at Stonebreaker Hold." }
WordHunterWoW_QuestEN[10033] = { title = "WANTED: Bonelashers Dead!", description = "A bounty is declared on the bonelashers of the Bone Wastes.  As known carriers of the plague, they are to be destroyed forthwith!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReport to Taela Everstride afterward to collect your reward.", objectives = "Kill 20 Bonelashers and then report to Taela Everstride at the Allerian Stronghold in Terokkar Forest.", completion = "Yeah, I'm sure that you killed all of those bonelashers.  It's obvious since the captain asked for you to turn in proof on that wanted poster.\n\n<Taela gives you a sarcastic look.>\n\nI'll take your word for it.  I'm not certain who I angered to pull this duty, but thanks for your efforts on behalf of the Alliance.  Here's a little something for all of your trouble." }
WordHunterWoW_QuestEN[10034] = { title = "WANTED: Bonelashers Dead!", description = "The bonelashers of the Bone Wastes bit Mawg and made him sick.  Now he wants all of them destroyed!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReturn to Mawg Grimshot after you've done the deed and he'll give you a good reward.", objectives = "Kill 20 Bonelashers and then report to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest.", completion = "You must have killed a lot of those bonelashers!  Good, I hate them!  Ever since I was bit by one of them, I keep having fainting spells.\n\nDo you realize how embarrassing that is?  Here, take this as thanks for exacting some revenge for me." }
WordHunterWoW_QuestEN[10035] = { title = "Torgos!", description = "There's a creature in the Bone Wastes so fearsome that only the dauntless dare to stalk him.\n\nI speak of Torgos, king of the bonelashers, who circles over Veil Rhaze on the western edge of the wastes.\n\nToo bad that there's an arakkoan scarecrow there, known as Torgos's Bane, which keeps him at bay.  I'd bet if you laid his mate Trachela's carcass at the foot of that scarecrow he'd come down anyway.  She can be found at Carrion Hill in the northern wastes.\n\nBring me one of Torgos's tail feathers.", objectives = "Call down Torgos with Trachela's Carcass. Acquire a Tail Feather of Torgos and return it to Taela Everstride at the Allerian Stronghold in Terokkar Forest.", progress = "You have the feather?  Am I to reward you for your foolhardy bravery?", completion = "Color me impressed, <class>.  Torgos was one of the toughest creatures I know of this side of Nagrand.\n\nWell, I suppose that's good enough for something from the Allerian Stronghold treasury.  Take your pick." }
WordHunterWoW_QuestEN[10036] = { title = "Torgos!", description = "I want Torgos, king of the bonelashers, dead!\n\nNot long ago, while I was out hunting at Veil Rhaze on the western edge of the wastes, he fell upon me.\n\n<Mawg taps his eyepatch.>\n\nHe took my eye, and now I would have his life!  Bring me one of his tail feathers as proof and I'll give you a worthy reward.\n\nYou'll need his mate Trachela's carcass though to call him down as he's deathly afraid of the old arakkoan scarecrow known as Torgos's Bane.\n\nFind her at Carrion Hill in the northern wastes.", objectives = "Call down Torgos with Trachela's Carcass. Acquire a Tail Feather of Torgos and return it to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest.", progress = "Did you kill him?  Is Torgos dead?!\n\nYou have proof?", completion = "I thank you, <name>!  You have exacted my revenge, and as promised you will be rewarded!\n\nTake your pick of one of these and use it well!" }
WordHunterWoW_QuestEN[10037] = { title = "Rather Be Fishin'", description = "Speaking of lakes, there's a lake with real good fishin' up to the northeast. I used to go up there with my friends, but my mom won't let me go anymore.\n\nShe says it's too dangerous, but I haven't seen anything up there but a few little spiders. Like spiders can do anything to you...\n\nMy favorites were always the eels that live up there. If you're going to be up by the lake, would you think about bringing back some of the eels? They're feisty but once you subdue 'em, you can bring 'em back no problem.", objectives = "Bring 8 Pristine Shimmerscale Eels to Seth in Shattrath City.", progress = "<Seth tugs on your cloak.>\n\nDid you find the eels? Didja?", completion = "Thanks! I can't remember the last time I had eel!\n\nHow should I cook 'em?" }
WordHunterWoW_QuestEN[10038] = { title = "Speak with Private Weeks", description = "A report's just come in from one of our scouts near Grangol'var Village.  He says that a shadowy band has moved into the ruins there.\n\n{name}, I want you to speak with Private Weeks and see how you can assist him to figure out what this unknown group is up to.  Just head west past Stonebreaker Hold.  His last report puts his position near the north entrance to the village.", objectives = "Speak with Private Weeks near the north entrance to Grangol'var Village in Terokkar Forest.", completion = "It's about time someone came out here.  I sent that report to the Allerian Stronghold over a week ago!\n\nBureaucracy!" }
WordHunterWoW_QuestEN[10039] = { title = "Speak with Scout Neftis", description = "I am informed that one of our scouts near Grangol'var Village is currently observing a shadowy band that has recently moved in there.\n\n{name}, I want you to speak with Scout Neftis and see how you can assist her in figuring out what this unknown group is up to.\n\nJust head south out of here, and then due west, skirting the north of the Bone Wastes.  Her last report puts her position near the southern entrance to the village.", objectives = "Speak with Scout Neftis near the south entrance to Grangol'var Village in Terokkar Forest.", completion = "It's about time someone came out here.  I sent that report to Stonebreaker Hold over a week ago!\n\nBlood elves and their bureaucracy!" }
WordHunterWoW_QuestEN[10040] = { title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", objectives = "While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor. Then return to Private Weeks at Grangol'var Village in Terokkar Forest.", completion = "Good, you finally made it back!  Okay, what did you figure out?  Who are they?" }
WordHunterWoW_QuestEN[10041] = { title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", objectives = "While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor. Then return to Scout Neftis at Grangol'var Village in Terokkar Forest.", completion = "Good, you finally made it back!  Okay, what did you figure out?  Who are they?" }
WordHunterWoW_QuestEN[10042] = { title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Lieutenant Gravelhammer at the Allerian Stronghold.\n\nGood luck, {class}!", objectives = "Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Lieutenant Gravelhammer at the Allerian Stronghold in Terokkar Forest.", completion = "That's dire news indeed!  Well, it would seem I made the right choice in sending you out there to help Weeks.  The last thing that we want is the Shadow Council establishing themselves right on our doorstep!\n\n<name>, in recognition of your efforts at Grangol'var Village, I hereby grant you the right to your pick of any of these fine rewards." }
WordHunterWoW_QuestEN[10043] = { title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Advisor Faila at Stonebreaker Hold.\n\nGood luck, {class}!", objectives = "Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Advisor Faila at Stonebreaker Hold in Terokkar Forest.", completion = "That is unfortunate news!  But, of course, I made the right choice in sending you out there to help Neftis.  The last thing that we need is the Shadow Council establishing a strong point right on our doorstep!\n\n<name>, you've earned yourself something nice.  Go ahead, take your pick." }
WordHunterWoW_QuestEN[10044] = { title = "A Visit With the Greatmother", description = "The Greatmother has asked that I seek you out and deliver a message. She wishes to speak with you at once.\n\nMy will has been sapped but make no mistake, {name}, if you anger the Greatmother, I will come down upon you with all the force that I can muster. She is in the main hall.\n\n<Garrosh points at the large building to the north.>\n\nListen to what she has to say and do as she tells you.", objectives = "Speak to Greatmother Geyah and listen to what she has to tell you.", completion = "We must first expand your mind so that you may commune with the ancestors." }
WordHunterWoW_QuestEN[10045] = { title = "Material Components", description = "Mother Kashur wishes to speak with you, {name}. Before this becomes possible, you must collect the herbs required to create a potion that will expand your mind, allowing you to commune with the spirits.\n\nYou must gather Olemba root from Terokkar, marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the Blade's Edge mountains. I have written down instructions on this parchment as to the cultivation of these herbs. Return to me when you have gathered the materials.", objectives = "Greatmother Geyah at Garadar in Nagrand has asked that you collect 1 Olemba Root, 1 Marshberry, 1 Telaari Frond and 1 Dragonspine.", progress = "Hello, dear.", completion = "You are very resourceful, <name>. Our greatest gatherers would have taken twice as long to collect the herbs.\n\n\n\nDo not be afraid." }
WordHunterWoW_QuestEN[10046] = { title = "Through the Dark Portal", description = "Two weeks ago, our scouts reported a heavily armed Alliance force under the command of Field Commander Romus departing Nethergarde Keep. With so many soldiers and supplies, along with such a distinguished commander, they can only have one goal: Outland.\n\nThe warchief sent an advance force through the portal, but if the Alliance believes there is a need for that many troops, perhaps we'd be wise to send our own reinforcements.\n\nJourney through the Dark Portal and report to Nazgrel at Thrallmar.", objectives = "Travel through the Dark Portal and speak with Nazgrel at Thrallmar.Two weeks ago, our scouts reported a heavily armed Alliance force under the command of Field Commander Romus departing Nethergarde Keep. With so many soldiers and supplies, along with such a distinguished commander, they can only have one goal: Outland.\n\nThe warchief sent an advance force through the portal, but if the Alliance believes there is a need for that many troops, perhaps we'd be wise to send our own reinforcements.\n\nJourney through the Dark Portal and report to Nazgrel at Thrallmar.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10047] = { title = "The Path of Glory", description = "The 'Path of Glory,' they called it. A road leading from the heart of their gruesome fortress to the Dark Portal, paved with the bones of my people.\n\nIt wasn't enough for them to hunt us down like animals, destroy our cities, and torture those who survived. No, they had to use our bones as paving stones, denying my brethren a proper burial under the Light.\n\nThose tortured souls still wander these lands, crying out for release. I ask you, {name}, help me in this undertaking.", objectives = "Cleanse 8 Trampled Skeletons on the Path of Glory with Draenei Holy Water, then return to Warp-Scryer Kryv at Honor Hold.", progress = "The cries seem somehow... fainter than they were before. The Light grant it's more than wishful thinking.", completion = "You have my sincere thanks for your efforts, <name>. Though much remains to be done, it gladdens me to know we have helped some find their long-deserved rest." }
WordHunterWoW_QuestEN[10048] = { title = "A Handful of Magic Dust", description = "I'm going to need dust, but not just any dust.\n\nThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Deirom.\n\nI won't need much, perhaps half a dozen handfuls, or so.", objectives = "Collect 7 handfuls of Pacifying Dust for Andarl at the Allerian Stronghold." }
WordHunterWoW_QuestEN[10049] = { title = "A Handful of Magic Dust", description = "I'm going to need dust, but not just any dust.\n\nThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Dugar.\n\nI won't need much, perhaps half a dozen handfuls, or so.", objectives = "Collect 7 handfuls of Pacifying Dust for Kurgatok at Stonebreaker Hold." }
WordHunterWoW_QuestEN[10050] = { title = "Unyielding Souls", description = "Near the end of our invasion, the Armory to the south fell under attack by the Horde's insidious Death Knights. Those vile shades cursed the Armory's defenders - and trapped their souls between the realms of the living and the dead.\n\nThose noble souls must be set free! I beg you, {name}, end my comrades' torment, for I have not the heart to slay them myself.", objectives = "Honor Guard Wesilow wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south.", completion = "The Sons appreciate your efforts, even if few are willing to speak of the armory." }
WordHunterWoW_QuestEN[10051] = { title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of the Allerian Stronghold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!", objectives = "Escort Isla Starmane to safety and then report to Captain Auric Sunchaser at the Allerian Stronghold in Terokkar Forest.", completion = "Isla Starmane just left, but she gave me a full rundown on what's going on out at Firewing Point.  It's understandable that she's quite distraught over what happened to the Cenarion Thicket.  Nasty blood elves!\n\nShe told me how you were instrumental in saving her so that we could get that information.  Allerian Stronghold is indebted to you for your service.\n\nPlease, accept this gift on behalf of us all." }
WordHunterWoW_QuestEN[10052] = { title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of Stonebreaker Hold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!", objectives = "Escort Isla Starmane to safety and then report to Advisor Faila at Stonebreaker Hold in Terokkar Forest.", completion = "Isla Starmane just left, but she gave me a full rundown on what's going on out at Firewing Point.  It's understandable that she's quite distraught over what happened to the Cenarion Thicket.\n\nShe told me how you were instrumental in saving her so that we could get that information.  Stonebreaker Hold is indebted to you for your service.\n\nPlease, accept this gift on behalf of us all." }
WordHunterWoW_QuestEN[10053] = { title = "Dealing with Zeth'Gor", description = "It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, {name}. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.\n\nThe Bonechewers at Zeth'Gor to the southeast are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut beneath the fel orc settlement, and kill him. Once he is dead, search the cave for the fel orc battle plans. We must not be taken by surprise.", objectives = "Defeat Grillok \"Darkeye\" and search his lair for the Bleeding Hollow Attack Plans." }
WordHunterWoW_QuestEN[10054] = { title = "Impending Doom", description = "A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.\n\nThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Honor Hold in concert with forces from Hellfire Citadel.\n\nThere's no time to bring word to Lieutenant Amadi. You must stop the Bonechewer forces before they can launch their attack!", objectives = "Slay 15 Bleeding Hollow Grunts, 10 Bleeding Hollow Necrolytes, 5 Bleeding Hollow Peons, and Warlord Morkh, then make your report to Lieutenant Amadi at Honor Hold's western tower." }
WordHunterWoW_QuestEN[10055] = { title = "Waste Not, Want Not", description = "Reinforcements are great, but I don't see 'em haulin' any wagons loaded with ingots or timber.\n\nTake a look around, friend. Trees are in short supply, and the mines are overrun with Legion scum.\n\nI'm in a bad way fer supplies, and I'm makin' what substitutions I can, but it's time to start reusing what we can.\n\nThe southern edge of the Path o' Glory is strewn with the ruins of siege machinery. Some pieces of 'em are still usable. Feeling up to a bit o' a salvage operation?", objectives = "Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Dumphry at Honor Hold.", progress = "Were you able to find any usable materials out there underneath all the dust, ash, and char?", completion = "This is in better condition than I thought it'd be. Sure, it's going to take some time to work off all the rust, the char, and the like, but I'll not complain." }
WordHunterWoW_QuestEN[10056] = { title = "Bleeding Hollow Supplies", description = "The orcish ruins of Zeth'Gor to the southeast serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.\n\nThe Sons of Lothar have been fighting them for some time, and the stories they tell would be nigh unbelievable if I hadn't seen these 'fel' orcs with my own eyes.\n\nSomething has changed them, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Go to Zeth'Gor and destroy any supplies you find there.", objectives = "Destroy 6 piles of Bleeding Hollow Supplies and report to Lieutenant Amadi at Honor Hold." }
WordHunterWoW_QuestEN[10057] = { title = "Looking to the Leadership", description = "The disturbances at Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.\n\nPerhaps we've been approaching this the wrong way. I've always assumed that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.", objectives = "Overcome the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos and return to Honor Guard Wesilow in the tower northwest of Honor Hold.", completion = "We can only hope that with the quieting of the ghosts of the officers, the spirits of the foot soldiers will follow. Thank you once again for your help, <name>." }
WordHunterWoW_QuestEN[10058] = { title = "An Old Gift", description = "<The priest's gaze slowly moves from his mug to you.>\n\nDon't you know better than to bother a man in his cups?\n\nOh, what's the use? I suppose newcomers are a good sign. What would Turalyon think?\n\nI remember the eve of our departure, when I gave Mysteries of the Light to him. During the campaign and the ensuing years, he never forgot to read his daily passage to the men.\n\nWhen he left us again, he gave the book back to me. Like a fool, I believed it safe in my quarters to the south of the armory.", objectives = "Retrieve Mysteries of the Light and return it to Father Malgor Devidicus at Honor Hold.", progress = "I thought I asked you not to bother me. What is it?", completion = "Is that really it? It's hard to believe it survived the battle. Conditions in the ruins haven't been kind to the book, but still, I'm glad to have it.\n\nIt's the only token I have of Turalyon.\n\n<Father Devidicus seems to be fighting back tears.>\n\nWhen you fight beside someone for so many years, they become closer than even family." }
WordHunterWoW_QuestEN[10059] = { title = "Dealing With Zeth'Gor", description = "It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, {name}. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.\n\nThe Bonechewers at Zeth'Gor are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut into the rock beneath the outpost, and kill him. Once he is dead, search the cave for the fel orc battle plans. Thrallmar must not be taken by surprise.", objectives = "Slay Grillok \"Darkeye\" and search his lair for the Bleeding Hollow Attack Plans." }
WordHunterWoW_QuestEN[10060] = { title = "Impending Doom", description = "A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.\n\nThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Thrallmar in concert with forces from Hellfire Citadel.\n\nThere's no time to bring word back to Thrallmar. You must stop the Bonechewer forces before they can launch their attack!", objectives = "Slay 15 Bleeding Hollow Grunts, 10 Bleeding Hollow Necrolytes, 5 Bleeding Hollow Peons, and Warlord Morkh. Then report to Stone Guard Ambelan at Spinebreaker Ridge." }
WordHunterWoW_QuestEN[10061] = { title = "The Unyielding", description = "When the Bonechewer fel orcs attacked the Expedition Armory, the garrison there fell quickly.  The battle was bloody and fierce, and there were no survivors.\n\nAlthough the dead were buried, their spirits continue to haunt those ruins.  Of late, I have been receiving visions that these spirits may soon become a threat to Thrallmar.\n\nThere is only one course of action to take.  We must grant these spirits rest.  You must overcome them in battle.", objectives = "Grelag wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south of Honor Hold." }
WordHunterWoW_QuestEN[10062] = { title = "Looking to the Leadership", description = "The disturbances at the Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.\n\nWe may be approaching this the wrong way. My visions suggested that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.", objectives = "Overcome the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos and return to Grelag at Spinebreaker Ridge." }
WordHunterWoW_QuestEN[10063] = { title = "Explorers' League, Is That Something for Gnomes?", description = "Babysitting! Would you believe it?\n\nThey pulled me out of a promising dig and sent me along with Captain Odesyus' expedition to babysit that little gnome!\n\nI'd never heard o' a gnome wanting to become a prospector before, so I asked.\n\nSeems we are takin' gnomes now, and this particular one has a fascination with murlocs!\n\nWell, he's gone off and set up shop in an old turtle shell on the northern shore of the island. Go and have a look if you don't believe me!", objectives = "Find Clopper Wizbang camped in an old turtle shell on the shore north of Blood Watch.", completion = "I thought so! That grumpy old dwarf was supposed to help me carry my equipment and gather data, but all he does is sit in that strange draenei town, drinking himself into a stupor." }
WordHunterWoW_QuestEN[10064] = { title = "Talk to the Hand", description = "The Hand of Argus has established a forward base at Vindicator's Rest, but they are sorely outnumbered by both the blood elves and mutated wildlife. Without backup, their outpost is in danger of falling, and we'd have no way to keep an eye on events near the Vector Coil.\n\nReport to Scout Jorli at Vindicator's Rest to the northwest and offer her your assistance, {name}.", objectives = "Report to Scout Jorli at Vindicator's Rest.", completion = "I was hoping Blood Watch would send reinforcements once they learned what we're up against." }
WordHunterWoW_QuestEN[10065] = { title = "Cutting a Path", description = "During our mission to reconnoiter the Sunhawks and their portal, I sustained a serious wound. Scout Loryi has managed to staunch the bleeding and she's trying to figure out a way to evacuate me to Blood Watch.\n\nThe problem is that we'd have to abandon our position here in order to guarantee a safe return.\n\nAs soon as we leave this consecrated ground, we'll be set upon by ravagers. If you can clear some of the enraged ravagers, it might allow us to make the trip back safely.", objectives = "Kill 10 Enraged Ravagers and return to Scout Jorli at Vindicator's Rest.", completion = "It looks a bit better out there, but I still wonder if I wouldn't be better off waiting for a medic here." }
WordHunterWoW_QuestEN[10066] = { title = "Oh, the Tangled Webs They Weave", description = "We don't dare abandon our post, or wander too far from Vindicator's Rest, {race}. The mutated creatures closest to the Vector Coil have been changed profoundly by energy leaking from the crystals.\n\nThe mutated tanglers appear to have gained a certain degree of sentience. They've learned to create, set, and conceal vicious traps that can ensnare even the most careful warrior.\n\nWe'll never be able to move against the Sunhawks if we're constantly forced to look underfoot. Attack the problem at its source, {name}.", objectives = "Kill 8 Mutated Tanglers and report to Vindicator Corin at Vindicator's Rest.", completion = "Well done, <name>. It's going to be much easier to get reinforcements from Blood Watch, or launch strikes against the Sunhawks without having to worry about what the tanglers are up to." }
WordHunterWoW_QuestEN[10067] = { title = "Fouled Water Spirits", description = "Most of the creatures touched by the crystals' energy have been corrupted in the same ways: strange marks on their flesh, increased aggression, and small crystal shards in their bodies. However, the fouled water spirits north of here appear to be turning entirely to crystal.\n\nI've never seen anything react to the crystals this way before, when we explored the foul pool, they were particularly dangerous. We must get rid of them before the Sunhawks can exploit them as a new source of energy.", objectives = "Kill 6 Fouled Water Spirits and return to Vindicator Corin at Vindicator's Rest.", completion = "Well done, <name>. It's important not to overlook any opportunity to deny the Sunhawks sustenance." }
WordHunterWoW_QuestEN[10068] = { title = "Frost Nova", description = "As you begin to grow in power, your connection to the arcane will develop, granting you access to new spells.\n\nGo, develop your power, and then demonstrate what you learn for me.", objectives = "Reach level 3 to learn Frost Nova. Locate a Training Dummy outside the Sunspire and practice using it 2 times.", completion = "Ah good, a <class>. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to." }
WordHunterWoW_QuestEN[10069] = { title = "Ways of the Light", description = "It is time for your first lesson in the ways of the Light, <name>. As you fight more battles, it will bring you closer to the light, and you'll start to uncover new abilities.\n\nGo, get more experience, and learn a new ability. Return and demonstrate it for me, and we'll continue your training.", objectives = "Reach level 3 to learn Seal of Command. Cast Seal of Command on yourself, then locate a Training Dummy outside the Sunspire and hit it.", completion = "Ah good, a <class>. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to." }
WordHunterWoW_QuestEN[10070] = { title = "Steady Shot", description = "And now, it is time for your first lesson.\n\nAs you become more skilled, you will begin to discover new techniques.\n\nGo out, get some more experience, and learn your first new ability. Once you do, go find a training dummy and practice your new skill.", objectives = "Reach level 3 to learn Steady Shot. Locate a Training Dummy outside the Sunspire and practice using Steady Shot 5 times.", completion = "Ah good, a <class>. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to." }
WordHunterWoW_QuestEN[10071] = { title = "Evisceration", description = "As you grow in power, you'll start to figure out the tricks of the trade.\n\nOne of the first things you'll probably figure out is how to Eviscerate your enemy after landing some initial attacks.\n\nGet some experience, learn how to do it, and then find one of the training dummies outside and give it a try.", objectives = "Reach level 3 to learn Eviscerate, then locate a Training Dummy outside the Sunspire and practice using Eviscerate 3 times.", completion = "Ah good, a <class>. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to." }
WordHunterWoW_QuestEN[10072] = { title = "Learning the Word", description = "As you grow in skill, so will the array of powers that you can call upon.\n\nI'd like you to go, continue to become more experienced, and discover a new spell. Once you do, come back and demonstrate it for me.", objectives = "Reach level 3 to learn Shadow Word: Pain. Practice casting it 5 times on nearby training dummies.", completion = "Ah good, a <class>. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to." }
WordHunterWoW_QuestEN[10073] = { title = "Corruption", description = "By now, you've heard the rumors about our kind, the warlocks. Pay them no mind; they are uttered by those jealous of our fearsome powers.\n\nAs you become more experienced, you will uncover mysteries of controlling fel energies. \n\nGo, continue your journey until you uncover a new technique. I want you to practice using this new spell on the training dummies outside the Sunspire.", objectives = "Reach level 3 to learn Corruption. Locate a Training Dummy outside the Sunspire and practice casting Corruption 5 times.", completion = "Ah good, a <class>. I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to." }
WordHunterWoW_QuestEN[10074] = { title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", objectives = "Chief Researcher Amereldine at Halaa wants 10 Oshu'gun Crystal Powder Samples.", progress = "The crystalline powder from the mountain is infused within the earthen core of this region.", completion = "Wonderful, <name>. This will help us in our battle against the Alliance filth that have surfaced in the Outland." }
WordHunterWoW_QuestEN[10075] = { title = "Oshu'gun Crystal Powder", description = "", objectives = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", progress = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", completion = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster." }
WordHunterWoW_QuestEN[10076] = { title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", objectives = "Chief Researcher Kartos at Halaa wants 10 Oshu'gun Crystal Powder Samples.", progress = "The crystalline powder from the mountain is infused within the earthen core of this region.", completion = "Wonderful, <name>. This will help us in our battle against the Horde filth that have surfaced in the Outland." }
WordHunterWoW_QuestEN[10077] = { title = "Oshu'gun Crystal Powder", description = "", objectives = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", progress = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", completion = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster." }
WordHunterWoW_QuestEN[10078] = { title = "Laying Waste to the Unwanted", description = "Now that we've gotten our salvage operation off the ground, it's time to begin the second phase of the plan.\n\nAcross the Path of Glory, the Horde still has their old blade throwers trained on us. Don't let their age fool you, {name}, they're still very dangerous. Much as we're working to reclaim what we can, we can't assume the Horde is going to dismantle their weaponry.\n\nTake this torch and burn the remaining siege equipment. I'll take no chances with Honor Hold's safety.", objectives = "Use the Flaming Torch to burn the Horde Blade Throwers overlooking the Path of Glory. Then, bring the Flaming Torch to Dumphry in Honor Hold.", completion = "That's the spirit!\n\nI'm glad we finally got some reinforcements, but I'm not so sure about their attitude toward the Horde. Where I come from, anyone with a weapon pointed at you is an enemy and needs to be dealt with like one!" }
WordHunterWoW_QuestEN[10079] = { title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits!\n\nNot only did they run all my workers out of the tunnels, but they're pounding away in there night and day! To make things worse, now I've got Danath on me back! He says he's going to take away me ale ration if I don't get this taken care of soon!\n\nNone of the miners'll go in there, and the guards are busy drinking themselves silly.\n\nI'm begging you, {name}, help me here. Danath can take me dignity, but he'll never take me ale!", objectives = "Kill 12 Gan'arg Sappers and return to Foreman Biggums.", completion = "By Bronzebeard's bronze... beard, you've done it! You're a hero, <name>." }
WordHunterWoW_QuestEN[10080] = { title = "Forge Camps of the Legion", description = "If you've spoken to Humphry, he's undoubtedly told you that he finds the infestation in the mines a minor annoyance, but I know it for what it is: a symptom of a larger evil.\n\nTo the northeast of the Horde outpost of Thrallmar, the Legion's minions labor night and day on something, but what is it?\n\nNone of the scouts I've dispatched to the camps have ever returned. The time for subtlety has passed, <name>. Fight your way into Forge Camp: Rage and find out just what the Legion is up to.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 10 Gan'arg Servants, 5 Forge Camp Legionnaires, and 5 Sisters of Grief, then search Forge Camp: Rage for evidence of the Legion's intentions." }
WordHunterWoW_QuestEN[10081] = { title = "To Meet Mother Kashur", description = "Do not be alarmed by what you might see once the effect has taken hold! These spirits are all around us - always. The potion allows your mind to be able to understand and ultimately see the spirits. You will need to be under its influence if you are to speak with Mother Kashur.\n\nYou will find her a great ways to the southwest, at the Ancestral Grounds.\n", objectives = "Greatmother Geyah wants you to speak with Mother Kashur.", completion = "The potion that you drank has no real effect. You can only see a spirit if they allow it. The potion is merely a symbol of your belief and dedication. It was a test and you passed..." }
WordHunterWoW_QuestEN[10082] = { title = "The Agitated Ancestors", description = "Do you see them walking around us? The Ancestral Grounds are normally quiet and undisturbed.\n\nAs of late, the ancestral spirits have risen and are extremely agitated. Something is causing a great disturbance to the spirits. We must discover what that something could be, but first, we must put the immediate threat to rest.\n\nThese ghosts that you see walking about are not truly the ancestors but a representation of their state of being. You must destroy the agitated orc spirits. Do this and return to me.", objectives = "Mother Kashur has asked that you put to rest 8 Agitated Orc Spirits.", completion = "It's no use. They continue to rise. There must be something more insidious underway." }
WordHunterWoW_QuestEN[10083] = { title = "The Legion's Plans", description = "You make a copy of the glowing glyphs etched into the ground, but without the second half, the diagram doesn't make sense.\n\nField Marshall Rohamus mentioned another camp to the west, Forge Camp: Spite. Could that be where the Legion is keeping the other half of the plans?\n\nIf the Legion has undertaken a massive production campaign, assembling at multiple sites would make sense.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve the Forge Camp: Spite Plans and return them to Field Marshal Rohamus at Expedition Point." }
WordHunterWoW_QuestEN[10084] = { title = "Assault on Mageddon", description = "With the skills of the mo'arg engineers and an endless supply of their gan'arg minions, they'll begin churning out fel reavers before we can get word to Nethergarde.\n\nWe have no choice but to move against them as soon as possible. We cannot strip Honor Hold's defenses to support you in this offensive, for to do so would be suicide. The fel orcs and the Horde will pounce on us at the first sign of weakness.\n\nHonor Hold has stood for 20 years, and we don't intend to lose it now.You will be able to choose one of these rewards:", objectives = "Kill Nightlord Malphas at Forge Base: Mageddon, and report to Force Commander Danath Trollbane at Honor Hold." }
WordHunterWoW_QuestEN[10085] = { title = "A Visit With The Ancestors", description = "I need for you to journey to the villages of the ancestors, {name}. Seek each one out and see if the ancestors remain.\n\nVisit Sunspring Post to the north, visit the Laughing Skull Ruins far to the north against the mountains, visit Garadar to the northeast, and finally, visit the Bleeding Hollow Ruins on the borders of Nagrand and the Terokkar Forest, to the east.\n\nReturn to me once you have observed the ancestors in their homes.", objectives = "Mother Kashur at the Ancestral Grounds in Nagrand has asked that you Visit Sunspring Post, Visit Laughing Skull Ruins, Visit Garadar and Visit Bleeding Hollow Ruins.", progress = "Move as the wind, <name>.", completion = "This is very troubling. You say that none of the ancestors were at their villages? That they were all moving south?" }
WordHunterWoW_QuestEN[10086] = { title = "I Work... For the Horde!", description = "Would you believe it?  These orcs hired me to help them shore up damaged fortifications and build explosives.  What a dream job!  It's too bad we're so short on materials, but a clever goblin like myself learns how to make do!\n\nCan you help me?  I need salvaged wood and metal from the ruined battlements along the Path of Glory.  Go down there and salvage, and watch out for those red-skinned orcs!\n\nWhen you're done, come back for big rewards!", objectives = "Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Megzeg Nukklebust in Thrallmar.", progress = "So how did the salvage mission go?  Did you find anything useful?", completion = "This stuff is great!  A little bent and a little burnt, but I've never let low grade materials stop me from making precision high explosives.\n\nThanks, <name>.  You really have an eye for quality trash!" }
WordHunterWoW_QuestEN[10087] = { title = "Burn It Up... For the Horde!", description = "I'm a lucky, lucky goblin.  I get to make explosives and killing machines, knowing they'll be used immediately on important missions!\n\nSpeaking of missions, I just got one from Thrallmar command: burn the Alliance cannons on the far side of the Path of Glory... the ones pointing dangerously close to Horde fortifications.  Take this torch and make your way to each cannon.  Fire the torch and watch the sparks fly!", objectives = "Use the Flaming Torch to burn the Eastern Alliance Cannon and the Western Alliance Cannon, and then return to Megzeg Nukklebust in Thrallmar.", progress = "I've been looking for the telltale signs of burning cannons -- smoke plumes, or the cries of burning fel orcs...\n\nAny luck on your mission?", completion = "I thought so!  I couldn't quite make out the destruction from here, but I can imagine how it must have looked.  Splendid!\n\nWell done, <name>.  Thrallmar command will be happy to hear of your success!" }
WordHunterWoW_QuestEN[10088] = { title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits, and on top of that, the peons have decided that this is a fine time for a nap! I don't know how they can sleep through all the disturbances coming from the mine, but that's the least of my problems.\n\nIf we don't get rid of those gan'arg pests soon, Thrallmar's supply of ore and other minerals will be cut off. I've already asked Watch Commander Krunk for help, but he says he can't spare the men with the town under constant attack. Will you help?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 12 Gan'arg Sappers and return to Foreman Razelcraz." }
WordHunterWoW_QuestEN[10089] = { title = "Forge Camps of the Legion", description = "Thrallmar has been subjected to bombardment from the Legion Camps since its establishment. We've managed to hold out so far, but the situation is getting more desperate with every day.\n\nShadow Hunter Ty'jin has made several attempts to learn more about the camps, but none of his scouts ever returned.\n\nThe time for subtlety has passed, <name>. Fight your way into Forge Camp: Rage and find out just what the Legion is up to.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 10 Gan'arg Servants, 5 Forge Camp Legionnaires, and 5 Sisters of Grief, then search Forge Camp: Rage for evidence of the Legion's intentions." }
WordHunterWoW_QuestEN[10090] = { title = "The Legion's Plans", description = "You make a copy of the glowing glyphs etched into the ground, but without the second half, the diagram doesn't make sense.\n\nThe glyphs indicate that another camp to the west, Forge Camp: Spite, is also involved in the project. Could that be where the Legion is keeping the other half of the plans?\n\nIf the Legion was forging something truly monstrous, assembling it at multiple sites would make sense.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve the Forge Camp: Spite Plans and return them to Overlord Hun Maimfist at Reaver's Fall." }
WordHunterWoW_QuestEN[10091] = { title = "The Soul Devices", description = "Gah!  They've been torturing me, trying to get me to tell them everything that I know.\n\nI failed - they fed the others to Hellmaw, and I was to be next.  But I told them nothing!\n\nThey're crazy!  They're hell-bent on summoning demonic forces that they have no way of controlling!\n\nThey're using special devices to make their soul shards, and their summoning, more powerful.  You must steal these devices!\n\nI would join you, but I must return to Shattrath City to report to the Lower City's spymistress.", objectives = "Steal 5 Soul Devices and deliver them to Spymistress Mehlisah Highcrown at the Terrace of the Light in Shattrath City.", progress = "Yes?  What can I do for you, <class>?", completion = "To'gun was here earlier giving me his report.  He should have stayed with you to help!\n\nI sent him back out there to assist Grik'tha.  I think they make a cute couple.\n\nSo, these are the soul devices that the Shadow Council were using to enhance their summoning power?  They look dangerous to me - maybe the Scryers will know what to do with them?\n\nPlease, take one of these as a reward for crippling the Shadow Council's operation in the labyrinth." }
WordHunterWoW_QuestEN[10092] = { title = "Assault on Mageddon", description = "With the skills of the mo'arg engineers and an endless supply of their gan'arg minions, they'll have churned out a fleet of fel reavers before we can get word to Orgrimmar.\n\nWe have no choice but to move against them as soon as possible. I cannot use Thrallmar's garrison to support you, since it would leave us too vulnerable.\n\nThere are any number of opportunists, the Alliance notwithstanding, who would eagerly pounce on our unprotected outpost. Do not fail, <name>. Too much depends on you.You will be able to choose one of these rewards:", objectives = "Kill Nightlord Malphas at Forge Base: Mageddon, and return to Overlord Hun Maimfist at Reaver's Fall." }
WordHunterWoW_QuestEN[10093] = { title = "The Temple of Telhamat", description = "Fortunately, the Path of Glory is not the only trace of my people in these lands. To the west, a few of our holy sites survive, although some have been overrun.\n\nWhile Velen prepared for the journey that would lead him to Azeroth, those of us who would remain behind sought to reestablish a presence at our holy places.\n\nIn the western part of the Hellfire Peninsula, you will find a small group of draenei at the Temple of Telhamat, led by Amaan the Wise. I am certain he'd be interested in meeting you.", objectives = "Speak with Amaan the Wise at the Temple of Telhamat in western Hellfire Peninsula.", completion = "Ah, so you've met Seer Kryv. He is a wise and gifted man and any <race> he would name a friend is also a friend of mine.\n\nMake yourself comfortable and introduce yourself to the others who call the temple home." }
WordHunterWoW_QuestEN[10094] = { title = "The Codex of Blood", description = "It has been two years since the Shadow Council summoning that resulted in the explosion of this once-great mausoleum, and the formation of the Bone Wastes.\n\nNow they are at war with an unbelievably powerful force on the inside.\n\n<name>, you must make your way into the Shadow Labyrinth to determine what they are up against, and to see if it poses a threat to us.  Our spies speak of their use of a forbidden book of unholy summoning, known only as the Codex of Blood.\n\nSeek your answers within its pages.", objectives = "Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun.", completion = "Opening the magically-suspended tome, a sense of dread overwhelms you.\n\nSomething is most definitely wrong here!\n\nYou read on, but what you read seems unbelievable!" }
WordHunterWoW_QuestEN[10095] = { title = "Into the Heart of the Labyrinth", description = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago!  It is what caused the explosion of Auchindoun, and the creation of the Bone Wastes beyond.\n\nKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!\n\nWith the grandmaster, and the rest of their leadership dead, you are Outland's last hope against this monstrosity!\n\n<name>, you know at the core of your being that you and your companions dare not fail!", objectives = "Destroy Murmur and inform Spymistress Mehlisah Highcrown at the Terrace of Light in Shattrath City of the events that have transpired inside the Shadow Labyrinth.", completion = "Murmur almost broke free?!  They've had that thing contained in there for two years... I wonder what they did wrong to lose control over it after all this time?\n\n<name>, by putting that beast down you've likely saved all of us!  I cringe to think what would have happened to all of us here, and the rest of Outland, if that thing had somehow managed to break free!\n\nI'm glad you helped us to take matters into our own hands and deal with the Shadow Council threat at Auchindoun.  How can we ever reward you?" }
WordHunterWoW_QuestEN[10096] = { title = "Saving the Sporeloks", description = "Ikeyen's been telling me stories about what happened to him down in those caves and I think it's just awful!\n\nYou know, maybe we should do something to help out those poor sporeloks.  Ikeyen says that they live there in the Funggor Cavern, but that the marsh beasts have recently invaded.\n\nWhy don't you go down there and see if you can clear some of those marsh beasts out?  It's just to the southwest.", objectives = "Slay 10 Marsh Dredgers and 10 Marsh Lurkers, and then return to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.", completion = "Good!  Those marsh beasts have no right to invade the home of the sporeloks!\n\nIt would be better if these creatures would learn to live in harmony, but when that's not possible, we'll be here to take care of the situation!\n\nHere, please take one of these as thanks for your help." }
WordHunterWoW_QuestEN[10097] = { title = "Brother Against Brother", description = "The Sethekk departed Skettis with great fanfare when Auchindoun exploded. Surely it must've been an omen of our master's arrival.\n\nMy brother, Syth, was one of their leaders and told us we were obligated to go into the temple ruins and face our god.\n\nAfter we took up residence in the ruins, calling them the Sethekk Halls, I began to doubt my brother and his ally, Ikiss.\n\nIn time, Syth had me cast out of the Halls, but he refused to let me take our sister Lakka with me. Will you help me rescue her?", objectives = "Kill Darkweaver Syth in the Sethekk halls, then free Lakka from captivity. Return to Isfar outside the Sethekk halls when you've completed the rescue.", completion = "I can't thank you enough, <name>. Knowing that Lakka is free means I can cut the rest of my ties to the Sethekk.\n\nPart of me will never forgive myself for Syth's death, but it had to be done. When I reach Skettis, I will perform the death rites for him. Perhaps his spirit will find rest once it has atoned for leading our people astray." }
WordHunterWoW_QuestEN[10098] = { title = "Terokk's Legacy", description = "My people honor an ancient hero named Terokk. Arakkoa hatchlings are regaled with stories of his deeds and descriptions of his beautiful plumage.\n\nHe dwelt among my people for hundreds of years, but mysteriously vanished one day, leaving only his mask, spear, and writings behind.\n\nThe relics are cherished by the arakkoa, but they were heartbroken when the Sethekk bore the objects away from Skettis at their departure.\n\nI have written down what little I know about their location within the halls.", objectives = "Bring Terokk's Mask, Terokk's Quill, and the Saga of Terokk to Isfar outside the Sethekk Halls.", progress = "The relics of Terokk have been absent from Skettis for too long. Were you able to recover them from the Sethekk?", completion = "I may never truly be forgiven for my role in the crimes of the Sethekk, but perhaps by restoring the relics of Terokk to my people, I can begin to redeem myself.\n\nThank you for helping me in this, <name>. You have no idea of the magnitude of what you've done this day." }
WordHunterWoW_QuestEN[10099] = { title = "The Mastermind", description = "Those infernal gan'arg keep scurrying into the mine! For each one you kill, two or three more seem to take its place!\n\nThere's got to be someone down there in the deepest reaches of the mine directing the incursion. You seemed to do well against them last time, and Light knows you're the only one brave enough to venture back into the mine. Find out who's responsible for this disturbance and make him pay!", objectives = "Locate and kill Z'kral in the mines beneath Honor Hold, then report back to Foreman Biggums.", progress = "I'm almost afraid to ask. Seeing you come out of the mine alive means one of two things: either you killed the monster, or you lost your nerve. Well, which is it?", completion = "I'm glad you managed to take care of, of... what did you say he called himself? Z'kral?\n\nFrom your description, it sounds more like an 'it' than a 'him' but all that matters is it's dead." }
WordHunterWoW_QuestEN[10100] = { title = "The Mastermind", description = "Don't get me wrong, <name>, I'm glad that you agreed to help with the mines, but for every sapper you killed, I swear two more appeared.\n\nI've been giving Watch Commander Krunk an earful, but he's still refusing to send me any help. He keeps muttering something under his breath about helboars. If I wasn't so sure he'd hit me, I'd tell him this is no time to be thinking about ribs!\n\nAnyway, it looks like there's someone down there deep in the mines directing this whole thing. Find him and kill him!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Locate and kill Urga'zz within the mines beneath Thrallmar, then return to Foreman Razelcraz." }
WordHunterWoW_QuestEN[10101] = { title = "When Spirits Speak", description = "Oshu'gun - the diamond mountain - was once sacred to my people. It was there that the clans would gather every year to celebrate the springtime festival. It was there that our shaman communed with the honored ancestors. It was the center of our culture - until the shadows overtook us. When the clans became a horde, the spirits of Oshu'gun fell silent. The ancestors turned their backs on us.\n\nYet something now draws them from their rest. Venture to Oshu'gun and discover what could trouble the spirits so.", objectives = "Mother Kashur at the Ancestral Grounds in Nagrand has asked that you seek out the vision you had. Find K'ure in Oshu'gun.", completion = "<A gentle, melodic voice fills your mind.>\n\nI am K'ure of the naaru, <name>. You stand within the heart of my ancient vessel. \n\nOshu'gun, as the orcs named it, is the ship that first brought the draenei to this world.  Though we fell from the heavens and crashed here many hundreds of years ago, my weakened energies have remained trapped within this wreckage. Regrettably, I am the source of the orc spirits' pain." }
WordHunterWoW_QuestEN[10102] = { title = "A Secret Revealed", description = "As my energies bled away over the centuries, a void slowly grew in my place - devouring the souls of those nearby. Helplessly, I watched as generations of orc souls were drawn into the vortex. Recently, my enemies harnessed the vortex and used it to draw countless void minions into their Burning Legion.\n\nNow, the key to ending this cycle and freeing the orc spirits lies with another naaru - A'dal. I have sensed his essence within the ancient city of Shattrath in the Terokkar Forest.", objectives = "Speak with A'dal in Shattrath City.", completion = "K'ure was wise to send you here. While we cannot assist you with the suffering of the orc ancestors, there is one that can.\n\nOne that is soon to be reborn of Light..." }
WordHunterWoW_QuestEN[10103] = { title = "Report to Zurai", description = "With the arrival of Field Commander Romus and his forces, the Alliance and their draenei friends have grown bold. They're militarizing every old draenei ruin from here to Shattrath.\n\nIn response, the trolls have established a new outpost in the eastern part of Zangarmarsh, just south of the Dead Mire. Swamprat Post, they're calling it. I'm glad they have a sense of humor about living in a place like that, because I wouldn't relish it.\n\nThe post's commander has asked me to send anyone I can spare.", objectives = "Report to Zurai at Swamprat Post in Zangarmarsh.", completion = "To be honest, I had expected more, but you'll have to do. Welcome to Swamprat Post." }
WordHunterWoW_QuestEN[10104] = { title = "Concerns About Tuurem", description = "The rumors from Tuurem are unsettling. Some say the town's ruins are overrun with crazed Broken and Lost Ones, while opportunistic artifact hunters steal draenei relics.\n\nIt's hard to know which are true and which aren't, but we have a responsibility to safeguard the ruins as best we can. Find Andarl at the Allerian Stronghold in Terokkar Forest. He is something of a student of magical relics. More than anyone else, he's likely to know what's going on there.", objectives = "Speak with Andarl at the Allerian Stronghold in Terokkar Forest.", completion = "I'm flattered that your Broken friend considers me a scholar of his people's relics, but to be honest, I haven't had much chance to study them since my arrival here. It was certainly my intent, but when I arrived, I found that there were other matters that required my attention." }
WordHunterWoW_QuestEN[10105] = { title = "News for Rakoria", description = "Now that Swamprat Post is complete, our control of the roads in and out of the marsh is much less tenuous. Our presence in Terokkar Forest is much less secure. Even so, at Stonebreaker Hold, Rakoria awaits word of our progress.\n\nShe's sharp and capable, {name}, but be careful around her. She's got a lot of goods she's eager to move along the roads, but don't assume she's got our best interests at heart. Rakoria goes where she believes there's profit to be found.", objectives = "Speak with Rakoria at Stonebreaker Hold in Terokkar Forest.", completion = "I'd hoped his men would have the outpost complete sooner, but it's not costing him money. Still, it's progress." }
WordHunterWoW_QuestEN[10106] = { title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", completion = "Well done, <name>.  Your actions in the field are instrumental in our battle for Hellfire Peninsula." }
WordHunterWoW_QuestEN[10107] = { title = "Diplomatic Measures", description = "Kilrath sends news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the southeast near the border of Terokkar. Good luck, {name}!\n\nBe warned, he is a blademaster...", objectives = "Jorin Deadeye at Garadar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins.", progress = "Speak.", completion = "So what is your decision? Will it be war or will you lend your assistance?" }
WordHunterWoW_QuestEN[10108] = { title = "Diplomatic Measures", description = "The huntress's agents send news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the east. Good luck, {name}!\n\nBe warned, he is a blademaster...", objectives = "Mo'mor the Breaker at Telaar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins.", progress = "Speak.", completion = "So what is your decision? Will it be war or will you lend your assistance?" }
WordHunterWoW_QuestEN[10109] = { title = "I Must Have Them!", description = "Do you see them?? By Gazlowe's horrific halitosis, I will have those eggs! Say, you look like you might be of some use.\n\nI'll tell you what, {race}; if you gather a few items for me to make my Jump-a-tron 4000 functional, I'll give you a key that will let you operate the machine as well! What can you do with a Jump-a-tron 4000 you say? What can't you do is more like it...\n\nI'll need air elemental gas from the air elementals of Nagrand. They're all over the place so don't ask me where to find 'em!", objectives = "Wazat across from Clan Watch in southern Nagrand wants you to bring him 3 Air Elemental Gases.", progress = "Got gas?", completion = "Excellent! Now just a few adjustments and this thing will be as good as new. Oh yes, your key! Here you go.\n\nBy the way, the Jump-a-tron still has a few kinks that I need to work out. Um, just be careful." }
WordHunterWoW_QuestEN[10110] = { title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", completion = "Nice work, <name>.  I could almost hear the battles waged at those forts.  I wish I was there to see them!" }
WordHunterWoW_QuestEN[10111] = { title = "Bring Me The Egg!", description = "Now that you've been initiated, I want you to get me that egg! Use the Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or serious permanent damage may occur from a bad jump.", objectives = "Wazat in Nagrand wants you to use the Jump-a-tron 4000 to get to the nest in the nearby tree and steal the Mysterious Egg.", progress = "Did I mention my love for eggs?", completion = "Well, it's no egg... Hey! I love chicken too! I'll just chomp right through this ginourmous talon! Thanks!" }
WordHunterWoW_QuestEN[10112] = { title = "A Personal Favor", description = "Hmmm?  A box you say?  Or was it several?  Do you know what material the box was constructed from?\n\nAnd what was the name of this merchant?  Empoor?  Are you certain that he's one of the Broken?  I don't do much business with their kind.\n\nPerhaps my memory would be jogged if you were to do me a favor?\n\nThe Skithian arakkoa - primitive casters that they are - recently stole a huge shipment of my more exotic goods.  I want it all back!\n\nYou can find Veil Skith just to the south of Shattrath City.", objectives = "Retrieve 5 of Lathrai's Stolen Goods. Return them to Wind Trader Lathrai near the World's End Tavern in the Lower City section of Shattrath City.", progress = "Hmm, is my memory improving?", completion = "Yes, indeed, I do believe that it's all getting clearer now.\n\nAnd I think that your diligence in this matter deserves more than just the information that you seek." }
WordHunterWoW_QuestEN[10113] = { title = "The Nesingwary Safari", description = "\"Go out and find us some supplies,\" he said. I was nearly killed about 15 times before I found this place! These Broken might not be the most hospitable bunch but at least they're not trying to tear my skin from my bones.\n\nAnyway, I'm not going back. My days of huntin' big game are over. If you end up heading northeast towards Zangarmarsh and run into the Nesingwary Safari, let them know that \"Shotgun\" quit. \n\nHey, maybe you can take my place! Good luck, stranger.\n", objectives = "\"Shotgun\" Jones wants you to speak with Hemet Nesingwary at the Nesingwary Safari on the outskirts of northeast Nagrand.", completion = "I suppose we'll have to find a replacement water boy. Say, you look like a powerful <class>. Interested in a job? Or did you come for the hunt?" }
WordHunterWoW_QuestEN[10114] = { title = "The Nesingwary Safari", description = "These orcs have never seen a tauren before - if you can believe such a thing. If it weren't for Captain Kroghan, they would have probably been serving me for their next meal right about now.\n\nBut where are my manners? I am Ohlorn Farstrider, hunter extraordinaire! I am part of the Nesingwary expedition that came up here from Azeroth in search of big game. If you are interested in the hunt, perhaps you should visit my crew at the Nesingwary Safari, due east of here near the border of Zangarmarsh.\n", objectives = "Ohlorn Farstrider wants you to speak with Shado 'Fitz' Farstrider at the Nesingwary Safari in Nagrand.", completion = "I am relieved to hear that he is safe. Have you come to join the hunt?" }
WordHunterWoW_QuestEN[10115] = { title = "Daggerfen Deviance", description = "The Kurenai and the draenei don't always see eye to eye, particularly on the issue of the Lost Ones. We are content to help the Lost Ones who seek us out, but we won't pursue them. Some draenei are intent on 'redeeming' them all.\n\nHowever, there are times when even the Lost Ones go too far, such as the Daggerfen. In their village to the west, they dabble in poisons and deceit, arts that come unnaturally to us.\n\nWe must put an end to this before the vile Daggerfen can extend their influence.", objectives = "Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers.", completion = "You have done well, <name>. The Daggerfen are beyond redemption by anyone's standards, but I'm not certain that the draenei would've acted with the proper speed in this situation." }
WordHunterWoW_QuestEN[10116] = { title = "WANTED: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against the Orebor Harborage.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous Kurenai and draenei and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the west of the Orebor Harborage.\n\nTo claim the bounty, present proof of the chieftain's demise to Ikuti.", objectives = "Bring Chieftain Mummaki's Totem to Ikuti at the Orebor Harborage.", progress = "So you wish to claim the bounty on Chieftain Mummaki?", completion = "Remarkable! There have been others who tried to claim the bounty, but they never returned. It's not hard to figure out what happened to them.\n\nI'm relieved that we'll no longer be troubled by Mummaki and his degenerates." }
WordHunterWoW_QuestEN[10117] = { title = "WANTED: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against Zabra'jin and its inhabitants.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous scouts and messengers and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the northwest of Zabra'jin.\n\nTo claim the bounty, present proof of the chieftain's demise to Shadow Hunter Denjai.", objectives = "Bring Chieftain Mummaki's Totem to Shadow Hunter Denjai.", progress = "So you wish to claim the bounty on Chieftain Mummaki?", completion = "You have my thanks, <name>. I was beginning to think that I was going to have to take a substantial part of the garrison up there and deal with Mummaki myself. Of course, there's no telling what might have happened to Zabra'jin then." }
WordHunterWoW_QuestEN[10118] = { title = "Message to the Daggerfen", description = "Of all the Lost One tribes in Zangarmarsh, the Daggerfen are the most cunning and most aggressive. They are highly organized and make no secret of the fact that they desire control over the other Lost Ones in the marsh.\n\nTheir attacks have already taken quite a toll on my scouts and messengers. I cannot afford to lose any more men.\n\nIf we don't act soon, they'll have complete control over the roads and Zabra'jin will effectively be surrounded.", objectives = "Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers and return to Shadow Hunter Denjai at Zabra'jin.", completion = "I think you've managed to send a fairly strong message to them. Perhaps now, the rest of my men won't be so afraid to take the fight to the Daggerfen. Or, if they are, they'll find themselves ashamed by their lack of bravery." }
WordHunterWoW_QuestEN[10119] = { title = "Burning Crusade: Through the Dark Portal", description = "For 20 years the Dark Portal has remained a silent monument - a eulogy to a time long since forgotten.\n\n<Relthorn looks around.>\n\nI never thought to see this day, yet here we stand, looking into the abyss.\n\nOn the other side of this gate we are locked in a savage war - a war that we cannot win without support. You must go through the Dark Portal and help our troops, <class>.\n\nReport to Commander Duron at once. He awaits you in Outland...", objectives = "Travel through the Dark Portal and find Commander Duron. He awaits your arrival on the other side - in the Outland.", completion = "Welcome to Outland, <name> -- welcome to the nightmare! Though the initial Expeditionary Force made it through unscathed, the Legion is attempting to retake the Dark Portal and prevent any of our reinforcements from coming through.\n\nAs much as I'd like your aid here, our troops and the Horde soldiers are able to fend off the Legion platoons that are attempting to take control of this platform.\n\nWe need you where your talents can best be utilized." }
WordHunterWoW_QuestEN[10120] = { title = "Arrival in Outland", description = "Aided by the Alliance, my forces will hold the line here, but I need you to deliver my report to General Krakork in Thrallmar. With his help, we'll be able to drive these demons back into the abyss that spawned them! Speak to Vlagga Freyfeather. She'll speed you on your way.", objectives = "Lieutenant General Orion at the Dark Portal in Hellfire Peninsula wants you to bring Orion's Report to Vlagga Freyfeather.", progress = "I saw you speaking with Orion - it must be important business...", completion = "So you're Orion's new messenger? I pray you fare better than the last one he sent, <class>.  With the Legion pressing in, you'd never make it to Thrallmar on foot. Say the word, and my faithful wyvern will deliver you there safely." }
WordHunterWoW_QuestEN[10121] = { title = "Eradicate the Burning Legion", description = "Though this land is full of strange new enemies, the Burning Legion is still the greatest threat to our Expedition. One of my most trusted warriors, Sergeant Shatterskull, has been studying the Legion's tactics - trying to discern the demons' true purpose in this land. Seek him out at the supply caravan just outside the southern wall.\n\nAnd {name} - be wary of the Legion. Their evil cannot be underestimated.", objectives = "Speak with Sergeant Shatterskull at the Supply Caravan just outside of Thrallmar, to the east.", completion = "No doubt you saw the Legion's warriors dotting the landscape on your flight from the Dark Portal. Though we defeated them at the Battle of Mount Hyjal some five years past, the cursed demons just keep coming back for more. If it's a challenge they crave, then the Horde will answer in kind!\n\nWe orcs have more than just a score to settle with the Legion. What about you, <name>? Shall I tell you of our enemy?" }
WordHunterWoW_QuestEN[10122] = { title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable scouts, Private Imarion, to track their movements, preparations and numbers, but he hasn't returned to report his findings.\n\nImarion was to focus his efforts on the northernmost camp along the Southern Rampart, near where it joined the Citadel. Find him, {name}. Without his information, we're sitting ducks.", objectives = "Search the northernmost camp along the Southern Rampart for any trace of Private Imarion.Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable scouts, Private Imarion, to track their movements, preparations and numbers, but he hasn't returned to report his findings.\n\nImarion was to focus his efforts on the northernmost camp along the Southern Rampart, near where it joined the Citadel. Find him, <name>. Without his information, we're sitting ducks.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10123] = { title = "Felspark Ravine", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords in Felspark Ravine, east of here. They are responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", objectives = "Sergeant Shatterskull at the Supply Caravan east of Thrallmar in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.", progress = "Thrallmar is safe so long as the arcanist and his bloodmages remain at the front.", completion = "Outstanding work, soldier. The frequency of the attacks is sure to lessen - at least until they bring forth more dreadlords.\n\nNow for the bad news: I've got your new orders..." }
WordHunterWoW_QuestEN[10124] = { title = "Forward Base: Reaver's Fall", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Forward Commander To'arch.\n\nNow move out!", objectives = "Report to Forward Commander To'arch at Reaver's Fall.", completion = "So you're the one responsible for clearing out Felspark, eh?  That's good to hear - we need soldiers like you who can take these fiends head on!" }
WordHunterWoW_QuestEN[10125] = { title = "Mission: Disrupt Communications", description = "Directly east of here is the Legion Front. The front acts as a mobile command station for the Burning Legion. Jutting out of the ground you'll see Legion antennas. The Legion uses these to communicate with their forge camps throughout Outland. They also serve as wards to scramble Legion transmissions, making magical surveillance impossible.\n\nI want you to take these explosives and use them to obliterate the antennas. Get all of them, <name>. They run south to north on the border of the Legion Front.Upon completion of this quest you will gain:", objectives = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you use To'arch's Explosives and destroy Legion Antenna: Spite, Legion Antenna: Rage, Legion Antenna: Hate, Legion Antenna: Fear." }
WordHunterWoW_QuestEN[10126] = { title = "Warboss Nekrogg's Orders", description = "The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their human prisoner south for interrogation.\n\nLieutenant Amadi mentioned that the Southern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Private Imarion.\n\nJudging by the note's mention of interrogation, it seems the private's fel orc captors see some value in keeping him alive. Pick up the trail before they decide to change their minds.", objectives = "Travel south along the west side of the South Rampart and search the next camp for signs of Private Imarion.The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their human prisoner south for interrogation.\n\nLieutenant Amadi mentioned that the Southern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Private Imarion.\n\nJudging by the note's mention of interrogation, it seems the private's fel orc captors see some value in keeping him alive. Pick up the trail before they decide to change their minds.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10127] = { title = "Mission: Sever the Tie", description = "It would be a dereliction of duty if I did not order you to take out the demons that inhabit the Legion Front, just east of this base.\n\nBoth sides of the front are set up in the same manner: Fel handlers roam between Legion encampments, which are in turn guarded by wrathguards. A shivan subjugator oversees the entire operation. Kill 'em all and let Kazzak sort 'em out.\n\nAnd watch out for patrolling fel reavers. I know you're tough but those things will make short work of you.Upon completion of this quest you will gain:", objectives = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula wants you to kill 4 Fel Handlers, 8 Wrathguards, and Subjugator Shi'aziv." }
WordHunterWoW_QuestEN[10128] = { title = "Saving Private Imarion", description = "The tracks lead south from Imarion's equipment, appearing to follow the Southern Rampart. The roughness of the shallow ruts suggests that Imarion's captors were in a hurry to move him to his next destination, but why?\n\nWas someone waiting there for him, perhaps the Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Private Imarion, you're likely to find Warboss Nekrogg too.", objectives = "Continue south along the Southern Rampart and search for where Warboss Nekrogg is holding Private Imarion.The tracks lead south from Imarion's equipment, appearing to follow the Southern Rampart. The roughness of the shallow ruts suggests that Imarion's captors were in a hurry to move him to his next destination, but why?\n\nWas someone waiting there for him, perhaps the Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Private Imarion, you're likely to find Warboss Nekrogg too.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10129] = { title = "Mission: Gateways Murketh and Shaadraz", description = "We've identified the two main transporters that the Burning Legion are using to bring in reinforcements: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into oblivion!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Brack -- he'll put you on a wyvern.", objectives = "Speak with Wing Commander Brack, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander To'arch at Reaver's Fall.", progress = "If you missed during your first pass, take another...", completion = "That will set them back weeks! Fantastic work, <name>. The Legion never expected such heavy resistance." }
WordHunterWoW_QuestEN[10130] = { title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Honor Hold.\n\nWith the hold's garrison concentrating on its eastern walls, an attack from the west would be devastating. Honor Hold can only hope to hold out if the western forces are kept out of the battle.", objectives = "Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Lieutenant Amadi at Honor Hold's western guard tower." }
WordHunterWoW_QuestEN[10131] = { title = "Planning the Escape", description = "Like I said, getting out of here won't be easy. Warboss Nekrogg may look like an overgrown brute, but he's no simpleton.\n\nHe won't let the cage key out of his sight and doesn't come down from his tower atop that chunk of wall until he's ready to question me or that orc he's managed to capture.\n\nIt's going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill a Shattered Hand Grenadier and bring his Crude Explosives to Private Imarion at Gor'gaz Outpost." }
WordHunterWoW_QuestEN[10132] = { title = "Colossal Menace", description = "You see that huge red crystal to the north?  It fell from the sky not long ago, causing a massive earthquake.\n\nWhen we came out here to investigate the disturbance, we found all of these colossi wandering about that weren't previously here.\n\nThere's definitely something strange about that crystal and the energies that it's emanating, but I don't have time for that.  Those mountain giants are my immediate concern.\n\nI want you to head up to Fallen Sky Ridge and deal with them.", objectives = "Slay 5 Raging Colossi and then return to Tola'thion at the Cenarion Post in Hellfire Peninsula.", completion = "Good work.\n\nIf you ask me, all that we have to do is kill enough of those colossi, and then we won't have to worry any longer about the ridge or that strange crystal in the middle of it.\n\nHere, take one of these as a gift from the Cenarion Expedition." }
WordHunterWoW_QuestEN[10133] = { title = "Mission: Kill the Messenger", description = "Your handiwork is already causing the Legion great discomfort, <name>. My scouts have just informed me that the Legion has resorted to sending communication via courier. We have successfully managed to cut their troops off from the host!\n\nWhat I ask of you next is more than I would ask of an ordinary soldier.\n\nThe Legion courier travels from the Pools of Aggonar to Forge Base: Mageddon, north of here. You must intercept the courier at Mageddon, dispose of him, and return to me with the Legion missive.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you find and slay Arix'malidash and recover the Legion Missive." }
WordHunterWoW_QuestEN[10134] = { title = "Crimson Crystal Clue", description = "As the colossus falls under the weight of your attacks, you notice for the first time that it was holding a red crystal fragment.\n\nWhile it was small and unnoticeable in the mountain giant's hand, it's a fairly hefty piece for you to carry around.  It also suspiciously looks like it's a piece of the giant crystal in the middle of the ridge.\n\nIt's most definitely a clue as to the strangeness that is occurring here, and you're sure that the druids at the Cenarion Post to the south will want to see it.", objectives = "Deliver the Crimson Crystal Shard to Tola'thion at the Cenarion Post in Hellfire Peninsula.", progress = "That's a big crystal you have there.  Did you get that while you were up at the ridge killing colossi?\n\nLet me take a look at it.", completion = "Hmph.  Just looks like a big lump of unrefined crystal to me.\n\nAdmittedly, I can feel a sickly, evil aura emanating off of it, but that's not exactly in my line of work.  I'm just here to put an end to the mountain giant menace." }
WordHunterWoW_QuestEN[10135] = { title = "Mission: Be the Messenger", description = "I am merely a field commander, <class>. The authority to act on this kind of information falls squarely on the shoulders of our leader, Nazgrel. You must take this missive to him in Thrallmar. Ride with the wind at your back, soldier. Let nothing prevent you from reaching Nazgrel!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Legion Missive to Nazgrel at Thrallmar in Hellfire Peninsula." }
WordHunterWoW_QuestEN[10136] = { title = "Cruel's Intentions", description = "Magister Bloodhawk finally deciphered the Legion missive you found earlier. It turned out to be attack plans sent by one of Highlord Kazzak's lieutenants - Arazzius the Cruel. Apparently, Arazzius commands the Legion ground forces in Hellfire. The time has come to terminate his command, {name}. Terminate with extreme prejudice. \n\nHead west to the Pools of Aggonar and put an end to this so-called 'Legion lord'. Today, the Horde reclaims Hellfire Peninsula. Let the Legion be damned. ", objectives = "Kill Arazzius the Cruel, then return to Nazgrel in Thrallmar.", completion = "For generations to come, they will sing songs of this day, <name> - songs of your valor. I wish Thrall had been here to celebrate this victory with us. The Legion is undone - and Hellfire now belongs to the Horde once again! There may yet be hope for this ravaged world - and our peoples' place within it. \n\nLok'tar ogar!" }
WordHunterWoW_QuestEN[10137] = { title = "Provoking the Warboss", description = "The plan succeeds or fails on how well these explosives are made...\n\nAs much as I'd hate to rely on anything made by an orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.\n\nOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, {name}.", objectives = "Use the Crude Explosives to create a disturbance and lure Warboss Nekrogg out of his tower. Kill him, obtain Nekrogg's Key, and use it to open Private Imarion's cage. Once you have freed Private Imarion, report to Lieutenant Amadi." }
WordHunterWoW_QuestEN[10138] = { title = "Under Whose Orders?", description = "One thing is clear, <name>: we can't keep this up. The fel orcs have us surrounded and as quickly as we can kill them, several spring up to replace them. We can't hope to win this war huddled behind Honor Hold's shattered walls and counting the days until our deaths at the hands of the fel orcs or the Legion.\n\nYou've done a remarkable job of sparing us from the brunt of the fel orc attack, but now you must fight your way up the Path of Glory and learn who is orchestrating these attacks.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 20 Shattered Hand Grunts, 10 Shattered Hand Warlocks, and capture Drillmaster Zurok's Orders. Then, return to Lieutenant Amadi at Honor Hold's western guard tower." }
WordHunterWoW_QuestEN[10139] = { title = "Dispatching the Commander", description = "From what I can tell, Drillmaster Zurok served as the right hand of the fel orc leader in Hellfire Peninsula, Force-Commander Gorax.\n\nThis Gorax isn't your typical fel orc brute, though. I almost admire the way he managed to keep us on the defensive for so long.\n\nZurok's orders indicate that Gorax's command center is located at the end of the Path of Glory, near where the citadel's walls meet the Northern Rampart. There's no telling what to expect, <name>, but it would be wise to travel with allies.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Force-Commander Gorax and report to Lieutenant Amadi at Honor Hold's western tower." }
WordHunterWoW_QuestEN[10140] = { title = "Journey to Honor Hold", description = "When you're ready, I'll arrange a flight straight to Honor Hold.\n\nFrom there, speak with Marshal Isildor and give him Duron's report.  He'll be happy to see another recruit from the homelands, and I'm sure the information in that report is important stuff!", objectives = "Take a flight to Honor Hold and deliver Duron's Report to Marshal Isildor.", progress = "Thank the Light you made it here safely. Honor Hold needs all the seasoned warriors it can muster.", completion = "Our expedition to this forsaken, wreck of a world has almost ground to a halt, <name>. We encountered more resistance than we bargained for.\n\nAs if facing the Burning Legion again wasn't bad enough - there are horrors in this land unlike anything we've ever encountered." }
WordHunterWoW_QuestEN[10141] = { title = "The Legion Reborn", description = "While the Burning Legion invaded Azeroth, they were also at work here, in Outland.  We have tracked their movements over the years, but this latest activity, {class} - well, this is beyond anything we've seen.\n\nSeek out Sergeant Altumus near the eastern supply caravan. She has been monitoring the invaders and may have insights into their purpose.\n\nBe swift - and take care, {name} - the Burning Legion is not to be underestimated.", objectives = "Speak with Sergeant Altumus at the East Supply Caravan just outside of Honor Hold, to the east.", completion = "Force Commander Danath may have misunderstood my request for reinforcements. You look capable, but... I asked for a full sized battalion!\n\nYou see, we have a bit of a demon problem..." }
WordHunterWoW_QuestEN[10142] = { title = "The Path of Anguish", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords at the Path of Anguish, east of here. They are the ones responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", objectives = "Sergeant Altumus at the East Supply Caravan east of Honor Hold in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.", progress = "Honor Hold is safe so long as the archers guard our skies.", completion = "Outstanding work, soldier. The frequency of the attacks is sure to lessen - at least until they bring forth new dreadlords.\n\nNow for the bad news: I've got your new orders..." }
WordHunterWoW_QuestEN[10143] = { title = "Expedition Point", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Rohamus's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 400 paces, across the Valley of Bones, until you run into a destroyed fel reaver. You'll see Expedition Point where a Legion base used to stand. Once there, you are to report to Forward Commander Kingston.\n\nNow move out!", objectives = "Report to Forward Commander Kingston at Expedition Point.", completion = "Glad to meet you, soldier.\n\nEnough chatting... now listen up -- I have a vital mission for you and I want you to succeed... and survive!" }
WordHunterWoW_QuestEN[10144] = { title = "Disrupt Their Reinforcements", description = "You'll find the Legion front to our northeast, and spaced along it are portals used to gather reinforcements from throughout Outland. We, {name}, are going to destroy those portals!\n\nTake this primer.  Designed in Area 52, it uses the demons' own power as an explosive device!  Defeat Legion forces around Portals Grimh and Kaalez to gather demonic rune stones, use the primer to detonate the stones inside the portals... then watch the fireworks!!\n\nGo, {name}, and return to me when your mission is complete.", objectives = "Defeat enemies around Portal Grimh and Portal Kaalez to gather Demonic Rune Stones.\n\nUse Kingston's Primer inside Portal Grimh and Portal Kaalez.\n\nReturn to Forward Commander Kingston with the remaining explosives.", progress = "I wish I could be there to watch the fire display.  Those explosives pack a big punch!", completion = "Well done, <name>.  Disabling those portals will stem the flow of Legion reinforcements for a long time!\n\nBut we can't rest yet..." }
WordHunterWoW_QuestEN[10145] = { title = "Mission: Sever the Tie UNUSED", description = "It would be a dereliction of duty if I did not order you to take out the demons that inhabit the Legion Front, just north of this base.\n\nBoth sides of the front are set up in the same manner: Fel handlers roam between Legion encampments, which are in turn guarded by wrathguards. A shivan subjugator oversees the entire operation. Kill 'em all and let Kazzak sort 'em out.\n\nAnd watch out for patrolling fel reavers. I know you're tough but those things will make short work of you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Forward Commander Kingston at Expedition Point in Hellfire Peninsula wants you to kill 4 Fel Handlers, 8 Wrathguards, and Subjugator Yalqiz." }
WordHunterWoW_QuestEN[10146] = { title = "Mission: The Murketh and Shaadraz Gateways", description = "Just west of the Dark Portal are two huge transporters: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into rubble!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Dabir'ee -- he'll put you on a gryphon and send you on your way.", objectives = "Speak with Wing Commander Dabir'ee, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander Kingston at Expedition Point.", progress = "This is a vital mission, <name>.  It's one I would not trust to just anyone.", completion = "That will slow them down, there's no denying it! I think you just put me in an uncharacteristically good mood, <name>!" }
WordHunterWoW_QuestEN[10147] = { title = "Mission: Kill the Messenger", description = "Your handiwork is already causing the Legion great discomfort, <name>. My scouts have just informed me that the Legion has resorted to sending communication via courier. We have successfully managed to cut their troops off from the host!\n\nWhat I ask of you next is more than I would ask of an ordinary soldier.\n\nThe Legion courier travels from the Pools of Aggonar to Forge Base: Mageddon, far north of here. You must intercept the courier at Mageddon, dispose of him, and return to me with the Legion missive.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Forward Commander Kingston at Expedition Point in Hellfire Peninsula has asked that you find and slay Arix'malidash and recover the Legion Missive." }
WordHunterWoW_QuestEN[10148] = { title = "Mission: Be the Messenger", description = "I am merely a field commander, <class>. The authority to act on this kind of information falls squarely on the shoulders of our leader, Force Commander Danath Trollbane. You must take this missive to him in Honor Hold. Ride with the wind at your back, soldier. Let nothing prevent you from reaching Danath!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Legion Missive to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula." }
WordHunterWoW_QuestEN[10149] = { title = "Mission: End All, Be All", description = "Do you know what would have happened if you had not intercepted this missive, <name>?\n\n<Danath nods.>\n\nThe entirety of the Legion army in Hellfire would have been knocking on our door. There is no way that we could have survived such an assault.\n\nThere is only one way to make sure that these orders never reach the Legion Front. You must travel to the Pools of Aggonar, far northwest of here, and slay this Arazzius creature.\n\nDo this and I will grant you a commendation.You will be able to choose one of these rewards:", objectives = "Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula has asked that you slay Arazzius the Cruel." }
WordHunterWoW_QuestEN[10150] = { title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable trackers, Scout Makha, to track their movements, preparations and numbers, but she hasn't returned to report her findings.\n\nMakha was to focus her efforts on the northernmost camp along the Northern Rampart, near where it ends in the rocks. Find her, {name}. Without her information, we're sitting ducks.", objectives = "Search the northernmost camp along the Northern Rampart for any trace of Scout Makha.Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable trackers, Scout Makha, to track their movements, preparations and numbers, but she hasn't returned to report her findings.\n\nMakha was to focus her efforts on the northernmost camp along the Northern Rampart, near where it ends in the rocks. Find her, <name>. Without her information, we're sitting ducks.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10151] = { title = "Warboss Nekrogg's Orders", description = "The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their orcish prisoner south for interrogation.\n\nShadow Hunter Ty'jin mentioned that the Northern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Scout Makha.\n\nJudging by the note's mention of interrogation, it seems the scout's fel orc captors see some value in keeping her alive. Pick up the trail before they decide to change their minds.", objectives = "Travel south along the west side of the Northern Rampart and search the next camp for signs of Scout MakhaThe orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their orcish prisoner south for interrogation.\n\nShadow Hunter Ty'jin mentioned that the Northern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Scout Makha.\n\nJudging by the note's mention of interrogation, it seems the scout's fel orc captors see some value in keeping her alive. Pick up the trail before they decide to change their minds.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10152] = { title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Thrallmar.\n\nWith the town's garrison concentrating on its eastern walls, an attack from the west would be devastating. Thrallmar can only hope to hold out if the western forces are kept out of the battle.", objectives = "Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Stone Guard Ambelan at Spinebreaker Post near Zeth'Gor." }
WordHunterWoW_QuestEN[10153] = { title = "Saving Scout Makha", description = "The tracks lead south from Makha's equipment, appearing to cross the Path of Glory. The roughness of the shallow ruts suggests that Makha's captors were in a hurry to move her to the next destination, but why?\n\nWas someone waiting there for her, perhaps Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Scout Makha, you're likely to find Warboss Nekrogg too.", objectives = "Continue south across the Path of Glory to the Southern Rampart and search for where Warboss Nekrogg is holding Scout Makha.The tracks lead south from Makha's equipment, appearing to cross the Path of Glory. The roughness of the shallow ruts suggests that Makha's captors were in a hurry to move her to the next destination, but why?\n\nWas someone waiting there for her, perhaps Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Scout Makha, you're likely to find Warboss Nekrogg too.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10154] = { title = "Planning the Escape", description = "Like I said, getting out of here won't be easy. Warboss Nekrogg may look like an overgrown brute, but he's no simpleton.\n\nHe won't let the cage key out of his sight and doesn't come down from his tower atop that chunk of wall until he's ready to question me or that human he's managed to capture.\n\nIt's going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill a Shattered Hand Grenadier and bring his Crude Explosives to Scout Makha at Gor'gaz Outpost." }
WordHunterWoW_QuestEN[10155] = { title = "Provoking the Warboss", description = "The plan succeeds or fails on how well these explosives are made...\n\nAs much as I'd hate to rely on anything made by a fel orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.\n\nOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, {name}.", objectives = "Use the Crude Explosives to create a disturbance and lure Warboss Nekrogg out of his tower. Kill him, obtain Nekrogg's Key, and use it to open Scout Makha's cage. Once you have freed Scout Makha, report to Stone Guard Ambelan at Spinebreaker Post near Zeth'Gor." }
WordHunterWoW_QuestEN[10156] = { title = "Under Whose Orders?", description = "One thing is clear, <name>: we can't keep this up. The fel orcs have us pinned down and as quickly as we can kill them, several spring up to replace them. We can't hope to win this war with our forces divided and locked in constant combat with the fel orcs and the demons of the Legion.\n\nYou've done a remarkable job of blunting the fel orc attack, but now you must fight your way up the Path of Glory and learn who is orchestrating this offensive.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 20 Shattered Hand Grunts, 10 Shattered Hand Warlocks, and capture Drillmaster Zurok's Orders. Then, return to Stone Guard Ambelan at Spinebreaker Post." }
WordHunterWoW_QuestEN[10157] = { title = "Dispatching the Commander", description = "From what I can tell, Drillmaster Zurok served as the right hand of the fel orc leader in Hellfire Peninsula, Force-Commander Gorax.\n\nThis Gorax isn't your typical fel orc brute, though. I almost admire the way he managed to keep us on the defensive for so long.\n\nZurok's orders indicate that Gorax's command center is located at the end of the Path of Glory, near where the citadel's walls meet the Northern Rampart. There's no telling what to expect, <name>, but it would be wise to travel with allies.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Force-Commander Gorax and report to Shadow Hunter Ty'jin at Thrallmar." }
WordHunterWoW_QuestEN[10158] = { title = "Bleeding Hollow Supplies", description = "The orcish ruins of Zeth'Gor to serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.\n\nShadow Hunter Ty'jin sent me here to keep an eye on the outpost and its strange inhabitants.\n\nSomething has changed these orcs, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Fight your way into Zeth'Gor and destroy any supplies you find there.", objectives = "Destroy 6 piles of Bleeding Hollow Supplies and report to Stone Guard Ambelan at Spinebreaker Post." }
WordHunterWoW_QuestEN[10159] = { title = "Keep Thornfang Hill Clear!", description = "We've been fighting an ongoing battle to keep the pass through Thornfang Hill to the west clear of ravagers.  It would be bad if we were to become completely cut off from the refuge in Zangarmarsh.\n\nWe don't want to displace the creatures, but there seems to be little choice as their attacks on travelers through the area have become more aggressive.\n\nClear some of the ravagers out of there if you can.", objectives = "Kill 8 Thornfang Ravagers and 8 Thornfang Venomspitters, and then return to Mahuram Stouthoof at the Cenarion Post in Hellfire Peninsula.", progress = "How fares your attempt to clear Thornfang Hill?", completion = "With the ravagers cleared, travelers to and from the Cenarion Refuge in Zangarmarsh should have an easier time of it.\n\nThe Cenarion Expedition is indebted to you." }
WordHunterWoW_QuestEN[10160] = { title = "Know your Enemy", description = "Rumors have surfaced that some new breed of orc is on the rise. Larger, meaner - more cunning than the brutes we're familiar with.  If these rumors are true then our forces, already stretched, may be taxed beyond their limit.\n\nI have entrusted my lieutenant, Amadi, with investigating this matter. If you would help us in this dark hour, seek her out. She is stationed at the broken tower just west of the Hold.\n\nAnd {name} - be careful out there. You're heading into a dangerous new world.", objectives = "Speak with Lieutenant Amadi at the old guard tower just west of Honor Hold.", completion = "<Lieutenant Amadi nods.>\n\nGood, we need all the help we can get. The increasing fel orc presence around the Southern Rampart concerns me. I sent out a scout to investigate, but he hasn't yet returned." }
WordHunterWoW_QuestEN[10161] = { title = "In Case of Emergency...", description = "In the event of an emergency, it's always the pilot's job to keep a level head, especially when the only orders your co-pilot follows come from his stomach.\n\nThe good news is that we won't need to wait days for replacement parts to be imported. The bad news is that the \"spare\" parts got scattered from here to the Valley of Bones to the east.\n\nThe other bad news? The spare parts aren't so spare. They, uh, fell off during our rapid descent. Could you help me collect enough to get us off the ground again?", objectives = "Collect 30 pieces of Zeppelin Debris and bring them to \"Screaming\" Screed Luckheed at the Zeppelin Crash.", progress = "Did you find enough of the parts? If not, I might have to use that frying pan Legassi keeps waving around. Then, I'd have to rename the zeppelin the \"Flying Skillet.\"", completion = "Some of this is in pretty bad shape, but there should be enough to work with here. With some creative engineering, I'm confident I can make it work!" }
WordHunterWoW_QuestEN[10162] = { title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a wyvern and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Wing Commander Brack when you're ready for takeoff.", objectives = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "Show them that not even the skies are safe!", completion = "You fly as if you've been doing this your entire life, <name>. Outstanding performance out there! Not even a scratch on the wyvern destroyers!" }
WordHunterWoW_QuestEN[10163] = { title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a gryphon and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Gryphoneer Windbellow when you're ready for takeoff.\n", objectives = "Wing Commander Gryphongar at Shatter Point in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "Show them that not even the skies are safe!", completion = "You fly as if you've been doing this your entire life, <name>. Outstanding performance out there! Not even a scratch on the gryphon destroyers!" }
WordHunterWoW_QuestEN[10164] = { title = "Everything Will Be Alright", description = "You've had quite an adventure, <name>. And before you've even set foot inside of the Auchenai Crypts.\n\nI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.\n\nWhat I ask is simple. Enter the Auchenai Crypts and destroy Exarch Maladaar so that the spirits trapped inside can finally rest in peace.", objectives = "Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and destroy Exarch Maladaar.", completion = "You've done it, <name>! The spirits are freed!\n\nAlthough I am without a material manifestation, I am still able to reward you with items from the spirit world. Use them with caution as such items are often volatile and can cause great harm to their user." }
WordHunterWoW_QuestEN[10165] = { title = "Undercutting the Competition", description = "That Shaffar is a shrewd one - I'll give him that... He's managed to keep the Consortium out while he safely pillages this crypt for all it's worth. I have no faith in these imbeciles actually breaking through Shaffar's defenses so I'll make you a deal, <race>.\n\nEnter the Mana-Tombs and kill Nexus-Prince Shaffar. Bring me back his body wrap as proof of this deed and I'll reward you handsomely.", objectives = "Nexus-Prince Haramad located outside of the Mana-Tombs wants you to kill Nexus-Prince Shaffar and bring Shaffar's Wrappings back to him.", progress = "I don't like to \"share.\"", completion = "Another competitor goes under... You do good work for a flesh beast, <race>. If you are ever in Netherstorm, look me up. I make my home at the Stormspire." }
WordHunterWoW_QuestEN[10166] = { title = "Whitebark's Memory", description = "This pendant brings back memories of a different time.  A better time.\n\nUnfortunately, memories are the last thing I need right now.\n\nI want you to bury this by the runestone in the Scorched Grove.  It was there that I first met the treant elder.  Put my old friend's memory to rest.", objectives = "Larianna Riverwind wants you to place Old Whitebark's Pendant by the runestone at the Scorched Grove.", progress = "You've returned, <name>.  Haven't you done enough?", completion = "I no longer belong to this world and must admit defeat.  The land has forever changed and nothing will ever be the same.\n\nLeave the pendant here with me, <name>.  Maybe one day, long after the elves are gone, a new tree will grow on this very spot - amongst a burnt forest and the husks of dead treants." }
WordHunterWoW_QuestEN[10167] = { title = "Auchindoun...", description = "Deep within the Auchenai Crypts is a tomb: A tomb unlike any that exists on this shattered realm. It was from this tomb, the first tomb, that the vast mausoleum of Auchindoun was born.\n\nYou must venture to the Auchenai Crypts of Auchindoun and find this tomb. Slay the guardian of the crypt to release the captive spirit within. The spirit holds the key... ", objectives = "Travel to the Auchenai Crypts in the Bone Wastes of Terokkar Forest and slay Exarch Maladaar to free the spirit of D'ore.", completion = "The memory is vivid, <name>. My energies were wholly drained from the crash. I was only a dim speck of void energies when the Prophet Velen and his draenei compatriots lifted my remains and brought them here. After much ceremony, my diminished form was laid to rest within this sarcophagus. I have been regenerating for nearly a thousand years. The cycle is almost complete..." }
WordHunterWoW_QuestEN[10168] = { title = "What the Soul Sees", description = "For several centuries, the spirits of Auchindoun coalesced into my darkened essence. Many of the catastrophes that befell this crypt were a direct result of my weakened state.\n\nRegrettably, there is nothing that can be done to stop this cycle. It is a facet of the naaru condition - without the void, the Light cannot exist.\n\nYour only recourse is to destroy the ancient spirits of Nagrand before they transform into creatures of the void. Use the soul mirrors found throughout this crypt to free them...", objectives = "Locate a Soul Mirror somewhere in the Auchenai Crypts and use it to call forth a Darkened Spirit from Ancient Orc Ancestors in Nagrand. Destroy 15 Darkened Spirits so that the ancestors may rest in peace.\n\nReturn to Mother Kashur at the Ancestral Grounds when this task is complete.", progress = "<Mother Kashur is visibly upset.>\n\nThese naaru are wise beyond all manner of life on this world.", completion = "You have completed a long and dangerous journey, risking life and limb to ensure the safety of the Mag'har and the serenity of our ancestors. For this I am thankful beyond what words could convey." }
WordHunterWoW_QuestEN[10169] = { title = "Losing Gracefully", description = "The Aldor have gained the favor of the Sha'tar today.  As if that should come as any sort of surprise!\n\nWatch them showing off their fancy footwork a few feet away from A'dal.  Could they possibly put any more effort into sucking up to the naaru?\n\nHarbinger Haronem's marksman regiment is so dedicated, it even brings its own cooking pot to avoid taking long breaks for lunch.  This cannot go without retribution, {name}.\n\nI want you to pour this vial into their meal.  The results should be... comical.", objectives = "Magister Falris in Shattrath wants you to take the Vial of Sedative Serum to the Terrace of Light and pour it into Haronem's Regiment Cooking Pot." }
WordHunterWoW_QuestEN[10170] = { title = "Return to the Greatmother", description = "Return to Greatmother Geyah at Garadar with news of your victory, {name}. This will surely lift the spirits of the Mag'har. Perhaps even the young Hellscream will be lifted from his malaise.", objectives = "Return to Garadar and speak to Greatmother Geyah.", completion = "I want you to personally deliver this news to Garrosh." }
WordHunterWoW_QuestEN[10171] = { title = "The Inconsolable Chieftain", description = "You have done so much for the Mag'har, {name}. Your accomplishments are known to all, including Garrosh. Go to him now and tell him of your latest victory. Tell him that you do what you do for him and his people. Surely he will be lifted by your words.", objectives = "Greatmother Geyah at Garadar has asked that you speak with Garrosh.", completion = "Everyone is proud. Proud that our people will live to see another winter. But beyond that? What is there?\n\nMaybe you should lead this clan, <name>. Maybe then I will be allowed to die when the Greatmother passes. Allowed to finally erase the shame of my family name. I long for such peace." }
WordHunterWoW_QuestEN[10172] = { title = "There Is No Hope", description = "You are an honorable {race}, {name}. You have done much for the Mag'har. No one could ever deny your service to my people. Alas, the time of the Mag'har is at an end. You have shown me, more than anything, that I am unfit to lead these people. My cursed blood runs too deep. I will not... I cannot become the second Hellscream to damn the orcs.\n\nPlease, {name}, return to the Greatmother and tell her what I have told you. I am too ashamed to see her... to look into her eyes.", objectives = "Speak to Greatmother Geyah and tell her what Garrosh told you.", completion = "<Tears stream down Greatmother Geyah's face.>\n\nThrall is coming.  I know he will be here soon." }
WordHunterWoW_QuestEN[10173] = { title = "The Archmage's Staff", description = "Allow me to introduce myself, {class}.\n\nI am Ravandwyr, apprentice to the Archmage Vargoth.\n\nMy master is... indisposed, shall we say. I am here on a matter of great importance.\n\nThe Arklon Ruins southeast of the city are a hotbed of Burning Legion activity. Their purpose in the ruins concerns neither me nor my master, but their leader, Ekkorash, possesses the archmage's staff.\n\nThis conjuring powder will allow you to draw the demon out of hiding. Sprinkle it on the brazier at the center of the ruins.", objectives = "Retrieve Archmage Vargoth's Staff from Ekkorash the Inquisitor and bring it to Ravandwyr in Area 52. To bring Ekkorash out of hiding, sprinkle the Conjuring Powder on the brazier in the center of the ruins.", progress = "I will not rest until Archmage Vargoth's staff is restored to him. Were you able to wrest it from the demon's grasp?", completion = "Ah, so you managed to recover the staff. Impressive, <name>. Perhaps you are the one I've been looking for.\n\nOh yes, your reward...\n\n\n\nNo doubt you had higher expectations, but that too will come with time. For now, consider opportunity the true reward." }
WordHunterWoW_QuestEN[10174] = { title = "Curse of the Violet Tower", description = "Now, you will be able to use the archmage's staff to contact him.\n\nHe resides in the Violet Tower, on an 'island' to the southeast. The tower is both sanctuary and prison to him, cursed as it is. Kirin Tor can neither enter nor leave, keeping me apart from my master.\n\nThe staff's magic can penetrate the tower's defenses, but only if invoked by one outside the Kirin Tor.\n\nTake the archmage's staff and use it to conjure his image. Tell him what has happened and that I have not completely failed him.", objectives = "Use Archmage Vargoth's Staff to make contact with Archmage Vargoth.\n\nIf you lose Archmage Vargoth's Staff, speak to Ravandwyr at Area 52 to receive a replacement.\n\nProvided item:", completion = "<Archmage Vargoth's image examines you as you convey Ravandwyr's message.>\n\nRavandwyr has everything a master can expect of his apprentice. When I gave him the staff and told him to flee, I hoped that he would use it to find help and free me once Kael'thas's forces withdrew from the tower. Since then, I have learned a great deal about the nature of the curse.\n\nIt can be broken, <name>, but it will require your help." }
WordHunterWoW_QuestEN[10175] = { title = "Thrall, Son of Durotan", description = "Return to your world, <name>. Go to my grandchild and tell him that his blood is here - on this shattered world.\n\nTell him that his father's legacy lives on.\n\nTell him everything...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Venture to Orgrimmar and deliver Geyah's message to Thrall.Return to your world, <name>. Go to my grandchild and tell him that his blood is here - on this shattered world.\n\nTell him that his father's legacy lives on.\n\nTell him everything...You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10176] = { title = "Ar'kelos the Guardian", description = "Now that you've gathered all the items I'll need to break Kael'thas's curse, one thing remains to be done. When Kael'thas sealed the tower, he placed an arcane golem, known as Ar'kelos, at the bottom of the tower.\n\nYou must defeat Ar'kelos in order allow me to work magic within the tower again.\n\nWhen you enter the Violet Tower, the curse will begin to affect you.\n\nOnce you have defeated Ar'kelos, ascend the tower and assist me in making preparations for the ritual.", objectives = "Enter the Violet Tower at the center of Kirin'Var Village and defeat Ar'kelos, then speak with Archmage Vargoth.", completion = "You have done well, <name>. Destroying the dampening field will make it much easier for me to prepare the magic that will lift the tower's curse at last." }
WordHunterWoW_QuestEN[10177] = { title = "Trouble at Auchindoun", description = "I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.\n\nSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.\n\nYou must make your way to the entrance of the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.", objectives = "Report to Field Commander Mahfuun at the entrance to the Shadow Labyrinth at Auchindoun in Terokkar Forest.", completion = "It's about time that you arrived.\n\nMehlisah said that she would be sending help days ago.  And we've been fighting in here longer than that!" }
WordHunterWoW_QuestEN[10178] = { title = "Find Spy To'gun", description = "To'gun, the fool!  We're barely holding off the attacks here, and he goes back in to get more information and try to save the other spies!\n\nI don't know whether to love him or kill him!\n\nThe Shadow Council must have used magic to ferret us out, because all of our spies had to get out of there in a hurry.  Most of us didn't make it.\n\nPlease, if you're brave enough to enter the Shadow Labyrinth, will you keep an eye peeled for To'gun?  It's been a while, and I fear the worst.", objectives = "Locate Spy To'gun in the Shadow Labyrinth of Auchindoun.", completion = "What?  Grik'tha sent you in here after me?\n\nI don't know whether to be touched or call her a fool!\n\nDo you think you could help me get out of this cage?  It's a bit cramped." }
WordHunterWoW_QuestEN[10179] = { title = "The Custodian of Kirin'Var", description = "When it became clear that our expedition was trapped in Outland with no way to return to Azeroth, the Kirin Tor contingent traveled to the Plains of Farahlon and built Kirin'Var village. I left the administration of the town in the hands of Custodian Dieworth, but when Kael'thas and his forces sealed me in the Violet Tower, I lost contact with the custodian.\n\nSearch for him in Kirin'Var Village and help him in any way you can, {name}. I'm certain he's got his hands full in the aftermath of the attack.", objectives = "Speak with Custodian Dierworth at Kirin'Var Village in Netherstorm.When it became clear that our expedition was trapped in Outland with no way to return to Azeroth, the Kirin Tor contingent traveled to the Plains of Farahlon and built Kirin'Var village. I left the administration of the town in the hands of Custodian Dieworth, but when Kael'thas and his forces sealed me in the Violet Tower, I lost contact with the custodian.\n\nSearch for him in Kirin'Var Village and help him in any way you can, <name>. I'm certain he's got his hands full in the aftermath of the attack.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10180] = { title = "Can't Stay Away", description = "I tried to persuade Isfar to remain here, in the safety of Shattrath, but he would have none of it. Instead, he's decided to venture out to Auchindoun again on his own.\n\nHe was lucky enough to escape the Sethekk Halls once, but if they discover him, there won't be a second time.\n\nI admire his desire to free his sister, but he's not going to be able to do it without help.\n\nFind Isfar and have a word with him, {name}. If you can't persuade him to come back, perhaps you could help him rescue Lakka?", objectives = "Speak with Isfar, who can be found just inside the Sethekk Halls in Auchindoun.", completion = "I should've suspected he would send you after me. He tried to talk me out of returning to the Sethekk Halls, but I couldn't live with myself if I allowed Lakka to die in there." }
WordHunterWoW_QuestEN[10181] = { title = "Collector's Edition: -pn - E - FLAG", description = "", objectives = "" }
WordHunterWoW_QuestEN[10182] = { title = "Battle-Mage Dathric", description = "The sword is of exceptional quality, finely crafted and perfectly balanced for a battle-mage. The seal of the Kirin Tor and the name \"Dathric\" are engraved into the weapon's pommel.\n\nTurning the weapon over in your hands, you notice a sense of wrongness radiating from the metal, as if the item is torn between two worlds. Could this be the item anchoring Battle-Mage Dathric's spirit to this world?\n\nPerhaps returning it to its proper place can break the bond, freeing Dathric's spirit to rest at last.", objectives = "Locate Battle-Mage Dathric's quarters in Wizard's Row and return the blade to his weapon rack. Then, speak with Custodian Dieworth at Kirin'Var Village.", progress = "What have you found, <name>?", completion = "You've done well, <name>. I can no longer sense any restlessness in Dathric's spirit. I would give much for the opportunity to speak to him one more time, but it is enough that he is finally at rest." }
WordHunterWoW_QuestEN[10183] = { title = "Off To Area 52", description = "I'm out here studying the nether - the ethereal currents and all that.  This is an ideal spot away from the lights and hubbub of town.  Isn't this bridge great?  If I could just keep this junk working.\n\nHey, you know, if you're looking for work there's plenty at Area 52!  It's just up the path and take a right at the fork in the road.\n\nWhy don't you deliver my latest research notes to Rocket-Chief Fuselage?  I'm sure that he'd have plenty for you to do, what with the X-52 rocket ship, and all!", objectives = "Deliver the Netherologist's Notes to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "Busy, busy.  No time to waste!  There's a rocket ship to be built!\n\nWhat do you want?", completion = "Oh, Coppernickels finally decided to report his findings, did he?  Lazy scientists!\n\nWhat's this?\n\n<The chief riffles through the notations a few times, clearly with a look of disbelief.>\n\nHe says here that the violent nether-energies flowing through the Netherstorm are going to rip everything to shreds in only a few months.\n\nThat's inconvenient - now we'll have to move up the time-table on building the rocket ship!" }
WordHunterWoW_QuestEN[10184] = { title = "Malevolent Remnants", description = "Most of the spirits in the village are little more than pale remnants of Kirin Tor mages. They retain no knowledge of their former selves and wander the ruins in blind anger.\n\nIt wasn't always like this, though. In the immediate aftermath of the attack, the spirits were restless, but not spiteful. With the passage of time they have only grown more aggressive. I dare not venture into the southern part of the village, for they will not spare even me. Quiet them and let us hope it will purge their anger.", objectives = "Custodian Dieworth at Kirin'Var Village wants you to defeat 20 Severed Spirits in Kirin'Var's Town Square.", completion = "<Custodian Dieworth shakes his head gently.>\n\nIt is not what they deserved, but it is the best we can do." }
WordHunterWoW_QuestEN[10185] = { title = "A Fate Worse Than Death", description = "After the blood elves leveled Kirin'Var Village, they started the construction of a large building to the northwest. Without the expertise of the archmage, we can't say for certain what's going on there.\n\nOne thing is clear, though. The blood elf activities have unleashed a tide of ravenous mana elementals on the village. They seem drawn to the ruins of Wizard Row, wreaking further destruction. We cannot permit this to continue.", objectives = "Kill 10 Mageslayers and 10 Mana Seekers and return to Custodian Dieworth at Kirin'Var Village.", completion = "<The custodian looks dismayed.>\n\nI can already see the next wave coming over the horizon. Culling them will work for the time being, but more permanent measures are needed." }
WordHunterWoW_QuestEN[10186] = { title = "You're Hired!", description = "Let me be the first to welcome you aboard, Junior Technician 3rd Grade {name}!\n\nWe're building my masterpiece out here - the X-52 Nether-Rocket!\n\nBut first we need to get all of the parts and fuel for it.  That's where you come in.\n\nTo start, I need crystals - LOTS of crystals - for the rocket's Etherlithium Engine Matrix.  The draenei had crystals coming out of their ears!\n\nSo head north to the Ruins of Enkaat and get them for me!  Nevermind all of the draenei ghosts.", objectives = "Collect 10 Etherlithium Matrix Crystals and return them to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "Does it look like the X-52 Nether-Rocket is ready for liftoff?  Am I cruising the Twisting Nether in the comfort of my command chair?  Exploiting strange new worlds?  Seeking out new technology and business opportunities?  Boldly going where no goblin has gone before?\n\nNo!\n\nSo, I hope you have those crystals that I sent you after.", completion = "Gah!  Those look rough.  Maybe we can use them in the tertiary engine manifold chamber?\n\nStill, a good job Junior Technician 3rd Grade!  You'll make 2nd Grade in no time." }
WordHunterWoW_QuestEN[10187] = { title = "A Message for the Archmage", description = "Although things are grim here, it heartened us quite a bit to hear from you that the archmage has not forgotten the village's plight.\n\n<The custodian glances up at the tower.>\n\nIt's ridiculous, isn't it? Sometimes it seems all that separates us is a wall of mere stone. The wall of magic is easy enough to forget.\n\nIf you would be so kind, ascend the tower and let Archmage Vargoth know that we are making progress with the village and will soon have a plan to ward off the mana creatures.", objectives = "Speak to Archmage Vargoth at the top of the Violet Tower in Netherstorm.Although things are grim here, it heartened us quite a bit to hear from you that the archmage has not forgotten the village's plight.\n\n<The custodian glances up at the tower.>\n\nIt's ridiculous, isn't it? Sometimes it seems all that separates us is a wall of mere stone. The wall of magic is easy enough to forget.\n\nIf you would be so kind, ascend the tower and let Archmage Vargoth know that we are making progress with the village and will soon have a plan to ward off the mana creatures.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10188] = { title = "The Sigil of Krasus", description = "Before we departed Azeroth all those years ago, the Kirin Tor entrusted our expedition with a powerful artifact, the Sigil of Krasus. It was a great boon to us in our battle against the orcs and it could play a key role in helping me break the enchantment that imprisons me.\n\nHowever, when Kael'thas divested me of my possessions, he gave the sigil to Spellbinder Maryana, who remained behind with the garrison. If he truly realized what he had in his possession, he wouldn't have given it away so easily.", objectives = "Retrieve the Sigil of Krasus from Spellbinder Maryana at Manaforge Coruu, northwest of the Violet Tower.", progress = "If I am to be free of the tower's curse, I must have the sigil.", completion = "Ah, it is as magnificent as I remembered. Can you not feel the power radiating from it?\n\nOf course, there is much more to be done, but you have my deepest thanks for restoring the sigil to me." }
WordHunterWoW_QuestEN[10189] = { title = "Manaforge B'naar", description = "You may have noticed one of Kael's manaforges on your way here.  You know, the large purple buildings sucking energy from the sky?\n\nWe were sent here by the Sha'tar to investigate them.  You can help our information gathering efforts by obtaining a personnel roster.  Giving us an idea of who's there and what they do will prove to be invaluable information.\n\nWe believe Captain Arathyn, leading a ballista team just outside of Manaforge B'naar, is in possession of one such roster.  Obtain it for us.", objectives = "Spymaster Thalodien at Area 52 wants you to go to the outskirts of Manaforge B'naar and retrieve the B'naar Personnel Roster from Captain Arathyn.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did you obtain the items I asked of you, <name>?", completion = "Excellent!  With this roster we can make more educated decisions when targeting Kael's followers at the manaforges.\n\nIt's too bad, I was beginning to take a liking to killing his lackeys indiscriminately." }
WordHunterWoW_QuestEN[10190] = { title = "Recharging the Batteries", description = "I have the very important task of collecting the machinery inside these ruins, but I'm having a problem keeping all of my bots charged up.\n\nThe phase hunters - those wyrm-looking things - have lots of energy!  You can find them all over the edges of this island, floating in from the nether.\n\nFill the battery on this recharging blaster by using it on a phase hunter when they're very weak, and then finish it off to soak up the last of its energy.", objectives = "Use the Battery Recharging Blaster on enough Phase Hunters to get the Battery Recharge Level to 10. Then return it to Bot-Specialist Alley at the Ruins of Enkaat in the Netherstorm.", progress = "Have you recharged the battery in that blaster yet?", completion = "Hey, watch where you're pointing that thing!  You've got it set to 'Kill'!!!\n\nIt looks like you've recharged the battery, and then some.  This'll help immensely to keep these guys going." }
WordHunterWoW_QuestEN[10191] = { title = "Mark V is Alive!", description = "Greetings, {race}.  I am charged up and fully functional.\n\nThere are fragile draenei machines in these ruins, which I must retrieve.  I am equipped with delicate servos in my wrist actuators, and the latest in combustion-pneumatic bump soakers.  Handling them with care will not be an issue.\n\nHowever, the ghosts that haunt these ruins will likely attack, so I will need you and your friends along for protection.", objectives = "Escort the Maxx A. Million Mk. V through the Ruins of Enkaat and back out to safety. Then speak with Bot-Specialist Alley just outside the Ruins of Enkaat in the Netherstorm.", progress = "Back so soon?\n\nIs everything okay with the Maxx A. Million Mk. V?!", completion = "You did it!  You did it!  I could just kiss you!\n\nOh, darn... the Maxx A. Million Mk. V is out of juice again.  Ah well, he had enough to get the job done, and that's what counts!\n\nRocket-Chief Fuselage will be pleased to get these draenei machines hooked up inside the X-52 Nether-Rocket!  That means a promotion for me!  I'm so happy, I just have to give you a reward!\n\nHere, take your pick from one of these." }
WordHunterWoW_QuestEN[10192] = { title = "Krasus's Compendium", description = "The Kirin Tor sent one other of Krasus's possessions with our expedition. It was his spellbook, called Krasus's Compendium. Containing all the spells he mastered, it lent us a much-needed advantage in the war.\n\nBefore Kael'thas and his forces laid siege to Kirin'Var, the compendium had been stolen from me by a rebellious apprentice intent on studying necromancy. The apprentice and his followers divided and studied the text in secret, locking themselves inside their houses in the southern part of town.", objectives = "Reclaim Krasus's Compendium - Chapter 1, Krasus's Compendium - Chapter 2, and Krasus's Compendium - Chapter 3 from Kirin'Var Village's Town Square.", progress = "Have you brought the book?", completion = "<Archmage Vargoth's image seems to inspect the compendium.>\n\nIt's a little worse for the wear, but considering the treatment it's been through, it's a miracle all of it survived. Safeguard it, <name>. Without it, we stand little chance of being able to break the tower's ward." }
WordHunterWoW_QuestEN[10193] = { title = "High Value Targets", description = "Based on the roster information, we know that the brains of the manaforge operations are the warp-masters and warp-engineers.  It is they who oversee the retrieval of a so called \"warp-energy\" by the manaforge and its delivery to a remote destination via a system of underground pipes.\n\nThe only other specialists in the area are geologists.  Everyone else is either part of the military or a magister crony; both easily replaced.\n\nGet in there and kill Kael's specialists; that's what'll hurt him the most.", objectives = "Spymaster Thalodien at Area 52 wants you to go to Manaforge B'naar and slay 2 Sunfury Warp-Masters, 6 Sunfury Warp-Engineers and 8 Sunfury Geologists.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "You're one reliable fellow, <name>.  If there's one thing I like more than killing Kael's lapdogs, it is having someone else do it for me.\n\nLess blood on my clothes that way." }
WordHunterWoW_QuestEN[10194] = { title = "Stealth Flight", description = "While you were gone, my men uncovered another one of these manaforges.  It is east of here and is known as Manaforge Coruu.\n\nTwo of my best spies have arranged a secret landing spot outside of the manaforge.  You are to help them infiltrate Kael's forces and obtain whatever information you can.\n\nSpeak to Veronia just outside the city walls; she's arranged for a windrider that will take you to Manaforge Coruu.  Once there, speak to Caledis Brightdawn; he will brief you on your mission.", objectives = "Speak to Veronia outside Area 52 and fly to Manaforge Coruu.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", completion = "Arranging for your flight wasn't cheap.  Let's hope you have what it takes to get the job done." }
WordHunterWoW_QuestEN[10195] = { title = "Mercenary See, Mercenary Do", description = "Ever since you brought that first batch of feathers and I completed Bertelm's hat, all the other mercenaries have been clamoring for their own, including Thander. It told them I'd get right on it, but I'm going to need a steady supply of arakkoa feathers for the project.\n\nI'll gladly accept any you happen to gather in your adventures in the forest.You will receive:", objectives = "Bring 30 Arakkoa Feathers to Ros'eleth at the Allerian Stronghold." }
WordHunterWoW_QuestEN[10196] = { title = "More Arakkoa Feathers", description = "I've had some success drawing the arakkoa spirits closer to me, but they are still very shy. Perhaps if I improve my disguise, they will be more willing to approach me in the trance.\n\nTo do that, though, I'll need more feathers like the ones you've already brought me. If you get any more of the feathers, I'd be very happy to take them off your hands.You will receive:", objectives = "Bring 30 Arakkoa Feathers to Malukaz at Stonebreaker Hold." }
WordHunterWoW_QuestEN[10197] = { title = "A Convincing Disguise", description = "Infiltrating the ranks of Kael's army will not be an easy task.  With my knowledge of illusionary magic I could pass you off as one of Kael's followers, but there are certain details in their uniforms I could not replicate.\n\nBring me a set of their robes, a pair of their gloves and a Sunfury guardsman medallion.  This will make the results of my magic much more convincing.", objectives = "Obtain a set of Sunfury Arcanist Robes, one pair of Sunfury Researcher Gloves and a Sunfury Guardsman Medallion and bring them to Caledis Brightdawn at Manaforge Coruu in Netherstorm.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Have you obtained the outfit pieces I asked of you?", completion = "Excellent!  When I'm through with you, you will be able to slip among the Sunfury ranks unnoticed." }
WordHunterWoW_QuestEN[10198] = { title = "Information Gathering", description = "I've prepared a uniform with the pieces you obtained.  It is magically enhanced to complete the illusion.\n\nWe spotted Commander Dawnforge going in to meet Arcanist Ardonis a few minutes ago.  He had a full retinue of guards with him, so whatever they're discussing is bound to be incredibly important; see if you can catch any of it.\n\nOh, I almost forgot.  You'll want to stay away from the arcane golems patrolling the manaforge.  They will see right through the illusion.", objectives = "Use the Sunfury Disguise, go into Manaforge Coruu and listen to the conversation between Commander Dawnforge and Arcanist Ardonis.\n\nCompleting tasks for the Scryers will cause your Aldor reputation level to decrease.", progress = "How goes the eavesdropping, <name>?  You'd best hurry.  I'm getting antsy here.", completion = "Manaforge Duro is in trouble?  I'm sure Thalodien will love to hear the news.  Let's wrap up the job here first." }
WordHunterWoW_QuestEN[10199] = { title = "That Little Extra Kick", description = "So, I'm just missing the one ingredient that'll give my concoction that little extra kick that it needs.\n\nThe sting of the nether rays, roaming around near the shaleskin flayers, delivers quite a punch.  Bring me some of their stingers and I'll extract the venom right out of them!\n\nI'm certain the results will be explosive!", objectives = "Obtain 5 Nether Ray Stingers for Boots at Area 52 in the Netherstorm.", progress = "If I can drain the venom from enough of those nether ray stingers, I think we might just have the most explosive fuel ever devised!", completion = "Wow!  Alright, now we're talking!\n\nLet me just take those little beauties and squeeze the badness right out of them.  This should make a rocket fuel brew that'll blow everyone's socks off!\n\nHere, just let me mix the shale oil and this stinger venom together, and we'll see what happens...." }
WordHunterWoW_QuestEN[10200] = { title = "Return to Thalodien", description = "It would be best if this information got back to Thalodien as soon as possible.  I'll stay here and cover our tracks.\n\nIt wouldn't do us much good to have Kael'thas find out what we were snooping around here.  Secret information is always better if your enemy doesn't know you have it.", objectives = "Return to Spymaster Thalodien at Area 52 in Netherstorm.", completion = "You do not cease to amaze me, <name>.  That was quite the feat of stealth you pulled off at Manaforge Coruu." }
WordHunterWoW_QuestEN[10201] = { title = "And Now, the Moment of Truth", description = "The oil is finally ready for its first test. It seems heavy enough to serve as a high quality weapon oil.\n\nThe only way to find out is to have a professional try it out. See Grek over there by the wanted posters? Sure, he's no poet, but the orc knows his way around a weapon!\n\nTake a sample of the oil to him and ask him to use it on his weapon. After he's had a chance to test it out, let me know what he thinks of it.", objectives = "Find Grek and ask him to try it on his weapon. Once he's tried out the oil, return to Rakoria with the results.", completion = "<You tell Rakoria the results of the test and she throws her head back, laughing.>" }
WordHunterWoW_QuestEN[10202] = { title = "A Defector", description = "We've recently been contacted by a Sunfury magister who wishes to join our ranks and swears he has information we're in need of.  We've checked our informants to make sure he's not a double agent and he checks out.\n\nHe's stationed in Manaforge Ara which makes communication difficult.  Talk to him and see what he knows.  If he's half as useful as he claims to be, we'll be able to put him to good use.", objectives = "Go to Manaforge Ara and speak to Magister Theledorn.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", completion = "It's about time you showed up.  I was beginning to wonder if the Scryers were interested at all." }
WordHunterWoW_QuestEN[10203] = { title = "Invaluable Asset Zapping", description = "See the fissure running through Area 52?  We did that!  <grin>\n\nIt's yielding up all sorts of goodies for the X-52 Nether-Rocket, but we're running short on equipment.\n\nWe had an operation at the Arklon Ruins to the southeast until the Burning Legion moved in.  I need you to take this Ultra Deconsolodation Zapper to the ruins.  Use it to beam our gear back to Lead Sapper Blastfizzle down in the fissure.\n\nJunior Technician 3rd Grade {name}, this is your chance for that promotion.  Don't blow it!", objectives = "Use the Ultra Deconsolodation Zapper to beam the Hyper Rotational Dig-A-Matic, Servo-Pneumatic Dredging Claw, Multi-Spectrum Terrain Analyzer, and the Big Wagon Full of Explosives back to Area 52. Then report to Lead Sapper Blastfizzle at the eastern end of the fissure that runs through Area 52 in the Netherstorm.", completion = "You must be the one that zapped all of that sapping equipment back to us here from the ruins!  Hooray for you!\n\nI've already reallocated the equipment out to our other locations.  Now we'll be able to expedite our fissure operations on this whole island by an order of magnitude!  The nether-rocket will be completed in no time!\n\nHmmm, that's odd.  Wait a minute, did you say that you sent four things back to us?  I only got three..." }
WordHunterWoW_QuestEN[10204] = { title = "Bloodgem Crystals", description = "Kael's magisters have refined their usage of mana crystals to the point where they can siphon large amounts of energy in a matter of seconds.\n\nThey do this by attuning smaller bloodgem crystal shards to larger, fully charged ones.\n\nGo to Manaforge B'naar and obtain one of these shards from a Sunfury magister and use it to siphon energy from one of the larger crystals.\n\nReturn to me so that I may study the effects of the aura.  Do not worry; any side effects should be temporary.", objectives = "Magistrix Larynna wants you to go to Manaforge B'naar and obtain a Bloodgem Shard from a Sunfury Magister. Use this shard near the larger Bloodgem crystals and return to her at Area 52.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did you investigate the bloodgems used by the Sunfury magisters, <name>?", completion = "Hmmm... just as I suspected.\n\nExposure to this level of raw energy greatly magnifies our innate addiction to magic.\n\nI'm not surprised Kael gets away with what he does; all his subordinates are basically drunk on this." }
WordHunterWoW_QuestEN[10205] = { title = "Warp-Raider Nesaad", description = "Warp-Raider Nesaad must be dealt with!  I have no idea how he survived my attack, but he cannot be allowed to continue his operation out there.\n\nGo back and take out Nesaad.  He keeps a small ethereal camp near the southwestern corner of the Heap.\n\nDon't fail like I did, {class}.", objectives = "Kill Warp-Raider Nesaad and then return to Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", completion = "It's a relief to hear that scum is finally dealt with.  You do good work, <name>... may I be so forward as to call you by your name?\n\nIf you're willing, I have another task that needs doing.  One that is very important and someone of your obvious skill should be able to handle with ease." }
WordHunterWoW_QuestEN[10206] = { title = "Pick Your Part", description = "Those ethereal clowns are as opportunistic as us, I'll give them that.  But no one, and I mean NO ONE, moves in on a B.O.O.M. claim!\n\nThe Heap to the south is ours!\n\nIf we're to finish the X-52 Nether-Rocket, we're going to need all of the new tech that we can get our hands on.  And since the ethereals are stealing from us, I think it's only fair that we repay them in kind.\n\nWhy don't you head down there and see if you can acquire some of their technology out from under their noses!", objectives = "Collect 10 pieces of Ethereal Technology and return them to Papa Wheeler at Area 52 in the Netherstorm.", progress = "Back with their tech so soon?  You better not just be pulling my leg here, <class>.\n\nThe success of the X-52 project out here depends upon you getting us that stuff a.s.a.p.!", completion = "Hehe, ethereal suckers!\n\nThanks for getting us these parts, <class>.  I bet we can just hook these babies right up inside the rocket.  I wonder what they do?  Should be fun finding out!\n\nHmm, let me see if I can dig up some pocket change to throw your way." }
WordHunterWoW_QuestEN[10207] = { title = "Forward Base: Reaver's Fall REUSE", description = "Your battle prowess has been noted by high command, <class>. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Foward Commander To'arch.\n\nNow move out!Upon completion of this quest you will gain:", objectives = "Report to Forward Commander To'arch at Reaver's Fall.Your battle prowess has been noted by high command, <class>. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Foward Commander To'arch.\n\nNow move out!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10208] = { title = "Disrupt Their Reinforcements", description = "Directly east of here is the Legion Front.  Spaced across the front are infernal portals and gateways, used to bring reinforcements to Hellfire Peninsula and throughout Outland. We're going to destroy those portals!\n\nTake these primers.  Designed in Area 52, they use the demons' own power as an explosive!  Defeat Legion forces around Portals Xilus and Kruul to gather demonic rune stones, use the primer to detonate four stones inside the portals, and watch!  Return to me when your mission is complete.", objectives = "Defeat enemies around Portal Xilus and Portal Kruul to gather Demonic Rune Stones.\n\nUse To'arch's Primer within Portal Xilus and Portal Kruul.\n\nReturn to To'arch with To'arch's Primers at Reaver's Fall in Hellfire Peninsula.", progress = "The Legion won't be prepared for the surprise you have for them, eh <name>?", completion = "Well done!  I could almost feel the tremors of the explosions from here!\n\nNow, we have one more bombing mission for you..." }
WordHunterWoW_QuestEN[10209] = { title = "Summoner Kanthin's Prize", description = "The next thing we must do is reclaim my familiar, Glacius, from the blood elf summoner who holds it captive. Summoner Kanthin was one of the most senior magisters in the force Kael'thas sent to decimate Kirin'Var. It's only natural that he would claim my familiar as a kind of trophy.\n\nI'm certain that Kanthin, fool that he is, has tried to compel Glacius to serve him. My scrying has revealed that Kanthin is now stationed at 'Manaforge Duro,' if that terminology has any meaning for you.", objectives = "Defeat Summoner Kanthin at Manaforge Duro, on the island to the north of Sunfury Hold, and reclaim the Stone of Glacius from him.", progress = "Have you secured the Stone of Glacius?", completion = "<You're not sure whether it's just distortion, or the archmage really is smiling.>\n\nWith the last of my possessions restored, I have everything I need to break through Kael'thas's magic. I'll begin working the spell right away." }
WordHunterWoW_QuestEN[10210] = { title = "A'dal", description = "Welcome to Shattrath City, {class}.  This might be the one place in all of Outland where you'll find any semblance of safety.\n\nA group of naaru known as the Sha'tar drove the demons away from here.\n\nIf you've never met a naaru, you ought to see A'dal inside the Terrace of Light.  The leader of the Sha'tar is an awe-inspiring sight if I ever saw one.  Sure is a change of pace from anything else in this bleak land.", objectives = "Speak to A'dal, the leader of the Sha'tar, in the center of the Terrace of Light.", completion = "<The light that filled your senses as you approached A'dal intensifies as you address him.  Melodic chimes continue to ring within your head.>\n\n<You are safe here.>" }
WordHunterWoW_QuestEN[10211] = { title = "City of Light", description = "Do not burden A'dal with petty inquisitions, {class}.  That just might be the most powerful being you ever come face to face with.\n\nYou do not look familiar.  I suppose you want to learn about the city?\n\nYou'll have to excuse me if I don't give you a tour myself, but I'm a bit busy discussing strategy with A'dal.  Perhaps you'll find a summoned servant acceptable in my stead?  Excellent!", objectives = "Follow Khadgar's servant and listen to its story. Return to Khadgar after completing this task.", progress = "The stories of men are ephemeral, <name>.  The stories of cities last well into the years.", completion = "I hope you learned a thing or two about Shattrath, <name>.  It might take some time for things to sink in." }
WordHunterWoW_QuestEN[10212] = { title = "Hero of the Mag'har", description = "I must set things in order before I leave. Return to the Greatmother and tell her that her grandson comes.You will receive:", objectives = "Return to Greatmother Geyah at Garadar in Nagrand.I must set things in order before I leave. Return to the Greatmother and tell her that her grandson comes.You will receive:" }
WordHunterWoW_QuestEN[10213] = { title = "Investigate the Crash", description = "When I was wounded in the wastes I saw a goblin zeppelin crash.  It went down to the northwest, beyond the Expedition Armory. \n\nThe zeppelin was on fire.  Shrieking, burning goblins were falling like bombs from the sky.  Of course I was in a lot of pain and I had lost a lot of blood.  I may have imagined the whole thing.\n\nIf you can find any survivors, we can offer them sanctuary here at Spinebreaker Post.  ", objectives = "Search for crash survivors.", completion = "We were shot down by the Burning Legion, even though we waved a flag of truce.  Who knew the Burning Legion was so mean? \n\nWe cannot come with you to Spinebreaker Post.  We need to repair our zeppelin and be on our way." }
WordHunterWoW_QuestEN[10214] = { title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits, and on top of that, the peons have decided that this is a fine time for a nap! I don't know how they can sleep through all the disurbances coming from the mine, but that's the least of my problems.\n\nIf we don't get rid of those gan'arg pests soon, Thrallmar's supply of ore and other minerals will be cut off. I've already asked Watch Commander Krunk for help, but he says he can't spare the men with the town under constant attack. Will you help?", objectives = "Kill 15 Gan'arg Sappers and return to Foreman Razelcraz." }
WordHunterWoW_QuestEN[10216] = { title = "Safety Is Job One", description = "Shaffar's ethereals have completely blocked us out of the Mana-Tombs. Thankfully, I've got a plan. While we can't go in through the front door, there are sure to be several transporters inside.\n\nI want you to clear the way for my crew first and then I want you to activate one of their transporters to teleport us inside.\n\nActivate the teleporter in the chamber right before Shaffar's chambers when the way has been cleared. Don't worry, I'll make it worth your while...", objectives = "Artificer Morphalius wants you to kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers and 5 Ethereal Spellbinders.\n\nOnce that's done, find the Ethereal Transporter in the chamber before Shaffar's and activate it.", completion = "<You close your eyes and press a button.>" }
WordHunterWoW_QuestEN[10217] = { title = "Fossil Fuel", description = "My Shredder is out of fuel!You will receive:", objectives = "Test" }
WordHunterWoW_QuestEN[10218] = { title = "Someone Else's Hard Work Pays Off", description = "Who were you expecting!? That idiot Morphalius was 'de-prioritized.' Now I'm here to clean up his mess. All I need from you is to watch my back as I go through Shaffar's ether gatherers and suck them dry of all that they have collected. If I successfully complete my mission, Haramad himself will reward you!\n\nWhat do you say? Escort me through the Mana-Tombs and then collect some incredible treasure? You already did most of the work anyway! Nothing's alive back behind us, right?", objectives = "Escort Cryo-Engineer Sha'heen safely through the Mana-Tombs so that he can gather the ether held inside Shaffar's ether collectors.\n\nReport to Nexus-Prince Haramad located outside the Mana-Tombs at the Consortium encampment should you succeed.", completion = "Seeing as how this was Morphalius's idea, I decided to give him his old job back. Well done little flesh beast. Well done, indeed!\n\nRemember, if you're ever looking for work and happen to be in Netherstorm, come find me at the Stormspire." }
WordHunterWoW_QuestEN[10219] = { title = "Walk the Dog", description = "", objectives = "" }
WordHunterWoW_QuestEN[10220] = { title = "Make Them Listen", description = "I was sent here to make contact with the Unyielding spirits.  These once proud Alliance soldiers were defeated long ago, and now their cursed spirits haunt the ruins to the west.  \n\nIf they would only join us we would gain a powerful ally.  Imagine, a legion of undying warriors to use against our enemies.  But these undead are mad with hatred and will not listen to me.  \n\nPerhaps they can be forced to join us.  ", objectives = "Mordiba wants you to defeat 12 Unyielding Footmen, 8 Unyielding Knights, and 6 Unyielding Sorcerers at the Expedition Armory to the west of Spinebreaker Post.", completion = "The Unyielding have felt the strength of the Horde.  No doubt they will soon be in the mood to listen to my proposed alliance." }
WordHunterWoW_QuestEN[10221] = { title = "Dr. Boom!", description = "{name}, my former protege, Sparky Uberthruster, wouldn't wear his helmet while down here and one day transformed into the infamous Dr. Boom!\n\nAnd he stole off to the northeast with most of our sapping equipment!  He and his Boom Bots have been a menace to Area 52 ever since.\n\nI need you to go to his Camp of Boom just outside of town and put an end to him!  Use these Boom's Doom bombs to take him out.\n\nAnd make sure not to get too close to him or his Boom Bots!", objectives = "Kill Dr. Boom and return with the good news to Lead Sapper Blastfizzle at Area 52 in the Netherstorm.", progress = "Have you saved us from the depredations of Dr. Boom?  I promise this time there won't be any exploding wagons, though that was a lot of fun!\n\nWe really should do that more often.", completion = "I'll always miss Sparky.  <sniff>  But we'll all sleep better now knowing that as Dr. Boom he is no longer around to terrorize us!\n\nJust let this be a lesson to you.  Don't come down here without a nether helmet!\n\nNow, how can I repay you?" }
WordHunterWoW_QuestEN[10222] = { title = "The Sunfury Garrison", description = "After Prince Kael'thas's forces destroyed the village and imprisoned the archmage in the Violet Tower, they withdrew to Sunfury Hold to the northeast. The very men who destroyed our village and slew our fellows toast their 'amazing victory' while we are helpless to avenge the fallen.\n\nWe must not allow these crimes to go unanswered! Be the instrument of our vengeance, {name}. Go to Sunfury Hold and claim the lives of those responsible for this crime.", objectives = "Custodian Dieworth at Kirin'Var Village wants you to kill 10 Sunfury Archers.", completion = "What you've done this day can never bring back the fallen, but perhaps it can help soothe their spirits. Although, truth be told, no amount of blood can quench my anger over the actions of Kael'thas." }
WordHunterWoW_QuestEN[10223] = { title = "Down With Daellis", description = "I'll never forget the blood elf who led the attack. He wore a tabard with a device I've never seen before, over top of crimson armor.\n\nHe was ferocious and merciless, leading from the front where most other blood elf officers would never be seen. He was responsible for the deaths of many Kirin Tor mages that day, but he didn't linger long at Sunfury Hold. Kael'thas has ordered him to Manaforge Duro to aid in their attempt to control the area. Find him, {name}, and silence his bow for good.", objectives = "Custodian Dieworth at Kirin'Var Village wants you to kill Master Daellis Dawnstrike.", progress = "Have you finished the task, <name>?", completion = "<You're not certain, but it seems as though Custodian Dieworth is on the verge of tears.>\n\nAt last, it is through. If I could will myself out of existence, I would, but the truth is I don't know how to let go. For the ones in the village, it is difficult but straightforward. I suppose this is the price we pay for retaining such strong ties to this place." }
WordHunterWoW_QuestEN[10224] = { title = "Essence for the Engines", description = "As the X-52's chief of engineering, I have to see to it that the nether-rocket's main engines are in tip-top shape.\n\nUnfortunately, I haven't built them yet.\n\n{class}, I'm in dire straits here!  I have almost all of the parts.  All that I'm missing is the engine core.\n\nLuckily for us, I think we can make use of the essence from the local mana wraiths to jump-start the engines.\n\nThey can be found near most of the glowing trenches in the northern part of the island.  Except for here in Area 52, of course.", objectives = "Collect 7 Mana Wraith Essences and return them to Chief Engineer Trep at Area 52 in the Netherstorm.", progress = "You have all of those essences yet?", completion = "Wow, that's a lot of essence!\n\nOk, let's see what happens when I mix it with the etherlithium matrix crystals." }
WordHunterWoW_QuestEN[10225] = { title = "Report to Engineering", description = "{name}!  I need you to take all of these etherlithium crystals over to Chief Engineer Trep, my, uh, chief of engineering.\n\nHe should know what to do with them.  And if he doesn't, you see to it that he finds out!", objectives = "Deliver the Etherlithium Matrix Crystals to Chief Engineer Trep at Area 52 in the Netherstorm.", progress = "Um, hi.   I'm a little busy here.  What's that you have there?", completion = "Ooh, etherlithium matrix crystals.  Yeah, those sound important!\n\nLet's just put them over here and I'll get to figuring them out in a moment." }
WordHunterWoW_QuestEN[10226] = { title = "Elemental Power Extraction", description = "Darn it, that didn't do it!\n\nOk, I've got another idea!  I had Xyrol whip up an elemental power extractor.  I'm not certain exactly what this power will do, but I know that I can use it.\n\nThe sundered rumblers and warp aberrations on the ledge of the Crumbling Wastes to the south have just what I need for the engines!\n\nThe extractor will change the form of their power into something solid that you'll be able to gather up after you've defeated them.", objectives = "Extract 5 Elemental Power for Chief Engineer Trep at Area 52 in the Netherstorm.", progress = "You have the power from those elementals yet?  Oh, don't hurry or anything.  It's just my life and career on the line.", completion = "That's more like it!  Alright, now I think we're in business.\n\nJust let me dump this stuff into the thing-a-ma-jig here and I'm sure it'll spit out a fully functioning phase engine core.\n\nOh, hey, I guess I ought to reward you for saving my neck!  Hehe." }
WordHunterWoW_QuestEN[10227] = { title = "I See Dead Draenei", description = "I see dead draenei. They're all around us.\n\nBah, nobody believes me because I'm a child. Not even my own mommy believes me.\n\n<Ha'lei points to Ramdor.>\n\nHe believes me, though... He sees them too. Boy does he get angry about it!\n\nIt's kind of funny. I see ghosts and people just smile and pat me on the head, trying to placate me. Ramdor sees ghosts and people label him as crazy. I sure hope I never grow up!\n\nYou should probably talk to Ramdor before you go inside. He was once a death priest.", objectives = "Speak to Ramdor the Mad, standing on the bone pile outside of the Auchenai Crypts.", completion = "The child is correct. I was once a \"death priest.\"\n\n<Ramdor winces.>\n\nSuch an unsavory title.\n\nThrough that corridor lies the Auchenai Crypts. Inside you will find the remnants of my priory. They are all mad now, of course. Insane to the last! I suppose I stood out, being the last one among them with any common sense. Of course, I was excommunicated for my beliefs.\n\nWhat are my beliefs, you say?" }
WordHunterWoW_QuestEN[10228] = { title = "Ezekiel", description = "I believe that the dead, which we have been caring for these last 500 odd years, should be left alone. Maladaar has other plans. He has retreated to the Crypt of Remembrance to start his experiments... Necromancy.\n\nI hope you weren't thinking about going in there... Not before helping me out so that these damned spirits will finally leave me alone. I know where they keep their treasures, {race}. Got your attention, eh?\n\nBring me the book of the dead, held by the Aldor, Ezekiel of Shattrath.\n", objectives = "Find and speak with Ezekiel of Shattrath in Shattrath City.", completion = "Book of the dead? Never heard of it... What's this about anyway? Who sent you?" }
WordHunterWoW_QuestEN[10229] = { title = "Decipher the Tome", description = "This tome appears to be some sort of history written in a secret Alliance cipher.  Althen, the historian in Spinebreaker Post, has studied the Unyielding for some time; he may be able to crack the Alliance code and decipher the book.  ", objectives = "Take the Mysterious Tome to Althen the Historian in Spinebreaker Post.", progress = "What is this?  A book carried by an Unyielding spirit?  How strange.  Let me study it.  Perhaps I can learn the history of the Unyielding.", completion = "I have studied ancient history my entire un-life.  I have never seen anything like this book.  It tells the entire history of the Armory, including events that happened after its destruction.  \n\nThe Unyielding have kept their history, even after they had fallen in battle.  With this book we will be able to understand the Unyielding and convince them to join us." }
WordHunterWoW_QuestEN[10230] = { title = "The Battle Horn", description = "Perhaps we have taken the wrong approach to the Unyielding? \n\nThe tome tells me the Expedition Armory was destroyed by orcs and death knights long ago.  The Unyielding remain here as vengeful spirits trapped in an eternal battle against the fel orc clans.  \n\nThey think only of revenge.  We must arrange for them to defeat their most hated enemies.  Enter the Expedition Armory once again and find Lieutenant Commander Thalvos.  He carries a battle horn that can summon the Unyielding.  Bring it to me.  ", objectives = "Take the Unyielding Battle Horn from Lieutenant Commander Thalvos and bring it to Althen the Historian in Spinebreaker Post.", progress = "We must help the Unyielding soon.  If we can convince them to join us the Horde will have gained a powerful ally.", completion = "You have done well <name>.  This ancient horn will allow us to summon the Unyielding. \n\nThat is, if they are willing." }
WordHunterWoW_QuestEN[10231] = { title = "What Book? I Don't See Any Book.", description = "Ramdor? Hrm, let me think... Ramdor... Oh yes, the death priest. What does he want with the book? Well it doesn't matter. Yes I lied to you and no I don't have the book. Not anymore, anyway. It was stolen. Probably by one of those filthy refugees.\n\nBesides, Auchindoun is now defunct. We have no use for the book. If you find it, you can keep it.\n\nLike I said, I saw some of those ruffians snooping around the terrace last week. Start your search with them. They're probably playing dice in the slums.", objectives = "Ezekiel said the book has been stolen. Your best bet is to find the Ruffians and see if they have any information.", progress = "Whaddya want?", completion = "Ok, ok! Don't hurt us. We had the book but we sold it..." }
WordHunterWoW_QuestEN[10232] = { title = "In A Scrap With The Legion", description = "The Burning Legion has moved in on our claim at the Scrap Field down the path and across the bridge to the east.\n\nThis could be a huge problem for us!  With the Legion at the Arklon Ruins, and now there, it's starting to look bad for us - and the rocket project - here at Area 52.\n\n{name}, I need you to go out there and deal with those demons!  I'd do it, but I'm a lover, not a fighter.\n\nYep, this is going to be trouble, I can feel it!", objectives = "Kill 5 Mo'arg Doomsmiths and 15 Gan'arg Engineers. Then return to Papa Wheeler at Area 52 in the Netherstorm.", completion = "Well, that's good and bad news, now isn't it?  We've dealt them a blow, but with the Burning Legion running free all over the Netherstorm - and getting closer to us here - well, I don't know how it's going to go.\n\nI have a feeling that we're going to have to change gears here for a while.  Hope you'll be able to help us out, <name>." }
WordHunterWoW_QuestEN[10233] = { title = "Torching Sunfury Hold", description = "Ridding Sunfury Hold of its garrison is not sufficient to keep the blood elves from reoccupying it. Kael'thas's followers are zealous and tenacious. Leaving them anything to use at Sunfury is effectively an invitation to return.\n\nNo, it must all be destroyed. See to it that their tents and artillery burn to ashes!\n\n<The ghost's fists clench.>\n\nSteal torches from the Sunfury flamekeepers to accomplish your task, {name}.", objectives = "Using a Flaming Torch, destroy 4 Sunfury Ballistas and 4 Sunfury Tents and return to Lieutenant-Sorcerer Morran at Kirin'Var Village.", completion = "<Lieutenant-Sorcerer Morran nods grimly.>\n\nThe Kirin Tor hardly relish destruction for its own sake, but we have no qualms about acting against our enemies, even in death." }
WordHunterWoW_QuestEN[10234] = { title = "One Demon's Trash...", description = "You look like a capable young man!  I was wondering if you could lend me a hand?\n\nTo the east is the Scrap Field, which the Burning Legion has moved into.  It's full of huge fel reaver parts.  There're also a whole bunch of smaller parts in there that they don't seem to care about.\n\nI want you to get in there and get me a lot of those smaller fel reaver parts!", objectives = "Gather 10 Fel Reaver Parts and return them to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", progress = "You have those parts yet?  With the Burning Legion moving in on each of our claims around here one at a time, we unfortunately have little time.", completion = "These will have to do for now, I suppose.  If only we could scare them off.\n\nHey, that gives me an idea!" }
WordHunterWoW_QuestEN[10235] = { title = "Declawing Doomclaw", description = "You know what might just discourage them?  Take out their leader!\n\nIt seems to work everywhere else from what I've heard.  And when they see a grizzled {class}, such as yourself take out their leader... why, I bet they'll tuck tail and run for the hills!\n\nGet back in there and take out the big one they call Doomclaw.  I hear he keeps himself in the eastern part of the Scrap Field underneath the pipe.\n\nBring me his claw, too!  Maybe we can make use of it.", objectives = "Obtain Doomclaw's Hand and deliver it to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", progress = "Dealt with Doomclaw yet?", completion = "He, uh... he said what?  THEY'RE GONNA GO AFTER AREA 52?!\n\nOh, this is not good... not good!" }
WordHunterWoW_QuestEN[10236] = { title = "Outland Sucks!", description = "I can't believe I left Booty Bay to come to Outland. My cousin Screed Luckheed promised me I would make a fortune, but instead he flew off in his zeppelin and left me here to try to scrape a living out of this mine. \n\nHow am I supposed to make a living here with helboars and demons and fel orcs attacking all the time? My shredder here was broken yesterday and the parts I need to fix it were stolen by fel orcs. They took the parts into the fissure to the southwest and may have dropped them there.", objectives = "Find 6 Shredder Parts and return to Foreman Razelcraz by the mine northwest of Thrallmar.", progress = "Did you find some spare parts for my shredder?  I really want to get it fixed so I can get back to mining.  I have to make a living somehow, if only so I can buy a one-way ticket back to Booty Bay.", completion = "Hurray, you found some parts!  Now maybe I can get my shredder working.  If I earn enough money I might be able to get back to Booty Bay. \n\nI sure hope my cousin, Screed Luckheed, crashes that stupid zeppelin of his.  I can't believe he tricked me into coming to Outland." }
WordHunterWoW_QuestEN[10237] = { title = "Warn Area 52!", description = "{name}, you have to get word back to Area 52 immediately!  Hurry!\n\nTell the rocket-chief that the Burning Legion is after us now!", objectives = "Deliver the bad news to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", completion = "Heh, you're kidding, right?  The Burning Legion is blaming us for all of that?\n\nBut YOU'RE the one that did it!\n\nOy, I have a headache and it's as big as this rocket.  Okay, okay, this calls for a change of plans.\n\nIf the Burning Legion thinks that it's going to come here, destroy our town and ruin my dream of cruising through the Twisted Nether, they are sadly mistaken.\n\nAnd I know just the goblin to help us out." }
WordHunterWoW_QuestEN[10238] = { title = "How to Serve Goblins", description = "Why would fel orcs steal my shredder parts?  I hate them so much.  They just sneak into my camp here and take things all the time.  A couple of days ago they stole three of my peons!  Now the rest of my peons have run off because they are afraid they are going to be eaten by fel orcs.  \n\nI can't run a mine without peons.  If you could save the peons that I lost maybe the others would come back.  The fel orcs have their camps along the wall to the southwest.", objectives = "Rescue Manni, Moh and Jakk from the Fel Orc camps and return to Foreman Razelcraz by the mine northwest of Thrallmar.", completion = "Thank you for saving my peons.  Now maybe I can get them to fix my shredder with those parts you found, earn some money and get out of Outland.  I can't wait to be back in Booty Bay." }
WordHunterWoW_QuestEN[10239] = { title = "Potential Energy Source", description = "We are not the only ones battling the influx of the mana beings. The blood elves, too, are troubled by them, but I'm not sure why.\n\nWhatever they're involved in over there, they don't seem to be stopping. Instead, I've seen them employ a variety of methods to kill the creatures. The most effective involves magical defenses fueled by some sort of concentrated energy.\n\nCapture some of these energy sources and bring them to me. Don't hesitate to stymie the elves if an opportunity presents itself.", objectives = "Lieutenant-Sorcerer Morran at Kirin'Var Village wants you to capture 10 Energy Isolation Cubes from the blood elf operations at Manaforge Coruu.", progress = "Were you able to gather any of their energy sources?", completion = "<Morran gingerly handles one of the containers.>\n\nI don't believe I've seen anything like this before. There's certainly a lot of energy suspended in here, but it's in a raw form. We'll have to be careful with it, but I think we can find a way to adapt this to help ward off the mana creatures." }
WordHunterWoW_QuestEN[10240] = { title = "Building a Perimeter", description = "We are prepared to try to construct a perimeter around the village using the energy source taken from the blood elves. I can't guarantee that it will work, but we have to attempt it.\n\nOtherwise, the mana creatures will surely continue devouring the spirits of the fallen Kirin Tor.\n\nUse this device at the small runes around the perimeter of town to release the energy there. If I've woven the field correctly, we should start noticing a difference once you've used the device at each point.", objectives = "Use the Rune Activation Device near the East Rune, Northeast Rune, and West Rune. The runes can be found around the perimeter of Kirin'Var Village's Wizard Row and Town Square districts. Return to Lieutenant-Sorcerer Morran once you've completed the task.", progress = "Have you activated all the runes? I'm eager to see if we can't improve upon the blood elf method here. Anything one of Kael'thas's men can do, real Kirin Tor can do better.", completion = "Excellent work. Keep your fingers crossed, <name>. I'm going to activate the shield." }
WordHunterWoW_QuestEN[10241] = { title = "Distraction at Manaforge B'naar", description = "We were sent here by the Sha'tar to investigate the manaforges that Kael'thas' army is operating here.  Unfortunately, the Scryers threaten to renege on their information-gathering duties unless we support them with military action.\n\nWe can't afford to compromise this mission over politics, so we've agreed to weaken the manaforge's defenses so that the Scryers can do their work.\n\nProve your loyalty to the Aldor and slay the Sunfury magisters and bloodwarders that guard Manaforge B'naar.", objectives = "Slay 8 Sunfury Magisters and 8 Sunfury Bloodwarders and return to Exarch Orelis at Area 52.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", completion = "Excellent work, <name>.  The Scryers have uncovered valuable information thanks to your distraction.  Maybe they'll actually share it with us this time." }
WordHunterWoW_QuestEN[10242] = { title = "Spinebreaker Post", description = "{name}, my equipment here is, unfortunately, not configured for all the tests I'd like to perform.  However, my colleague at Spinebreaker Post, Apothecary Albreck, possesses the required implements.\n\nI have acquired a sample of Bleeding Hollow blood -- gained from a past mission of Thrallmar's agents.  Take the sample to Albreck and allow him to study it.\n\nTo reach Spinebreaker Post, speak with Wing Commander Brack, near the wyverns to the south.", objectives = "Apothecary Zelana at Reaver's Fall wants you to speak with Wing Commander Brack to take a wyvern to Spinebreaker Post, and then bring the Bleeding Hollow Blood Sample to Apothecary Albreck at Spinebreaker Post.", progress = "Welcome to Spinebreaker Post.  How might my talents serve you?", completion = "A blood test, is it?  It will be my pleasure.  I always enjoy working with blood..." }
WordHunterWoW_QuestEN[10243] = { title = "Naaru Technology", description = "The Scryers obtained a personnel roster for Manaforge B'naar and are now having a field day picking out assassination targets.\n\nThey've missed one small bit of information, scribbled on the side of the roster.  It appeared to be a password or code like those used to access naaru-made technology like the Exodar or Tempest Keep.\n\nGo inside the manaforge and look for a control panel.  Copy its readouts on this scroll as well as you can.  We must confirm our suspicions about the origin of the technology.", objectives = "Go inside Manaforge B'naar and find the B'naar Control Console.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "The symbols scrolling in front of you look alien and unintelligible.", completion = "You unwrap the scroll and ready yourself to copy down the strange symbols." }
WordHunterWoW_QuestEN[10244] = { title = "R.T.F.R.C.M.", description = "Cracking the seal on this rather large tome, you can't quite make out what the words say.  They appear to be written in the language of demons.\n\nHowever, you can make out the pictures, which tell their own story.\n\nThis is clearly a fel reaver construction manual, and you know for a fact that Mama Wheeler will want to take a look at it!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Fel Reaver Construction Manual to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm." }
WordHunterWoW_QuestEN[10245] = { title = "B'naar Console Transcription", description = "You try to transcribe the shapes as you see them flash across your eyes.  The results are less than exact, but should serve as adequate evidence to prove or disprove the Aldor's suspicions.", objectives = "Deliver the B'naar Console Transcription to Anchorite Karja at Area 52 in Netherstorm.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Let us see what you've brought to us, <name>.", completion = "You've done well, <name>.  Allow me a few moments to go over your transcription.\n\nYou have the priesthood's thanks, <class>." }
WordHunterWoW_QuestEN[10246] = { title = "Attack on Manaforge Coruu", description = "Your success at Manaforge B'naar was quite noteworthy.  I'm sure that Anchorite Karja will ask you for a repeat performance at Manaforge Coruu next.\n\nWe've learned of a particularly important regiment of Sunfury arcanists and researchers being deployed there and I would like you to target them.  Succeed and you will deliver a crushing blow against our enemy's forces.", objectives = "Travel to Manaforge Coruu and slay 8 Sunfury Arcanists and 5 Sunfury Researchers. Return to Exarch Orelis when you've completed this task.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "Excellent job, <name>.  With your dedication we're sure to defeat our enemy." }
WordHunterWoW_QuestEN[10247] = { title = "Doctor Vomisa, Ph.T.", description = "On the outskirts of town to the east are the Proving Grounds.  Our top experimentalist, Doctor Vomisa, has been toying with a combination of fel reaver, ethereal, and of course, goblin technologies there.\n\nThis is in no small part thanks to your gathering efforts Junior Technician 3rd Grade, {name}!\n\nGo to him; I know that he'll have a solution for saving Area 52.\n\nAnd since he's likely to use you as a test subject, if I were you, I'd bring some friends along just in case.", objectives = "Speak with Doctor Vomisa, Ph.T. at the Proving Grounds in Netherstorm.", completion = "Well, well, it would appear that we are in luck, young man.\n\nI was just recently able to finish the construction of my latest invention, the Scrap Reaver X6000!\n\nAnd you're going to have the honor of helping me test it so that it can be used in defense of Area 52!" }
WordHunterWoW_QuestEN[10248] = { title = "You, Robot", description = "Doctor Vomisa, Ph.T. at your service.  Here, take this controller.  I want you to activate it and give my newly-invented Scrap Reaver X6000 a spin.\n\nJust stay nearby!  The controller is tied to my console here, and if you get too far away, the robot will cease to function.\n\nTry out everything... I'll be watching and calibrating its servos based upon your test run.", objectives = "Activate the Scrap Reaver X6000 Controller and test out its capabilities. Then give your feedback to Doctor Vomisa, Ph.T at the Proving Grounds in the Netherstorm. Deal with any problems that arise.", progress = "What did you think?  Still needs some tweaking, eh?", completion = "Well, my boy that certainly was exciting!  And for my money, I'd say that the Scrap Reaver X6000 performed admirably, despite its rookie pilot.\n\nHehe, no, don't take offense, I was just kidding.  After all, you just saved Area 52 and the X-52 Nether-Rocket from certain doom!" }
WordHunterWoW_QuestEN[10249] = { title = "Back to the Chief!", description = "I'm certain that the rocket-chief is going to want to have a word or two with you!\n\nIf I were you, I wouldn't hesitate to get back to Area 52 and speak with him!", objectives = "Report to Rocket-Chief Fuselage at Area 52 in the Netherstorm immediately!", completion = "<name>!  Or, should I say Junior Technician 1st Grade <name>?!  Oh hell, who am I kidding?  Skipping a grade isn't a good enough reward for what you've done.  I'm going to make you my first officer!\n\nYou've saved all of us, and more importantly the X-52 Nether-Rocket!  I could just kiss you... but I won't.\n\nInstead, please let me present you with the gratitude of Area 52.  Take your pick!" }
WordHunterWoW_QuestEN[10250] = { title = "Bloody Vengeance", description = "East of here is an old destroyed Alliance siege tower.  Now scavengers loot it for old nails and bits of scrap.  Long ago, many Alliance warriors lost their lives at this tower and their banner was captured by Urtrak, a foul orc commander.\n\nBlow the Unyielding battle horn near the Alliance banner.  This will get the attention of Urtrak.  It may also summon forth warriors who fell in battle long ago.", objectives = "Blow the Unyielding Battle Horn near the Alliance Banner. Kill Urtrak and then return to Althen the Historian at Spinebreaker Post.", progress = "Have you blown the horn by the siege tower yet?  We must do this soon.  Who knows when Thrallmar will have need of the Unyielding.", completion = "I am glad to hear that the Unyielding joined you in your battle.  I thought they might come to the sound of their own battle horn, but I could not be sure.  Perhaps we have given some of them the vengeance they so desperately crave.  \n\nYou have slain Urtrak and we must report your victory to Commander Hogarth in the Expedition Armory.  He will understand the risks you have taken on his behalf." }
WordHunterWoW_QuestEN[10251] = { title = "The Master's Grand Design?", description = "A couple of draenei paid us a visit last night. They'd somehow learned that we had the book in our possession and made a very generous offer to \"take it off our hands.\"\n\nWe didn't ask them what they wanted with the book but the young one kept talking about \"the master's grand design,\" whatever that means.\n\nLook, I don't ask questions when money is in play. They gave us a lot of gold and we gave them the book.\n\nHe said that they lived in Nagrand - in the old Abandoned Armory, north of Telaar.", objectives = "Find Nitrin the Learned at the Abandoned Armory in Nagrand.", completion = "The signs were all there but I turned a blind eye.\n\nThe Legion's grasp grows stronger every day. Even in these parts...\n\nHad I known... Had I known that my boy was communing with demons... They offered him power and then gave him a taste of that power. That was all that it took...\n\nThe book is gone. Taken by Levixus... His plans are known only to me and his dark master.\n\nStranger, I don't know if you've ever done right in your life, but know this: the boy must be stopped." }
WordHunterWoW_QuestEN[10252] = { title = "Vision of the Dead", description = "It has already begun. Levixus stands atop the ruins of Auchindoun and reads from the book of the dead. He calls the dead out by name and, through demonic ritual, binds the tortured souls to his will. He will raise all of Auchindoun if given the chance!\n\nBut... you must first prepare. You cannot do battle with that which you cannot see.\n\n<Nitrin hands you a parchment.>\n\nBring me the items I require to brew the tincture. It will open your mind and allow you to see into the spirit world.", objectives = "Nitrin at the Abandoned Armory in Nagrand wants you to bring him 1 Mountain Gronn Eyeball, 1 Flawless Greater Windroc Beak, and 1 Aged Clefthoof Blubber.", progress = "Levixus's army grows in size and power with each second that passes. You must hurry.", completion = "Stranger... I was not forthright with you. Once you drink this potion, you will forever see into the world of the dead. This recipe that you drink of is a rite of initiation for all death priests of Auchindoun. Many go mad after its effects have taken hold. Seeing the dead is ... shocking.\n\n<Nitrin puts the potion up to your lips.>\n\nDo you wish to continue?" }
WordHunterWoW_QuestEN[10253] = { title = "Levixus the Soul Caller", description = "Go now, {name}. You will find Levixus on the uppermost ruins of Auchindoun. Enter there from the southern reaches of the Bone Wastes. He stands amidst a storm of souls...\n\nDestroy him and take the book of the dead. Once you have the cursed book in your possession, destroy it! Destroy it so that such an atrocity can never again be made possible.", objectives = "Destroy Levixus and take the Book of the Dead from his possession.\n\nDeliver the Book of the Dead to Ramdor the Mad standing outside the Auchenai Crypt entrance of Auchindoun.\n\nYou had a deal, remember?", progress = "Who are you and what do you want? Oh... It's YOU.", completion = "If the old draenei said to destroy the book, why didn't you?\n\n<Ramdor glares at you.>\n\nBah, what's the difference. You might be greedy but at least you're honest.\n\nMe on the other hand... I lied to get this book. I have no idea where these poor lost souls kept their treasure nor would I tell you if I did - however - I do have something for you. You did a good thing on this day. Perhaps a great thing... You should be rewarded.\n\nBy the way, welcome to the fold.\n\n<Ramdor points to the spirits.>" }
WordHunterWoW_QuestEN[10254] = { title = "Force Commander Danath", description = "<Marshal Isildor spits in the dust.>\n\nWell, time to earn your pay. Report at once to Force Commander Trollbane within the keep. He and his advisors will no doubt be heartened to see you.\n\n<Marshal Isildor salutes you stoically.>\n\nFor the Alliance!", objectives = "Marshal Isildor wants you to report to Force Commander Danath Trollbane in Honor Hold.", completion = "Well met, my brother.  I'm glad you've come. I am Danath - leader of the Sons of Lothar, and force commander of this hold." }
WordHunterWoW_QuestEN[10255] = { title = "Testing the Antidote", description = "I think there's something we can use in the blood as the base of an antidote. Don't look at me like I've lost my mind!\n\nIt's a common theme in nature. Often, the cure for something can be derived from the toxin itself. That's just what I aim to do.\n\nRidding the boars of their demonic influence would probably eliminate their aggression and give us insight into how to best attempt to help other species.", objectives = "Use the Cenarion Antidote on a Hulking Helboar and observe the results. Once you have the results of the experiment, return to Thiah Redmane at the Cenarion Post in Hellfire Peninsula.", progress = "Do you have the results of the experiment?", completion = "<Thiah Redmane's eyes widen as you describe the results of the experiment.>\n\nBut, how could that happen? I'm certain I prepared the antidote correctly!\n\nI've seen it work with spider and snake venoms, so why would it backfire here? Perhaps that's one of Outland's many peculiarities, <name>. I'd best pass this information along to my comrades." }
WordHunterWoW_QuestEN[10256] = { title = "Finding the Keymaster", description = "In retrospect, I suppose I should've expected Kael'thas's magic to be this robust. He's always been a talented mage, but I've never seen anything like the power he wielded during the attack on the tower.\n\nThe ward keeps me from being able to scry out the force holding it in place, but it doesn't preclude you from scrying.\n\nYou'll require a focus, though. A crystal-bearing giant named Apex roams the plains to the west of Manaforge Duro. One of its crystals would make an excellent scrying focus.", objectives = "Locate Apex and obtain Apex's Crystal Focus from him. Return to the Violet Tower and use Apex's Crystal Focus near Archmage Vargoth's Orb to discover who holds the key to breaking the tower's curse.", progress = "What did your scrying reveal?", completion = "<You describe the results of your scrying.>\n\nCommander Sarannis, you say? Hmm...\n\nShe's one of Kael'thas's advisors, but certainly not a mage. I remember her from the attack on Kirin'Var Village. I think your impressions are correct, <name>. She's not maintaining the curse personally, but she holds the key to it." }
WordHunterWoW_QuestEN[10257] = { title = "Capturing the Keystone", description = "It doesn't surprise me that Kael'thas has put the key to this ward in the hands of someone like Commander Sarannis. Prince Kael'thas is a great many things, but he is no simpleton.\n\nIn order to break this curse once and for all, you must enter Tempest Keep and claim the keystone.\n\nOnly once the keystone has been destroyed will I regain my freedom.", objectives = "Venture into Tempest Keep's Botanica and retrieve the Keystone from Commander Sarannis. Bring it to Archmage Vargoth at the Violet Tower.", progress = "Did you obtain the keystone?", completion = "<The archmage's eyes light up when you hand him the stone.>\n\nAmazing! From what little I've seen of the fate of Farahlon, I'm not certain I want to go outside, but it's much better than being trapped here for the rest of my days." }
WordHunterWoW_QuestEN[10258] = { title = "Honor the Fallen", description = "Hogarth, the commander of the Armory, is in the eastern tower.  You must report your victory over Urtrak to him.  Perhaps he will be friendly?  Of course he may try to consume your soul.  One can never tell with spirits such as these. \n\nThe Unyielding are still against us and will no doubt kill you if they can.  Be careful {name}.  ", objectives = "Report to Commander Hogarth in the Expedition Armory.", completion = "We lost our battle against the fel orcs so very long ago. You have restored some of our lost honor by killing Urtrak. \n\nTake one of our weapons with you.  When you are fighting our most hated foes, use this weapon, and those who are free of our curse will come to your aid.  \n\nBefore you leave, those who died at the siege tower wish to honor you for destroying our enemies." }
WordHunterWoW_QuestEN[10259] = { title = "Into the Breach", description = "Battle rages non-stop at the portal!  The Argent Dawn is fighting a desperate fight -- and if we lose, then there will be no end to the demon's fire.\n\nHelp us, <name>.  Enter the breach and lend aid to our brothers and sisters.  Help stem this tide of darkness!  The Argent Dawn -- and the world -- needs you!You will receive:", objectives = "Kill 6 Invading Felguards and then return to Argent Emissary Proudwell." }
WordHunterWoW_QuestEN[10260] = { title = "Netherologist Coppernickels", description = "You must have crossed the main bridge into Netherstorm from Blade's Edge.  Did you see Netherologist Coppernickels working with all of his crazy equipment there?\n\nStrange... I've been expecting a report from him and it's overdue.  He's probably forgotten.  You know those 'science' types.\n\nHead back out to the bridge and pin him down.  Don't accept any of his excuses, just get me that report.\n\nThanks!Upon completion of this quest you will gain:", objectives = "Speak with Netherologist Coppernickels at the bridge leading into the Netherstorm from Blade's Edge.You must have crossed the main bridge into Netherstorm from Blade's Edge. Did you see Netherologist Coppernickels working with all of his crazy equipment there?\n\nStrange... I've been expecting a report from him and it's overdue. He's probably forgotten. You know those 'science' types.\n\nHead back out to the bridge and pin him down. Don't accept any of his excuses, just get me that report.\n\nThanks!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10261] = { title = "WANTED: Annihilator Servo!", description = "WANTED:  1 Annihilator Servo to replace the failing one in my Long Neck Spectrum Analyzer.\n\nYou and your friends might want to check with the blood elves at Manaforge B'naar to the west to see if they have any spares.  They seem to have a few arcane annihilators roaming about.\n\nPlease deliver the servo in pristine condition to Papa Wheeler at Area 52.", objectives = "Obtain an Annihilator Servo and deliver it to Papa Wheeler at Area 52 in the Netherstorm.", progress = "I hope that you're here concerning the wanted ad that I placed!", completion = "Woo hoo!  Do you know how hard these things are to come by?  It's not like I'm getting a regular shipment of parts out here.\n\nTell you what, as payment I want you to take something out of my box of junk.  I'm sure there'll be something in there you can use.  And if not, sell it.\n\nAlright, let me just take that off of your hands and get it into my Long Neck Spectrum Analyzer before the failing servo in it explodes!" }
WordHunterWoW_QuestEN[10262] = { title = "A Heap of Ethereals", description = "There is something else that I want your help with.\n\nA group of ethereals, known as the Zaxxis, have cut their relationship with the Consortium and gone into business for themselves.  They've even cut deals with the Sunfury blood elves.  This will not be tolerated!\n\nI infiltrated their group at the Heap to the south.  But after I took out their leader, I had to escape here to Area 52.\n\n{class}, go down there and bring back their insignias.  Of course, not all wear them because they're cowards.", objectives = "Collect 10 Zaxxis Insignias and return them to Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", progress = "Is it done?  Have you wiped the Zaxxis scum from the face of Outland and brought me their insignia?", completion = "These insignia are a good start.\n\nUnfortunately while you were at the Heap, one of my other agents amongst the Zaxxis sent word to me that Warp-Raider Nesaad still lives!" }
WordHunterWoW_QuestEN[10263] = { title = "Assisting the Consortium", description = "The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things.\n\nLuck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured.\n\nThere's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals.  As a representative of the Aldor, I would like for you to help him in any way that you can.", objectives = "Speak with Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", completion = "Hello, <race>.\n\nYou don't happen to be available for a recovery mission of some importance?" }
WordHunterWoW_QuestEN[10264] = { title = "Assisting the Consortium", description = "The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things.\n\nLuck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured.\n\nThere's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals.  As a representative of the Scryers, I would like for you to help him in any way that you can.", objectives = "Speak with Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", completion = "Hello, <race>.\n\nYou don't happen to be available for a recovery mission of some importance?" }
WordHunterWoW_QuestEN[10265] = { title = "Consortium Crystal Collection", description = "Our leader, Nexus-Prince Haramad, has tasked me with the acquisition of a crystal artifact from the Arklon Ruins to the southeast.\n\nThey're old draenei ruins.  Unfortunately for both myself and the goblins here, the Burning Legion has decided to move in to perform their own excavation.\n\nIf you're willing to help me, go to the ruins and take the crystal artifact from the dreadlord named Pentatharon.", objectives = "Obtain an Arklon Crystal Artifact and return it to Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", progress = "I get the impression that the prince is looking for a particular crystal, but I'm not certain what it is.\n\nHave you already recovered the one from the dreadlord?", completion = "Let me have a look at that.\n\nHmm, there doesn't appear to be anything special about it.  I doubt this is it, though the manner in which you describe the Burning Legion's activities at the ruins, it sounds as if they're searching for something in particular as well.\n\nLet us hope that it's not the crystal that the nexus-prince wants so badly." }
WordHunterWoW_QuestEN[10266] = { title = "Request for Assistance", description = "While you were at the Arklon Ruins, I received a request for assistance from one of our representatives out in the field.  It would appear that the Consortium is having some 'difficulties' in trying to recover property from the blood elves, which they refuse to pay for.\n\nPlease head east out of Area 52 and cross the bridge to the next island over.  You'll find my associate, Gahruj, at the Midrealm Post, just inside of Eco-Dome Midrealm.", objectives = "Seek out and offer your services to Gahruj. He is located at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", completion = "Yes, it's true.  The blood elves have reneged on yet another purchase of goods that has already been delivered.\n\nAs Nether-Stalker Khay'ji has vouched for you, I am hopeful that you will be able to assist me in this matter." }
WordHunterWoW_QuestEN[10267] = { title = "Rightful Repossession", description = "Our business relations with the blood elves appear to be at an end.  A few weeks ago a large shipment of surveying equipment was delivered to them at Manaforge Duro.  They have refused to pay for it.\n\n{name}, I would ask that you pay the blood elves of Manaforge Duro to the east a visit.  They appear to be having some trouble with an infestation of mana creatures there, so take advantage of their preoccupation.\n\nI care not what happens to them, but I would very much like to see the return of our property.", objectives = "Collect 10 Boxes of Surveying Equipment and return them to Gahruj at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", progress = "Do you have possession of the surveying equipment which the blood elves defaulted on?", completion = "Well, I for one am glad that this petty little business is behind us.  I cannot remember a time when the Consortium has had dealings with such boorish and untrustworthy beings.\n\nYou, however, seem to be very trustworthy, <name>.  Perhaps you wouldn't mind doing me one more favor?" }
WordHunterWoW_QuestEN[10268] = { title = "An Audience with the Prince", description = "Nexus-Prince Haramad has conveyed to me that he is interested in the immediate return of this property to him personally.  I would greatly appreciate if you would deliver it in my stead.\n\nIt is a great honor to gain an audience with the nexus-prince, and I am sure that he would be keenly interested in hearing the tales of your adventures here in the Netherstorm.\n\nSeek out his chamber atop the Stormspire to the north.  He is often present as a holographic image, which you may address.", objectives = "Deliver the Surveying Equipment to the Image of Nexus-Prince Haramad at the Stormspire in the Netherstorm.", progress = "Approach.", completion = "I welcome you to the Stormspire, <class>.  Please enjoy the hospitality of the Consortium.\n\nYou may place that equipment anywhere.  I suspect that you'll be picking it back up rather soon." }
WordHunterWoW_QuestEN[10269] = { title = "Triangulation Point One", description = "There is another reason for the retrieval of the surveying equipment.  There is a crystal from draenei legend of great importance to me.\n\nIt is said that the crystal bestows god-like powers to its bearer!  But it is in danger of being unearthed by others - namely the Burning Legion.\n\n{name}, take the equipment and use it to find the first triangulation point.  We know it to be somewhere to the east near Manaforge Ultris.\n\nAfterward, check-in with my agent, Dealer Hazzin, on the Manaforge Ultris island.", objectives = "Use the Triangulation Device to point your way toward the first triangulation point. Once you have found it, report the location to Dealer Hazzin at the Protectorate Watchpost on the Manaforge Ultris island in the Netherstorm.", progress = "Hello, traveler.  You come to Hazzin because you are in need of my goods?", completion = "<Dealer Hazzin lowers his voice to a whisper.>\n\nAh, I know of your mission.  It is one of great importance to Nexus-Prince Haramad!\n\nNow that we know the location of this first triangulation point, you must move swiftly to find the second!" }
WordHunterWoW_QuestEN[10270] = { title = "A Not-So-Modest Proposal", description = "From the look on your face, I can tell you're a {race} who appreciates a good profit.\n\nI've built a reputation as a dealer in exotic goods, and I'm about to launch a new venture.\n\nI need a reliable subcontractor to procure the goods from the Celestial Ridge.\n\nFirst, you'll need to re-energize a teleport pad. There is a spare power pack in Access Shaft Zeon, which is on the south side of Manaforge UItris. The Protectorate is operating in there, so you may be able to follow their tracers to your goal.", objectives = "Retrieve the Teleporter Power Pack and bring it to the Ethereal Teleport Pad on the Celestial Ridge to the east of Manaforge Ultris. Activate the pad and give the Teleporter Power Pack to the Image of Wind Trader Marid so he can install it.", progress = "Are you prepared to discuss business now, <name>?", completion = "This power cell should hold for our purposes. Once the money starts rolling in, we'll improve it even more.\n\nEnough with such things. Every moment spent in discussion translates to lost profit." }
WordHunterWoW_QuestEN[10271] = { title = "Getting Down to Business", description = "As you've no doubt seen, the area is teeming with nether dragons in various stages of growth. All nether dragons, young and old, contain an essence that's highly desired by K -- err, by a client of mine.\n\nMost people aren't willing to risk their lives to gather it, so we've got the place to ourselves. You can start by gathering the essence from any of the creatures out here, but it's imperative that we start building a supply right away. Return to me once you have the first batch.", objectives = "Charge the Essence Gatherer by using it on Nether Drakes or Nether Dragons on the Celestial Ridge, then return to the Ethereal Teleport Pad area.", progress = "I'm certain you have many questions, all of which will be answered in due time.", completion = "And to think, that wretched ethereal was going to sell these essences to the blood elves like so much candy..." }
WordHunterWoW_QuestEN[10272] = { title = "A Promising Start", description = "We've come here to investigate rumors of a strange breed of dragons, perhaps even descendents of Deathwing himself. These are clearly not ordinary black dragons, though.\n\nWe'll know more once we've had a chance to examine their eggs. Their hatred for my flight runs deep, so I can't get close enough to gather the eggs. Will you agree to help?", objectives = "Gather 15 Nether Dragonkin Eggs, then return to Tyri and Jorad on the Celestial Ridge.", progress = "Were you able to gather the eggs?", completion = "These will work quite nicely, <name>. Thank you for agreeing to help us.\n\nBefore we can continue, however, there is something else we'll need to address." }
WordHunterWoW_QuestEN[10273] = { title = "Troublesome Distractions", description = "Your former employer, Wind Trader Marid, must've gotten wind that you're helping us now. Through my projection, I've seen his nether-stalkers entering the area, hoping to track us down.\n\nWe've been able to evade them so far, but Marid must be dealt with before the problem grows more severe.\n\nIf your impressions of Marid are correct, he'll do just about anything to secure the supply of his product. Return to him and tell him you're prepared to offer a deal. Lure him away and slay him.", objectives = "Speak with Wind Trader Marid and lure him away from his trading post. Deal with him and then return to Tyri and Jorad on the Celestial Ridge.", completion = "Now that that troublesome ethereal has been dealt with, we can focus our efforts on understanding these nether dragons. I've had a chance to examine the eggs and I've made a few discoveries." }
WordHunterWoW_QuestEN[10274] = { title = "Securing the Celestial Ridge", description = "The nether dragons have the same ferocious temperament as their black dragon forbears, but there is something entirely alien about them. They hatch and mature rapidly, harnessing the strange energies that forged their kind in the destruction of Draenor.\n\nThere is so much more I need to know about them, but I believe the powers may be of use to my own flight. If we can displace the leader of these drakes, Veraku, with a show of dominance, we can cow the rest of them into submission.", objectives = "Use the Challenge of the Blue Flight to provoke Veraku on the southern edge of the Celestial Ridge. Defeat him and return to Tyri and Jorad on the Celestial Ridge.", progress = "Have you challenged and defeated Veraku?", completion = "Well done, <name>. Well done indeed. The nether dragonkin will not accept a blue dragon among them at first, but with time and the firm demonstration of my authority, they will come around. Scattered, isolated, and without a definitive leader, we must be vigilant in preventing them from falling under the sway of a malevolent power, keeping them in check all the while." }
WordHunterWoW_QuestEN[10275] = { title = "Triangulation Point Two", description = "I've recalibrated the triangulation device with the information that you provided from the first point.  You'll use it in exactly the same manner to discover the second.\n\nAll that I can tell you is that the second point is somewhere far to the west.\n\nOnce you've located it, speak with Wind Trader Tuluman; another of the nexus-prince's agents.  He's posing as a weapon merchant at a small trading post next to the bridge, which leads to the island that Manaforge Ara is on.", objectives = "Use the Triangulation Device to point your way toward the second triangulation point. Once you have found it, report the location to Wind Trader Tuluman at Tuluman's Landing, just on the other side of the bridge from the Manaforge Ara island in the Netherstorm.", progress = "You wish to buy or sell?", completion = "Very good indeed.  The nexus-prince shall be pleased!\n\nWe now have the second point, which will now tell us where the third is, and the general vicinity of the crystal!" }
WordHunterWoW_QuestEN[10276] = { title = "Full Triangle", description = "With the data from both the first and second points, I'm now certain that the crystal is at the top of the Ruins of Farahlon to the northeast.\n\nUnfortunately, the data indicates that the crystal is moving, which means that it has already been discovered, probably by the Burning Legion!\n\nJust in case, I recommend that you take some friends along.\n\nSlay the demon that has the crystal and return it to Nexus-Prince Haramad.", objectives = "Recover the Ata'mal Crystal and deliver it to the Image of Nexus-Prince Haramad at the Stormspire in the Netherstorm.", progress = "Hello again, my friend.  How fare your efforts to find the crystal?", completion = "Beyond my wildest dreams, I never thought that you would be able to retrieve the crystal!\n\nAnd then to actually give it to me!  Do you have any idea how powerful it is?\n\nYour selflessness is inspirational and beyond reproach, <name>!  You have given me much to think about." }
WordHunterWoW_QuestEN[10277] = { title = "The Caverns of Time", description = "Greetings, {name}. Please follow the custodian. She will make things a bit more... clear.", objectives = "Andormu at the Caverns of Time has asked that you follow the Custodian of Time around the cavern.", progress = "Do not return until you have at least a rudimentary understanding of what is happening.", completion = "Hopefully you now have a better understanding of what is expected of you." }
WordHunterWoW_QuestEN[10278] = { title = "The Warp Rifts", description = "Long have I wandered through Outland, searching for the truth of the void.  Now I am old and weak.  Perhaps you will help me? \n\nI must learn the secrets of the voidwalkers.  You must find the Warp Fields to the west.  West of the Expedition Armory there is a dark place on the edge of the abyss where time and space are weak.  Use my unstable warp rift generator in the Warp Fields to create a warp rift.  You must gather warp nether from the creatures that come through.  ", objectives = "Use the Unstable Warp Rift Generator in the Warp Fields. Gather 3 Warp Nethers from Unstable Voidwalkers and return them to Ogath the Mad in Spinebreaker Post.", progress = "Have you managed to use my experimental device yet?  I think my unstable warp rift generator will work out there so close to the abyss.", completion = "Unbelievable.  You have touched the void itself!  <name>, you have saved my life's work.  But there is more that must be done, and you can help me." }
WordHunterWoW_QuestEN[10279] = { title = "To The Master's Lair", description = "Ah, {name}. We have been expecting you. Please, allow one of my brothers to fly you down to the master. He awaits you below...", objectives = "Speak to Andormu at the Caverns of Time.", completion = "We must prepare you for the battles that lie ahead..." }
WordHunterWoW_QuestEN[10280] = { title = "Special Delivery to Shattrath City", description = "I am an ethereal of my word, {name}.  You have truly inspired me.\n\nI am now going to give you the ata'mal crystal to hand over to the naaru.  As it was your heroics that made this possible, I wish for you to deliver it.\n\nYou may use my personal teleporter to go directly to Shattrath City.  Simply step through it and you will be transported there.\n\nGive the crystal to the naaru known as A'dal on the Terrace of Light.  May the trade winds be at your back.", objectives = "Deliver the Ata'mal Crystal to A'dal on the Terrace of Light in Shattrath City.", progress = "<The musical tinkling of the naaru's speech fills your mind.>\n\nI sense that you have something of great power with you, <race>.  What is it that you bring to me?", completion = "You have recovered Spirit's Song!  It is the ata'mal crystal that Prophet Velen left behind with his people for safekeeping before he went upon his ill-fated mission to the Exodar.\n\nOdd that he did not foresee it falling into the hands of the Burning Legion, if even for a short time.\n\nOr, perhaps he did?  It may be that he foresaw all of this, and left it there so that you would retrieve the crystal and deliver it to me here?\n\nI sense that is the truth of it.  You are a great hero of your people, <name>!" }
WordHunterWoW_QuestEN[10281] = { title = "Formal Introductions", description = "Greetings, {name}. Do not be alarmed. This is merely a projection of my current form. It's the only way my companion and I could keep watch without revealing ourselves.\n\nThe ethereal who approached you, Marid, is little better than a swindler in the guise of a legitimate merchant. I'd like you to consider working with me instead. My purpose out here is to find out more about the unusual dragonkin on this ridge. Meet me at the north end of the ridge and we will discuss this further.", objectives = "Find Tyri at the north end of the Celestial Ridge and speak with her.", completion = "My name is Tyrygosa, of the brood of Malygos, but most call me 'Tyri.' My companion is the paladin Jorad Mace.\n\nWord of these strange dragonkin has already traveled far and I fear that too many will rush to exploit them for profit without realizing the true nature of what they're dealing with. With your help, we're hoping to gain insight into these creatures before others discover their presence." }
WordHunterWoW_QuestEN[10282] = { title = "Old Hillsbrad", description = "To the west is the timeway to Hillsbrad of the past - 7 years to be exact.\n\nForces are working against the Horde warchief, Thrall, attempting to prevent him from ever escaping Durnholde Keep.\n\nIf Thrall never escapes, this world - as you know it - will cease to exist.\n\nGather a group of adventurers and take the timeway to old Hillsbrad. Two of our agents await you inside.\n\nSpeak with Erozion on the other side.", objectives = "Andormu at the Caverns of Time has asked that you venture to Old Hillsbrad and speak with Erozion.", completion = "Our worst fears might soon be realized. The forces at work behind this temporal disturbance are a new flight of dragons known as the Infinite. We do not know where they came from or why they are destroying timeways.\n\nIn this pocket of time, they have kidnapped Taretha Foxton, daughter of Tammis Foxton, the secretary of Aedelas Blackmoore, ruler of Durnholde and overseer of all internment camps on Azeroth." }
WordHunterWoW_QuestEN[10283] = { title = "Taretha's Diversion", description = "Taretha was integral in Thrall's survival and upbringing and instrumental in shaping Thrall's life.\n\nIt was Taretha who created the original diversion at Durnholde, allowing Thrall to escape.\n\nNow the Infinite have captured Taretha and hold her at Tarren Mill. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges in Durnholde. When you have done this, speak with young Thrall in the basement prison of Durnholde.", objectives = "Travel to Durnholde Keep and set 5 incendiary charges at the barrels located inside each of the internment lodges using the Pack of Incendiary Bombs given to you by Erozion.\n\nSpeak to Thrall in the basement prison of Durnholde Keep when you have the Internment Lodges Set Ablaze.", completion = "You are friends of Taretha? So this is her new plan? Very well then..." }
WordHunterWoW_QuestEN[10284] = { title = "Escape from Durnholde", description = "You look upon me now and see only a boy, but in my heart and soul I hide my dreams. I have plans for my people, stranger. One day, they shall overthrow their oppressors and rise as one. They will break free from the bonds that hold them and from that uprising shall be born the orcish Horde.\n\nI promise you, stranger, should we make it out of here alive, when I have the means to reward this selfless deed, I will seek you out... I will find you.\n\n<Thrall nods.>\n\nWe will leave when you are ready.", objectives = "When you are ready to proceed, let Thrall know. Follow Thrall out of Durnholde Keep and help him free Taretha and fulfill his destiny.\n\nSpeak with Erozion in Old Hillsbrad should you complete this task.", completion = "You have done a great thing, <name>. Alas, the young warchief's memory of these events must be as they originally were... Andormu awaits you in the master's lair." }
WordHunterWoW_QuestEN[10285] = { title = "Return to Andormu", description = "This timeline has been restored and the assault of the Infinite Dragonflight upon Hillsbrad has been squashed.\n\nReturn to Andormu at once. He awaits your arrival in the master's lair.", objectives = "Return to the child Andormu at the Caverns of Time in the Tanaris desert.", completion = "Please accept a gift from the bronze flight. These items will assist you in your journeys through time." }
WordHunterWoW_QuestEN[10286] = { title = "Arelion's Secret", description = "Arelion's journal does not deal with any sort of scholarly studies.  It details his escapades with a young female blood elf!  How could I've been such a fool?\n\nUnfortunately, the floozy's identity is not revealed in this journal.  Aledis, a colleague of Arelion's, was his best friend and confidant.  Go question him and find out who he was having this affair with.\n\nI saw Aledis leave Falcon Watch for Zangarmarsh.  Follow the road headed north from town; it'll eventually lead west, toward Zangarmarsh.", objectives = "Magistrix Carinda wants you to interrogate Magister Aledis, last seen traveling from Falcon Watch to Zangarmarsh.", completion = "I'll talk, <class>.  Put your weapon down, I don't want any more trouble." }
WordHunterWoW_QuestEN[10287] = { title = "The Mistress Revealed", description = "I'm Arelion's friend, but I'm not going to take the beating of my life for him.  His mistress is Viera Sunwhisper.\n\nGo tell that harpy of a wife of his.  What's she going to do anyway?", objectives = "Return to Magistrix Carinda at Falcon Watch in Hellfire Peninsula.", completion = "Viera Sunwhisper?  That lousy little brat.\n\nI will show her I'm not one to be trifled with!" }
WordHunterWoW_QuestEN[10288] = { title = "Arrival in Outland", description = "I want you to speak with Amish Wildhammer and catch the first flight to Honor Hold. When you arrive at Honor Hold, you'll be greeted by Marshal Isildor. I have prepared a report detailing our situation here.  Give him the report, and tell him you're ready for duty.\n\nYou have your orders, soldier, now move out!  And though your blood must be burning to help us against the fiends below, waste no time here.  Honor Hold needs you even more.", objectives = "Commander Duron at the Dark Portal in Hellfire Peninsula wants you to bring Duron's Report to Amish Wildhammer.", progress = "I saw you speaking with Duron over there.  You must be on an important mission!", completion = "Reports for Honor Hold?  No problem -- we'll get you there fast and safe on one of my gryphons!" }
WordHunterWoW_QuestEN[10289] = { title = "Journey to Thrallmar", description = "When you're ready, I'll summon a wyvern to fly you to Thrallmar. Once you arrive, deliver Orion's report to General Krakork.\n\nLok'tar ogar, {name} - good luck.", objectives = "Take Vlagga Freyfeather's Wind Rider to Thrallmar. Bring Orion's Report to General Krakork.", progress = "A report from Orion? Give it here, quickly!\n\n<Frowning, General Krakork quickly scans the tattered document.>\n\nDamn, it's just as we feared. Orion and his warriors could be overrun at any moment!", completion = "I'll rally what troops I can and send them to aid Orion's forces at the Dark Portal. The Legion will not soon forget the battle cry of the Horde! As for you <name>, you've done a great service for Thrallmar this day. I expect you'll be a great help to us here... if you have the wits to survive, that is." }
WordHunterWoW_QuestEN[10290] = { title = "In Search of Farahlite", description = "To the northeast is an area called the Netherstone, a landmark not seen when this was a lush, green land. Newly-exposed crystal formations have shown us a mineral we've called farahlite in honor of this land's former identity.\n\nThe tiny amount of farahlite we've mined has already proven popular with our clients. The highest grade of the mineral comes not from static deposits, but from the giants around the Netherstone. I can offer you a cut of the profits if you'll help supply the higher grade farahlite.", objectives = "Gather 4 pieces of Raw Farahlite and return to Zuben Elgenubi at the Stormspire.", progress = "I understand the dangers of gathering farahlite are great, but so are the opportunities. A merchant who isn't willing to take the risk may as well close his doors and save himself the trouble.", completion = "Ah, yes. This is precisely the grade I was hoping for. We may give up mining the crystal formations altogether if we can secure a supply from the giants." }
WordHunterWoW_QuestEN[10291] = { title = "Report to Nazgrel", description = "Though our warriors are without peer, our hold on this wasteland is still tenuous. Report to Nazgrel inside the barracks - he has need of agents... such as you. If we can't protect our holdings here, we'll be of no use to anyone. Now go!", objectives = "General Krakork in Thrallmar wants you to speak with Nazgrel.", completion = "We've already lost many brave warriors to this cursed wasteland. I have little interest in sending more untested recruits to the slaughter.\n\n<Nazgrel glares at you sternly through his ragged wolf-mask>\n\nStill, if General Krakork sent you to me, he must have seen something in you. What say you then, <name>? Will you serve your warchief with honor?" }
WordHunterWoW_QuestEN[10292] = { title = "More Power!", description = "Gathering a precious commodity in small batches has a quaint, cottage-industry feel to it, but it's just not competitive in today's market.\n\nNo, what we need is a method of mass producing farahlite! Then, the quantity on the market will be completely within our control.\n\nI have an idea, but it's going to require a powerful, focused energy source. There's only one possible place to find an energy source powerful enough. Go to the Legion's camps to our north and 'procure' some of their cannon.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Zuben Elgenubi wants you to capture 8 Legion Cannon and bring them back to the Stormspire." }
WordHunterWoW_QuestEN[10293] = { title = "Hitting the Motherlode", description = "Now that we've got a good baseline product, we're going to need something of higher quality. Certainly the farahlite we've gathered so far is nice, but I know there's better out there.\n\nWe'll have to get a sample directly from Cragskaar, the patriarch of the Farahlon giants! You should be able to find it among the other giants in the Netherstone area. It's got huge pieces of farahlite jutting from its back and that's exactly what we need. Fell the giant and collect a farahlite core from it.", objectives = "Zuben Elgenubi at the Stormspire wants you to obtain a Farahlite Core.", progress = "You're still alive, which means you've either got the core, or you've changed your mind. Which is it?", completion = "Well done! I can't wait to put this to the test." }
WordHunterWoW_QuestEN[10294] = { title = "Void Ridge", description = "We have to improve my warp rift generator.  You must take it to Void Ridge.  Head east of here.  You must avoid the foul fort of Zeth'Gor.  To the east beyond Zeth'Gor is a small pass through the mountains.  Through this pass you will find Void Ridge, a terrible place on the edge of the abyss.\n\nYou must kill the walkers that you find there, and bring me shards of their souls.  With their power we will improve upon the warp rift generator and open a portal to the beyond that cannot be closed.  ", objectives = "Go to Void Ridge and kill the creatures you find. Collect 40 Void Ridge Soul Shards and return them to Ogath the Mad in Spinebreaker Post.", progress = "You have done it then?  You have the shards that we need?", completion = "Excellent, the warp rift generator is almost complete.  There is only one final ingredient we require.  Soon we shall be able to open up a warp rift to the deepest parts of the abyss.  \n\nWho knows what strange creature may come through?  Think of it <name>, the power such knowledge will bring is limitless." }
WordHunterWoW_QuestEN[10295] = { title = "From the Abyss", description = "My warp rift generator is complete. You can now use it to summon a true prince of the void, a creature whose soul shard will tell us much of what lies beyond.  \n\nGo south in Void Ridge and use my warp rift generator near the void stones.  Look for a cluster of crystals near the edge of the abyss.  A huge warp rift will form and Void Baron Galaxis will surely appear.  \n\nDestroy this creature and bring me his soul shard.  ", objectives = "Kill Void Baron Galaxis and collect his soul shard. Take the shard to Ogath the Mad in Spinebreaker Post.", progress = "Have you destroyed Void Baron Galaxis yet?", completion = "You have saved my life's work <name>.  \n\nThey called me insane, they laughed at me, they thought I was mad for my obsession with the Void Ridge and Warp Fields.  Now with this soul shard I can unlock the secrets of the voidwalkers.  I will command the power of the abyss." }
WordHunterWoW_QuestEN[10296] = { title = "The Black Morass", description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.", objectives = "Travel through the Caverns of Time to the Black Morass during the opening of the Dark Portal and speak with Sa'at.", completion = "Indeed, if the orcs never make it to Azeroth, the Alliance will never form. Eventually civil war will break out, further weakening the human kingdoms.\n\nUltimately the Burning Legion will invade Azeroth, destroying it in the absence of any defenders." }
WordHunterWoW_QuestEN[10297] = { title = "The Opening of the Dark Portal", description = "Beyond this timeway the Guardian, Medivh, feverishly works to open the Dark Portal.\n\nScattered across the morass, rifts will materialize. Infinite will pour out of the rifts and attempt to destroy Medivh's shields and, ultimately, Medivh.\n\nKill their rift lords and leaders! Do this until Medivh succeeds.", objectives = "Sa'at inside the Black Morass of the Caverns of Time has tasked you with defending Medivh until he succeeds in opening the Dark Portal.\n\nReturn to Sa'at should you succeed in your task.", progress = "Use your chrono-beacon if you require aid. You may only use one chrono-beacon per pocket of time.", completion = "You have done well, <name>. The timeways are safe once more." }
WordHunterWoW_QuestEN[10298] = { title = "Hero of the Brood", description = "Return to the child, Andormu, <name>. He awaits you outside this pocket of time, in the master's lair.\n\nI hear flutterings. The Scale of Sands has shown interest in your abilities. Perhaps they too would like to speak with you.", objectives = "Return to the child, Andormu, at the Caverns of Time in the Tanaris desert.", completion = "Once more you have secured the present and the future of this world, <name>. Please accept these items as reward for your accomplishments." }
WordHunterWoW_QuestEN[10299] = { title = "Shutting Down Manaforge B'naar", description = "We cannot shut down the manaforges by force as we'd risk causing an explosion that would shake Outland to the core.\n\nAccording to your transcription, there is an emergency shutdown that permanently disables the technology - a safety mechanism common in naaru constructs.\n\nTo perform this procedure you will have to obtain a crystal that will allow you to communicate with the console.  This access crystal is in the possession of an overseer called Theredis according to our information.", objectives = "Return to Manaforge B'naar and obtain the B'naar Access Crystal from Overseer Theredis. Use it at the Manaforge B'naar console to shut it down and report back to Anchorite Karja.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you succeeded in your task, <name>?", completion = "The Light smiles upon you, <name>.  We were all praying for your success." }
WordHunterWoW_QuestEN[10300] = { title = "Rebuilding the Staff", description = "<Ravandwyr inspects the staff, noting that part of the headpiece seems to be missing.>\n\nSimply barbaric! Ekkorash must've taken the staff's crystalline headpiece for use in some other trinket, not realizing that it works in concert with the rest of the staff.\n\nAs long as it remains broken, the staff's power is greatly diminished. With a suitable draenei crystal, I should be able to repair it. I've heard the goblins remarking about the crystals carried by the ghosts at the Enkaat Ruins to the north.", objectives = "Obtain 4 Flawless Crystal Shards from the ghosts at the Enkaat Ruins and return them to Ravandwyr at Area 52.", progress = "Have you managed to find some suitable crystals for a new headpiece for the archmage's staff?", completion = "<Ravandwyr carefully examines the crystals, then selects one.>\n\nThis crystal should work. I'll reshape the stave's socket to secure the new headpiece.\n\nWhen Archmage Vargoth sees it, he will be disappointed, but I can bear my master's disappointment if it means we've freed him." }
WordHunterWoW_QuestEN[10301] = { title = "Unlocking the Compendium", description = "While I'm glad to have most of Krasus's Compendium back, it's useless without the heliotrope oculus. You see, Krasus was well aware of the sheer power of the spells recorded in the book and took steps to safeguard them from prying eyes.\n\nOnly a knowledgeable mage can use the oculus to unlock the compendium's secrets.\n\nDuring Kael'thas's attack, one of his lieutenants, Spellreaver Marathelle, looted it and took it to Sunfury Hold northeast of the tower. No doubt she thought it a pretty little bauble.", objectives = "Obtain the Heliotrope Oculus from Spellreaver Marathelle at Sunfury Hold.", progress = "Have you recovered the oculus?", completion = "Excellent, <name>. Now, we have most of what we'll need to attempt to break Kael'thas's magic.\n\nAnd if the blood elves suffer from the loss of their local commander, so much the better." }
WordHunterWoW_QuestEN[10302] = { title = "Volatile Mutations", description = "The irradiated power cores from the Exodar have been wreaking havoc on the environment here. The most obvious effect has been the appearance of the strange creatures that seem to have sprung up near them.\n\nThere may be something we can do to help them, but now, their sheer numbers are becoming too much for us to handle.\n\nI'd like you to go out and cull their numbers somewhat, and perhaps I'll have another idea after giving it some thought.", objectives = "Kill 8 Volatile Mutations, then return to Botanist Taerix at the Crash Site in Ammen Vale.", progress = "I am working on a solution I think may be effective with the strange creatures. I just need more time.", completion = "You're finished? That's good news. Hopefully, we can find a way to avoid the killing of these mutated beasts in the future.\n\nI believe I have formed a plan that might give us an alternative solution to this problem, but I will need your help." }
WordHunterWoW_QuestEN[10303] = { title = "The Blood Elves", description = "You must eliminate... the blood elf... threat.  Find out... what they're... up to!\n\nThey're on the... ridge behind me.", objectives = "Kill 10 Blood Elf Scouts then return to Tolaan in the Shadow Ridge of Ammen Vale.", progress = "There are too many of them... We must whittle them down or else the survivors will have no chance against them.", completion = "These blood elves mean to kill us all. How are we to divert them from this course?" }
WordHunterWoW_QuestEN[10304] = { title = "Vindicator Aldar", description = "With your help, we were able to find a solution to our problems faster than I could have hoped.\n\nI don't have any other work for you to do. My apprentices and I can handle the rest.\n\nYou should go speak with Vindicator Aldar on the other side of the ship.", objectives = "Speak with Vindicator Aldar at the Crash Site in Ammen Vale.", completion = "<name>, is it? I've heard good things about you and the work you've been doing in the short time since you came to.\n\nWe'll definitely need your help getting things back to normal. Zhanaa, over there, could also use your help, I'm sure." }
WordHunterWoW_QuestEN[10305] = { title = "Abjurist Belmara", description = "This worn, sturdy tome is no spellbook, as you might expect a Kirin Tor mage to carry. The pages of the volume are covered with hand-copied stories, accompanied by colorful illustrations.\n\nThe tome seems to be far older than its former owner and may have even been a family heirloom. A powerful tie to the book may have been the last thread tying Belmara's spirit to the ruins of Kirin'Var. Returning it to its proper place on the bookshelf in her quarters might help appease her restless spirit.", objectives = "Locate Abjurist Belmara's quarters in Wizard Row and return the book to its Bookshelf. Then, speak with Custodian Dieworth at Kirin'Var Village.", completion = "Ah, yes. I'd heard that Abjurist Belmara had an old book of stories, but I had no idea that she brought it with her to Outland. I'm certain her spirit will rest easier knowing that you've found it and returned it to her dwelling." }
WordHunterWoW_QuestEN[10306] = { title = "Conjurer Luminrath", description = "The cloak, undoubtedly of high elven craftsmanship, is richly tailored, even by the standards of the Kirin Tor. The symbols and characters sewn into the cloak's fabric hold no meaning for you, but clearly imbue the garment with magical properties.\n\nPerhaps this object binds the spirit of its former owner to this plane of existence. If so, returning it to the dresser in Conjurer Luminrath's quarters might break the spirit's link to this world, allowing it to rest.", objectives = "Locate Conjurer Luminrath's quarters in Wizard Row and return the mantle to his Dresser. Then, speak with Custodian Dieworth at Kirin'Var Village.", completion = "We used to always comment that Luminrath would wear that cloak with just about anything. To him, red went equally well with white, black, purple, blue, yellow, orange, and green. He would never wear the same robe two days in a row, but the cloak was always there..." }
WordHunterWoW_QuestEN[10307] = { title = "Cohlien Frostweaver", description = "Looking at the hat, you find yourself asking if any Kirin Tor mage would own such headgear. Judging from the hat's wear, it seems the gnome wouldn't go anywhere without it.\n\nYou try on the hat momentarily, discovering no magical properties beyond a faint urge to dance.\n\nThe treasured possession might be the source of the dead mage's bond to the village. Placing the hat in the footlocker in Cohlien's quarters might free his spirit.", objectives = "Locate Cohlien Frostweaver's quarters in Wizard Row and return the hat to his Footlocker. Then, speak with Custodian Dieworth at Kirin'Var Village.", completion = "<The custodian smiles at the mention of Cohlien's name.>\n\nYou're absolutely right about the hat. He wore it all the time and wouldn't let it out of his sight.\n\nThere were a couple of times when a fellow mage, who shall remain nameless, 'borrowed' the hat and hid it as a prank. Needless to say the threat of one of Cohlien's frostbolts changed his mind.\n\nI'm going to miss little Cohlien. He had quite a way with the elven women." }
WordHunterWoW_QuestEN[10308] = { title = "Another Heap of Ethereals", description = "", objectives = "The Consortium is keenly interested in wiping out all of the Zaxxis rebels at the Heap to the south.\n\n<class>, if you would like to ingratiate yourself further with us, go back down there and bring back more of their affiliation insignia.", progress = "The Consortium is keenly interested in wiping out all of the Zaxxis rebels at the Heap to the south.\n\n<class>, if you would like to ingratiate yourself further with us, go back down there and bring back more of their affiliation insignia.", completion = "Traitors, all of them!\n\nGood work, <class>!  If you find your way back down there again, I'm always looking to add to my collection of their insignia!" }
WordHunterWoW_QuestEN[10309] = { title = "It's a Fel Reaver, But with Heart", description = "You see that scrapped fel reaver over there to the south?  Isn't it a thing of beauty?\n\nI want its heart!\n\nWhat?  Yes, of course it has a heart... what doesn't?\n\n<N. D. looks indignant for a moment.>\n\nGo on over there, pry it open, bring back what I want and I'll give you a nice finder's fee in return.\n\nOh, and I'd take a friend or two along if I were you.  These Zaxxis ethereals are a pretty mean bunch!\n\nTake this fel zapper to jumpstart its heart when you're ready to begin.", objectives = "Recover the Heart of the Fel Reaver and deliver it to N. D. Meancamp at The Heap in the Netherstorm.", progress = "My eyesight must be going from all of the nether radiation.  You have that fel reaver's heart yet?", completion = "Wow, look at that... a beating fel reaver heart!  Well, it's not really 'beating', but you know what I mean.\n\nI can't wait to put this thing to good use.  Or, maybe sell it.  I know a few suck... er, clients that might be interested.\n\nHere, you've earned your pay and then some!" }
WordHunterWoW_QuestEN[10310] = { title = "Sabotage the Warp-Gate!", description = "With the Burning Legion nearby at the fel reaver scrap field, we must do what we can to stop the flow of demons into the area.\n\nThey have a warp-gate to the south in an area that they've cleverly named Invasion Point: Destroyer.\n\nI need you to go with me to the site and keep me safe while I sabotage it.\n\nAfterward, go to the Midrealm Post to the north inside Eco-Dome Midrealm and apprise Gahruj of our success.\n\nWe're going to need a friend or two of yours along to help with this.", objectives = "Escort Drijya to the warp-gate at Invasion Point: Destroyer, and see to it that he is kept safe while he attempts to sabotage it. Then speak to Gahruj at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", completion = "That is most excellent news, my friend!\n\nYou and Drijya have done us a great service.  With that warp-gate out of commission, the nearby demons will not be getting any further reinforcements.\n\nPlease allow me to reward you in the proper manner of the Consortium." }
WordHunterWoW_QuestEN[10311] = { title = "Drijya Needs Your Help", description = "{class}, it is good to see a helpful face around here.\n\nThe Burning Legion at the nearby fel reaver heap has become more bold, and I am beginning to fear for our safety here.  The demons are constantly receiving reinforcements from Invasion Point: Destroyer to the south.\n\nMy compatriot, Drijya, has gone down there to scout and see if he can do something about the Burning Legion's warp-gate.\n\nPlease find and assist him in any way that you can.", objectives = "Speak with Drijya near Invasion Point: Destroyer in the Netherstorm.", completion = "I hope that Gahruj has sent you to help me with my mission." }
WordHunterWoW_QuestEN[10312] = { title = "The Annals of Kirin'Var", description = "Silencing the spirits has not bled them of their aggression as we had hoped it would. The malevolent spirits you subdued have reemerged in the streets of the town.\n\nWe must uncover what is causing this to happen. The destruction of Kirin'Var was just the beginning, or else the spirits would have been quieted by now.\n\nThe town hall in the southern section of Kirin'Var maintained a logbook of all the residents. Last I heard, it was in the keeping of Battle-Mage Dathric. Perhaps his spirit still has it.", objectives = "Retrieve the Annals of Kirin'Var from the town hall of Kirin'Var Village and return it to Custodian Dieworth.", progress = "Were you able to find the registry?", completion = "<Custodian Dieworth accepts the registry from you, leafing through the pages.>\n\nHmm...\n\nIt seems I was right. There is a pattern here.\n\nThe most aggressive and dangerous ghosts coincide with the most powerful and highest ranking Kirin Tor who resided in the village. The townspeople and tradesmen seem overlooked by comparison. What could this mean?" }
WordHunterWoW_QuestEN[10313] = { title = "Measuring Warp Energies", description = "If our instincts are right and these manaforges have been made using technology from Tempest Keep, then all of Outland could be in grave danger.\n\nTempest Keep's energy-recharging mechanisms were never supposed to be used this close to the land.  The warp energies are capable of destroying this very land, even when contained within Kael's pipelines.\n\nTake this orb to Manaforge B'naar; it is attuned to measure warp energies.  Use it at the pipelines' ends, where they go into the earth.", objectives = "Exarch Orelis in Area 52 wants you to take the Warp-Attuned Orb to Manaforge B'naar and use it at the end of its four pipelines.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "This is grave news, <name>.  The warp energies emanating from the pipelines are dangerously high.\n\nWe must find a way to shut down the manaforges or what little remains of Outland will be shattered into pieces." }
WordHunterWoW_QuestEN[10314] = { title = "A Lingering Suspicion", description = "The strange magical device resembles nothing you've ever seen before. It's certainly not of blood elf manufacture.\n\nAs you sense spirits moving closer to the building, the orb glows with a greater intensity, which fades as the spirits leave. There's no question that it plays a role in the corruption of the ghosts.\n\nHow it works remains a mystery. Perhaps Custodian Dieworth will have some insight if you can provide the remains of some of the spirits along with your observations.", objectives = "Collect 10 Loathsome Remnants from the twisted spirits in Kirin'Var Village's Chapel Yard and bring them to Custodian Dieworth.", progress = "What have you discovered, <name>?", completion = "<Custodian Dieworth examines the remnants.>\n\nThe device you described sounds like a necromantic focus... I should've known that no-good apprentice would stoop to this. I thought his training would keep him from going this far, but I guess he's proven me wrong." }
WordHunterWoW_QuestEN[10315] = { title = "Neutralizing the Nethermancers", description = "The blood elves are fools!  I'm glad that our trade relations with them have fallen apart.  In all of my travels throughout the cosmos, I have never encountered beings so selfish.\n\nThey continue to destroy the land around us with their manaforges, so let's see if we can put a dent in their operations across the bridge at Manaforge Ara.\n\nTheir nethermancers channel energy to and from the blood gems to stabilize the flow of power.  Go over there and wipe them out!", objectives = "Kill 15 Sunfury Nethermancers and return to Nether-Stalker Oazul at Tuluman's Landing in the Netherstorm.", completion = "Anything that we can do to encourage them to stop what they're doing at these manaforges is a good thing.\n\nThey certainly do not seem to be able to be reasoned with.  And it seems clear to me that whatever their leaders have in mind, they are insane.\n\nAs remuneration for your faithful service to the goals of the Consortium, I would like to offer you the coin of your realm if it does not offend you." }
WordHunterWoW_QuestEN[10316] = { title = "Searching for Evidence", description = "Whoever is behind the transformation of the spirits has been very deliberate in their actions, taking care to target the most powerful mages first, but why? The kind of magic required to influence the spirits of slain Kirin Tor mages must be very powerful.\n\nWhy would a powerful mage go to all this trouble? I'm inclined to say this is another plot of Kael'thas's, designed to cause more misery here. If there are blood elves here, they're likely to be hiding in the houses across the covered bridge.", objectives = "Search Kirin'Var Village's Chapel Yard for clues about who is behind the manipulation of the spirits.", completion = "A glowing orb sits atop a square-shaped pedestal. At first glance, it seems to be a repository for magical energy, but what kind of energy, and for whose use?" }
WordHunterWoW_QuestEN[10317] = { title = "Dealing with the Foreman", description = "The blood elves call the mine underneath Manaforge Ara the Trelleum Mine.  Ever since they lost the one underneath Manaforge Ultris, this is where their sole supply of material for running the forges is coming from.\n\nNeedless to say, it would be a boon for us to cripple their mining operation.  Perhaps we'd even be able to move in and take it over for ourselves?\n\nWhatever the case, I want you to go in there and deal with Foreman Sundown.  The mine is around the back of the island to the left.", objectives = "Deal with Foreman Sundown inside the Trelleum Mine, which is underneath Manaforge Ara in the Netherstorm.", completion = "<The foreman speaks in hushed tones.>\n\nYou came in here to kill me?  Hmph.  Well I guess the ethereal don't know everything, do they?\n\nI'm not the one that you want, trust me." }
WordHunterWoW_QuestEN[10318] = { title = "Dealing with the Overmaster", description = "I used to be the foreman here.  But now that I've been demoted, I've come to realize our pilgrimage from Quel'Thalas to Outland was all a lie.\n\nA lie perpetrated by Kael'thas to strengthen his forces here in the Netherstorm.\n\nI've tried to convince my brethren that we should leave, especially with the Burning Legion here, but they are all too stubborn.\n\nDo me a favor?  Kill Overmaster Grindgarr.  Then return to your ethereal and tell him that I am no longer his enemy.", objectives = "Slay Overmaster Grindgarr. Then return to Wind Trader Tuluman at Tuluman's Landing in the Netherstorm.", completion = "A doomguard overmaster?  That's odd!  What's the Burning Legion doing in there?\n\nSo, some of the blood elves are defecting.  We'll keep that in mind if we ever attempt to take the place by force.  At least there's some good news that has come from all of this, no?\n\nPlease, <name>, take this with my deepest gratitude." }
WordHunterWoW_QuestEN[10319] = { title = "Capturing the Phylactery", description = "I suppose an explanation is in order. You've met one of the archmage's apprentices, Ravandwyr, but there was also another named Naberius.\n\nHe was an ardent student, but was drawn to necromancy. When Kael'thas appeared with his forces, Naberius seized the opportunity to betray the archmage, handing over the secrets to the tower's defense.\n\nNow, it seems, he has become a lich. If we are to stop him, we must capture his phylactery. Knowing him, he would've buried it somewhere out of sight in his domain.", objectives = "Recover Naberius's Phylactery from Kirin'Var Village's Chapel Yard district and bring it to Custodian Dieworth.", progress = "You must recover Naberius's phylactery before we can attack him. Otherwise, he will be invulnerable.", completion = "Excellent work, <name>. Possession of the phylactery will be the key to our victory. When you enter battle with Naberius, I will smash it, exposing him to your attacks." }
WordHunterWoW_QuestEN[10320] = { title = "Destroy Naberius!", description = "Archmage Vargoth saw the danger in Naberius's pursuit of necromancy, but I don't think he ever anticipated that his own apprentice would wreak this much destruction upon the Kirin Tor.\n\nYou must defeat him, {name}, or else he will continue enslaving the spirits of our fallen brothers, robbing them of their rightful rest and destroying what little remains of Kirin'Var.\n\nWith his phylactery in hand, he can be confronted by two or three combatants, but who knows what his magic might do to more foes?", objectives = "Custodian Dieworth in Kirin'Var Village wants you to confront and defeat Naberius in the village's Chapel Yard.", completion = "The defeat of Naberius is a great achievement, <name>. I can't help thinking that we might have had a chance against Kael'thas's forces if the apprentice's loyalties had been in the right place that day." }
WordHunterWoW_QuestEN[10321] = { title = "Shutting Down Manaforge Coruu", description = "Your success at B'naar has given us a great deal of hope, {name}.\n\nWe've shared our discoveries with the Scryers and in return they've given us more information on the remaining manaforges.\n\nThree other manaforges still stand, in full control of the Sunfury army.\n\nYou will find Manaforge Coruu to the east.  Overseer Seylanna holds the access crystal there.  Obtain it and use it on the manaforge's control console to begin the emergency shutdown.\n\nWe're all counting on you, {name}.", objectives = "Travel to Manaforge Coruu, east of Area 52, and obtain the Coruu Access Crystal from Overseer Seylanna. Use it at the Manaforge Coruu Console to shut it down and return to Anchorite Karja.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed your task yet, <name>?", completion = "Excellent work.  Only two manaforges remain active.\n\nSoon Kael'thas will be cut off from his main source of power." }
WordHunterWoW_QuestEN[10322] = { title = "Shutting Down Manaforge Duro", description = "We've received news from one of the two manaforges that remain operational.  The Sunfury army is losing control of Manaforge Duro.\n\nDroves of errant mana creatures have been attracted to it by its increased energy production - the manaforge is in chaos.\n\nAn explosion at Duro has the potential to cause a chain reaction that would endanger all of Outland.  Overseer Athanel is in possession of the access crystal you need to safely disable the manaforge.", objectives = "Anchorite Karja wants you to go Manaforge Duro and obtain the Duro Access Crystal from Overseer Athanel. Use it at the Manaforge Duro Console to shut it down.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed your task yet, <name>?", completion = "You are blessed by the naaru, <name>.  Your dedication to the cause will not go unnoticed or unrewarded." }
WordHunterWoW_QuestEN[10323] = { title = "Shutting Down Manaforge Ara", description = "One manaforge is all that keeps Tempest Keep functional.  After we bring Manaforge Ara down, Kael will have to resort to depleting whatever energy he's got stored up.\n\nTravel to Manaforge Ara, in the northwest, and deliver the final blow that we need by shutting it down.\n\nThe last access crystal is in the possession of Overseer Azarad.  Be warned that we expect heavy opposition in the last of Kael's functional manaforges.  You're likely to need the assistance of reliable friends.", objectives = "Travel to Manaforge Ara and obtain the Ara Access Crystal from Overseer Azarad. Use it at the Manaforge Ara console to shut it down.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed the task I asked of you, <name>?", completion = "The Burning Legion?  Allied with Kael'thas Sunstrider?\n\nThis is dire news.  It explains much about what we've seen here and in Shadowmoon.\n\nWe must send word back to Shattrath City immediately." }
WordHunterWoW_QuestEN[10324] = { title = "The Great Moongraze Hunt", description = "Well done, {name}! Well done!\n\nNow that you've cut your teeth with the moongraze stag, it's time you graduated to more formidable prey. Do not allow the casual disinterest of the moongraze bucks to fool you: when provoked, they are a fearsome foe.\n\nYou'll find the bucks north of here. Good hunting.", objectives = "Bring 6 Moongraze Buck Hides to Acteon at Azure Watch.", progress = "The buck hides are rugged and strong, making for very tough flesh - almost inedible, but we can use them for other purposes.", completion = "Wonderful! You're turning into quite the hunter, <name>.\n\nHow would you like to look more like me? Well here is your chance! While you were out hunting, I fashioned these items out of some buck hides I had laying around. Take your pick!" }
WordHunterWoW_QuestEN[10325] = { title = "Marks of Kil'jaeden", description = "As you probably know, {name}, the Aldor are keepers of the Light and servants of the naaru.\n\nDiametrically opposed to us are the agents of the Burning Legion - demons bent on the destruction of worlds and the corruption of the innocent.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of low-ranking Legion and their Shadow Council followers.  We know of a Shadow Council hideout in the Bone Wastes and there are many Legion outposts in Nagrand and the Blade's Edge Mountains.", objectives = "Bring 10 Marks of Kil'jaeden to Adyen the Lightwarden in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Do you bear any of our enemies' insignias, <name>?", completion = "Facing the demons of the Burning Legion and the mad cultists that worship them is no small feat, <name>.  You've shown great dedication and courage.  Keep it up and your renown among the Aldor will continue to grow." }
WordHunterWoW_QuestEN[10326] = { title = "More Marks of Kil'jaeden", description = "", objectives = "Do you bear more of our enemies' insignias, <class>?  The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", progress = "Do you bear more of our enemies' insignias, <class>?  The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", completion = "You continue to prove your worth, <name>.  Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded." }
WordHunterWoW_QuestEN[10327] = { title = "Single Mark of Kil'jaeden", description = "", objectives = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", progress = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", completion = "You continue to prove your worth, <name>.  Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded." }
WordHunterWoW_QuestEN[10328] = { title = "Sunfury Briefings", description = "Something about these manaforges has been bothering me, {name}.  Naaru technology is incredibly advanced; it should've taken Kael'thas years to even begin to understand it.\n\nInformation-gathering on the subject has been difficult as Kael's army is well disciplined and destroys all evidence of written communication.\n\nWe've been informed Manaforge Duro is under attack by mana creatures.  It is possible that those defending it have not yet destroyed their briefings.  Obtain them and bring them to me.", objectives = "Go to Manaforge Duro and retrieve the Sunfury Military Briefing and the Sunfury Arcane Briefing from the Sunfury units stationed there. Return to Exarch Orellis when you've completed this task.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Did you have any luck with the briefings from Manaforge Duro?", completion = "Excellent job, <name>!  Let us see what can be learned from these briefings." }
WordHunterWoW_QuestEN[10329] = { title = "Shutting Down Manaforge B'naar", description = "I was having a friendly discussion with the Aldor while you were gone.  Manaforges sure look like modified naaru technology from Tempest Keep.  Apparently, most naaru constructs have certain safeguards that allow them to be permanently disabled in case of emergency.\n\nThe procedure is usually initiated at a control console via an access crystal.  Lo and behold, according to the roster you secured, such a crystal is in the possession of a fellow called Overseer Theredis.  Obtain it and see what you can do.", objectives = "Return to Manaforge B'naar and obtain the B'naar Access Crystal from Overseer Theredis. Use it at the B'naar Control Console to shut it down, then report back to Spymaster Thalodien.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did the plan work?  I was half-expecting you to get blown up, to tell you the truth.", completion = "Of course it worked!  I'm a spymaster; my information is always accurate.\n\nAnyhow, I have a whole new exciting job lined up for you.  You want to hear about it?  Of course you do." }
WordHunterWoW_QuestEN[10330] = { title = "Shutting Down Manaforge Coruu", description = "Thalodien told us of your success in disabling Manaforge B'naar.  He expects a repeat performance here and asked us to keep an eye out for anyone using a crystal to access the console inside.  Overseer Seylanna holds the access crystal, we're sure of it.\n\nGo back in there and finish the operation.  No need to be stealthy anymore; get the crystal, begin the shutdown, kill the technicians trying to stop you and get out.\n\nHurry, it won't be long before Kael's lapdogs sniff us out.", objectives = "Obtain the Coruu Access Crystal from Overseer Seylanna. Use it at the Coruu Control Console to shut down the manaforge and return to Caledis Brightdawn.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Have you completed your task yet, <name>?", completion = "We heard all the commotion and were just about to leave.  Glad to see you didn't take too bad of a beating." }
WordHunterWoW_QuestEN[10331] = { title = "Indispensable Tools", description = "You haven't seen a heavy smithing hammer lying around by chance, have you? I brought it out here with me to finish the shoes for some of old man Amorlin's horses, but I can't find it.\n\nI've searched the barn no less than a half dozen times and I just can't seem to find it. Maybe one of the other apprentices retrieved it and took it back to the smithy? Would you be willing to go down there and take a look? The workshop is to the southeast of the tower in the Town Square.", objectives = "Retrieve the Smithing Hammer from the Kirin'Var Apprentices and bring it back to Apprentice Andrethan in Kirin'Var Village.", progress = "Did you have any luck finding my hammer?", completion = "Thank goodness! Now I can get back to work. I know you think I'm crazy, working on the piece that will earn me journeyman status away from the forge proper, but I can't run the risk of one of the other apprentices copying my design." }
WordHunterWoW_QuestEN[10332] = { title = "Master Smith Rhonsus", description = "At last, my journeyman project is complete! I can't wait to formally present it to Master Rhonsus.\n\n<The apprentice looks at you as you describe your experiences retrieving the hammer.>\n\nThey attacked you? All of them? By the Light, they've gone mad!\n\nWhat are we to do, {name}? It grieves me to say so, but it may be necessary to kill Master Rhonsus. It would leave me as the only smith in Kirin'Var, but I believe my training is sufficient to serve the town's needs.", objectives = "Apprentice Andrethan in Kirin'Var Village wants you to kill the ghost of Rhonsus, the town's master blacksmith.", completion = "Master Rhonsus taught me everything I know about my trade. I will honor his memory by using my skills to serve the people of Kirin'Var." }
WordHunterWoW_QuestEN[10333] = { title = "Help Mama Wheeler", description = "Say, {name}, I was wondering if you could do me another favor.\n\nMy partner out in the field could probably use a hand.  I was wondering if you could go check in on her.\n\nI'm sure that Mama Wheeler will appreciate the help.  Just don't mind her sharp tongue.\n\nShe's trying to look out for our interests to the east.  You'll find her just inside Eco-Dome Midrealm at the Midrealm Post.", objectives = "Speak with Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", completion = "What?!  He called me his 'partner'?  I'm his wife!\n\nAnd he said I had a sharp tongue!  Ooh, when I get back to Area 52, I'm going to box his big, green ears!\n\nBut I'm glad that you're here.  He was right about one thing; I can definitely use your help!" }
WordHunterWoW_QuestEN[10334] = { title = "Needs More Cowbell", description = "Where, oh where has my Bessy gone? After the attack, I searched the fields and the Chapel Yard for her, but she was nowhere to be seen!\n\nAll I have left of her is this old cowbell. She usually comes running when she hears it, but these feeble old bones probably couldn't shake it hard enough.\n\nI'll loan you Bessy's bell if you're willing to go out to the fields and ring it as hard as you can. Perhaps all Bessy's waiting for is a little more cowbell.", objectives = "Find Bessy in the fields near Kirin'Var Village's Chapel Hill in Netherstorm.", progress = "<The cow looks at you distrustfully, but stands its ground.>", completion = "<Removing the bell from your pack, you ring it a couple of times and show it to Bessy, who seems to recognize it. The cow allows the bell's cord to be fastened around her neck and looks at you expectantly.>" }
WordHunterWoW_QuestEN[10335] = { title = "Surveying the Ruins", description = "I have to get over to the Ruins of Farahlon to start my excavations!  The problem is that the place has been infested by demons!\n\nMaybe you could do some preliminary work for me?\n\nThere are three locations within the ruins to the northeast where I want you to place surveying markers.  Each is near a draenei banner.\n\nReturn to me when you've managed to place all three markers.", objectives = "Place the three Surveying Markers and then return to Zephyrion at the Stormspire in the Netherstorm.", progress = "That was fast.  You must be a very efficient person to have placed all three of those markers already.", completion = "You're not just pulling my bandage, right?  That's most excellent news!\n\nNow that you've done the surveying grunt-work, I'll be able to take my team up to the ruins and see what's there to be procured.\n\nYou have my thanks, <class>." }
WordHunterWoW_QuestEN[10336] = { title = "The Minions of Culuthas", description = "A few weeks ago, the Burning Legion moved into the Ruins of Farahlon, thwarting our plans to excavate the site for its artifacts.\n\nThen earlier today, I learned that one of their dreadlords, Culuthas, somehow killed off all of the other Burning Legion.  He has since summoned in demons that serve him.\n\n{class}, I want you to go up to those ruins to the northeast and rid them of their demon infestation.", objectives = "Slay 10 Hounds of Culuthas and 5 Eyes of Culuthas.", completion = "Truly an exceptional job.\n\nWith the demons of Culuthas slain, Zephyrion will be able to safely take his excavation team into the Ruins of Farahlon.\n\nAccept this coin as a token of my gratitude." }
WordHunterWoW_QuestEN[10337] = { title = "When the Cows Come Home", description = "Realizing that Bessy is still staring at you, you gesture toward Thadell's location. You find yourself promising to protect the cow on her way home. Upon finishing your sentence, you realize there's no possible way the cow could understand anything you've said.\n\nShrugging your shoulders, you prepare to guard the bovine on her way back to Thadell.", objectives = "Escort Bessy safely back to her owner, Thadell.", progress = "Have you found my Bessy?", completion = "Bessy, is that you?\n\n<The farmer turns to you.>\n\nThank you for bringing back my Bessy, <name>. I couldn't live without her!" }
WordHunterWoW_QuestEN[10338] = { title = "Shutting Down Manaforge Duro", description = "So Manaforge Duro is under attack and Sunfury forces have lost control?  What a dilemma!  If Duro goes down, then Tempest Keep goes down.  Only drawback is... if Tempest Keep is destroyed, the explosion will probably take what little remains of this forsaken land with it.\n\nDead Kael'thas is good.  Dead everyone else is... not that great, I suppose.  It pains me to ask this of you, but go to Manaforge Duro and shut it down before it goes up in flames.  The access crystal is held by Overseer Athanel.", objectives = "Return to Manaforge Duro and obtain the Duro Access Crystal from Overseer Athanel. Use it at the Duro Control Console to shut it down and report back to Spymaster Thalodien.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did you complete the shut down?  You should hurry before I change my mind about the whole deal.", completion = "That makes three manaforges you've shut down, <name>.  Kael'thas must be having a real fit right about now." }
WordHunterWoW_QuestEN[10339] = { title = "The Ethereum", description = "Directly south of here you will find the Ethereum Staging Grounds. The Ethereum are there, preparing for something... Perhaps an assault on Ultris.\n\nWe can't take any chances, though, {class}. Break through their perimeter defenses and take out their training facility.\n\nOnce you've destroyed their soldiers and Captain Zovax, locate Ethereum transponder Zeta and use it to establish contact with me to get your next set of orders.", objectives = "Kill 5 Ethereum Assassins, 5 Ethereum Shocktroopers, 2 Ethereum Researchers, and Captain Zovax, then activate Ethereum Transponder Zeta.", progress = "Well done, fleshling...", completion = "We must gather whatever data that they've stored in this area." }
WordHunterWoW_QuestEN[10340] = { title = "Shatter Point", description = "{name}, you've done a great job here at the front, and you showed a lot of talent with that armored gryphon... I think I have another mission in mind for you.\n\nThis new mission launches from Shatter Point -- an attack base the Wildhammers set up on a floating piece of land near the Portal.  It's a little unnerving there, but you have tough guts.  You'll be fine.\n\nTalk to Wing Commander Dabir'ee and have him send you to Shatter Point.  From there, report to the gryphon master Runetog Wildhammer.", objectives = "Forward Commander Kingston wants you to speak with Wing Commander Dabir'ee, ride a gryphon to Shatter Point, and then report to Runetog Wildhammer.", completion = "Hah hah!  A fresh <race> from the mainland!  Well don't worry -- Shatter Point might make you queasy but she doesn't stray far!\n\nAnd I've only seen her flip upside down once... or twice." }
WordHunterWoW_QuestEN[10341] = { title = "Kick Them While They're Down", description = "The news you've discovered is fortunate, {name}.  Not only do you get to waltz into Manaforge Duro unfettered, this also presents a great opportunity to deal a blow to Kael's army.\n\nUse the mana creature assault to your advantage and pick off any Sunfury stragglers you run into.\n\nI do not take particular glee in the senseless slaughter of my own kin the way that Thalodien does, but the tactical advantage here is too high to pass up.", objectives = "Slay 8 Sunfury Conjurers, 6 Sunfury Bowmen and 4 Sunfury Centurions. Return to Magistrix Larynna at Area 52 after completing this task.\n\nCompleting tasks for the Scryers will cause your Aldor reputation to decrease.", completion = "You've done well, <name>.  Kael's army will not easily recover from the blow you've dealt today." }
WordHunterWoW_QuestEN[10342] = { title = "Securing the Shaleskin Shale", description = "I make a good living selling drinks to the boozehounds around here.  But I want something more!\n\nThe rocket-chief is always telling me how he can't perfect the rocket fuel needed to get the X-52 off of the ground.\n\nWe can solve that little problem for him.\n\nFor starters I need to extract the oil from the shale of the local shaleskin flayers!  It'll form a concentrated, if explosive, base for the mix that I have in mind.\n\nFind the flayers, and their shale, all over the place near the purple rocks.", objectives = "Collect 5 Shaleskin Shale and give them to Boots at Area 52 in the Netherstorm.", progress = "You have enough of that shale yet?  I'm going to need a lot of it to extract the amount of oil that'll be needed for the X-52 Nether Rocket's fuel.", completion = "OK!  Ingredient number one is down.\n\nNow, if you're up to it, we'll move on to something that'll give the shale oil that little extra kick that it'll need to blast the nether rocket into the Twisting Nether... or oblivion, whichever comes first." }
WordHunterWoW_QuestEN[10343] = { title = "The Unending Invasion", description = "Kael'thas's assault on Kirin'Var began with thundering noise and a bright flash of light in the officer quarters to the northwest. The destruction there was the most severe and after the withdrawal of the blood elves, a strange thing began to happen.\n\nBeings of pure mana began streaming into the village from all over the area. For now, we're containing them as we can, but with more information about the weapon Kael'thas used, I hope to cut off the flow of mana creatures entirely.", objectives = "Search the mana creature infested area of Kirin'Var Village for a Mana Bomb Fragment and bring it to Lieutenant-Sorcerer Morran.", progress = "Did you find the remains of the weapon Kael'thas used against the village?", completion = "A mana bomb?\n\n<Morran turns the fragment over in his hands.>\n\nIt's nigh unthinkable! Even the best minds in Dalaran couldn't have conceived of a weapon like this. The sheer magnitude of the disturbance must've torn a rift in the nether, giving these creatures access to our lands." }
WordHunterWoW_QuestEN[10344] = { title = "Wing Commander Gryphongar", description = "Wing Commander Gryphongar runs this outfit of Wildhammers.  If this is your first time to Shatter Point, then you should report to him.\n\nYou'll find him inside what's left of that tower over yonder.", objectives = "Speak with Wing Commander Gryphongar in Shatter Point.", completion = "You spoke with Runetog?  A fine dwarf he is.  Keeps his gryphons in good shape and battle ready.\n\nI'm Gryphongar, commander here at Shatter Point.  I know it's not pretty, but this hunk of rock is a vital staging point for sorties into Hellfire.  You'll see gryphons flying out and in non-stop!\n\nAdvice?  Here's some: keep your gear stowed, your stomach empty, and your eye on the horizon... if Shatter Point starts to teeter, then grab onto something that won't float away!" }
WordHunterWoW_QuestEN[10345] = { title = "The Flesh Lies...", description = "You see these corpses, {race}? Arconus is responsible for this slaughter. He's sucked them dry, leaving nothing more than a fleshy husk. But don't let the bodies fool you! Inside those corpses lie flesh beasts, waiting to pounce on the unsuspecting fool that gets too close.\n\nI've got my orders. I must remain here until backup arrives. That doesn't mean that you can't take my igniter and destroy the withered corpses that litter the mines. One way or another, the mission must be completed.", objectives = "Use the Protectorate Igniter on 12 Withered Corpses. Return the Protectorate Igniter to Agent Araxes outside of Access Shaft Zeon when the task is complete.", progress = "Any luck in finding Ya-six?", completion = "You saved my wrappings, <name>. The Protectorate will know of what you've done on this day, friend." }
WordHunterWoW_QuestEN[10346] = { title = "Return to the Abyssal Shelf", description = "<name>, you've proven yourself as a capable gryphon rider, and we could use you on more sorties over the Abyssal Shelf.  What say you, <class>?  Do you want some more flight time?", objectives = "Gryphoneer Windbellow at Shatter Point in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "There are still plenty of targets on the Abyssal Shelf, <name>.  Grab a gryphon when you're ready for another run.", completion = "How'd it go out there this time?  You're in pretty good shape... maybe even good enough for another run!" }
WordHunterWoW_QuestEN[10347] = { title = "Return to the Abyssal Shelf", description = "<name>, are you ready for another sortie over the Abyssal Shelf?  I fear that, if we do not maintain pressure on the Legion forces there and allow them to strengthen their hold, then we may suffer a large demon attack from the north.\n\nWhat say you, <class>?  Do you want to take another windrider and hammer the Abyssal Shelf one more time?", objectives = "Wing Commander Brack at Reaver's Fall in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "The Legion must not think they are safe high atop the Abyssal Shelf.  We must hit them repeatably!", completion = "The other windrider pilots speak highly of you, <name>.  You've scored quite a lot of kills on the Abyssal Shelf.  Keep up the good works!" }
WordHunterWoW_QuestEN[10348] = { title = "New Opportunities", description = "I hear that a group of 'druids' from Azeroth has taken quite an interest in the effects of our eco-dome technology.\n\nThe Cenarion Expedition's representatives are eager to get access to the plants growing within the domes, particularly one called the ivory bell, known for its healing properties. They're found in clumps of brush around larger plants in Eco-Dome Midrealm.\n\nI'll share the profits with you if you're willing to gather the herbs for my first delivery.", objectives = "Gather 15 Ivory Bells and return to Mehrdad at Midrealm Post.", progress = "Have you managed to gather the herbs?", completion = "Interesting choice, isn't it? The healing properties had better be miraculous. I'm charging a lot of money for a rather plain looking flower." }
WordHunterWoW_QuestEN[10349] = { title = "The Earthbinder", description = "You should take the crystal lump over to the earthbinder.  She's just like you... always needing to get to the bottom of a mystery and thinking all of the time.\n\nIf you ask me, she thinks a little too much.\n\nJust give it to her and I'm sure that she'll get you into a heap of trouble figuring out what is going on up there on the ridge.", objectives = "Take the Crimson Crystal Shard to Earthbinder Galandria Nightbreeze at the Cenarion Post in Hellfire Peninsula.", progress = "Is that a piece from the giant crystal shard up on Fallen Sky Ridge?", completion = "Oh, excellent!  I've been waiting to get my hands on a piece of that thing, but Tola'thion's been dragging his feet.\n\nHe's supposed to be out here helping me to investigate what's going on up on Fallen Sky Ridge.  Instead he's just been sending poor dupes like you - no offense - up there into the slaughter mill.\n\nIf you give me the crystal maybe I can find a link between it and the colossi." }
WordHunterWoW_QuestEN[10350] = { title = "Behomat", description = "While you have learned many hard lessons from me during our time together, it is time that I entrusted you to wiser hands.\n\nBehomat, who trained me when I was as green as grass, will be your new teacher. I have told him that you will be seeking him out, and he is expecting you.\n\nYou will find him at the center of the Warriors' Terrace, at the highest point of the Traders Tier of the Exodar.", objectives = "Speak with Behomat at the Traders Tier of the Exodar.", completion = "Ah, so you've finally come. I am Behomat, and I will instruct you in the ways of the <class> arts. Ruada told me of your trial against the ravager, and I am impressed. And I have a gift for you.\n\nWhat we have scavenged from the wreckage of the Exodar is little, and must be given to those most able. Please take a weapon suited to your fighting style and carry it with the knowledge you have earned it.\n\nAnd speaking of fighting styles, it's time you learned something new." }
WordHunterWoW_QuestEN[10351] = { title = "Natural Remedies", description = "It must be that the evil emanations from that giant crystal are summoning the mountain giants and driving them insane.\n\nIt's too big to move, and beyond our ability to destroy, but I know a way to quell its power.\n\nI've summoned a circle at the northwest corner of the crystal on the ridge.  Take this seed to the circle and channel its powers to heal the land through the natural forces of rain, growth and insect repopulation.\n\nBeware, {name}, I sense an external force at play here... this is not natural!", objectives = "Use the Seed of Revitalization at the Earthbinder's Circle to heal the land around the crystal. Then, return to Earthbinder Galandria Nightbreeze at the Cenarion Post in Hellfire Peninsula with any information that you gain.", progress = "Did it work?  What did you learn?  Did you find out who or what is behind what happened at Fallen Sky Ridge?", completion = "Goliathon?  Pathaleon the Calculator?\n\nKAEL'THAS!?\n\nPrince Kael'thas has a hand in this?\n\n<The earthbinder fumes.>\n\nIt is insanity what he has done!  Dropping giant crystals from the sky and decimating the land can only be the work of a madman!\n\nI can assure you, the Cenarion Expedition will counter any further attempts by their forces to do this ever again.\n\nWe owe you a great debt, <name>." }
WordHunterWoW_QuestEN[10352] = { title = "A Donation of Wool", description = "", objectives = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Ironforge for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", progress = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Ironforge for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, <name>!" }
WordHunterWoW_QuestEN[10353] = { title = "Arconus the Insatiable", description = "Araxes and I were deployed to Ultris 2 days ago. Our mission: Find and terminate the void lord Arconus. We tracked him to this mine and discovered that he'd been feeding off the energies of the creatures in the area.\n\nA fire-fight broke out which resulted in Araxes and I separating. Now I'm stuck here, badly injured. The mission is in shambles!\n\nIf you can take out Arconus, high command would be grateful. Should you accept this mission, I will assist by providing a reflection of myself as a guardian.", objectives = "Agent Ya-six at Access Shaft Zeon in Netherstorm has asked you to slay Arconus the Insatiable and return to Commander Ameer at the Protectorate Watch Post in Netherstorm.", completion = "And Ya-six? Did he make it?\n\nLet's damn well hope so. I was unable to get reinforcements back to them... Ethereum have the entire area covered now.\n\nMy apologies, I nearly forgot about your reward." }
WordHunterWoW_QuestEN[10354] = { title = "A Donation of Silk", description = "", objectives = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", progress = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, <name>!" }
WordHunterWoW_QuestEN[10355] = { title = "Withered Flesh", description = "We must determine how far the damage has spread. The basidium you brought me comes from a bog giant. Their larger, hardier cousins, the bog lords, should prove more resistant to the degeneration that's struck the giants.\n\nIt would be good to know how the changes in the Dead Mire have affected the other creatures out there, too.\n\nReturn to the Dead Mire and see if you can get samples from the bog lords and the hydra in the area.", objectives = "Gather 5 Parched Hydra Samples and 5 Withered Bog Lord Samples and bring them to Ruam at Telredor.", progress = "Were you able to gather the samples?", completion = "<Ruam examines the samples, looking distressed.>\n\nIt's exactly as I'd feared, <name>. The drying environment is taking a heavy toll on creatures never meant to live outside swampy environments. We'll have to continue to monitor the area and consult with the Cenarion Expedition to see if anything can be done." }
WordHunterWoW_QuestEN[10356] = { title = "A Donation of Mageweave", description = "", objectives = "We are currently gathering mageweave. A donation of sixty pieces of mageweave cloth will net you full recognition by our people for your generous actions\n\nIf you currently have sixty pieces, you may donate them now.", progress = "We are currently gathering mageweave. A donation of sixty pieces of mageweave cloth will net you full recognition by our people for your generous actions\n\nIf you currently have sixty pieces, you may donate them now.", completion = "Our thanks for your donation, <name>." }
WordHunterWoW_QuestEN[10357] = { title = "A Donation of Runecloth", description = "", objectives = "We are currently gathering runecloth.  A donation of sixty pieces of runecloth will net you full recognition by our people for your generous actions.\n\nIf you currently have sixty pieces, you may donate them now.", progress = "We are currently gathering runecloth.  A donation of sixty pieces of runecloth will net you full recognition by our people for your generous actions.\n\nIf you currently have sixty pieces, you may donate them now.", completion = "Our thanks for your donation.\n\nShould you continue to offer runecloth, I will make certain that word of your good works reaches the leaders of the Exodar." }
WordHunterWoW_QuestEN[10358] = { title = "Additional Runecloth", description = "", objectives = "Well met again, <name>. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts.\n\nIf you have the stack of runecloth now, I can accept the donation.", progress = "Well met again, <name>. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts.\n\nIf you have the stack of runecloth now, I can accept the donation.", completion = "We offer thanks for your continued efforts, <name>." }
WordHunterWoW_QuestEN[10359] = { title = "A Donation of Wool", description = "", objectives = "Give me sixty pieces of wool cloth and you will receive full recognition by Silvermoon for your generous actions.\n\nIf you have them now, I can take them.", progress = "Give me sixty pieces of wool cloth", completion = "Ah, wool cloth. I'll see to it others hear of your donation." }
WordHunterWoW_QuestEN[10360] = { title = "A Donation of Silk", description = "", objectives = "Give me sixty pieces of silk cloth and you will receive full recognition by Silvermoon for your generous actions.\n\nIf you have them now, I can take them.", progress = "Give me sixty pieces of silk cloth", completion = "Ah, silk cloth. I'll see to it others hear of your donation." }
WordHunterWoW_QuestEN[10361] = { title = "A Donation of Mageweave", description = "", objectives = "Give me sixty pieces of mageweave cloth and you will receive full recognition by Silvermoon for your generous actions.\n\nIf you have them now, I can take them.", progress = "Give me sixty pieces of mageweave cloth", completion = "Ah, mageweave cloth. I'll see to it others hear of your donation." }
WordHunterWoW_QuestEN[10362] = { title = "A Donation of Runecloth", description = "", objectives = "Give me sixty pieces of runecloth and you will receive full recognition by Silvermoon for your generous actions.\n\nIf you have them now, I can take them.", progress = "Give me sixty pieces of runecloth", completion = "Runecloth, mmm? Well, so long as you keep bringing it, I will continue to sing your praises to the people of Silvermoon." }
WordHunterWoW_QuestEN[10363] = { title = "Additional Runecloth", description = "", objectives = "For another stack of twenty runecloth, I will see to it that you are recognized for your continuing efforts on behalf of Silvermoon.\n\nSimply hand it to me when you're ready.", progress = "For another stack of twenty runecloth, I will see to it that you are recognized for your continuing efforts on behalf of Silvermoon.\n\nSimply hand it to me when you're ready.", completion = "Well, well. Even more runecloth." }
WordHunterWoW_QuestEN[10364] = { title = "Caedmos", description = "You have come far in a short time, <name>. Faster than I had expected or hoped. It is time that you continued your training under the tutelage of Caedmos.\n\nI have sent word to him at the Exodar to expect you. You'll find him in the Anchorites' Sanctum near the entrance of the Vault of Lights.You will receive:", objectives = "Speak with Caedmos in the Vault of Lights of the Exodar.You have come far in a short time, <name>. Faster than I had expected or hoped. It is time that you continued your training under the tutelage of Caedmos.\n\nI have sent word to him at the Exodar to expect you. You'll find him in the Anchorites' Sanctum near the entrance of the Vault of Lights.You will receive:" }
WordHunterWoW_QuestEN[10365] = { title = "Shutting Down Manaforge Ara", description = "You've done much better than any of us anticipated.  Manaforge Ara is the last of Kael's working manaforges.  You'll find it northwest of here, though you're likely to have to do some circumnavigating to get to it.  We want you to shut it down.\n\nThe last access crystal is in the possession of Overseer Azarad.  This is Kael's very last source of energy as far as we know, so expect heavy opposition.  I'd bring a couple of friends along if I were you.\n\nHmm... Azarad.  What an odd name for a sin'dorei.", objectives = "Travel to Manaforge Ara and obtain the Ara Access Crystal from Overseer Azarad. Use it at the Manaforge Ara console to shut it down.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Have you completed the task I asked of you, <name>?", completion = "The Burning Legion is in cahoots with Kael?  Hah!  Voren'thal is going to have a field day with this information.\n\nDo you think the thousands of pilgrims that have come from Azeroth want to be allied with the Burning Legion?  I think not!" }
WordHunterWoW_QuestEN[10366] = { title = "Jol", description = "The path of the Light and purity is not an easy one to walk, <name>. Even I, at times, struggle with following its course.\n\nYou should seek out my master, Jol, at the Exodar. She trained me when I was beginning my journey, and I believe she will find in you a new star pupil.\n\nYou will find Jol in the Vault of Lights of the Exodar at the Vindicators' Sanctum, a room surrounded by a vibrant glow of light.Upon completion of this quest you will gain:", objectives = "Speak with Jol in the Vindicators' Sanctum of the Exodar.The path of the Light and purity is not an easy one to walk, <name>. Even I, at times, struggle with following its course.\n\nYou should seek out my master, Jol, at the Exodar. She trained me when I was beginning my journey, and I believe she will find in you a new star pupil.\n\nYou will find Jol in the Vault of Lights of the Exodar at the Vindicators' Sanctum, a room surrounded by a vibrant glow of light.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10367] = { title = "A Traitor Among Us", description = "Anywhere you see a tribe of enslaved Broken you will also find a traitor.  A despicable being who sold his brothers for promises of power.\n\nThere is a hut at the top of the stairs in the center of the ruins.  That's the turncoat's hut.\n\nHe's not there right now, so you will be able to sneak in if you're patient.  Inside you will find a coffer with a key inside of it.  That key unlocks the chains that keep the Dreghood elders prisoner.  Bring it to me.\n\nBeware, Arzeth the Merciless wanders nearby.", objectives = "Naladu at the Ruins of Sha'naar wants you to obtain the Sha'naar Key from a nearby hut.", progress = "Did you obtain the key, <name>?", completion = "I thank you, <name>.  My people will soon be free thanks to you." }
WordHunterWoW_QuestEN[10368] = { title = "The Dreghood Elders", description = "The Dreghood spirit is broken because our elders are imprisoned.  Take this key and go downstairs to free them.\n\nThey are Morod the Windstirrer, Akoru the Firecaller and Aylaan the Waterwaker.  Once they are free, the spirits will return to the Dreghood tribe.", objectives = "Free Morod the Windstirrer, Akoru the Firecaller and Aylaan the Waterwaker at the Ruins of Sha'naar. Return to Naladu after completing this task.", progress = "Tell me, <name>.  Have the Dreghood elders been released?", completion = "I can feel it, <name>!   The spirits are returning to us." }
WordHunterWoW_QuestEN[10369] = { title = "Arzeth's Demise", description = "Yes, the elemental spirits have returned to us!  We are not as strong as we once were, but a little magic can go a long way in the right hands.\n\nArzeth has great powers bestowed upon him by his dark lord.  Take this staff.  It was once a great symbol of our tribe.  Use it against Arzeth and his powers will be temporarily removed from him.  Defeat him then, so that my people may finally be free!", objectives = "Use the Staff of Dreghood Elders on Arzeth the Merciless and slay him after he's lost his powers. Return to Naladu at the Ruins of Sha'naar after completing this task.", progress = "Is it done, <name>?  Is Arzeth dead?", completion = "It is true, <name>.  I was once Naladu the Keeper of Earth.\n\nIt was I who betrayed the other Dreghood elders in exchange for empty promises of power.  You can despise me now if you wish to.  What matters is that my tribe is free once again and that the spirits have returned to us.\n\nI will not be joining the rest of the tribe, but I can die in peace now.  May the spirit of earth find a new servant among my brothers." }
WordHunterWoW_QuestEN[10371] = { title = "Yorus Barleybrew", description = "A dwarven warrior known as Yorus Barleybrew has issued a challenge to all skilled Alliance warriors.\n\nHe waits at the Lakeshire Inn, in a place known as the Redridge Mountains in the Eastern Kingdoms.  The journey will be long, but it'll be worth it for you to test yourself, <name>.Upon completion of this quest you will gain:", objectives = "Speak with Yorus Barleybrew at the Lakeshire Inn in Redridge Mountains.A dwarven warrior known as Yorus Barleybrew has issued a challenge to all skilled Alliance warriors.\n\nHe waits at the Lakeshire Inn, in a place known as the Redridge Mountains in the Eastern Kingdoms. The journey will be long, but it'll be worth it for you to test yourself, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10372] = { title = "A Discreet Inquiry", description = "Eralan, an associate of mine in Tranquillien, has made an inquiry about securing some help for an urgent job.\n\nNow, I don't know what she has in mind because I don't ask questions, but you've proven yourself more than capable. I want you to travel to Tranquillien in the Ghostlands and have a word with Eralan.\n\nShe may be a bit gruff, but she's trustworthy.Upon completion of this quest you will gain:", objectives = "Speak with Eralan in Tranquillien.Eralan, an associate of mine in Tranquillien, has made an inquiry about securing some help for an urgent job.\n\nNow, I don't know what she has in mind because I don't ask questions, but you've proven yourself more than capable. I want you to travel to Tranquillien in the Ghostlands and have a word with Eralan.\n\nShe may be a bit gruff, but she's trustworthy.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10373] = { title = "A Call to Arms: The Plaguelands!", description = "Hear ye, hear ye!  All heroes are called upon to heed these words!\n\nA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!\n\nHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!", objectives = "Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains.", completion = "Welcome to the Plaguelands, hero. This is one of the most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there. I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands." }
WordHunterWoW_QuestEN[10374] = { title = "A Call to Arms: The Plaguelands!", description = "Heroes of the realm, hear me - the Horde calls upon you for swift action!\n\nA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!\n\nHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!", objectives = "Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity.", completion = "Welcome to the Plaguelands, hero. This is one of the most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there. I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!\n\nIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands." }
WordHunterWoW_QuestEN[10375] = { title = "Obsidian Warbeads", description = "You've proven yourself to our people, {name}.  Now is time for you to show us that you're willing to stand by us, even in the face of the strongest enemy.\n\nThe ogres of Outland are ", objectives = "" }
WordHunterWoW_QuestEN[10376] = { title = "Symbol of Hope", description = "", objectives = "" }
WordHunterWoW_QuestEN[10377] = { title = "Nothing to Fear", description = "", objectives = "" }
WordHunterWoW_QuestEN[10378] = { title = "Consume Magic", description = "", objectives = "" }
WordHunterWoW_QuestEN[10379] = { title = "Touch of Weakness", description = "", objectives = "" }
WordHunterWoW_QuestEN[10380] = { title = "A Dark Pact", description = "We've been so blind, {name}, that the alliance of two of our most dangerous enemies went completely unnoticed.\n\nI wouldn't be surprised if the Scryers had something to do with hiding this information from us, but we must now face the reality.  The Burning Legion and Kael'thas' Sunfury army serve under the same banner.\n\nThese demons are the only reason Kael'thas was ever able to utilize the technology in Tempest Keep.  Under Orelis's orders I must command you to destroy them.", objectives = "Kaylaan at Tuluman's Landing in Netherstorm wants you to slay 6 Gan'arg Warp-Tinkers, 3 Daughters of Destiny and 3 Mo'arg Warp-Masters.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "It is done then.  We come here, hunt them down and slay them at the bidding of our masters.  No quarter is given or expected.\n\nMakes you wonder sometimes." }
WordHunterWoW_QuestEN[10381] = { title = "Aldor No More", description = "My mission here is finished.  I did what Orelis ordered me to - I've never failed to.\n\nNo more.  I foresee a great carnage - a crusade, they'll call it - following the news of this alliance between Kael'thas and the Burning Legion.\n\nFirst they give our holiest city away to our enemies and then they ask us to die fighting their enemies.  Go back to Orelis; tell him the naaru can fight their own fights from now on.", objectives = "Report back to Exarch Orelis at Area 52.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "The bad news you bring fills my heart with sorrow.  Two of our deadliest foes join forces and one of the dearest sons of Shattrath has lost his way." }
WordHunterWoW_QuestEN[10382] = { title = "Go to the Front", description = "Well, {name}, I hope you're prepared for the next phase of our operation. The Legion never rests - and neither shall we! Take a gryphon and fly over to Honor Point - it's a small post near the Legion Front. \n\nSpeak with Field Marshal Brock. He'll have instructions for you when you arrive. Oh, and tell that pasty-faced shield-kisser I said 'hello'.  \n", objectives = "Take a gryphon to Honor Point and speak with Field Marshal Brock.", completion = "Well met, <class>. I'm glad that crusty old dwarf finally saw fit to send us some help!" }
WordHunterWoW_QuestEN[10383] = { title = "This is a Breadcrumb!", description = "Hello.  You should find out about those wabbits.", objectives = "Speak with Jonathan LeCraft about the wabbits.Hello. You should find out about those wabbits." }
WordHunterWoW_QuestEN[10384] = { title = "Ethereum Data", description = "Look around you, fleshling. Very close to this transponder should be an Ethereum data cell. Locate that data cell, open it, and retrieve the contents.\n\nBring it back to this transponder at once!", objectives = "Recover the Ethereum Data Cell and return it to Commander Ameer.", progress = "Have you recovered the data cell?", completion = "<You hold the data cell out so Ameer can read the plans.>\n\nNothing... Damn them! They're clever but not as clever as Ameer!\n\nWhat I'm about to ask you to do is quite dangerous. I'll understand if you don't want to continue, fleshling." }
WordHunterWoW_QuestEN[10385] = { title = "Potential for Brain Damage = High", description = "They're using relays to transfer information around the staging grounds.\n\nThere is only one way for you to see these relays and extract the information they hold. Unfortunately, doing so may cause you irreparable brain damage.\n\nIf you're still interested, you'll need to slay Ethereum here at the staging grounds and take their essences. Once you have an essence, drink it down. It will temporarily allow you to see an Ethereum relay, giving you enough time to destroy a relay and extract its information.", objectives = "Recover 12 pieces of Ethereum Relay Data.", progress = "Have you recovered the relay data?", completion = "The Protectorate's reason for existence is now fully realized.\n\nThe Ethereum are not here to hunt Dimensius! They are here to become void!\n\nThey are manipulating the void energy at this manaforge to bond their own energy into a creature known as a nexus-stalker.\n\nThey are undoubtedly using a proto-accelerator to complete the transformation." }
WordHunterWoW_QuestEN[10386] = { title = "The Fel Reaver Slayer", description = "Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion.  You definitely have the courage for one of his \"missions.\"  \n\nSpeak with him if you've got the stomach for more carnage.  He is celebrating just over there by that fallen fel reaver.  He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.Upon completion of this quest you will gain:", objectives = "Speak with Overlord Hun Maimist.Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion. You definitely have the courage for one of his \"missions.\"  \n\nSpeak with him if you've got the stomach for more carnage. He is celebrating just over there by that fallen fel reaver. He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10387] = { title = "The Fel Reaver Slayer", description = "Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion.  You definitely have the courage for one of his \"missions.\"  \n\nSpeak with him if you've got the stomach for more carnage.  He is celebrating just over there by that fallen fel reaver.  He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.Upon completion of this quest you will gain:", objectives = "Speak with Overlord Hun Maimist.Overlord Hun Maimfist is always looking for volunteers for his suicide attacks against the Burning Legion. You definitely have the courage for one of his \"missions.\"  \n\nSpeak with him if you've got the stomach for more carnage. He is celebrating just over there by that fallen fel reaver. He and his guards killed it just a few hours ago, we would all have died here but for his ferocity and skill in battle.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10388] = { title = "Return to Thrallmar", description = "Hope you enjoyed your flight, friend. A messenger arrived while you were away - seems Nazgrel's got a new use for you. You'd best head back to Thrallmar and check in with him. I have a feeling the Legion's just getting warmed up. \n", objectives = "Return to Thrallmar and speak with Nazgrel.", completion = "Ah, <name>, you've come just in time. Our scouts have discovered that the Legion positions on the ridge behind us are actually 'forge camps'. It's there that the demons are constructing their infernal fel reavers. If we move against them quickly we can disrupt their production!" }
WordHunterWoW_QuestEN[10389] = { title = "The Agony and the Darkness", description = "Greetings, {name}. I've deciphered the Legion missive and uncovered the demons' strategic plans for this Peninsula. Apparently, there is a large group of hellish terrorfiends gathering near the Pools of Aggonar in the west. We cannot allow such a force to go unchallenged. You must go there and decimate their cursed numbers. ", objectives = "Magister Bloodhawk wants you to kill 10 Terrorfiends in the Pools of Aggonar.", completion = "Bravo, <name>. I knew you would be victorious! The Legion's defeat draws ever nearer!" }
WordHunterWoW_QuestEN[10390] = { title = "Forge Camp: Mageddon", description = "{name}, we have reason to believe that the easternmost forge camp is not yet complete. The Legion's gan'arg servants are working 'round the clock to get the facility up and running. We can't allow that to happen. \n\nHead east to Forge Camp: Mageddon and slay 10 gan'arg. Bring me the head of their master - Razorsaw - and the Legion's fel reaver production will grind to a halt!   \n\n", objectives = "Nazgrel in Thrallmar wants you to attack Forge Camp: Mageddon and kill 10 Gan'arg Servants and return with the head of Razorsaw.", progress = "Move quickly, <class>, we've got to shut down Forge Camp: Mageddon before the demons finish its construction!", completion = "Well done, <class>, That's one less forge camp we'll need to worry about. It'll take the Legion a while to get that facility back up and running. You've just bought us the one thing we'd run out of - time." }
WordHunterWoW_QuestEN[10391] = { title = "Cannons of Rage", description = "There is a second production facility, Forge Camp: Rage, that lies to the immediate northeast of Thrallmar. The demons have positioned a number of their fel cannons along the ridge - and they're aimed straight at us! You must enter the camp and destroy these fel cannons. \n\n{name}, you must be sure to detonate them all - or nothing will stop the Legion from raining fiery hell down upon our heads!  \n", objectives = "Destroy 3 Fel Cannon MKIs in Forge Camp: Rage and return to Nazgrel in Thrallmar.", completion = "I knew you had spirit, <name>, but you've outdone yourself this time! We heard those wretched cannons exploding from here! That should teach the Legion not to underestimate the Sons of Durotar!" }
WordHunterWoW_QuestEN[10392] = { title = "Doorway to the Abyss", description = "You are an honor to us, {name}. But now we must strike before the Legion recovers! To the north of Thrallmar lies Invasion Point: Annihilator. It houses a warp-portal through which the Legion draws its reinforcements. \n\nYou must overload that portal - and blast it back to the abyss it came from. The portal's activation key will be held by the Point's commander - Warbringer Arix'Amal. Slay him. Take the key. Use it on the portal and do what must be done. May the warchief's blessings be with you.   ", objectives = "Slay Arix'Amal to get the Burning Legion Gate Key. Use the Burning Legion Gate Key on the Rune of Spite, then return to Nazgrel in Thrallmar.", progress = "Hurry, <name>. Every second that warp-portal stands open, another foul demon is brought into this world!", completion = "Praise the ancients, you've done it, <name>! The Legion has suffered a terrible defeat - and Thrallmar is safe once again. Ah, if I had but a hundred warriors with your heart and cunning, this broken land would be tamed already! I salute you." }
WordHunterWoW_QuestEN[10393] = { title = "Vile Plans", description = "The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one in Thrallmar that can transcribe such vile script - the blood elf Magister Bloodhawk. \n\n", objectives = "Take the Burning Legion Missive to Magister Bloodhawk in Thrallmar.", progress = "I have little time to waste, <class>. What is this you pester me with?", completion = "You were right to bring this to my attention. This could be a production order for additional fel reavers - or new attack plans! This will take some time to decipher. Leave me. I will summon you when I know more. \n\n<Magister Bloodhawk nods to you as you turn to leave> \n\nYou are a sharp one, <name>. I shall be watching your progress with interest." }
WordHunterWoW_QuestEN[10394] = { title = "Disruption - Forge Camp: Mageddon", description = "Pay close attention, {name}. We've been surveying the Legion camps that lie along the ridge ahead. We have reason to believe that these so-called 'Forge Camps' are where the demons are constructing those blasted Fel Reavers. \n\nYou can see the closest target, Forge Camp: Mageddon, to the west. Our intelligence suggests that it's still under construction. If you can slay the Gan'arg Servants and their master - Razorsaw - we can bring the Legion's Fel Reaver production to a grinding halt!   \n\n", objectives = "Kill 10 Gan'arg Servants and Razorsaw at Forge Camp Mageddon and return to Forward Commander Brock at Honor Point.", progress = "Don't tell me your getting cold feet, <class>? If they finish construction on that Forge Camp, you'll have more to worry about than just those Fel Reavers! Get to it!", completion = "Well, I must say, I am impressed, <name>. I didn't think you had the mettle for this mission. Well done. Well done, indeed." }
WordHunterWoW_QuestEN[10395] = { title = "The Dark Missive", description = "The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one at Honor Hold who can decipher such archaic script - the draenei mystic, Kryv. \n\nTake the Burning Legion Missive to Warp-Scryer Kryv who resides within the War-Room at Honor Hold.\n", objectives = "Take the Missive to Warp-Scryer Kryv in the main keep of Honor Hold.", progress = "What is it, <class>? I sense you've found something that speaks of a coming doom.", completion = "It is fortuitous that you intercepted this missive when you did, <name>. Though it will take me some time to decipher, I can already sense the hatred and urgency woven into this scroll. I fear the Legion's true motives in this land will soon be made evident...\n\nGive me a moment to decipher this script." }
WordHunterWoW_QuestEN[10396] = { title = "Enemy of my Enemy...", description = "Now we focus on the second target - Forge Camp: Rage. It lies just west of Mageddon. Trouble is, the demons have a number of fel cannons aimed straight at the Horde's outpost of Thrallmar! Though I can scarcely believe it, we actually need the Horde to help us hold the line at the Dark Portal. We can't afford to let Thrallmar fall.  You've got to destroy these cannons before the Legion pulverizes our allies! ", objectives = "Destroy 3 Fel Cannon MKIs in Forge Camp: Rage and return to Field Marshal Brock at Honor Point.", progress = "The Legion could start shelling the Horde at any time, <name>! You need to destroy those blasted cannons!", completion = "I have to hand it to you, <name>, you're a fighter born! Those Horde yokels may never know how close they came to the end. It takes real character to step in harm's way on behalf of your enemies. That's the kind of honor and commitment that holds the Alliance together!" }
WordHunterWoW_QuestEN[10397] = { title = "Invasion Point: Annihilator", description = "Well, we've located the Legion's final base on the ridge - Invasion Point: Annihilator. It lies northwest of Forge Camp: Rage - and it houses a warp-portal through which the Legion has been drawing its reinforcements! \n\nYou've got to close that portal to prevent any more demons from coming through. The Point's overlord, Warbringer Arix'Amal, holds the portal's activation key. Take it from him and shut that blasted gateway down!  \n", objectives = "Slay Arix'Amal. Take the Burning Legion Gate Key. Use the Burning Legion Gate Key on the Rune of Spite.", progress = "You close down that war-portal yet, <name>? While you're here shuffling your feet, there are more demons entering Outland!", completion = "Great job! That should drastically cut down on the number of demons trying to creep up our backsides. I can't thank you enough for your help out here, <name>." }
WordHunterWoW_QuestEN[10398] = { title = "Return to Honor Hold", description = "PH: Go to Honor Hold.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "PH:  Go to Honor Hold.PH: Go to Honor Hold.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10399] = { title = "The Heart of Darkness", description = "It is just as I feared. Arix'Amal - the demon you killed earlier, was working for a secret Legionlord - Arazzius the Cruel. It appears this new villain has amassed a force of hellish terrorfiends near the Pools of Aggonar. \n\nYou must journey there and slay the terrorfiends before they strike against us. But be wary, friend - the Pools of Aggonar lie within a tortured, poisonous valley. You can find the cursed pools to the northwest of here, beyond Hellfire Citadel. \n\nLight be with you, {name}.  \n", objectives = "Kill 10 Terrorfiends in the Pools of Aggonar and return to Warp-Scryer Kryv in the main keep of Honor Hold.", completion = "I foresaw this great victory, <name>. The blessed naaru smile upon you this day." }
WordHunterWoW_QuestEN[10400] = { title = "Overlord", description = "The honorable Warp-Scryer has told me of your perils, {name} - and of the new foe you've discovered. If Kryv is to be believed, this 'Arazzius the Cruel' is as powerful and evil as any foe the Sons of Lothar have ever faced. \n\nWill you stand for us now, {name}? Will you face this Legionlord and deliver the Light's justice upon him? If so, you will find him at the Pools of Aggonar. If not, his evil will most certainly find you. \n", objectives = "Slay Arazzius the Cruel in the Pools of Aggonar and return to Force Commander Danath Trollbane in the keep of Honor Hold.", completion = "Light be praised, I knew you'd do it! Arazzius and his minions are no more! Soon, we'll have the Legion running for home and this battered world will be safe once more. Then, when justice has been met, we can return home as well. \n\nThank you, <name> - the Alliance and the Sons of Lothar honor you this day!" }
WordHunterWoW_QuestEN[10401] = { title = "Mission: End All, Be All", description = "Do you know what would have happened if you had not intercepted this missive, <name>?\n\n<Nazgrel nods.>\n\nThe entirety of the Legion army in Hellfire would have been knocking on our door. There is no way that we could have survived such an assault.\n\nThere is only one way to make sure that these orders never reach the Legion Front. You must travel to the Pools of Aggonar, west of here, and slay this Arazzius creature.\n\nDo this and I will see to it that the Warchief grants you a commendation.You will be able to choose one of these rewards:", objectives = "Nazgrel at Thrallmar in Hellfire Peninsula has asked that you slay Arazzius the Cruel." }
WordHunterWoW_QuestEN[10403] = { title = "Naladu", description = "Perhaps not all hope is lost for the Dreghood.  I am one of four elders that guided this tribe before we were enslaved by the Illidari.  I thought the others were dead, but I've slowly learned that at least two others are alive - chained down and powerless just as I am.\n\nI've not yet been able to find Naladu and fear for the worst.  There are more huts in the ruins upstairs; perhaps you could look for him.  It would be a great boon for our tribe if all our elders were alive.", objectives = "Seek out Naladu inside the Ruins of Sha'naar.", completion = "You've come to help my tribe, <race>?  How unusual.  There aren't many that care about the fate of the Broken in this land." }
WordHunterWoW_QuestEN[10404] = { title = "Against the Legion", description = "We've established that the Burning Legion has been providing Kael'thas with technological assistance, magnifying his threat many times over.\n\nBased on the Legion's numbers in the region, the largest impact we can make on our enemy's alliance is through a head-on attack on the forge bases to the north.\n\nGo to Forge Base: Oblivion and Forge Base: Gehenna and destroy our enemies.  May the Light guide your blade, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Exarch Orelis at Area 52 wants you to go to Forge Base: Oblivion and Forge Base: Gehenna and slay 12 Gan'arg Forgehands, 6 Mo'arg Forgelords and 6 Wrathbringers.\n\nPerforming quests for the Aldor will cause your Scryers reputation to decrease." }
WordHunterWoW_QuestEN[10405] = { title = "S-A-B-O-T-A-G-E", description = "We must destroy the machinery that is making these nexus-stalker aberrations possible. To strike at their proto-accelerator would be futile as it is an ethereal creation. We must instead destroy the manaforge energy tube that they are using as a conduit.\n\nI have all that I need to create a device to overload the conduit save for one item. I need a wrapping from an archon or overlord that might be transforming soon in order to calibrate the device.", objectives = "The Image of Commander Ameer at the Ethereum Staging Grounds - Ethereum Transponder Zeta - wants you to recover 1 Prepared Ethereum Wrapping.", progress = "Have you recovered the wrapping?", completion = "Excellent! Now to calibrate the device." }
WordHunterWoW_QuestEN[10406] = { title = "Delivering the Message", description = "I'm sending one of my demolitionists out to place the disruption device. Just make sure no harm comes to him as he's placing the disruptor.\n\nKeep him protected! He will not fight back if enemies attack him, as he is only a holographic image, but the image can be destroyed!\n\nReturn to me once the job is done.", objectives = "Escort the Protectorate Demolitionist to the Manaforge Ultris Conduit and protect him while he sabotages the pipeline.", progress = "He must succeed!", completion = "Thanks to you, their plans are in ruin! Now only one thing remains... Salhadaar." }
WordHunterWoW_QuestEN[10407] = { title = "Socrethar's Shadow", description = "The infamous eredar, Socrethar, leads the Burning Legion in Netherstorm.  Mentioning his name is enough to make most draenei shudder.  He gives orders from an island in the northwest that only his most trusted lieutenants can access.\n\nTo get there you will need to obtain a teleportation stone, which won't be an easy task.  The first half of the stone is in the possession of Forgemaster Morug at Forge Base: Oblivion.  The second half is held by Silroth at Forge Base: Gehenna.", objectives = "Anchorite Karja at Area 52 wants you to obtain the First Half of Socrethar's Stone from Forgemaster Morug at Forge Base: Oblivion and the Second Half of Socrethar's Stone from Silroth at Forge Base: Gehenna.\n\nPerforming quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Have you obtained Socrethar's teleportation stone, <name>?", completion = "Your dedication to our cause is exemplary, <name>. With Socrethar's teleportation stone in our possession only one thing remains to be done." }
WordHunterWoW_QuestEN[10408] = { title = "Nexus-King Salhadaar", description = "I have in my possession another disruptor--one capable of destroying the three conduits that surround Salhadaar. Once the conduits are destroyed, Salhadaar's protective force fields will be down. For this act, he will strike at you with a ferocity you have never before witnessed, {name}.\n\nIf you are willing to rid the world of Salhadaar, I will give you the disruptor.", objectives = "Use the Protectorate Disruptor to bring down Salhadaar's force fields, then destroy Nexus-King Salhadaar.", progress = "Is... Is he really dead? Destroyed?", completion = "It has been a thousand years, maybe more, since Salhadaar began his crusade to exterminate all that would stand in his way. I can hardly believe that this is the last we'll see of him... You have done all of us a great service, <name>, and for that you will be rewarded." }
WordHunterWoW_QuestEN[10409] = { title = "Deathblow to the Legion", description = "When facing eredar of great power, large armies are useless for the most part.  Their corruptive powers over mortal souls are such that only the strongest-willed can even stand face to face with them.\n\nTake this stone to the Invasion Point: Overlord, between Forge Base: Oblivion and Gehenna and bring your closest, strongest friends with you.  Orelis and Karja will meet you at Socrethar's Seat; I will send Adyen along with them.\n\nMay the Light prevail today, {name}.  May Socrethar meet his end.", objectives = "High Priestess Ishanah wants you to go to the Legion Teleporter at the northwestern corner of Netherstorm and use it to teleport to Socrethar's Seat. Once there, defeat Socrethar.\n\nPerforming quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Light be with you, <class>.", completion = "It is done, <name>.  Socrethar has been destroyed.\n\nI and the others will recover from our wounds, <name>.  The wrath of Socrethar's magic was far too much for young Kaylaan, however.  Not even my strongest prayer could raise him.\n\nIt is an unbearable pity that one so young would fall in battle.  However, in the end his will was strong enough to recover from the Legion's corruption and we may find solace in that." }
WordHunterWoW_QuestEN[10410] = { title = "Ishanah's Help", description = "The time has come to face Socrethar, {name}.  Confronting an eredar leader isn't something that's taken lightly among us.  A single mistake is likely to cost us our lives if we're ill-prepared.\n\nTake Socrethar's teleportation stone to High Priestess Ishanah at the Shrine of Unending Light in Shattrath City.  She will determine how we need to handle the situation.", objectives = "Take Socrethar's Teleportation Stone to High Priestess Ishanah at the Shrine of Unending Light on the Aldor Rise in Shattrath City.\n\nPerforming quests for the Aldor will cause your Scryers reputation to decrease.", progress = "What troubles you, child?", completion = "Socrethar... I remember that name.  He was once a renowned warrior of the Light and pride was his only flaw." }
WordHunterWoW_QuestEN[10411] = { title = "Electro-Shock Goodness!", description = "Around the ruined manaforge you will find the run-off of Dimensius's handy work. Seeping sludge occupies the pools that surround Ultris. Directly below those pools, where the Ethereum Staging Grounds now stand, you will find even more run-off in the form of void waste.\n\nThe best method of disposal is to use electro-shock to break slimes down to globules. Use this elixir to augment your attacks with electricity. The resultant discharge will break the slimes up into their raw form. Destroy the globules!", objectives = "Researcher Navuud at the Protectorate Watch Post in Netherstorm has asked that you destroy 30 Void Waste Globules and 30 Seeping Sludge Globules.", progress = "Both the sludge and waste are extremely toxic. They will form into a congealed void horror if left unchecked!", completion = "I hope it's not too late. Did you notice any abnormally large slimes at or near the area where the void wastes drain into?" }
WordHunterWoW_QuestEN[10412] = { title = "Firewing Signets", description = "It is no secret that Kael'thas Sunstrider perceives us as a great threat.  Let's face it - not many sin'dorei, fresh from Silvermoon, are willing to join the sort of company that Kael keeps.\n\nIt's also no secret that this is not just a war of words.  Scryers and the armies that serve Kael'thas attack each other on sight.  The only way to prove you're with us, {name}, is to do your share of fighting.\n\nKael's lower ranking followers wear Firewing signets to indicate their rank.  Bring them to me.", objectives = "Magistrix Fyalenn in Shattrath City wants you to bring her 10 Firewing Signets.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Go on, <name>.  Speak.", completion = "Well done, <name>.  You might prove to be a useful ally after all." }
WordHunterWoW_QuestEN[10413] = { title = "The Horrors of Pollution", description = "You carefully fill a vial with the fallen void horror's ooze.\n\nResearcher Navuud at the Protectorate Watch Post would be quite interested in such a find! Take it to him at once!", objectives = "Take the Vial of Void Horror Ooze to Researcher Navuud at the Protectorate Watch Post in Netherstorm.", progress = "Hrm, you look a bit dirty... What have you gotten yourself into?", completion = "WHAT!? You faced off against a void horror? And lived?! Incredible!\n\nThis sample is worth its weight in gold. A find like this deserves a reward." }
WordHunterWoW_QuestEN[10414] = { title = "Single Firewing Signet", description = "", objectives = "Even the smallest contribution to our cause is noted, <name>.  Our enemies are many, but we shall prevail!", progress = "Even the smallest contribution to our cause is noted, <name>.  Our enemies are many, but we shall prevail!", completion = "Yes... Kael's numbers continue to dwindle as our numbers continue to grow.\n\n<This quest can be repeated up to Honored reputation.>" }
WordHunterWoW_QuestEN[10415] = { title = "More Firewing Signets", description = "", objectives = "What have you done for us lately, <name>?  The war against Kael'thas is not going to fight itself, you know?", progress = "What have you done for us lately, <name>?  The war against Kael'thas is not going to fight itself, you know?", completion = "Excellent!  All who oppose us will be crushed!\n\n<This quest can be repeated up to Honored reputation.>" }
WordHunterWoW_QuestEN[10416] = { title = "Synthesis of Power", description = "Arcane tomes are not ordinary books that happen to deal with arcane matters.  There is intrinsic power in them - a power I've learned to synthesize into a single arcane rune.\n\nShould you find an arcane tome in your travels I will give you one such rune.  Only the most powerful wielders of magic carry the books I need.  In Outland this usually means Kael's blood elves - but you'd be surprised by where such tomes often turn up.", objectives = "Voren'thal the Seer in Shattrath City wants you to obtain an Arcane Tome.\n\nPerforming quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Have you obtained an arcane tome yet, <name>?", completion = "As promised, <name>.  The entirety of the book's raw power, condensed into a single rune." }
WordHunterWoW_QuestEN[10417] = { title = "Run a Diagnostic!", description = "Wherever the Consortium establishes a presence, we bring our eco-dome technology. The fields allow us to work in a controlled and life-sustaining atmosphere since we often find ourselves in hostile environments.\n\nNetherstorm's volatile conditions and creatures have begun to destroy the equipment that sustains our domes, especially the generator east of here. I've started a diagnostic there in hopes of understanding what can be done to combat the damage. Would you collect the results and bring them to me?", objectives = "Retrieve the Diagnostic Results and return them to Mehrdad at Midrealm Post.", progress = "Did you get the diagnostic results?", completion = "<Mehrdad nods, then examines the diagnostic results.>\n\nThis is worrisome. The damage is much more severe than I believed. I can send to the Stormspire for some tools to begin repairs, but that's useless unless we've isolated what's damaging the equipment in the first place." }
WordHunterWoW_QuestEN[10418] = { title = "Deal With the Saboteurs", description = "In searching the area for clues about the damage to our equipment, I've seen pieces of the shield generators at the bottom of the small lake to the north. I'm not sure why the crocolisks have taken an interest in the equipment, but we have to put a stop to this problem.\n\nThe Consortium is quite clear on this matter. If it comes down to a choice between the equipment and crocolisks, the animals will have to go. I'll make it worth your while to deal with them.", objectives = "Mehrdad at Midrealm Post wants you to kill 8 Barbscale Crocolisks.", completion = "The area's looking clearer already. The domes are quite useful, but the major drawback is the rampant growth they encourage in some places, accelerating the growth and proliferation of native species." }
WordHunterWoW_QuestEN[10419] = { title = "Arcane Tomes", description = "", objectives = "Have you obtained any more arcane tomes, <name>?", progress = "Have you obtained any more arcane tomes, <name>?", completion = "The power contained in this tome is tremendous.  Yet it is easily condensed into a single rune by one with a clear mind." }
WordHunterWoW_QuestEN[10420] = { title = "A Cleansing Light", description = "This temple is one of the holiest places in all of Outland.  The power of the Light here is so strong, that even items with the strongest fel taint can be cleansed of a worldly item.\n\nShould you run into any fel armaments in your confrontations with demonic enemies, bring them to me and I will demonstrate the cleansing power of the Light.", objectives = "Bring a Fel Armament to Ishanah in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Have you obtained any fel armaments yet, <name>?", completion = "Watch as foul materials disintegrate.  Watch as metal turns to dust.\n\nThe Light cleanses all and only the purest residue remains." }
WordHunterWoW_QuestEN[10421] = { title = "Fel Armaments", description = "", objectives = "Have you run into any fel armaments lately?  Let the Light do its work, <name>.  Do not allow these foul objects to remain in this world.", progress = "Have you run into any fel armaments lately?  Let the Light do its work, <name>.  Do not allow these foul objects to remain in this world.", completion = "The fel materials are removed from this world.  Only the Light's residue remains." }
WordHunterWoW_QuestEN[10422] = { title = "Captain Tyralius", description = "Captain Tyralius took a platoon of soldiers south towards the Ethereum Staging Grounds 10 days ago. We haven't heard from him or his crew since.\n\nChances are good that they were ambushed and killed but I'm getting a curious reading from my instruments.\n\nI think it's a distress signal but these things have been wrong before. If Tyralius is still alive, they're keeping him in one of their prisons. You'll have to locate the prison and open it with a key, probably found on the warden.", objectives = "Flesh Handler Viridius at the Protectorate Watch Post in Netherstorm has asked that you find and free Captain Tyralius.", completion = "Thank you, <name>. Tyralius suffered massive injuries but we think he's going to make it.\n\nHe mentioned fields of prisons, much like the one you rescued him from. Prisons full of creatures from all across the universe!\n\nWe'll be in touch should a need arise to crack those open. The Consortium has already expressed some interest in sending some teams out and is working on some technology to break through the Ethereum's locks." }
WordHunterWoW_QuestEN[10423] = { title = "To the Stormspire", description = "Master Engineer Ghabar will want to know about the results of the diagnostics. If anything, they caution us to keep a close eye on the workings of our dome generators. As the fields become more and more unstable, their effects will become harder to control. It could spell disaster for our expedition and anything else housed within the domes.\n\nYou'll find Ghabar at the Stormspire. Just follow the road north from this eco-dome and across the bridge. It'll lead you to the elevator at the base of the spire.", objectives = "Speak with Ghabar at the Stormspire in Netherstorm.", completion = "<You introduce yourself and report the results of Mehrdad's diagnostics at Eco-Dome Midrealm.>\n\nMehrdad is little more than a technician, but he possesses a keen eye for detail. If his observations are correct, then we'll need to take diagnostics at the rest of our dome generators as soon as possible." }
WordHunterWoW_QuestEN[10424] = { title = "Diagnosis: Critical", description = "If Mehrdad's results are correct -- and I have no reason to believe they're faulty -- then the rest of the domes could be in trouble.\n\nI do think Mehrdad has failed to identify the underlying cause of the failures. From time to time, creatures damage the generators, but never this severely.\n\nTo be on the safe side, I'd like for you to run a set of diagnostics at the Stormspire's main dome generator, located in Eco-Dome Sutheron at the very eastern edge of the dome.", objectives = "Use the Diagnostic Device while standing near the Eco-Dome Sutheron Generator and bring the Diagnostic Results back to Ghabar at the Stormspire.", progress = "Did you get those diagnostics?", completion = "These results match Mehrdad's exactly, but why? The only possible explanation I can think of is that some of the dome generation equipment has failed or gone missing. That would cause the domes to weaken significantly and fall out of balance as the diagnostics indicate." }
WordHunterWoW_QuestEN[10425] = { title = "Escape from the Staging Grounds", description = "Thank K'aresh! He would have torn me apart!\n\nI'm a Protectorate soldier, fleshling. My platoon was sent on a recon mission about 10 days ago. As we were moving across the upper ledges of this island, a group of Ethereum jumped us. At least I think it was Ethereum. They had the same energy color but their wrappings looked void.\n\nOnly Tyralius was spared. I think they put him in a prison cell.\n\nI've got to get back to the Protectorate Watch Post! Can you escort me back?\n", objectives = "Escort the Captured Protectorate Vanguard back to Protectorate Watch Post in Netherstorm.", completion = "<Commander Ameer appears pleased.>\n\nWell done, fleshling! This soldier might be the key to taking down the Ethereum's entire operation." }
WordHunterWoW_QuestEN[10426] = { title = "Flora of the Eco-Domes", description = "Just look around you, {class}! Isn't it amazing? Of course, this incredible resurgence of life is a byproduct of the ethereal domes, but imagine what it could do in the hands of the expedition.\n\nI'm preparing to negotiate with the ethereals for access to their technology, but I'd like to get a better idea of its effects on plant-based life.\n\nI've built a device to concentrate the dome's energies on the lashers in this area. Would you be so kind as to test it for me and share the results?", objectives = "Use the Energy Field Modulator on Farahlon Lashers. Observe the results and report back to Aurine Moonblaze at the Stormspire when you have conducted 10 tests.", progress = "Did you try focusing the dome's energy?", completion = "Oh my! Focusing the dome's energy seems to continue accelerating growth to the point where it breeds extreme aggression. If we do get the ability to use this technology, we have to be sure to calibrate it correctly." }
WordHunterWoW_QuestEN[10427] = { title = "Creatures of the Eco-Domes", description = "Your work with the lashers turned up some astounding information, but I wonder if it holds true for animals as well.\n\nGathering information on the talbuks that live underneath this dome is going to be trickier than studying the lashers, I'm afraid.\n\nUsing this tagging device, you can put a weakened talbuk to sleep and apply a tag that I'll use to track the animal as it matures. The tagging mechanism won't work unless the talbuk has expended most of its energy.", objectives = "Tag 12 Talbuks for Aurine Moonblaze at the Stormspire. You may tag either Talbuk Sires or Talbuk Does using the Talbuk Tagger.", progress = "Were you able to tag enough of the talbuk?", completion = "Excellent work. I'll keep a close eye on the ones you tagged and see if they mature as quickly as the other lifeforms in the dome.\n\nWith the proper control, we could use this technology to regrow the ruined areas of Outland and Azeroth." }
WordHunterWoW_QuestEN[10428] = { title = "The Missing Fisherman", description = "In the fevered dreams of our injured guest, she spoke of a fisherman, Cowlen, who was in some distress at Silvermyst Isle, to the southwest, off the coast of Azuremyst.\n\nWith all that has been happening, no one has had the opportunity to look into it, but I do feel a bit of worry. Perhaps there's something you can do, {name}?", objectives = "Find Cowlen at the southeast docks of Silvermyst Isle off the coast of Azuremyst.", completion = "My family... What have I done... What could I have done?\n\nWhy must I be punished so?" }
WordHunterWoW_QuestEN[10429] = { title = "When Nature Goes Too Far", description = "The dome technology possesses such power! Certainly, there are bounds beyond which we dare not go, {name}.\n\nCreatures allowed to grow too large or too fast could be just as bad as a barren landscape.\n\nI have heard rumors of just such a creature in the pool to the east. I've heard the ethereal merchants conspiring to catch the overgrown hydra for sport, but I have another purpose in mind for the giant. Bring me the creature's heart so I may study it.", objectives = "Aurine Moonblaze at the Stormspire wants you to bring her a Hulking Hydra Heart.", progress = "Did you get the sample from the monstrous hydra?", completion = "<Aurine accepts the heart.>\n\nEven for a creature of that size, this heart is far too large. It struggled to keep up with the creature's gigantic body. I have little doubt it would've died before reaching half its normal lifespan.\n\nEven with such risks, I'm determined to convince the Consortium to share their technology. There's too much promise here to give up now." }
WordHunterWoW_QuestEN[10430] = { title = "Testing the Prototype", description = "I've been working on a portable generator repair kit for use in some of the harsher climates that the Consortium operates in. Granted, it wasn't designed for Netherstorm, but we shouldn't have any problems with it.\n\nI had already scheduled a test with one of my best techs up at Eco-Dome Farfield beyond the Netherstone to the northeast. Take this prototype to Tashar. He'll know what to do with it. If it works, we can use it to reinforce the shield generators at the larger domes.", objectives = "Bring the Repair Apparatus to Tashar at Eco-Dome Farfield in Netherstorm.", progress = "It looks like you've got the prototype. Did Ghabar send you?", completion = "This looks a little peculiar. Ghabar definitely didn't have Netherstorm in mind when he designed it.\n\nDon't look so surprised, <name>. Netherstorm is tame compared to some of the environments I've worked in. Nevertheless, a failing dome is always a concern." }
WordHunterWoW_QuestEN[10431] = { title = "Outside Assistance", description = "The Sunfury briefings support the theory that Kael'thas has been receiving outside help in constructing and running these manaforges.  Who this is remains a bit of a mystery, though we're likely to find out in Manaforge Ara.\n\nI've sent a group of my men to scout the surrounding area.  Go to Tuluman's Landing, north of here, and speak to Kaylaan.  See what he's discovered at Manaforge Ara.  Find out who is assisting the Sunfury army and take care of them. ", objectives = "Go to Tuluman's Landing, north of Area 52, and speak to Kaylaan.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "You're all the help Orelis is sending?  He must think very highly of you.\n\nLet's get this over with." }
WordHunterWoW_QuestEN[10432] = { title = "Damning Evidence", description = "As you may have noticed, there are servants of the Burning Legion all over Manaforge Ara.  Kael'thas has entered an alliance with the Burning Legion.  He must've caught wind of Illidan's descent into insanity and switched paymasters accordingly.\n\nIf the Scryers get definite proof of this, it will give them a considerable political advantage.  I know for a fact that the Legion forces at this manaforge have orders that bear Kael's seal.\n\nGet these orders and bring them to Thalodien.", objectives = "Obtain 8 Orders from Kael'thas from demons at Manaforge Ara and bring them to Spymaster Thalodien in Area 52.\n\nPerforming quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Well?  What did Theledorn have to say?", completion = "This is big, <name>.  Very big!\n\nVoren'thal is going to want to hear about this as soon as possible." }
WordHunterWoW_QuestEN[10433] = { title = "Keeping Up Appearances", description = "The ethereals are clever and very observant, so it's no accident that I'm here posing as a simple furrier. In fact, I've been sent from Area 52 to appraise the technology the ethereals use to generate their eco-domes.\n\nI'd like to enlist your help, {class}. We've been asked to use non-goblin agents whenever possible.\n\nWhat I want you to do is bring me a number of ripfang lynx pelts in the guise of a hunter. You can find the lynxes all over Eco-Dome Midrealm.", objectives = "Bring 10 Ripfang Lynx Pelts to Shauly Pore at Midrealm Post.", progress = "<Shauly raises his voice so as to catch the attention of the ethereals in the area.>\n\nHave any pelts to sell me?", completion = "<Shauly makes a show of admiring the skins.>\n\nThese are magnificent, utterly magnificent! I'll pay you top coin for these! How much to retain your services?" }
WordHunterWoW_QuestEN[10434] = { title = "The Dynamic Duo", description = "Excellent job.\n\n<Shauly winks at you.>\n\nI think they're buying it. Now, when I send you up to speak with my associates at the Stormspire, there won't be any suspicion at all.\n\nYou'll want to look for Action Jaxon and Audi the Needle up there. They'll tell you everything you need to know. Tell 'em Shauly sent you.", objectives = "Speak with Audi the Needle at the Stormspire in Netherstorm.", completion = "<You introduce yourself and tell Audi that Shauly sent you.>\n\nAh, yes, we've been expecting someone to help us, err -- move some, uh, merchandise." }
WordHunterWoW_QuestEN[10435] = { title = "Retrieving the Goods", description = "<Audi looks around and then lowers her voice.>\n\nI'm sure Shauly told you a bit about our work here. When Jaxon and I are out in the field 'hunting,' we've been collecting pieces of the ethereal eco-dome generators and hiding them in the nests of our prey, the raptors in Eco-Dome Farfield.\n\nIt's a remote area to the northeast of the Stormspire, close to the Netherstone. I don't anticipate you'll run into many ethereals there, but would you be willing to help us collect the dome generator pieces?", objectives = "Audi the Needle at the Stormspire wants you to bring her 10 Dome Generator Segments.", progress = "Did you collect everything?", completion = "Excellent work! The most difficult part of the project is done. Now, all we need is a way to get these back to Area 52 and attract the interest of the Cenarion Expedition as well. There should be enough here for our own needs and to earn a little profit on the side." }
WordHunterWoW_QuestEN[10436] = { title = "All Clear!", description = "Before we can begin the test, we have to make certain the area is clear of anything that might interfere. In our case, that means these overgrown lizards.\n\n<Tashar gestures toward the scythetooth raptors.>\n\nThere's no telling what might happen if one of those decides to take a nice bite out of the generator while it's charging. I've seen a lot of strange things in all my years as a technician, including more than a few abominations that had their beginnings as humble animals.", objectives = "Tashar, stationed at Eco-Dome Farfield, wants you to kill 12 Scythetooth Raptors.", progress = "Have you cleared the test area?", completion = "Well done. It looks like everything is in order. We're ready to begin." }
WordHunterWoW_QuestEN[10437] = { title = "Recipe for Destruction", description = "Atop Manaforge Ultris lies the tear in the nether that Void Lord Dimensius came through. That tear provides Dimensius with a link to the Void, rendering him immune to physical harm. If we can get a lock on the conduit that Dimensius is using to keep himself phased out of this plane of existence, we can destroy it and then destroy Dimensius.\n\nTo do this, we're going to first need you to collect fragments of Dimensius from the void creatures that he sends out to do his dirty work.", objectives = "Recover 4 Fragments of Dimensius.", progress = "Have you collected enough fragments?", completion = "Excellent. With these fragments, we can calibrate a bomb that will destroy the void conduit atop Ultris. With the void conduit destroyed, Dimensius's connection with the void will be severed and he will be left defenseless!" }
WordHunterWoW_QuestEN[10438] = { title = "On Nethery Wings", description = "Here it is, {name}. Take this phase disruptor and mount up! The Protectorate nether drake will fly you close enough to Ultris so that you can drop the disruptor on top of the void conduit.\n\nDrop as many disruptor charges as possible to ensure complete annihilation!\n\nWhen you are ready, speak with the nether drake and he'll take you up.\n\nIf you miss the mark you will have to get more bombs from me before you can go up again.", objectives = "Professor Dabiri at the Protectorate Watch Post in Netherstorm wants you to use your Phase Disruptor when you get in range of the Void Conduit that rests atop Ultris. Drop as many charges of the Phase Disruptor as you can to ensure total annihilation. The Phase Disruptor charges will automatically home in on the Void Conduit so long as you are close enough to use it.\n\nReturn to Professor Dabiri should you succeed!", completion = "The time to strike has come! With the tear gone, Dimensius is vulnerable to physical and magical attacks!" }
WordHunterWoW_QuestEN[10439] = { title = "Dimensius the All-Devouring", description = "Your brave actions have forced Ameer to react! He has deployed Captain Saeed and the Avengers!\n\nNow all that is left to do is destroy Dimensius.\n\nWhen you are ready, I will call for Saeed. If he is not currently fighting another battle, he will be awaiting orders from you directly east of here.\n\nLet him know when you are ready to fight and he will put his troops in motion!\n\nI wish you luck, fleshling! We have hunted Dimensius for a thousand years!", objectives = "Speak with Captain Saeed, follow his army to Manaforge Ultris, and kill Dimensius the All-Devouring!", progress = "What of the void lord?", completion = "For a thousand years, all we have known is conflict. We have defended our people from the attacks of both void creature and ethereal alike.\n\nNow, one of our most hated enemies lies dead - finally.\n\nI give you the thanks of a hundred million ethereals, fleshling." }
WordHunterWoW_QuestEN[10440] = { title = "Success!", description = "The test was a resounding success! We can certainly use this device to start repairing the domes.\n\nCarry word of the test results to the Stormspire and let Ghabar know that I've also found a pattern in the damage to the shield generators. Key pieces of generator units have gone missing from a number of sites. This is no accident, {name}, no technological failure. We're being stolen from. ", objectives = "Return to Ghabar at the Stormspire in Netherstorm.", completion = "I'll have my techs get to work on those repairs right away.\n\nTashar's suspicion of sabotage worries me, though. I can't think of anyone who would be bold enough to steal our technology. Not anyone who knows what we're capable of, anyway. It may be time to lock down the Stormspire." }
WordHunterWoW_QuestEN[10441] = { title = "Peddling the Goods", description = "<Audi lowers her voice again.>\n\nNow that we have the goods, I'll be sending most of the parts on to Area 52. There's enough here for more than one generator, presenting us with a perfect business opportunity.\n\nI've seen the Cenarion Expdedition's representative trying to negotiate. I want you to let her know that we can provide what she seeks at a very reasonable price. There's no reason for her to continue dealing with those two-timing ethereals.", objectives = "Speak with Aurine Moonblaze at the bottom of the Stormspire in Netherstorm.<Audi lowers her voice again.>\n\nNow that we have the goods, I'll be sending most of the parts on to Area 52. There's enough here for more than one generator, presenting us with a perfect business opportunity.\n\nI've seen the Cenarion Expdedition's representative trying to negotiate. I want you to let her know that we can provide what she seeks at a very reasonable price. There's no reason for her to continue dealing with those two-timing ethereals.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10442] = { title = "Helping the Cenarion Post", description = "{class}, there's some tauren by the name of Thiah Redmane that keeps pestering us for assistance.  She's with the Cenarion Expedition, and they've setup a little post just to the west on the south side of the road leading to Zangarmarsh.\n\nIf you hit Thornfang Hill, you've gone too far.\n\nDo you think you might head over there and see what she needs?  I don't want to have to bother Ranger Captain Venn'ren with such trivialities.", objectives = "Falconer Drenna Riverwind wants you to offer your services to Thiah Redmane at the Cenarion Post in Hellfire Peninsula.", completion = "Oh, goodness, you must be the help I requested weeks ago from Falcon Watch.\n\nWell, you're here now and there's a lot to be done.  I have just the thing to start you out." }
WordHunterWoW_QuestEN[10443] = { title = "Helping the Cenarion Post", description = "The Cenarion Circle has sent an expedition to Outland and, as I understand it, they are here to study what has happened and to help reverse any damage that they can.\n\nThey've setup a little post just to the west on the south side of the road leading to Zangarmarsh.\n\nIf you hit Thornfang Hill, you've gone too far.\n\nWould you please go and see how you might help them?  Speak with Thiah Redmane as she is the one that sent the request to us for assistance.", objectives = "Amaan the Wise would like for you to offer your services to Thiah Redmane at the Cenarion Post in Hellfire Peninsula.", completion = "Oh, goodness, you must be the help that I requested from the Temple of Telhamat.\n\nI'm glad that you're here; there's a lot to be done, and I have just the thing to start you out." }
WordHunterWoW_QuestEN[10444] = { title = "Report to the Allerian Post", description = "This calls for immediate action!\n\nWe have someone out in the field closer to Firewing Point that I want you to speak with.  He'll have a better idea of what our next step should be.\n\nReport to Lieutenant Meridian out at the Allerian Post and apprise him of the situation.  You'll find the post to the northeast on the southern bank of the river just south of Firewing Point.\n\nGodspeed, {name}.", objectives = "Jenai Starwhisper wants you to report to Lieutenant Meridian at the Allerian Post in Terokkar Forest.", completion = "Bomb parts.  So my suspicions were true.  That's not something that I wanted to be right about.\n\nOkay, you and I have some grim business ahead of us then." }
WordHunterWoW_QuestEN[10445] = { title = "The Vials of Eternity", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.", objectives = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.", progress = "I've asked the impossible of you, yet I expect you to succeed.  Much depends on it.", completion = "The power contained even in this small amount of water from the Well of Eternity is incredible.\n\nI can see clearly into every moment in time linked to Hyjal... the creation of the second Well of Eternity, Illidan's imprisonment, the enchantment of the World Tree and... yes!  The Battle of Mount Hyjal.\n\nWe must make haste, the timeline is not safe." }
WordHunterWoW_QuestEN[10446] = { title = "The Final Code", description = "They're building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.\n\n{name}, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.\n\nTake the final code to the mana bomb that they're working on in the central courtyard and set it off.\n\nOnly then will we be certain that the Allerian Stronghold is safe.", objectives = "Lieutenant Meridian wants you to use The Final Code to set off the Mana Bomb. Then report back to Jenai Starwhisper at the Allerian Stronghold in Terokkar Forest.", completion = "YOU DID IT!  YOU SAVED US!  YOU SAVED THE ALLERIAN STRONGHOLD!!\n\nWith their forces decimated, their leader dead and the mana bomb destroyed, we can all breathe much easier now.\n\n<name>, I've never seen such selflessness... such heroism!  Please, accept this on behalf of all of us." }
WordHunterWoW_QuestEN[10447] = { title = "The Final Code", description = "They're building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.\n\n{name}, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.\n\nTake the final code to the mana bomb that they're working on in the central courtyard and set it off.\n\nOnly then will we be certain that Stonebreaker Hold is safe.", objectives = "Sergeant Chawni wants you to use the Final Code Sheet to set off the Mana Bomb. Then report back to Tooki at Stonebreaker Hold in Terokkar Forest.", completion = "YOU DID IT!  YOU SAVED US!  YOU SAVED STONEBREAKER HOLD!!\n\nWith their forces decimated, their leader dead and the mana bomb destroyed, we can all breathe much easier now.\n\n<name>, I've never seen such selflessness... such heroism!  Please, accept this on behalf of all of us." }
WordHunterWoW_QuestEN[10448] = { title = "Report to Stonebreaker Camp", description = "This calls for immediate action!\n\nWe have someone out in the field closer to Firewing Point that I want you to speak with.  She'll have a better idea of what our next step should be.\n\nReport to Sergeant Chawni out at Stonebreaker Camp and apprise her of the situation.\n\nTake the road north out of the hold.  From the middle of Tuurem, follow the road to the east.  You'll find the camp on the bank of the river that lies just southwest of Firewing Point.\n\nGood luck, {name}.", objectives = "Tooki wants you to report to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest.", completion = "Bomb parts. So my suspicions were true.  That's not something that I wanted to be right about.\n\nOk, you and I have some grim business ahead of us then." }
WordHunterWoW_QuestEN[10449] = { title = "Apothecary Zelana", description = "Apethecary Zelana has been studying the beasts of Hellfire Peninsula in the field.  She wants a sample of the blood you gathered; with luck, she might discover what turned those Bonechewer freaks' skins red!\n\nZelana is at Reaver's Fall, southeast of Thrallmar.  Follow the road east and when you see a destroyed, green-glowing hunk of metal, you're there.  She has a camp set up behind the wyverns.", objectives = "Vertok Axebreaker in Thrallmar wants you to bring Bonechewer Blood Samples to Apothecary Zelana at Reaver's Fall.", progress = "It is my honor to serve the wishes of the Horde.  How might I aid you?", completion = "Ah, yes.  The blood of the Bonechewer clan.  I am very curious about these orcs... they are still the depraved fiends of the past, but their strength and power is greater than what I had heard...\n\nWell, let us begin, shall we?" }
WordHunterWoW_QuestEN[10450] = { title = "Bonechewer Blood", description = "Bonechewers!  They should all die!  The sight of their red skin and depravity makes my blood boil!\n\nI have a mission for you, {name}.  Kill Bonechewer orcs and collect their vile blood.  There is an apothecary who needs the blood for her tests, so we can discover how these orcs fell to the demon taint, a taint from which we so recently freed ourselves.\n\nBonechewers scavenge near the ruined battlements along the Path of Glory, to the south.  Return to me when your mission is complete.", objectives = "Bring 12 Bonechewer Blood Vials to Vurtok Axebreaker in Thrallmar.", progress = "Did you face the bonechewers, <name>.  I hope their blood was spilled in great gouts!", completion = "Hah!  So you did meet the bonechewers, our depraved cousins.  Well done, <name>.  My only regret is that more of them could not lay down their lives and spill their blood, to cool my outrage!" }
WordHunterWoW_QuestEN[10451] = { title = "Escape from Coilskar Cistern", description = "Thank the Earthmother! I parted ways with the others several days ago. I was intent on discovering the source of the disturbance that the spirits of water were feeling. My search led me to Coilskar where I discovered that the naga were befouling the water supply of Shadowmoon Valley.\n\nUnfortunately, I was discovered and taken prisoner. There's no telling what ghastly things they had in store for me.\n\nWe must leave this place! Help me escape and then seek out Torlok at the Altar of Damnation.\n", objectives = "Escort Earthmender Wilda out of Coilskar Cistern and then seek out Earthmender Torlok at the Altar of Damnation, found at the western outskirts of the Hand of Gul'dan.", completion = "Praise the Earthmother. I am certain that Wilda will find her way home. Please accept this as a token of our appreciation." }
WordHunterWoW_QuestEN[10452] = { title = "DON'T USE [PH] Fel Orc 1", description = "[PH Fel Orc 1.", objectives = "[PH Fel Orc 1.[PH Fel Orc 1." }
WordHunterWoW_QuestEN[10453] = { title = "DON'T USE [PH] Fel Orc bread", description = "[PH Fel Orc bread", objectives = "[PH Fel Orc bread[PH Fel Orc bread" }
WordHunterWoW_QuestEN[10454] = { title = "FLAG - OFF THE RAILS", description = "", objectives = "" }
WordHunterWoW_QuestEN[10455] = { title = "The Encroaching Wilderness", description = "We've been growing the Living Grove at an accelerated rate, but somehow the lynxes there have become lost to our control.\n\nWhere once their population was stable, the grovestalker lynxes are now beginning to encroach upon Sylvanaar, and there have been a number of unpleasant incidents of late.\n\nI suspect that the arakkoa of Veil Lashh are somehow behind it, but the immediate issue is with the lynxes themselves.\n\nI would be most grateful if you would help us to deal with this situation.", objectives = "Slay 12 Grovestalker Lynxes.", completion = "That was fast.  Are you sure that you dealt with as many as was necessary?\n\nExcellent, there's something else that you can help us with if you are willing?" }
WordHunterWoW_QuestEN[10456] = { title = "Marauding Wolves", description = "The filthy races of the Horde have taken over a settlement to the east.  They've brought with them a large pack of the dire wolves that they prefer to use as mounts and sentries.\n\nThese sentries have been marauding across the bridge that separates us.  They've been stalking our fey drakes, which are critical to the pollination of the Living Grove.\n\nUse the east exit to traverse the bridge over Bloodmaul Ravine that leads to the Jagged Ridge to the east, and bring me their tails as proof!", objectives = "Collect 4 Thunderlord Dire Wolf Tails.", progress = "I cannot stress strongly enough the need for those Thunderlord dire wolves to be dealt with.  Their very existence endangers the stability of the Living Grove and all of our work here.", completion = "Good.  I'll see if I can fashion something useful from these tails.\n\nNo doubt that the Horde will find a way to replenish the numbers of their wolf pack, but for now we can breathe a little easier.\n\n<name>, if you are willing there's something else that I would ask of you in defense of Sylvanaar and the Living Grove." }
WordHunterWoW_QuestEN[10457] = { title = "Protecting Our Own", description = "Though you've done a great deal of good work in defense of our new home here, I still feel that the Living Grove needs more protection.\n\nPlease, take this small tree bough that I have imbued with the force of nature.  When used upon the seedlings that I have planted out in the grove, it will call down a storm to accelerate the growth of a treant defender.\n\nThese treants are critical to the defense of the grove, especially if you choose not to make Sylvanaar your home for long.", objectives = "Use Rina's Bough on 5 of the Grove Seedlings to summon forth defenses for the Living Grove.", progress = "How fares the bolstering of the Living Grove's defenses?\n\nWith the intentions of the arakkoa at Veil Lashh unknown, and the Horde just on the other side of the ravine, I fear that if we do not move quickly we will find ourselves in a poor situation to protect our new home and our work in the grove.", completion = "Now that you have strengthened the grove's defenses, I feel much safer.\n\nYou've earned our thanks and appreciation, <name>.\n\nOf course, it just occurred to me that there's something else that we need to take care of!" }
WordHunterWoW_QuestEN[10458] = { title = "Enraged Spirits of Fire and Earth", description = "We must try and make amends. We must commune with the elements of this region and see if anything can be done!\n\nI grant you the totem of spirits, {race}. If you slay an enraged elemental spirit in close proximity of the totem, it will consume the elemental's soul. You must use the totem to consume many souls before you may return to me.\n\nDo this for the spirits of fire and earth first. Return to me when the totem is full.", objectives = "Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 8 Earthen Souls and 8 Fiery Souls.", progress = "I fear that this land may be without hope.", completion = "When all of the elemental souls of this region have been placed inside the totem, we will commune with them and find out if anything can be done for Shadowmoon Valley." }
WordHunterWoW_QuestEN[10459] = { title = "Revered Among the Cenarion Expedition", description = "We've taken notice of your accomplishments, {name}.  What you've done for us goes beyond what we expect from our allies.\n\nI've a special request to ask of you, but I must test your dedication first.", objectives = "Ysiel Windsinger at the Cenarion Refuge wants you to become revered with the Cenarion Expedition." }
WordHunterWoW_QuestEN[10460] = { title = "Defender's Pledge", description = "", objectives = "Are you sure this is the path you seek to take, <name>?  This is not a decision you ought to take lightly.\n\nThis ring is imbued with a droplet from the Well of Eternity.  It will grow in power as you prove yourself to the Scale of the Sands." }
