WordHunterWoW_QuestEN[10464] = { title = "Sage's Vow", description = "You've made your pledge, {class}.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.\n\nFail and the timeline as we know it will be unravelled!", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands.", progress = "You continue to serve us well, <name>.", completion = "You've proved your worth, <race>.  Up to a certain point, at least.\n\nThe favor of Nozdormu's prime mate is not obtained easily." }
WordHunterWoW_QuestEN[10465] = { title = "Restorer's Vow", description = "You've made your pledge, {class}.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.  Fail and the timeline as we know it will be unravelled!", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands.", progress = "You continue to serve us well, <name>.", completion = "You've proved your worth, <race>.  Up to a certain point, at least.\n\nThe favor of Nozdormu's prime mate is not obtained easily." }
