WordHunterWoW_QuestEN[10468] = { title = "Sage's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!" }
WordHunterWoW_QuestEN[10469] = { title = "Restorer's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!" }
WordHunterWoW_QuestEN[10470] = { title = "Champion's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!" }
WordHunterWoW_QuestEN[10471] = { title = "Defender's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!" }
WordHunterWoW_QuestEN[10472] = { title = "Sage's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", progress = "May time always be on your side, <name>.", completion = "You are one with time, <name>.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!" }
WordHunterWoW_QuestEN[10473] = { title = "Restorer's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", progress = "May time always be on your side, <name>.", completion = "You are one with time, <name>.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!" }
