WordHunterWoW_QuestEN[10729] = { title = "Path of the Violet Mage", description = "", objectives = "Are you certain of your choice, <name>?  This is not a decision you ought to take lightly.\n\nThe Violet Signet will grow in power as you continue to prove yourself to the Violet Eye." }
