WordHunterWoW_QuestEN[10733] = { title = "Down the Violet Path", description = "You've chosen your path, <class>.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", objectives = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, <name>. Behold as I unleash the power contained in your signet!" }
WordHunterWoW_QuestEN[10734] = { title = "Down the Violet Path", description = "You've chosen your path, <class>.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", objectives = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, <name>. Behold as I unleash the power contained in your signet!" }
