WordHunterWoW_QuestEN[10737] = { title = "The Master's Touch", description = "I've put together the very key I used as an apprentice.  It looks completely functional as far as keys go.  In regards to opening Karazhan, however, this might as well be a piece of scrap metal.\n\nWithout Medivh's consent, the key is worthless.  Yes, of course I know Medivh is dead.  This merely makes things difficult, not impossible\n\nThere is a place in Azeroth called the Caverns of Time, guarded by the bronze dragonflight.  Find a way inside, travel back in time and get Medivh to enable the key.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Go into the Caverns of Time and convince Medivh to enable your Restored Apprentice's Key." }
WordHunterWoW_QuestEN[10738] = { title = "Distinguished Service", description = "You have not disappointed us, <name>.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", objectives = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, <name>.  Your signet may look the same, but its powers grow as you continue to prove your loyalty." }
WordHunterWoW_QuestEN[10739] = { title = "Distinguished Service", description = "You have not disappointed us, <name>.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", objectives = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, <name>.  Your signet may look the same, but its powers grow as you continue to prove your loyalty." }
