WordHunterWoW_QuestEN[10741] = { title = "Distinguished Service", description = "You have not disappointed us, <name>.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", objectives = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, <name>.  Your signet may look the same, but its powers grow as you continue to prove your loyalty." }
WordHunterWoW_QuestEN[10742] = { title = "Showdown", description = "Now it comes to this. We will bring Goc forth from his lair, and we will destroy him. With Goc dead, the Bladespire ogres will threaten the Mok'Nathal no longer. Go to Goc's altar outside Gruul's Lair, then blow my horn. I will come, and we will face the son of Gruul together.", objectives = "Use Rexxar's Battle Horn at the Altar of Goc, then kill Goc.", progress = "Only through the deaths of Goc and Gorgrom the Dragon-Eater will we free the Mok'Nathal.", completion = "The battle was hard and you fought well, <name>. I am honored to have stood by your side in the battle against Goc. I am thankful beyond words.\n\nThe Mok'Nathal should know of these great defeats, but I am not ready to face them yet. I know my father's mind, and I know my heart. There is still much I can learn and do to become stronger, to show to him that I am his true son." }
WordHunterWoW_QuestEN[10743] = { title = "txt>Hero of the Mok'Nathal", description = "", objectives = "" }
WordHunterWoW_QuestEN[10744] = { title = "News of Victory", description = "You must bring word of our success to Kurdran Wildhammer immediately! His men, under Wing Commander Nuainn, have fought nonstop to keep Wildhammer Stronghold safe and your return will surely bolster their spirits. With the threat from the Legion out of the way, Kurdran can finally turn his attention to dealing with the forces of Illidan. Our place here is far from secure, but we've won a major victory this day.", objectives = "Return to Wildhammer Stronghold and speak with Kurdran Wildhammer.", completion = "<Kurdran listens to your report.>\n\nThat is good news, indeed! Mere days ago, I wouldn't have dreamt that we could break the Legion's siege on the stronghold.\n\nNot only have you halted their offensive, but you've broken the back of their war machine as well! You have the gratitude of the Wildhammer clan for your valor, <name>." }
WordHunterWoW_QuestEN[10745] = { title = "News of Victory", description = "You must bring word of our success to Overlord Or'barokh immediately! Now that we've crushed the Legion and obliterated their presence in Shadowmoon Valley, the overlord can turn his attention to our other foes.\n\nAlthough the Kor'kron guard will never admit it, they'll be glad we're no longer fighting on two fronts.", objectives = "Return to Shadowmoon Village and speak with Overlord Or'barokh.", completion = "<The overlord listens to your report.>\n\nExcellent news! Holding the line against the Legion's infernals was taking too many resources. Not that I expected my men to break, but they were greatly strained.\n\nYou have proven your worth to the Horde this day. The Kor'kron guard would be honored to fight by your side anytime." }
WordHunterWoW_QuestEN[10746] = { title = "DEPRECATED Karazhan: LAB - E - Exalted Ring - Caster", description = "Your accomplishments have gone beyond my greatest expectations, <name>.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.You will receive:", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands." }
WordHunterWoW_QuestEN[10747] = { title = "Whelps of the Wyrmcult", description = "I need to examine the whelps that they are raising at the Blackwing Coven.\n\nThere should be an abundance of them flying around inside their cavernous base, as well as a number of eggs, which if you get close to them will likely hatch.\n\nPlease, {name}, take the net and capture a handful of them alive for me.\n\nFind them by heading west across the Wyrmskull Bridge and heading through the Wyrmskull Tunnel.  Follow the path to its end past Grishnath and the Raven's Wood.", objectives = "Use the Blackwhelp Net to capture 10 Wyrmcult Blackwhelps.", progress = "Did you run into much trouble snatching the whelps?  I hope you didn't get singed!", completion = "Oh my goodness, these are more than I'd hoped for!  You are certainly to be lauded for your heroics!\n\nThis looks like a fine brood of blackwhelps to make a start with.  Examining them, that is.\n\nPlease, accept this as payment.  I insist!" }
WordHunterWoW_QuestEN[10748] = { title = "Maxnar Must Die!", description = "They've left us no choice, {name}.  It's time to put an end to the threat from the Blackwing Coven by taking out their leader, Maxnar the Ashmaw.\n\nI don't know if you caught a glimpse of him while you were in there, but he's one of the dragonkin, half-man, half-dragon.  And he's tough, so don't underestimate him!\n\nFinish it quickly and with any luck you'll secure the safety of Evergrove and the Ruuan Weald.", objectives = "Slay Maxnar the Ashmaw.", completion = "Now we can breathe more easily knowing that the leader of our enemy has been dealt with.  Not only that, but you've saved the entire mountain range from their depredations.\n\nWhatever their ultimate goals, you've foiled them!\n\nYou have our gratitude, <name>.  Please accept this token of our esteem, as well as our unending hospitality." }
WordHunterWoW_QuestEN[10749] = { title = "Baron Sablemane's Poison", description = "Here, take this to your master. I'm sure that whatever the reason, Rexxar will put it to good use.\n\nOh, and do be certain to remind him that he owes me.\n\nHe knows what I want, and I'm certain that however he intends to obtain it for me, I'll be seeing you again sooner than you think.\n\nNow, do be a good little boy and run this up to Rexxar.", objectives = "Deliver Baron Sablemane's Poison to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", progress = "<class>, you are back so soon? Do you have the poison?", completion = "This is unsavory business, this use of poisons. But it will do what we want." }
WordHunterWoW_QuestEN[10750] = { title = "The Path of Conquest", description = "Word has come from my wind riders, {name}. The Eclipsion blood elves are planning something big. They have begun forming their armies at the Path of Conquest, far to the southeast - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you have done so, use this flare gun to signal a wind rider. One will swoop down from the sky to meet you. Inform them of what you have discovered and they will give you your next set of orders.", objectives = "Travel to the Path of Conquest in Shadowmoon Valley.", progress = "What have you to report, soldier?", completion = "Indeed, these troublesome whelps are up to something insidious. We must investigate further..." }
WordHunterWoW_QuestEN[10751] = { title = "Breaching the Path", description = "We're going to need more time, {race}. I'm going to fly further ahead with some of the other wind riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a wind rider with the Kor'kron flare gun once you have thinned their numbers.", objectives = "Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 10 Eclipsion Spellbinders.", completion = "You won't believe this, grunt." }
WordHunterWoW_QuestEN[10752] = { title = "Onward to Ashenvale", description = "Recently Raene Wolfrunner came through Auberdine from Darnassus and was heading to Ashenvale; she said something about the Furbolgs. I wasn't given an opportunity to ask more about her situation but perhaps you can seek her out and lend her your aid <class>. Take the southern road out of Auberdine. Once you reach Ashenvale border continue your path down the road. There you will find Astranaar and Raene Wolfrunner.", objectives = "Speak with Raene Wolfrunner in Astranaar.", completion = "So Thundris Windweaver still thinks I need looking after? I'll need to remind him who saved whom; he seems to forget it was I that pulled him from harm's way.\n\nWell now that you're here, <race>, perhaps I can find something for you to do." }
WordHunterWoW_QuestEN[10753] = { title = "Culling the Wild", description = "The number of atrocities committed by the Burning Legion is countless. Even as we speak, they send their legion forces against the creatures of this land. Helpless to defend against their power, they fall one by one. {name}, help me stop these crimes of nature destroy all which they corrupt. \n\nOver the hill, east of here, you will see the corruption spreading across Bladed Gulch. Kill the ones causing the crime, the Fel Corrupters, and as many Felsworn as you can.", objectives = "Slay 4 Felsworn Scalewing, 4 Felsworn Daggermaw, and 2 Fel Corrupters.", completion = "I do not pride myself knowing we destroyed what Elune has created, but the corruption needed to be stopped. You have done well <class>." }
WordHunterWoW_QuestEN[10754] = { title = "Entry Into the Citadel", description = "This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.\n\nMaybe this could prove to interest to Danath, the force commander at Honor Hold.", objectives = "Bring the Primed Key Mold to Force Commander Danath at Honor Hold in Hellfire Peninsula.", progress = "You've something to show me, <name>?", completion = "Could this be?  Let me take a closer look at that mold." }
WordHunterWoW_QuestEN[10755] = { title = "Entry Into the Citadel", description = "This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.\n\nMaybe this could prove to interest to Nazgrel, the leader of the Horde's forces in Thrallmar.", objectives = "Bring the Primed Key Mold to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "You've something to show me, <name>?", completion = "A key mold?  Could this be what grants us access to the Shattered Halls?" }
WordHunterWoW_QuestEN[10756] = { title = "Grand Master Rohok", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it as the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Rohok, our resident blacksmith.  If anyone can forge this key it is he.", objectives = "Bring the Primed Key Mold to Rohok at Thrallmar in Hellfire Peninsula.", progress = "What is this?", completion = "Nazgrel wants me to work on a key?  Does he forget we're in a battlefield?  There are blades and spears to forge!" }
WordHunterWoW_QuestEN[10757] = { title = "Rohok's Request", description = "Fel orc blacksmiths may not be the most skilled in the world, but there is some craftsmanship to their trade.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", objectives = "Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Rohok at Thrallmar in Hellfire Peninsula.", progress = "Have you obtained the materials I requested?", completion = "Excellent.  Let's give it a shot." }
WordHunterWoW_QuestEN[10758] = { title = "Hotter than Hell", description = "It's no good, {name}!  No matter how many coals I put to the fire, it's just not enough heat.\n\nThere's only one thing I can think of that is hot enough to temper this key and it is the insides of the Legion's fel reavers.\n\nI've only ever seen one downed once.  I remember seeing its insides fuming, shooting fire and steam as it fell.  Take this mold and plunge it into a fallen fel reaver.  I recommend you get yourself some friends if you plan to take one down.", objectives = "Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains. Bring the Charred Key Mold to Rohok in Thrallmar.", progress = "Did you do what I asked of you, <class>?", completion = "You've succeeded!  Only thing left for you to do is try it out." }
WordHunterWoW_QuestEN[10759] = { title = "Find the Deserter", description = "I get the feeling that all the pieces are here, but I just can't put them together in a way that makes sense.\n\nI think our best lead is to attempt to locate this deserter. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him along the road in Magma Fields to the northwest. It seems a likely place for him to take refuge.", objectives = "Locate Parshah in the Magma Fields and speak to him.", completion = "<The arakkoa cackles.>\n\nYes, I am the deserter mentioned in the commander's journal. I have been waiting for the day when others might recognize the threat posed by those I once called brothers." }
WordHunterWoW_QuestEN[10760] = { title = "The Sketh'lon Wreckage", description = "The Sketh'lon Wreckage, just to the east, is an eerie place. The peons are convinced that it's cursed.\n\nThere are few trees here, so the peons have no choice but to venture into the arakkoa ruins to chop wood. The arakkoa spirits prey on the work groups, draining their life and using it to fuel their foul magics.\n\nWe must find out what is driving the dark conclave and stop them before their influence expands. Search the Sketh'lon Wreckage for evidence of their plans.", objectives = "Recover the Skethlon Commander's Journal Page 1, Skethlon Commander's Journal Page 2, and Skethlon Commander's Journal Page 3 from the Dark Conclave arakkoa at the Sketh'lon Wreckage to Sergeant Kargrul at Shadowmoon Village.", progress = "What have you discovered?", completion = "<The sergeant examines the journal pages.>\n\nI don't see much of use here, but there are a couple of entries that could prove useful. It looks as though these arakkoa were preparing some kind of elaborate magical ritual up until the time of their deaths, but why? There's also a curious note here about a 'deserter.'" }
WordHunterWoW_QuestEN[10761] = { title = "Find the Deserter", description = "There's nothing here that would explain why the spirits of these arakkoa have remained in this world or how they came into thirst for the blood of orcs.\n\nI think our best lead is to try to find the deserter mentioned in the journal. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him on the road through the Magma Fields to the southeast.", objectives = "Locate Parshah in the Magma Fields and speak to him.", completion = "<The arakkoa cackles.>\n\nYes, I am the deserter mentioned in the commander's journal. I have been waiting for the day when others might recognize the threat posed by those I once called brothers." }
WordHunterWoW_QuestEN[10762] = { title = "Grand Master Dumphry", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it at the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Dumphry.  He is a master of his craft.  If he can't craft this key for you, no one can.", objectives = "Bring the Primed Key Mold to Dumphry in Honor Hold.", progress = "What is this?", completion = "A key?  Danath should have us working on siege engines!" }
WordHunterWoW_QuestEN[10763] = { title = "Dumphry's Request", description = "Fel orcs might be complete barbarians but their smithing is not as primitive as you might think.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", objectives = "Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Dumphry at Honor Hold in Hellfire Peninsula.", progress = "Have you obtained the materials I requested?", completion = "Let's try it then.  Let's see what fel orc crafting is all about." }
WordHunterWoW_QuestEN[10764] = { title = "Hotter than Hell", description = "It's not working, lad.  I cannot give it enough heat... the materials will not be properly tempered.\n\nYou know, the fel reavers used by the Burning Legion are powered by a scalding core of fel fire - it burns much hotter than normal fire.\n\nIf you could find enough people to take one down, you could heat the mold in the insides of the fallen reaver.  Beware, {class}, those fel reavers pack quite a punch.", objectives = "Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains. Bring the Charred Key Mold to Dumphry in Honor Hold.", progress = "Did you do what I asked of you, <class>?", completion = "You've done it, laddie!  Only thing left to do is for you to take it to Hellfire Citadel and kill yourself some orcs!" }
WordHunterWoW_QuestEN[10765] = { title = "When Worlds Collide...", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. You've probably already noticed the smaller giants on the path as well. Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", objectives = "Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command.", progress = "What have you to report, soldier?", completion = "So they are attempting to gain the favor of the giants, eh? I have a plan that promises to sever this unholy union." }
WordHunterWoW_QuestEN[10766] = { title = "Invasion Point: Cataclysm", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Wildhammer Stronghold won't be safe until the Legion's presence is erased from Shadowmoon Valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Plexi will meet you at your destination.", objectives = "Report to Plexi at Invasion Point: Cataclysm.", completion = "Pleased to meet you, <name>. Name's Plexi.\n\nI won't bore you with formalities. We both know why we're here. Now, let's get to work." }
WordHunterWoW_QuestEN[10767] = { title = "Invasion Point: Cataclysm", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Shadowmoon Village won't be safe until the Legion's presence is erased from the valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Nakansi will meet you at your destination.", objectives = "Report to Nakansi at Invasion Point: Cataclysm.", completion = "You must be the <race> Blood Guard Gulmok told me to expect. I have a plan in mind, but I'll need your help to complete the preparations." }
WordHunterWoW_QuestEN[10768] = { title = "Tabards of the Illidari", description = "The wind riders must return to Shadowmoon Village to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a wind rider using the Kor'kron flare gun. Prepare yourself for a bit of espionage, {race}!", objectives = "Collect 10 Illidari Tabards.", progress = "What have you to report, soldier?", completion = "Ah-ha! These will do quite nicely." }
WordHunterWoW_QuestEN[10769] = { title = "Dissension Amongst the Ranks...", description = "Researcher Tiorus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", objectives = "Slay 5 Crazed Colossus while in disguise as an Illidari blood elf and return to Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley. He will also want his Kor'kron Flare Gun returned.", progress = "You have returned!", completion = "Well, well, well... If it isn't the grunt I sent out into the field. You're back and in one piece.\n\n<Or'barokh nods.>\n\nI knew you wouldn't let me down, soldier. You've stopped a major Illidari advance and, in doing so, earned yourself a little reward." }
WordHunterWoW_QuestEN[10770] = { title = "Little Embers", description = "Northeast of here, on the plateau above us lies the burnt ashes of my ancient home. A great wood flourished there before the Burning Legion sent their imps to burn us away. So many died that even centuries later my tired old heart hungers for revenge. There are too many of them for us to ever reclaim the land, but you could make them afraid.\n\nSurely you will help me?", objectives = "Mosswood the Ancient wants you to kill 8 Scorch Imps and then return to him in Ruuan Weald.", completion = "There are so many that we could never kill them all, but you have given me hope. Perhaps I shall try harder for the next few centuries to revive my beloved wood." }
WordHunterWoW_QuestEN[10771] = { title = "From the Ashes", description = "If you follow the road east and up the side of the mountain, then turn north, you will come to my long lost home.\n\nOnce there was a wood there. Its name is forgotten. Long ago the Burning Legion summoned scorched imps and other creatures of flame. My home was destroyed and my people fled. Now only I remain. \n\nI have saved some ironroot seeds that could be planted in fertile volcanic soil. Their magic is strong. Do this for me and I will share with you the treasures of a forgotten age.", objectives = "Mosswood the Ancient wants you to journey to Skald and plant Ironroot Seeds in three different mounds of Fertile Volcanic Soil and then return to him in Ruuan Weald.", progress = "Is it done?  Did you return some life to my ancient home?", completion = "You destroyed many of those foul little creatures.  I can rest easier in that knowledge." }
WordHunterWoW_QuestEN[10772] = { title = "The Path of Conquest", description = "My gryphon riders have come back with a bit of news! The Eclipsion blood elves are planning something big. They've begun forming their armies at the Path of Conquest, located east of here - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you've done so, use this flare gun to signal a gryphon rider. One will swoop down from the sky to meet you. Tell 'em what you've discovered and they'll give you the next set of orders.", objectives = "Travel to the Path of Conquest in Shadowmoon Valley.", progress = "What have you to report, soldier?", completion = "Indeed, these troublesome whelps are up to something insidious. We must investigate further..." }
WordHunterWoW_QuestEN[10773] = { title = "Breaching the Path", description = "We're going to need more time, {race}. I'm going to fly further ahead with some of the other gryphon riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a gryphon rider with the Wildhammer flare gun once you have thinned their numbers.", objectives = "Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 5 Sons of Corok.", completion = "You won't believe this, soldier!" }
WordHunterWoW_QuestEN[10774] = { title = "Blood Elf + Giant = ???", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. What are giants even doing here? Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", objectives = "Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command.", progress = "What have you to report, soldier?", completion = "So they are attempting to gain the favor of the giants, eh? I have a plan that could serve to sever this unholy union." }
WordHunterWoW_QuestEN[10775] = { title = "Tabards of the Illidari", description = "The gryphon riders must return to Wildhammer Stronghold to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a gryphon rider using the Wildhammer flare gun. Prepare yourself for a bit of espionage, {race}!", objectives = "Collect 10 Illidari Tabards.", progress = "What have you to report, soldier?", completion = "Ah-ha! These will do quite nicely." }
WordHunterWoW_QuestEN[10776] = { title = "Dissension Amongst the Ranks...", description = "Gnomus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", objectives = "Slay 5 Crazed Colossus while in disguise as an agent of Illidan and return to Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley. He will also want his Wildhammer Flare Gun returned.", progress = "You have returned!", completion = "Well, well, well... If it isn't the soldier I sent out into the field. You're back and in one piece.\n\n<Yoregar nods.>\n\nI knew you wouldn't let me down, soldier. You've stopped a major Illidari advance and, in doing so, earned yourself a little reward." }
WordHunterWoW_QuestEN[10777] = { title = "Asghar's Totem", description = "What you read in the commander's journal is true. While the orcish Horde massed under Gul'dan, my people sought to defend ourselves from the threat by striking against him. Gul'dan learned of their intentions and cast a mighty spell that destroyed our camps and twisted the spirits of my brothers.\n\nThey must be stopped before they unleash a greater evil. In the Sketh'lon Wreckage to the north, seek out Asghar and bring me the totem he carries. With it, we can begin to thwart the dark conclave's plans.", objectives = "Bring the Sketh'lon War Totem to Parshah in the Magma Fields.", progress = "Have you recovered the totem from Asghar?", completion = "<Parshah examines the totem.>\n\nGood. This old totem hasn't lost its power over the years, but it alone is not enough to stop the dark conclave." }
WordHunterWoW_QuestEN[10778] = { title = "The Rod of Lianthe", description = "The totem alone is not strong enough to counteract the sinister magics of the dark conclave.\n\nWe can combine it with other objects of power, forming a staff to focus the energies. We cannot rescue my brethren from the depths of their depravity, but we can stop them.\n\nOne of the items I need for the staff is the Rod of Lianthe, held by the blood elves at Eclipse Point to the southeast. It is kept in a pavilion on the top tier of the ruins and will be heavily guarded. Use caution, {name}.", objectives = "Obtain Lianthe's Key from any of the blood elves at Eclipse Point and use it to open Lianthe's Strongbox and claim the Rod of Lianthe. Return the rod to Parshah in the Magma Fields.", progress = "Did you manage to get the rod?", completion = "Well done. Such a treasure deserves better than to be shut away in a dark chest. We shall see it used for a worthy purpose." }
WordHunterWoW_QuestEN[10779] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Huntress Kella Nightbow at LOCATION. She can put you on the path to earning a pet of your own.You will receive:", objectives = "Speak with Huntress Kella Nightbow at LOCATION.Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Huntress Kella Nightbow at LOCATION. She can put you on the path to earning a pet of your own.You will receive:" }
WordHunterWoW_QuestEN[10780] = { title = "Sketh'lon Feathers", description = "There is one last element missing from the staff. We must direct the staff's power toward the Dark Conclave spirits.\n\nWe can do that by gathering feathers scattered on the ground at the Sketh'lon Base Camp and using them in the staff. The base camp is to the south, east of Wildhammer Stronghold.\n\nGul'dan's magic utterly destroyed my brethren, leaving only their spirits, but it did not stop there. The magic fed on the spell the arakkoa were preparing, forging a sinister force that engulfed the spirits.", objectives = "Gather 8 Sketh'lon Feathers and bring them to Parshah in the Magma Fields.", progress = "Have you gathered the feathers for the staff?", completion = "<Parshah accepts the ash-dusted feathers, shaking his head.>\n\nIt would've been better if they had died that day, but nothing is ever that simple. That Gul'dan's magic would turn them into the kind of threat they tried to stop is a particularly cruel twist of fate." }
WordHunterWoW_QuestEN[10781] = { title = "Battle of the Crimson Watch", description = "They are probably searching for you on the Path of Conquest as we speak. You must make your escape, {race}!\n\nLeave me, I'm done for... They... I think I hear them coming. It's now or never! Get out! If you choose to stay, you will have to fight!\n\nIf you fight and somehow manage to survive, take what you have learned here and deliver that knowledge to A'dal in Shattrath City.", objectives = "Battle the forces of Illidan at Crimson Watch and survive!\n\nReturn to A'dal at Shattrath City should you emerge the victor.", completion = "This Crimson Sigil will be investigated. They pose a threat to all life on Draenor. I foresee a day when their dark master has to answer for his crimes. Perhaps it will be you who brings him to justice, hero." }
WordHunterWoW_QuestEN[10782] = { title = "Imbuing the Headpiece", description = "The staff is nearly finished!\n\nAll that remains is to imbue the headpiece with power flowing from the echoes of Gul'dan in this accursed place. To the east, near the Fel Pits and south of the Deathforge, is the Altar of Damnation.\n\nThere, fragments of Gul'dan's past are trapped. When you carry the unfinished headpiece of the staff into the area around the altar, don't be surprised if some of the entities react to it. You will be carrying a dangerous object with strong connections to the cataclysm.", objectives = "Travel to the Altar of Damnation, and use the Unfinished Headpiece while standing near Gul'dan. When the headpiece is energized, return to Parshah in the Magma Fields.", progress = "Have you returned with the imbued headpiece?", completion = "<Parshah accepts the headpiece, handing it gingerly.>\n\nThis holds the power that we'll need to disrupt the dark conclave's efforts in the Sketh'lon Base Camp." }
WordHunterWoW_QuestEN[10783] = { title = "Baron Sablemane", description = "Here is my plan. We will poison the ogres and then destroy their gronn master.\n\nDuring my travels in these mountains, I met a man named Baron Sablemane. He is a master of the alchemical arts, and may be convinced to assist us.\n\nYou will find him at the Circle of Blood, down in the canyon to the north of here. Whatever price he requires, I will leave it to your discretion to accept.", objectives = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", completion = "Hello, <race>. I am Baron Sablemane. A friend of Rexxar's is a friend of mine." }
WordHunterWoW_QuestEN[10784] = { title = "Crush the Bloodmaul Camp", description = "<Tor'chunk leans in close to whisper.>\n\n{name}, you've done us more than proud in the fight against the ogres so far.  And while I have every confidence in what Rexxar has planned, I would still ask that you crush the ogres at Bloodmaul Camp before returning.\n\nThat way we'll be doubly certain of the outcome.\n\nTo get there, head north down the ramp out of Thunderlord.  Then, at the base of the ramp, head west across Dragons' End and north through the Churning Gulch and Daggermaw Canyon.", objectives = "Slay 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks.", completion = "<Tor'chunk nods his head in obvious approval of your killing prowess.>\n\nYou continue to impress me, <name>.  Every time one of those stinking ogres is felled, we come one step closer to ridding ourselves of an unworthy foe." }
WordHunterWoW_QuestEN[10785] = { title = "It's a Trap!", description = "There's is no cause of fury greater in this world than that of Gruul and his sons. They slaughtered my people - my children - and now I will have revenge.\n\nI have fashioned a trap from dragon fire, and if you're clever enough, you can use it to kill even a gronn.\n\nJust hurry, take the trap to Rexxar. My thirst for revenge must be quenched.", objectives = "Deliver the Dragonfire Trap to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", progress = "Did you recover whatever was in that gronn's sack for Sablemane? What has he given us?", completion = "Hmm, a trap fashioned from the essence of dragon fire? I wonder how Sablemane comes by such rarified substances?\n\nIt does not matter. What does matter is that we are going to use it to slay a son of Gruul." }
WordHunterWoW_QuestEN[10786] = { title = "Slaughter at Boulder'mok", description = "I know that Rexxar has plans for you to head to Boulder'mok.  I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies far to the northwest.  Travel north to Ruuan Weald, and from there head west through the tunnel and past the Raven's Wood.\n\n{name}, I want you to kill the Bladespire ogres of Boulder'mok.  Wipe them out!", objectives = "Slay 5 Boulder'mok Brutes and 3 Boulder'mok Shaman, and then return to Tor'chunk Twoclaws at Thunderlord Stronghold in the Blade's Edge Mountains.", completion = "<Tor'chunk grins at the story that you tell him about your adventures at Boulder'mok.>\n\nAh, I wish that I could have been there with you.  Let me tell you something, <name>: never accept any duty that keeps you from the glory of battle!\n\nHah!  After all of the ogre killing that you've done, are there any still left in these mountains for me?!" }
WordHunterWoW_QuestEN[10788] = { title = "Return to Talionia", description = "One of your masters, Talionia, in Silvermoon City has sent a summons for you, <name>.  I'm certain it is time you learned to summon and control a more powerful demon, so I suggest you see her at once.  I understand Talionia is found in The Sanctum, a cozy little den of evil found along Murder Row.Upon completion of this quest you will gain:", objectives = "Speak with Talionia in Silvermoon City.One of your masters, Talionia, in Silvermoon City has sent a summons for you, <name>. I'm certain it is time you learned to summon and control a more powerful demon, so I suggest you see her at once. I understand Talionia is found in The Sanctum, a cozy little den of evil found along Murder Row.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10789] = { title = "Return to Carendin Halgar", description = "Ah, so there you are, <name>.\n\nCarendin Halgar has sent out word for you to come see him in the Magic Quarter of Undercity.  He is not known for his patience, so I would not wait long.Upon completion of this quest you will gain:", objectives = "Speak with Carendin Halgar in Undercity.Ah, so there you are, <name>.\n\nCarendin Halgar has sent out word for you to come see him in the Magic Quarter of Undercity. He is not known for his patience, so I would not wait long.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10790] = { title = "Return to Mordak Darkfist", description = "You are a long way from home, <race>.  Perhaps it is time you returned to learn from your master, Mordak Darkfist.  His knowledge is known to all of our craft, even those of us here.\n\nMordak dwells in the Cleft of Shadow in Orgrimmar.Upon completion of this quest you will gain:", objectives = "Speak with Mordak Darkfist in Orgrimmar.You are a long way from home, <race>. Perhaps it is time you returned to learn from your master, Mordak Darkfist. His knowledge is known to all of our craft, even those of us here.\n\nMordak dwells in the Cleft of Shadow in Orgrimmar.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10791] = { title = "Welcoming the Wolf Spirit", description = "I've nearly completed the vestments that I'll wear during the ceremony. As I add the finishing touches, I'd like you to set this incense by the candles near the runestone to my left.\n\nI believe it will help us to attract the wolf spirit's attention, since it was made in the days of the orcish clans. I can almost imagine my ancestors using it in a ceremony paying tribute to the wolf spirit after a successful hunt.\n\nOnce you've placed the incense, I'll begin the ceremony.", objectives = "Use the Ceremonial Incense near the candles in Malukaz's hut and observe the ceremony. When the ceremony is complete, speak with Malukaz again.", progress = "Reestablishing ties with the wolf spirit is just the beginning of my journey, not the end.", completion = "This is incredible! I set out on this journey unsure of whether the wolf spirit would answer our summons and now it feels as though he's always been here. Perhaps he was, <name>.\n\nPerhaps he was waiting for the orcs to realize what their choices had wrought." }
WordHunterWoW_QuestEN[10792] = { title = "Zeth'Gor Must Burn!", description = "The Bleeding Hollow clan have betrayed their noble heritage!  We, the orcs who fought and died to save ourselves from the fel taint of Mannoroth, look upon our vile cousins and see only weakness and ignobility... and for that, they must burn!\n\nEnter Zeth'Gor, their bastion to the east, and burn their buildings.  Kill peons for their torches, ignite them at their forge, and hurl the burning torches at their hovels, their stable and their barracks.  Burn them all, and then return to me!\n\nFor the Horde!", objectives = "Kill Bleeding Hollow Peons for their torches, ignite them at Zeth'Gor's forge then throw the burning torches at Zeth'Gor Buildings.", completion = "Hah!  I could see the smoke and flames of Zeth'Gor from here!  May the Bleeding Hollow fiends burn to ash and drift far from the sight of any true orc!\n\nThank you, <name>.  You helped burn away an afront to every orc's spirit." }
WordHunterWoW_QuestEN[10793] = { title = "The Journal of Val'zareq: Portends of War", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.", objectives = "Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch.\n\nLook for him inside a crystalline prison.", progress = "<General Auralion is floating in the middle of the crystal.>\n\nWha... What are you doing here?", completion = "You slew their conqueror? Then we haven't much time...\n\nThe Crimson Sigil is a group comprised of Illidan's elite minions. They are at the top of the chain of command for all Illidari forces outside of the Black Temple. These soldiers communicate directly with the Betrayer here, carrying out his orders without question.\n\nThey are the fiends that will undoubtedly lead an assault on this world, trampling under foot all that would stand in their way." }
WordHunterWoW_QuestEN[10794] = { title = "Rogues of the Shattered Hand", description = "<name>, there are secrets in the world that we do not yet possess.  The Shattered Hand in Orgrimmar can lead you to one of these secrets: the method for brewing deadly poisons.  Do as they ask and you will gain their trust.\n\nTo reach Orgrimmar, take the portal in Silvermoon City to Undercity.  Then, travel outside the city and find the nearby tower where the goblin Zepplins pick up their passengers.  From there, fly to the city of Orgrimmar where you can find Shenthul in the Cleft of Shadow.Upon completion of this quest you will gain:", objectives = "Speak with Shenthul in Orgrimmar." }
WordHunterWoW_QuestEN[10795] = { title = "A Date with Dorgok", description = "Good, I've seen you around and I've been meaning to speak to you about a matter of some importance.\n\nThere are reports coming in that for some reason the Bloodmaul ogres are planning an offensive against Sylvanaar and Ruuan Weald.  We don't know who or what is pushing them to do this, but I intend to nip their plan in the bud!\n\nBloodmaul Camp is where the attacks are to be staged from.  Head northwest down the ramp out of the Ruuan Weald and you will find it.  I want you to kill their leader, Dorgok!", objectives = "Slay Dorgok at Bloodmaul Camp.", completion = "With Dorgok dead, the Bloodmaul ogres are without leadership, and should be in disarray until another leader arises from within their ranks.\n\nThank you, <class>, I think we can breathe a little easier now." }
WordHunterWoW_QuestEN[10796] = { title = "Crush the Bloodmaul Camp!", description = "I've heard that you've done us more than proud in the fight against the ogres thus far.  Now, I would ask that you face them again.  I want you to crush the ogres at Bloodmaul Camp!\n\nTo get down there, head northwest down the ramp out of the Ruuan Weald.  You'll find them at the base of the ramp.\n\nGood luck, {class}!", objectives = "Slay 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks.", completion = "<The lieutenant nods her head in obvious approval of your killing prowess.>\n\nI am impressed, <name>.  Your reputation seems to be well-deserved.\n\nEvery time one of the ogres is felled, we come one step closer to ridding ourselves of a danger that has no intention of leaving us in peace." }
WordHunterWoW_QuestEN[10797] = { title = "Favor of the Gronn", description = "A token in the form of a small statuette falls from Dorgok's dead clutch.  It bears a striking resemblance to one of the gronn.\n\nSurely, Commander Haephus Stonewall at Evergrove in the Ruuan Weald, up the ramp to the east, would be interested in this!", objectives = "Deliver Gorgrom's Favor to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains.", progress = "Hello, lad, what news do you bring?", completion = "Oh, now that's pretty.  Looks a lot like those gronn that are always bossing the Bladespire ogres around.\n\nOdd that you should find it in the hands of one of the Bloodmaul leaders." }
WordHunterWoW_QuestEN[10798] = { title = "Pay the Baron a Visit", description = "This is bad news.  Gorgrom the Dragon-Eater is behind the recent Bloodmaul plans against Sylvanaar!\n\nWhy he's manipulating them, and not just using the Bladespire, I don't know.  But if we're to deal with a gronn, we're going to need help.\n\nI know a man who is wise in the ways of all sorts of exotic magics.  Baron Sablemane is his name, and you can find him at the Circle of Blood, back down the ramp to the northwest, and then southwest through the canyon.\n\nAsk him to fashion us a trap for the gronn.", objectives = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", completion = "Ah, an envoy from the vaunted Alliance.  Tell me, lackey, why is it that you are here, begging me for this thing, instead of your illustrious commander?\n\nCould it be that he is afraid of me?  It says something about you that you are not, but I haven't quite decided yet what that is." }
WordHunterWoW_QuestEN[10799] = { title = "Into the Churning Gulch", description = "Very well, I'll create this trap, but first I want something in return.\n\nThere happens to be a nearby gronn that is in possession of an item that I want, but you can't face him, not yet anyway.\n\nSo, you and I are going to fashion a sleeping powder from the poison of the nearby crust bursters.\n\nYou'll find them in the Churning Gulch to the southwest.  Bring me a number of their glands, and be quick about it!", objectives = "Collect 7 Crust Burster Venom Glands.", progress = "You have all of the venom glands?  If not, begone and waste no more of my time until you do!", completion = "Very well.  A simple, if mundane, task has been completed.  Now, hand me the glands and I will perform the difficult part." }
WordHunterWoW_QuestEN[10800] = { title = "Goodnight, Gronn", description = "I've outdone myself again.  I've fashioned a sleeping powder for you to use on Grulloc, the gronn I spoke of who is guarding what I want.\n\nGrulloc keeps himself at the Cursed Hollow, an area at the eastern edge of Dragons' End on the other side of the Circle of Blood.\n\nIf I were you, I wouldn't tarry long once you have his sack.  The effects of the dust won't last long.", objectives = "Collect Grulloc's Sack.", progress = "You are before me again, <class>.  This must mean that you've procured the sack out from underneath Grulloc's nose.", completion = "<Baron Sablemane peers inside the gronn's sack and seems satisfied.>\n\nVery well, you have upheld your end of the bargain.  And now, I will gift your Commander Stonewall with the trap." }
WordHunterWoW_QuestEN[10801] = { title = "It's a Trap!", description = "There's nothing more that I hate in this world than the sons of Gruul and their father!  They slaughtered my people, and my children, and now I will have a taste of revenge!\n\nI have fashioned a trap from some dragon fire, and if you're clever enough, you might just be able to use it to kill a gronn.\n\nI'm sure that you have a particular gronn in mind; it matters not to me which one you kill.  Just hurry, take the trap to your Commander Stonewall.\n\nMy thirst for revenge must be quenched!", objectives = "Deliver the Dragonfire Trap to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains.", progress = "Did the baron fashion us a trap?  One powerful enough to kill a gronn?", completion = "Hmm, a trap fashioned from the essence of dragon flame?  I wonder how Sablemane comes by such rarified substances?\n\nIt does not matter.  What does matter is that we are going to use it to slay a son of Gruul!" }
WordHunterWoW_QuestEN[10802] = { title = "Gorgrom the Dragon-Eater", description = "We must show the ogres that we are not to be trifled with. We must send a message.\n\nTravel to Boulder'mok and kill the ogres there. Make sure you keep their heads.\n\nThen go to Gorgrom's altar and place the trap there for him. Gorgrom will appear, and you must lure him into the trap. When he is dead, mount your grisly totems near his corpse, so that the ogres may look at their fallen master and their fallen brothers, and know the price for seeking to destroy us.", objectives = "Collect 3 Grisly Totems from Boulder'mok ogres. Then, use Sablemane's Trap at Gorgrom's Altar to summon and kill Gorgrom the Dragon-Eater.\n\nWhen Gorgrom is dead, place the 3 Grisly Totems near his corpse.", progress = "Has the message been delivered?", completion = "Well done, <name>. Well done!\n\nI suspect we will hear little more from the ogres and their master." }
WordHunterWoW_QuestEN[10803] = { title = "Slaughter at Boulder'mok", description = "I know that we have plans for you to head to Boulder'mok. I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies to the west. Travel southwest, cross the bridge and head through the tunnel. On the west side of the Raven's Wood you will find them.\n\n{name}, I want you to wipe out the Bladespire ogres of Boulder'mok.", objectives = "Slaughter 5 Boulder'mok Brutes and 3 Boulder'mok Shaman.", completion = "<Lieutenant Fairweather grins at the story that you tell her about your adventures at Boulder'mok.>\n\nAh, I wish that I could have been there with you.  Let me tell you something, <name>: never accept any duty that keeps you from the glory of the battlefield!\n\nHah!  After all of the ogre killing that you've done, are there any still left in these mountains for me?!" }
WordHunterWoW_QuestEN[10804] = { title = "Kindness", description = "Something has them spooked, {race}.\n\n<Mordenai points to the nether drakes flying overhead.>\n\nThey won't even come down to feed. I have seen several fall to the earth, dead from exhaustion before their bodies hit the ground.\n\nWe must save them! The Rocknail flayers that are found near the crystals are their natural prey. Kill flayers and take their carcasses. Place a carcass in the field and stand extremely still. As long as you do not make any aggressive motions, they will not attack you.", objectives = "Mordenai at Netherwing Fields in Shadowmoon Valley wants you to feed 8 Mature Netherwing Drakes.", progress = "I cannot save them by myself, <name>!", completion = "You are a kind and compassionate <race>, friend." }
WordHunterWoW_QuestEN[10805] = { title = "Massacre at Gruul's Lair", description = "You've proven yourself resourceful, and now I think I'm going to put you to personal use in my own fight against Gruul and his sons.\n\nThe Bladespire clan are the favored of the gronn, and while you may have thinned out their numbers elsewhere, you haven't yet dealt with their strongest.\n\nGruul protects the exterior of his lair with only the toughest of ogres, and it is those that you must kill.  Head north through the Daggermaw Canyon and you will find Gruul's Lair at the end.", objectives = "Slay 10 Bladespire Enforcers, 5 Bladespire Battlemages, 5 Bladespire Ravagers and their leader, Fingrom.", completion = "Very well, I chose wisely when I selected you to spearhead my fight.  Time to ramp things up to a whole new level, I think.\n\nYou remember that little goodie that you stole for me out from underneath Grulloc's nose?  You're going to get a chance to put it to good use." }
WordHunterWoW_QuestEN[10806] = { title = "Showdown", description = "The time has come for us to face Goc, the master of the Bladespire ogres. It is also time that I take a hand in events, to see the last of the gronn's life.\n\nTake my signet ring. When you come to the Altar of Goc, use it, and I will come to join you.\n\nTogether we will destroy Goc.", objectives = "Use Sablemane's Signet at the Altar of Goc, then kill Goc.", progress = "In time, all the sons of Gruul will be destroyed.", completion = "You fought surprisingly well for a <race>, and it was an honor to have you at my side.  My transformation must have been quite a surprise for you.  I trust it was not too startling?\n\nLet us keep my true identity between the two of us for now, shall we?  In return, and for your adept service, I grant you your choice of any of these baubles." }
WordHunterWoW_QuestEN[10807] = { title = "The Ashtongue Broken", description = "The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, to the north.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.", objectives = "Varen the Reclaimer wants you to go to the Ruins of Baa'ri and slay 3 Ashtongue Handlers, 4 Ashtongue Warriors and 6 Ashtongue Shaman.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "Glory to the Scryers, <name>.  You've done the Seer's bidding by defeating those who follow Illidan." }
WordHunterWoW_QuestEN[10808] = { title = "Thwart the Dark Conclave", description = "The spirits of the dark conclave seek to summon an ancient and powerful evil through a ritual conducted at the lava pits to the south of the Sketh'lon Base Camp.\n\nGul'dan's magic mingled with their own, empowering them to aid this creature in manifesting in our world! We must not allow this to happen, {name}. The death and destruction it would bring are unimaginable!\n\nCarry the staff with you to the site of the summoning and use its magics to stop the dark conclave once and for all!", objectives = "Slay the Dark Conclave Ritualists and use the Staff of Parshah to end the Dark Conclave's summoning ritual, then return to Parshah in the Magma Fields.", progress = "Is it done, <name>? Have you stopped the dark conclave from completing their ritual?", completion = "I have sought a way to stop the dark conclave for years, and you have succeeded where I failed. The conclave's dark rituals will threaten us no more.\n\nI often feel guilty for abandoning my fellows all those years ago, but now I finally know that I made the right decision. If not for my wavering conscience then, I might have ended up as a shade among them." }
WordHunterWoW_QuestEN[10809] = { title = "WANTED: Worg Master Kruush", description = "The poster reads:\n\n\"Worg Master Kruush leads the worg riders of the Bleeding Hollow clan.  A price has been placed on his head, for his riders exact heavy tolls on supply trains to Spinebreaker Post.\"\n\n\"Scouts report him within Zeth'Gor, and the hero able to bring the severed head of this villain to me will earn the thanks of the Horde, and a large bounty.\"\n\n\"-Captain Darkhowl\"", objectives = "Kill Worg Master Kruush and bring his head to Captain Darkhowl in Spinebreaker Post.", progress = "Report, <name>.  Is that Bleeding Hollow blood I see on your sleeve?  I hope so!", completion = "Ah, so you slew that villain, Kruush!  Well done, <name>!  Well done!  His death will defang those cursed worg riders.  In fact, I hope you took a few of them out during your foray into Zeth'Gor!\n\nHere's your reward.  You earned every piece of it!" }
WordHunterWoW_QuestEN[10810] = { title = "Damaged Mask", description = "As you examine the damaged mask, you hear strange sounds coming from within. If the mask wasn't damaged you might be able to hear the sounds more clearly.\n\nO'Mally Zapnabber in Ruuan Weald might be able to fix the mask.", objectives = "Deliver the Damaged Mask to O'Mally Zapnabber at Evergrove in the Blade's Edge Mountains.", progress = "Don't be bothering me! Can't you see I'm trying to unlock mysterious powers?", completion = "Ah, what's that you have? Let me take a closer look, <class>. Yes, yes... it's just what I thought it was. Here, let me fix this mask for you." }
WordHunterWoW_QuestEN[10811] = { title = "Seek Out Neltharaku", description = "Their patron soars high above, {name}. Perhaps the kindness that you showed his children has moved his heart. Seek Neltharaku out and enlist his aid. Together, you may be able to solve the plight of the Netherwing drakes.\n\n<Mordenai points to the sky.>\n\nFly high, friend...", objectives = "Seek out Neltharaku, patron of the Netherwing Dragonflight.", completion = "My children have told me of your heroic deeds, <race>. There is more that you can do." }
WordHunterWoW_QuestEN[10812] = { title = "Mystery Mask", description = "Ok, it should work now. What is it, you ask? Why, it's a communication device - it allows those blockheads to communicate with each other. You know, the Burning Legion! I would suggest that you hand this mask to Wildlord Antelarion. He's over there pacing around. Always moving, he is.\n\nWell get moving, he's been trying to get his hands on one of these for sometime now.", objectives = "Deliver the Mystery Mask to Wildlord Antelarion at Evergrove in the Blade's Edge Mountains.", progress = "I cannot believe my eyes.", completion = "That mask you hold in your hands is a Felsworn gas mask and by the appearance, it's not damaged. The trouble we can cause Forge Camp: Anger is boundless. Are you interested in helping us out, <name>?" }
WordHunterWoW_QuestEN[10813] = { title = "The Eyes of Grillok", description = "{name}, you have braved the lair of the Bleeding Hollow orcs, dreaded Zeth'Gor, and survived!  Perhaps you have the strength to aid me, for I aim to gaze into the mind of its darkest witch, Grillok!\n\nTake this shard.  Use it to ensorcel an Eye of Grillok and bind it to yourself.  Return here and approach my cauldron... and it will pull the eye from you.\n\nGo, {name}.  And use care -- An Eye of Grillok will betray you to our enemies if given the slightest opening!", objectives = "Use Zezzak's Shard to capture an Eye of Grillok, then approach Zezzak's cauldron to extract it. After it is removed, return Zezzak's Shard to him.", progress = "The orcs of the Bleeding Hollow Clan were dark allies long ago... and even darker enemies now.", completion = "I am indebted to you, <name>.  You have again braved Zeth'Gor and held its darkness close to your heart.  I will study the eye and perhaps pierce the secrets of its master, Grillok.\n\nLet us hope that he can no longer use its magic!" }
WordHunterWoW_QuestEN[10814] = { title = "Neltharaku's Tale", description = "I have information that you may find useful. Please listen to what I have to tell you, {race}.", objectives = "Speak with Neltharaku and listen to his story.", completion = "So you will help us?" }
WordHunterWoW_QuestEN[10815] = { title = "The Journal of Val'zareq: Portends of War", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.", objectives = "Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch." }
WordHunterWoW_QuestEN[10816] = { title = "Reclaiming Holy Grounds", description = "You did well against the Broken in Baa'ri, {name}.  Let's see how well you do against Illidan's most feared army.\n\nThe fel orcs of the Shadowmoon Clan occupy the Ata'mal Terrace, once a very holy site where ata'mal crystals were used in spiritual ceremonies.\n\nWe had reason to believe they were hiding an actual ata'mal crystal in the vicinity, but our scrying has revealed nothing.  Nevertheless, the fel orcs are on draenei holy ground and their presence must be dealt with.", objectives = "Vindicator Aluumen wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "Excellent work, <class>.  May the Light continue to protect you." }
WordHunterWoW_QuestEN[10817] = { title = "The Great Retribution", description = "You did well against the Ashtongue Broken, {name}.  I have another challenge for you, should you be up to it.\n\nNot too long ago, the Sanctum of the Stars suffered a tremendous attack by Illidan's fel orcs.\n\nWe've determined it was perpetrated by the Shadowmoon orcs who occupy the Ata'mal Terrace.\n\nShow them that the Scryers are not to be trifled with.", objectives = "Varen the Reclaimer wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "You've gained my utmost respect today, <name>.\n\nSlaying one fel orc is not an easy task.  Massacring a score of them is, well... heroic." }
WordHunterWoW_QuestEN[10818] = { title = "Baron Sablemane Has Requested Your Presence", description = "{name}, while you were out being one hell of a {class}, Baron Sablemane sent his pet dragon up here with a message.\n\nHe's asked for you personally.  From what I understand, he wants you to head up his own fight against the gronn.\n\nI guess you're the most qualified person in all of Outland to help him, but if I were you, I'd get in contact with a couple of friends first and ask them to join you at the Circle of Blood.", objectives = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", completion = "Ah, I see that you decided to take your sweet time answering my summons.\n\nNo matter, I have plenty of time to exact my revenge, and I intend for you to be my proxy in the coming battle!" }
WordHunterWoW_QuestEN[10819] = { title = "Felsworn Gas Mask", description = "I have a very special mission for you, {name}. I need you to infiltrate Forge Camp: Anger east of here. When you enter the camp you will need to wear the Felsworn gas mask and locate the Legion communicator. Once you have located the communication device speak with whomever is on the other side of the device.\n\nIf all works out you can trick the demon into something devious! Try telling the demon that Camp Anger has revolted.\n\nGood luck to you {class}.", objectives = "Wear the Felsworn Gas Mask and use the Legion Communicator at Forge Camp: Anger in the Blade's Edge Mountains.\n\nProvided item:", completion = "What's the meaning of this! No one summons me! Speak, or I will silence you forever!" }
WordHunterWoW_QuestEN[10820] = { title = "Deceive thy Enemy", description = "For every moment I hear silence, you draw closer to your death! SPEAK!\n\nWhat? The camp has revolted? This cannot possibly be true! My minions would not dare undermine my authority.\n\nWell then, every last one of them will pay for this treachery, they will pay dearly. Silence them all and be done with it! Report back to me once you have carried out my order or you shall be dealt with.", objectives = "Slay 4 Doomforge Attendants and 4 Doomforge Engineers.", progress = "My patience is tiring, why have you not finished them?", completion = "That will surely teach those that don't do as I say...\n\nBy the way... where is Doomcryer? Why have you reported this revolt to me and not she?" }
WordHunterWoW_QuestEN[10821] = { title = "You're Fired!", description = "Doomcryer did nothing to stop the revolt? How dare she! She has been trying to undermine my authority for some time. However, this time will be her last. You must summon her and deal with her personally.\n\nHer anger guards hold the keys that summon her to Forge Camp: Anger. Retrieve the five keys and activate the five Legion obelisks. The obelisks have a short duration, so make sure they are all activated at the same time. Remember, the anger guards carry more keys.", objectives = "Slay Doomcryer.", completion = "That is great news, great news indeed, <name>. I could not have asked for a better outcome. Your service to our people is most greatly appreciated; choose one of the following heroic items.\n\nYour name will forever be remembered in our peoples' hearts." }
WordHunterWoW_QuestEN[10822] = { title = "Single Sunfury Signet", description = "", objectives = "Even the smallest contribution to our cause is noted, <name>. Our enemies are many, but we shall prevail!", progress = "Even the smallest contribution to our cause is noted, <name>. Our enemies are many, but we shall prevail!", completion = "Victory to the Scryers! Kael's forces will soon crumble." }
WordHunterWoW_QuestEN[10823] = { title = "More Sunfury Signets", description = "", objectives = "How fares the battle against Kael's forces?", progress = "How fares the battle against Kael's forces?", completion = "You're making a name for yourself, <name>. Keep it up." }
WordHunterWoW_QuestEN[10824] = { title = "Sunfury Signets", description = "The survival of the Scryers hinges on outrecruiting Kael'thas.  Every pilgrim from Quel'Thalas that joins his side brings him closer to victory.  The opposite is true for us.\n\nSoon, however, we will run out of recruits and it will come down to what side can kill the other quicker.  Prove your worth to the Scryers by bringing me Sunfury signets worn by  high-ranking blood elves allied with Kael'thas and Illidan.  You'll find them at Eclipse Point to the west and the Ruins of Karabor, to the northeast.", objectives = "Battlemage Vyara at the Sanctum of the Stars wants you to bring her 10 Sunfury Signets.\n\nPerforming quests for the Scryers will cause you Aldor reputation level to decrease.", progress = "Go on, <name>.  Speak.", completion = "Kael's elves are extremely well-trained.  Excellent job." }
WordHunterWoW_QuestEN[10825] = { title = "The Truth Unorbed", description = "This strange, magical orb drops from beneath the contour feathers of the arakkoa.\n\nSuffused with an eerie, purple glow, the orb pulses to an unheard beat.  Holding it makes you mildly uncomfortable, and so you quickly place it within your pack.\n\nPerhaps Tree Warden Chawn at Ruuan Weald to the west, through the tunnel and across the Wyrmskull Bridge, would be interested in examining it?", objectives = "Deliver the Orb of the Grishna to Tree Warden Chawn at Evergrove in the Blade's Edge Mountains.", progress = "<class>, do you feel that?  I sense something unnatural and evil nearby.", completion = "Yes, it's that orb you have there!  Odd, it appears to be of arakkoan design.  Were you recently at Grishnath?\n\nAll right, that explains that, but I wonder what diabolical purpose this object serves.  Though it radiates evil, it also somehow feels as if it were connected to the natural world.\n\nHere, allow me to try to activate it.  The evil is so strong within it, there's some sort of residual memory here...." }
WordHunterWoW_QuestEN[10826] = { title = "Marks of Sargeras", description = "By now it should be clear to you why we oppose the Burning Legion and those who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  Here in Shadowmoon you will find a strong Legion presence to the far west in Legion Hold and the Deathforge.", objectives = "Bring 10 Marks of Sargeras to Harbinger Saronen in Shadowmoon Valley.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Do you bear any of our enemies' insignias, <name>?", completion = "Your courage is strong, friend.  Let it be known to all that you are a true ally of the priesthood!" }
WordHunterWoW_QuestEN[10827] = { title = "More Marks of Sargeras", description = "", objectives = "Do you bear more of our enemies' insignias, <class>? The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", progress = "Do you bear more of our enemies' insignias, <class>? The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", completion = "You continue to prove your worth, <name>. Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded." }
WordHunterWoW_QuestEN[10828] = { title = "Single Mark of Sargeras", description = "", objectives = "I'll take any leftover marks you might have. Do not worry, your actions will be duly noted.", progress = "I'll take any leftover marks you might have. Do not worry, your actions will be duly noted.", completion = "You continue to prove your worth, <name>." }
WordHunterWoW_QuestEN[10829] = { title = "Treebole Must Know", description = "This is troubling!  The arakkoa are causing the ancients and protectors to become possessed by evil spirits!\n\nBut, there is one ancient that could not possibly have been affected.  His name is Treebole, and you must go to him at once if we're to save the trees of the Raven's Wood!\n\nGo back to the Raven's Wood.  You will find him at the fork in the path just past Grishnath.", objectives = "Speak with Treebole, an ancient of lore who lives in the Raven's Wood of the Blade's Edge Mountains.", completion = "Greetings, tiny <race>.  The birds in my boughs whispered to me that you were to be expected.\n\nYou are here to help free the trees of the woods from their possession?" }
WordHunterWoW_QuestEN[10830] = { title = "Exorcising the Trees", description = "The Grishna have caused the leafbeards and stonebarks to be inhabited by evil koi-koi spirits.\n\nWe must save the trees or soon all of the Raven's Wood will be lost forever!\n\nCombine the magic of a Grishnath orb, found throughout Grishnath, with a dire pinfeather from a dire raven.\n\nUse the resultant exorcism feather to draw out and slay the koi-koi spirit as quickly as possible.  The stonebarks are too powerful for this ritual, but if enough leafbeards are saved, they will be freed as well.", objectives = "Collect 5 Grishnath Orbs and 5 Dire Pinfeathers and then combine them into Exorcism Feathers. Use these feathers to exorcise and slay 5 Koi-Koi Spirits from the Raven's Wood Leafbeards.", progress = "The evil that is inhabiting the trees is beginning to seep into every natural thing in the woods.\n\nYou must act quickly, <name>, before all is lost!", completion = "The evil is lifting from the Raven's Wood!  Can you feel it, <name>?\n\nYou have saved us, and all of the surrounding wildlife, from certain destruction, little one!\n\nI keep stashed four magic rings amongst my boughs for such occasions as this, when a hero arises to do some great deed.\n\nYou are one such hero!  On behalf of all of the Raven's Wood, we give you thanks." }
WordHunterWoW_QuestEN[10831] = { title = "Becoming a Mooncloth Tailor", description = "I can teach you the ways of mooncloth tailoring, if you are interested.. By specializing in mooncloth tailoring, creating primal mooncloth will yield twice the normal amount and you will have access to several exclusive patterns. All that is required is that you pass a simple test.\n\nAs to the test, your task is to create a small sample of primal mooncloth in the moonwell at Cenarion Refuge. I will provide all the materials you'll need. When you've created the sample, bring it back to me for examination.You will learn:", objectives = "Use the Square of Imbued Netherweave while standing in Cenarion Refuge's moonwell to create a Sample of Primal Mooncloth. Bring the completed sample back to Nasmara Moonsong in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization." }
WordHunterWoW_QuestEN[10832] = { title = "Becoming a Spellfire Tailor", description = "I can teach you the ways of spellfire tailoring if you wish, but be warned, it's a dangerous pursuit.\n\nCreating spellcloth in Netherstorm attracts powerful nether-wraiths. I'm searching for a way to lessen backlash, but I need more nether-wraith essence for my research.\n\nTake this beacon with you to Netherstorm and use it to summon a nether-wraith. Bring back its essence and I'll agree to teach you. As a spellfire tailor, you'll receive twice as much cloth and have access to exclusive patterns.You will learn:", objectives = "Bring a sample of Nether-wraith Essence to Gidge Spellweaver in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization." }
WordHunterWoW_QuestEN[10833] = { title = "Becoming a Shadoweave Tailor", description = "If you become a shadoweave specialist, you will make twice as much shadowcloth as an average tailor and have access to several exclusive patterns.\n\nOf course, any tailor can use the Altar of Shadows, but a shadoweave tailor possesses a deeper attunement to the altar, unlocking powers that few can fathom.\n\nTake this crystal to eastern Shadowmoon Valley, and find Netherwing Pass leading south from the Netherwing Fields. Near the world's edge, you will find the Altar of Shadows. Use the crystal there.You will learn:", objectives = "Use the Crystal of Deep Shadows near the Altar of Shadows to deepen your attunement to the altar, then return to Andrion Darkspinner in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization." }
WordHunterWoW_QuestEN[10834] = { title = "Grillok \"Darkeye\"", description = "Grillok Darkeye has wagered a piece of himself to dark powers, and gained great magic for it.  His lost eye burns deep in some hellish pit, now a demon's trinket... and the patch that covers his betrayal holds its own dark secrets.\n\nBring me Grillok's eyepatch, {name}, and I will reward you greatly for your service...", objectives = "Kill Grillok Darkeye and bring Grillok's Eyepatch to Zezzak in Spinebreaker Post.", progress = "The evils of the Bleeding Hollow orcs know no bounds, and are rivaled by only their Shattered Hand cousins.", completion = "Ah, yes.  Just as some who lost a hand or a leg in battle will oftentimes feel their severed limb, I wonder if Grillok still clutched at his lost eye in his dark, dark dreams...\n\nI too will dream on this, and if fortune is with us then perhaps I will learn what drew Grillok and the Bleeding Hollow orcs to succumb to demons." }
WordHunterWoW_QuestEN[10835] = { title = "Apothecary Antonivich", description = "{name}, I have prepared a preliminary report of my findings regarding the Bleeding Hollow orcs.  My colleague in Thrallmar, Apothecary Antonivich, will be happy to receive them.  He too studies the phenomenon of fel orcs... in hopes of preventing such a tragedy from again befalling our orcish allies.\n\nTake him this report, and I will continue my study of the blood you brought me.  If fortune is with us, we will isolate the cause of the fel orc affliction.", objectives = "Bring Albreck's Findings to Apothecary Antonivich at Thrallmar in Hellfire Peninsula.", progress = "Good day, <name>.  And how is your stay in Hellfire Peninsula?  I trust it has been fruitful...", completion = "Ah, a report from Albreck?  Very good.  The Royal Apothecary Society works feverishly to determine how the orcs of Hellfire Peninsula became fel orcs.  Their betrayal is unforgivable... and we must ensure that our orc friends are forever safe from future corruption." }
WordHunterWoW_QuestEN[10836] = { title = "Infiltrating Dragonmaw Fortress", description = "I require time so that I may devise a plan to save my children and mate. You will buy me this time, mortal.\n\nVenture into Dragonmaw Fortress, located on the eastern edge of the Netherwing Fields, and lay waste to all Dragonmaw orcs that you find. The ensuing chaos and confusion should have a considerable impact on their plans.\n\nBe warned, some of my kin are too far gone - their minds corrupted by the Dragonmaw. For them, the only resolution is death. You have my permission to end their lives as well.", objectives = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to slay 15 Dragonmaw Orcs.\n\nAny Dragonmaw Orc in Dragonmaw Fortress will suffice.", completion = "Well done, <name>. I have discovered a way in which we can free the enslaved drakes that are being held at Dragonmaw Fortress." }
WordHunterWoW_QuestEN[10837] = { title = "To Netherwing Ledge!", description = "I believe that I can imbue nethervine crystals with my own essence. The power contained within these imbued crystals should be sufficient to free enslaved drakes of their masters' grasps.\n\nTravel to Netherwing Ledge, an island located off the broken shelf of Shadowmoon Valley, to the southeast. It is on Netherwing Ledge that you will find nethervine crystals. Return to me when you have collected enough crystals to fill your packs.\n\nAnd {name}, Beware the Dragonmaw that now inhabit the island.", objectives = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to collect 12 Nethervine Crystals from Netherwing Ledge.", progress = "I require nethervine crystals.", completion = "<Neltharaku takes the crystals from you.>\n\nI will prepare the crystals for you now." }
WordHunterWoW_QuestEN[10838] = { title = "The Demoniac Scryer", description = "The Demoniac Scryer is now ready.  Take it behind Hellfire Citadel, to Hellfire Basin, and summon it upon the ground.  It will then begin to attune itself to Hellfire Citadel.  After its attunement, speak to the Scryer and transcribe what it tells you.  Bring that transcription to me...\n\nGo, {name}, but only when you are ready.  There is no doubt that Hellfire Citadel will detect the Scryer and send wardens to destroy it!", objectives = "Use the Demoniac Scryer in Hellfire Basin, wait for it to attune, and then take a reading.\n\nReturn the Demoniac Scryer and the Demoniac Scryer Reading to Apothecary Antonivich in Thrallmar.", progress = "Do you have the reading?  Has your mission with the Demoniac Scryer been successful?", completion = "You obtained the reading?  Excellent -- I am sure this data will prove invaluable to our research.  I will disseminate it to Apothecaries Zelana and Albreck.\n\nYou should be proud, <name>.  Your strength and bravery is unquestionable... as is your service to the Horde." }
WordHunterWoW_QuestEN[10839] = { title = "Veil Skith: Darkstone of Terokk", description = "Veil Skith lies to the northwest of the caravan and to the south of Shattrath in a secluded grove of the forest. It is rumored that the colony of Skettis has constructed a maligned altar of worship. This Darkstone of Terokk must be purified if the arakkoa of Skith are ever to be redeemed.\n\nTake this Rod of Purification and cast it upon the Darkstone. Blessed by A'dal, the rod's purity might be enough to bring clarity to the Darkstone. Go now and may the light shine upon thee.", objectives = "Use the Rod of Purification on the Darkstone of Terokk in Veil Skith and return to Kirrik the Awakened at the Refugee Caravan in the Bone Wastes.", progress = "Darkness surrounds us. What have you to say about Veil Skith?", completion = "I heard the explosion from here. Not with my ears, but with my heart.\n\nIf the touch of the blessed Naaru, A'dal, is not enough to bring the arakkoa to redemption, nothing will be. Those who have not given themselves over to the Light are mere servants of evil.\n\nThey must be destroyed." }
WordHunterWoW_QuestEN[10840] = { title = "The Tomb of Lights", description = "To the east, buried under the charred sand, is the Tomb of Lights, a lost resting place of the dead.  Before our caravan was ambushed I was going to journey to the tomb and cleanse it of evil spirits.  \n\nLittle did I know it was already infested with another kind of evil.  Even now the ethereals plunder the bodies of the fallen for trinkets and keepsakes that were given to the dead centuries ago.  \n\nThere is little I can do while our caravan struggles to survive.  ", objectives = "High Priest Orglum wants you to journey to the Tomb of Lights and kill 10 Ethereal Nethermancers and 10 Ethereal Plunderers and then return to him at the Refugee Caravan.", completion = "Out here in the wilds of Outland we are weak with few heroes to defend our rights, but you have given them something to fear <class>.  I do not think the ethereals will soon forget the strong right arm of <name>." }
WordHunterWoW_QuestEN[10841] = { title = "The Vengeful Harbinger", description = "[PH]  Go into the Tomb of Light and activate the thingy.", objectives = "[PH]  Activate the thingy." }
WordHunterWoW_QuestEN[10842] = { title = "Vengeful Souls", description = "The Tomb of Lights has become corrupted by the Shadow Council and the draenei dead have become cursed spirits, angry and confused with a burning hatred for the living.\n\nEnter the tomb and seek out these tragic victims. Give them the rest that they deserve.", objectives = "High Priest Orglum wants you to journey into the Tomb of Lights and defeat 5 Vengeful Draenei.", completion = "On behalf of the tortured souls you have freed, I thank you, <race>." }
WordHunterWoW_QuestEN[10843] = { title = "Since Time Forgotten...", description = "Since time forgotten we have fought with the Bladespire ogres.\n\nWe have managed to push them back so that now they only hold a tenuous grip at Bladespire Outpost.  It's back the way that you came, on the southwestern edge of the Razor Ridge.\n\nProve your worth to me by killing their leader, Gnosh Brognat.\n\nLet us see what stuff you are made of when fighting the ogres.", objectives = "Slay Gnosh Brognat, leader of the ogres at the Bladespire Outpost.", completion = "<Leoroxx appraises you with a keen eye, seemingly trying to take your measure.>\n\nThe death of Gnosh Brognat is a boon to all of the Mok'Nathal.  This is a good thing for you.\n\nLet us see if we can push the boundaries of your prowess just a bit more." }
WordHunterWoW_QuestEN[10844] = { title = "Forge Camp: Anger", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10845] = { title = "Slay the Brood Mother", description = "My hunters have just returned from a scouting mission to the Singing Ridge.  It seems that the nether drakes, which infest the crystals there, have increased greatly in number, and threaten to spill out into our laps.\n\nSince you have proven yourself a competent slayer, let us see if your {class} skills are the match of an adult drake.\n\nFind the Singing Ridge by heading south through the Scalewing Shelf.  Enter and slay their brood mother, Dreadwing.", objectives = "Slay Dreadwing.", completion = "No?  You slew Dreadwing?  Perhaps I was wrong about you, <class>.\n\nPerhaps.\n\nStill, you have slain the chiefs of the three greatest threats that we face.  That is something to be proud of.\n\nI offer you a token of my appreciation, but don't let it go to your head.  You still do not fully understand what it is to be Mok'Nathal, and we may still have need to call upon your skills." }
WordHunterWoW_QuestEN[10846] = { title = "Understanding the Mok'Nathal", description = "<Leoroxx looks you in the eye with the kind of stare that chills your soul.>\n\nYou come to the Mok'Nathal, but you do not understand us.  You do not understand our struggle to survive.\n\nIf you would understand us, then you will have to endure a taste of that struggle.\n\nTo the south are the Vekh'nir arakkoa.  They have enslaved a group of ogres in the caverns known as Trogma's Claim and their leader, Vekh is in there.\n\nSlay him!", objectives = "Slay Vekh, leader of the Vekh'nir arakkoa.", completion = "The Vekh'nir are the least of our adversaries.\n\nSo, you know how to slay an overgrown bird.  This does not make you a true warrior.  This does not give you a full understanding of our ways.\n\nBut it's a start." }
WordHunterWoW_QuestEN[10847] = { title = "The Eyes of Skettis", description = "Doom harkens from the cliffs of Skettis.\n\nMy people, the arakkoa, face a fate shrouded in unspeakable evil. Too often have we abused dark magic for wrongdoing. Through A'dal I have learned of the Light and of redemption.\n\nTerokk watches his colonies from Skettis through orbs enchanted by the black art. Steal these Eyes from Veil Reskk and Veil Shienor in northern Terokkar. Let me see what Terokk sees. Let me look through the eyes of Skettis.", objectives = "Bring the Eye of Reskk and the Eye of Shienor to Rilak the Redeemed in the Lower City section of Shattrath City.", progress = "You have returned, <class>. What news do you bring?", completion = "Your bravery should be commended. The guardians of Skettis do not part with their belongings willingly.\n\nBut heroics of the past are of little consequence now. We shall see if such bravery continues to persist in the future, for Terokk's gaze fixates on the south.\n\nThese Eyes are all seeing." }
WordHunterWoW_QuestEN[10848] = { title = "Veil Rhaze: Unliving Evil", description = "Veil Rhaze was a particularly wicked colony of Skettis.\n\nDespite the village's eradication by the Auchindoun disaster, Terokk's influence remained in the maligned spirits there. Travel west to Veil Rhaze and slay those murderous wretches. You'll find them to the west of the Shadow Tomb, on the border of Bone Wastes and Terokkar Forest.\n\nThis will be our first blow against Terokk and the guardians of Skettis.", objectives = "Kill 4 Deathtalon Spirits, 4 Screeching Spirits and 2 Spirit Ravens and return to Kirrik the Awakened at the Refugee Caravan.", completion = "Those foul spirits deserved to die. The death they would have wrought on others is reason enough.\n\nWe cannot hope to redeem those in Terokk's grasp. But we shall deliver them a devastating blow in the name of the Light." }
WordHunterWoW_QuestEN[10849] = { title = "Seek Out Kirrik", description = "Other arakkoa took part in the betrayal of Terokk.\n\nKirrik recognized Terokk as a charlatan, not a prophet. The only prophecy Terokk envisioned was the doom borne of his own bidding.\n\nIt was Kirrik who led us bravely from Skettis. After our pilgrimage to Shattrath, Kirrik traveled to the colonies in search of others.\n\nThis missive tells of what the Eyes have seen. Kirrik must be told! Follow the road south out of Shattrath to the Bone Wastes and look for the caravan.", objectives = "Take Rilak's Missive to Kirrik the Awakened at the Refugee Caravan in the Bone Wastes.", progress = "You have traveled far and bear news for me.", completion = "Rilak's tale is grim, traveler. As you can see from the state of the caravan, there is much sorrow and darkness in the forest of Terokk these days." }
WordHunterWoW_QuestEN[10850] = { title = "Nether Gas In a Fel Fire Engine", description = "", objectives = "You uncover an opening through which fuel is loaded into the fel reaver.", progress = "You uncover an opening through which fuel is loaded into the fel reaver.", completion = "The fel reaver's engine begins to rumble and sputter as you supply it with the incorrect fuel." }
WordHunterWoW_QuestEN[10851] = { title = "The Totems of My Enemy", description = "There is the right way to honor one's ancestors, and there is the wrong way.\n\nThe Bladespire ogres carry totems with them, but they do not use them to show their respect.  Instead, they seek to use them to manipulate and control.\n\nWe should steal their totems because they are unworthy!  We will then put them to better use.\n\nGo to the Bladespire Outpost to the west, just southwest of the Razor Ridge.  Slay the Bladespire mystics and crushers, and take their totems from them!", objectives = "Collect 5 Bladespire Totems.", progress = "Have you gone to Bladespire Outpost and taken their totems from them?", completion = "This looks like a good assortment.  We should be able to find a respectful use for one or two of them.\n\nIn fact, I have an idea for how to do just that!" }
WordHunterWoW_QuestEN[10852] = { title = "Missing Friends", description = "We broke down here because some guys came in the night and made a lot of noise.  It was scary.  I don't know when we are going to get moving again.  \n\nSome of my friends are missing though.  I don't know where they are.  I think those scary bird men took them away to the northwest.  They probably are all locked up in cages and stuff.  If you find them that would be great.  I'm kind of worried about them.", objectives = "Ethan wants you to find 12 of his missing friends in Veil Skith and then return to him at the Refugee Caravan.", completion = "You found all my friends!  Now I have someone to play with.  Thank you, Mister <name>.  \n\nSince I have kids to play with maybe you would like one of my toys?  That way you have something to play with too." }
WordHunterWoW_QuestEN[10853] = { title = "Spirit Calling", description = "The spirits of the nether drakes in the Singing Ridge are in need of liberation.\n\nThe nether drakes were not always nether drakes.  They used to be black drakes.\n\nBut then, with the destruction of this world, a wave of nether energy washed over everything and had the side-effect of changing the drakeling eggs.\n\nNow they are all twisted versions of their former selves.  We must help them to find peace.\n\nDo this by slaying a drake near to the spirit calling totem, and then take its spirit from it.", objectives = "Use the Spirit Calling Totems to collect 8 Lesser Nether Drake Spirits.", progress = "The drakes of the Singing Ridge may pose a threat to us, but I think they are majestic creatures.\n\nOr, at least they were.  I hope that you will be able to save their spirits.\n\nAnd if you are in need of more totems, I have a few to spare.", completion = "You have done a good thing this day, <class>.  The spirits of the drakes will truly sing again now that they have been freed.  And the residual part of their spirits that they leave behind are powerful medicine, too.\n\nI wonder, are you up for a journey to the north?  There is something that I am curious about concerning the activities of the ethereal.\n\nI sense a great deal of pain coming from their direction." }
WordHunterWoW_QuestEN[10854] = { title = "The Force of Neltharaku", description = "Take this enchanted nethervine crystal and make your way back to Dragonmaw Fortress. Once there, seek out the enslaved drakes and invoke the magic of the nethervine crystal. My own energies will pour forth, causing the drakes to break free from the bond of their captors. When you see that the drake has broken free, help it defeat its captor! It will most assuredly be weak from the imprisonment.\n\nRelease all that you can find and return to me, {name}.", objectives = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to free 5 Enslaved Netherwing Drakes.", progress = "Waste no time, we have much work to do!", completion = "<Neltharaku laughs.>\n\nThe orcs must have been shocked to see the drakes turn on them in such a manner. Well done, <name>. Perhaps you truly are the hero of our flight." }
WordHunterWoW_QuestEN[10855] = { title = "Fel Reavers, No Thanks!", description = "Ah, yes - the fel reaver!  Certainly the Legion's most terrible mechanical creation.  There are no less than three of these abominations aimed at the Stormspire.\n\nFortunately for us, they are not active yet.  This affords us the possibility of dealing with them through sabotage instead of brute force.\n\nObtain condensed nether gas from the gan'arg at Forge Base: Oblivion and fill a nearby fel reaver's fuel tank with it.  I've a feeling its engine won't handle it too well.", objectives = "Obtain 5 Condensed Nether Gas from Gan'arg Mekgineers at Forge Base: Oblivion, northwest of the Stormspire, and load them into a nearby Inactive Fel Reaver. Return to Nether-Stalker Nauthis after you've completed this task.", completion = "That is excellent news, <name>.  Now that we know how to deal with these, I can have hirelings sabotage any remaining reavers." }
WordHunterWoW_QuestEN[10856] = { title = "The Best Defense", description = "Brave acts of industrial sabotage will only get us so far, {name}.  Just as Forge Base: Oblivion serves as an assembly site for Fel Reavers, Forge Base: Gehenna serves as a staging ground for their army as it is where the majority of the Legion's teleportation devices are located.\n\nI want you to go in there and put a dent in their numbers.  They must have a full regiment of wrathbringers by now and we just can't allow that.", objectives = "Nether-Stalker Nauthis wants you to slay 12 Wrathbringers at Forge Base: Gehenna, north of the Stormspire.", completion = "Nice work, <name>.  Keep it up and I'll put in a good word with the Nexus-Prince." }
WordHunterWoW_QuestEN[10857] = { title = "Teleport This!", description = "As fun as killing demons might be, it does us little good when the Legion can keep using its teleporters to replace anything we kill.\n\nUnfortunately, I don't have any high-powered explosives handy... but the mo'arg that maintain the teleporters do.\n\nTake this rod... I've tuned its powers to interfere with mo'arg brain frequencies.  Return to Forge Base: Gehenna and use it on any mo'arg you see.  You won't have long, but you'll be able to use their demolition charges on the nearby teleporters.", objectives = "Nether-Stalker Nauthis wants you to use the Mental Interference Rod on the Mo'arg at Forge Base: Gehenna and use their Detonate Teleporter ability on the three teleporters in the forge camp.", progress = "Is it done then?  Are the teleporters shut down?", completion = "Thanks to you, <name>, I'll breathe a little easier.  Figure of speech, of course!\n\nI suppose you'll want some form of reward now." }
WordHunterWoW_QuestEN[10858] = { title = "Karynaku", description = "It shames me to ask for your assistance once more, {name}, but you are my flight's only hope. Without my mate, the netherwing brood may die out completely.\n\nMake your way to the top of Dragonmaw Fortress and find Karynaku.\n\nWe will be flying overhead. Should a break appear in their defenses, the might of the netherwing will swoop down to assist you.\n", objectives = "Seek out Karynaku at Dragonmaw Fortress.", completion = "It is the chains. They sap my power. The only way is to get the key from Zuluhed and unbind me." }
WordHunterWoW_QuestEN[10859] = { title = "Gather the Orbs", description = "The Razaani ethereals have strange devices that emit small, pink floating light orbs.  They remind me of souls.\n\nThey are not to be confused with the large yellow balls that break free of the ethereal when they die, these are something else entirely.\n\nI'd like for you to head north to Razaan's Landing and drop some totems, which will attract the pink light orbs.\n\nBring them back to me so that I might determine exactly what they are.", objectives = "Use the Orb Collecting Totem to collect 15 Razaani Light Orbs.", progress = "Have you collected all of the Razaani Light Orbs that are needed?", completion = "Something does not feel right.\n\nPlease, <name>, hand me the totem.  I must examine those orbs!" }
WordHunterWoW_QuestEN[10860] = { title = "Mok'Nathal Treats", description = "Hungry, {race}?  The Great Spirit helps those that help themselves.  If you want to earn a meal, I suggest that you listen up, because Braagor there isn't going to give you anything for free, nor as tasty!\n\nThe raptors and scalewings of Razor Ridge and the Scalewing Shelf have everything that's needed for two of the most delicious dishes you'll ever taste.  Bring me their raptor ribs and serpent flesh, and I'll make some of each for you.\n\nI may even teach you how to cook them up for yourself, if you hurry.", objectives = "Collect 3 Raptor Ribs and 3 Serpent Flesh.", progress = "Have all of the ingredients yet?  Talking about it with you has made my mouth water!", completion = "Mmm, I can taste them already.  Quickly, hand over those parts... I'm going to get them diced up and onto the fire!\n\nLuckily for you, this stuff keeps, and I mean for a long time!  So, take these, and I suppose you can have the recipes as well for being so kind as to restock my larder." }
WordHunterWoW_QuestEN[10861] = { title = "Veil Lithic: Preemptive Strike", description = "In the wretched colony to the southwest known as Veil Lithic, Terokk's minions are attempting to befoul their avian brethren before they hatch. The dark sorcerers of Lithic encase eggs in a shadowy curse. When the hatchlings emerge, they mindlessly serve Terrok.\n\nTravel to Veil Lithic and prematurely break the eggs before the curse has time to seep in. Even if you are too late, you can put down the tainted ones.\n\nRemember, the Light shines brightest in the darkness.", objectives = "Break the cursed eggs in Veil Lithic. Redeem 3 Hatchlings and slay 3 Malevolent Hatchlings before returning to Kirrik the Awakened at the Refugee Caravan.", completion = "It is grim work toiling with someone's hatchlings, yet ignoring the brewing evil would be a bleak proposition as well. You have done well.  A'dal's favor shines upon your heart." }
WordHunterWoW_QuestEN[10862] = { title = "Surrender to the Horde", description = "The cowardly arakkoa attack us daily.  They ambush our hunters and sometimes even raid inside our walls.  We kill them when we can, but their magic is strong and they often escape our warbands.  \n\nI have learned that some arakkoa claim to be friendly with the Horde.  They live in Shattrath City to the northwest.  Rilak the Redeemed is their leader.  Search for him in the Lower City, and when you find him, demand his surrender.", objectives = "Rokag wants you to seek out Rilak the Redeemed in the Lower City section of Shattrath City and demand that he and his people surrender to the Horde.", completion = "Your people are angry but there is little I can do.  Some of us have been touched by the power of the naaru and we are forever changed.  Those of us who remain in the wild are as we have always been." }
WordHunterWoW_QuestEN[10863] = { title = "Secrets of the Arakkoa", description = "Out here on the frontier we have to deal with the arakkoa every day.  They strike at us when they please, raiding our supply lines and killing our scouts.  \n\nYet we know very little about these enigmatic creatures.  I have received news that northwest of here in Shattrath City there are arakkoa who are not hostile.  They might be willing to share the secrets of their race.  \n\nRilak the Redeemed is their leader.  He resides in the northern part of the Lower City.", objectives = "Lady Dena Kennedy wants you to seek out Rilak the Redeemed in the Lower City section of Shattrath City and find out what secrets he will share of the Arakkoa.", completion = "You are wise to find me.  There is much that I can show you." }
WordHunterWoW_QuestEN[10864] = { title = "A Burden of Souls", description = "I have a device, the Demoniac Scryer, that can analyze fel magic.  I would have you use the Scryer, but first... you must appease it.  The Scryer, you see, has trapped within it a creature of vast intelligence and its needs are, shall we say, quite eccentric.\n\nTo appease the Scryer, you must kill orcs.  Specifically, they must be Shattered Hand orcs -- the Scryer demands their souls.\n\nReturn to me when the souls are reaped.  You will find the orcs north, and south, and surrounding... Hellfire Citadel.", objectives = "Kill 20 Shattered Hand orcs, then return to Apothecary Antonivich in Thrallmar.", completion = "Well done, <name>.  Your soul is burdened with many deaths... and the Demonaic Scryer will now perform its duties for you.\n\nLet us hope you are ready for the coming trial..." }
WordHunterWoW_QuestEN[10865] = { title = "Inform Leoroxx!", description = "Quickly, you must inform Leoroxx of what is transpiring up at Razaan's Landing!\n\nThose orbs were comprised of souls, some of them Mok'Nathal!", objectives = "Speak with Leoroxx about what the Razaani ethereal are up to. He can be found at Mok'Nathal Village in the Blade's Edge Mountains.", completion = "What you say, is it even possible?  What am I saying?  Of course it is, if the spiritcallers say so.\n\nRemember before when I said that we might need your further assistance?  It would seem that I can tell the future." }
WordHunterWoW_QuestEN[10866] = { title = "Zuluhed the Whacked", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", objectives = "Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku.", progress = "<Karynaku groans.>", completion = "I am free! You have saved us, <name>!" }
WordHunterWoW_QuestEN[10867] = { title = "There Can Be Only One Response", description = "There can be only one response to this... this, DEFILEMENT of the souls of our ancestors!\n\n{name}, if you would aid us to restore the souls of our honored dead to their rightful place, go back to Razaan's Landing.\n\nGo back up there and kill the razaani until their leader, Nexus-Prince Razaan shows his cowardly face.  Kill him and get those souls back, and then give them over to Spiritcaller Dohgar!", objectives = "Collect the Collection of Souls.", progress = "Have you done it?  Are the souls of our ancestors safely recovered from the evil of the ethereals?", completion = "Good that the ethereal filth and their leader are dead.  I wish a thousand plagues upon their brethren!\n\nYou are to be rewarded for your actions on behalf of all of the Mok'Nathal, <name>!  You are truly one of our heroes.\n\nLet us now release the souls of our ancestors to the cleansing fire." }
WordHunterWoW_QuestEN[10868] = { title = "Arakkoa War Path", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could charge out to meet them in numbers. They use their summoning circles to rescue their warriors from certain death, but they cannot run from us if we attack their homes. Veil Reskk and Veil Shienor lie to the north and northeast.\n\nFind these arakkoa nests and kill as many as you can.", objectives = "Advisor Faila asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to her in Stonebreaker Hold.", completion = "Well done <class>.  The arakkoa have learned to fear the might of the Horde." }
WordHunterWoW_QuestEN[10869] = { title = "Thin the Flock", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could marshal our soldiers.  \n\nVeil Reskk and Veil Shienor lie to the north and northwest.  Find these arakkoa nests and kill as many as you can.  They may not fear us, but at least we can thin their numbers.", objectives = "Lieutenant Gravelhammer asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to him in Allerian Stronghold.", completion = "Well done <class>.  The arakkoa have learned to fear the might of the Alliance." }
WordHunterWoW_QuestEN[10870] = { title = "Ally of the Netherwing", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", objectives = "Let Karynaku return you to Mordenai in the Netherwing Fields.", completion = "You have proven yourself as an ally of the Netherwing. My mother is free and my brothers and sisters are saved!\n\nPerhaps someday, we will call for you again. When that day comes, know that you will be welcomed with open arms - a brother to the Netherwing Dragonflight." }
WordHunterWoW_QuestEN[10871] = { title = "Ally of the Netherwing", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", objectives = "Let Karynaku return you to Mordenai in the Netherwing Fields.", completion = "You have proven yourself as an ally of the Netherwing. My mother is free and my brothers and sisters are saved!\n\nPerhaps someday, we will call for you again. When that day comes, know that you will be welcomed with open arms - a brother to the Netherwing Dragonflight." }
WordHunterWoW_QuestEN[10872] = { title = "Zuluhed the Whacked", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", objectives = "Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku.", progress = "<Karynaku groans.>", completion = "I am free! You have saved us, <name>!" }
WordHunterWoW_QuestEN[10873] = { title = "Taken in the Night", description = "Our small outpost is under constant attack. Several nights ago, we were raided by the spiders of Netherweb Ridge, on the southeastern edge of the Bone Wastes. They poisoned many of our people, wrapped them in webs and carried them away. Some of our warriors took up arms and with little preparation pursued the spiders.\n\nWe have not seen the captives or our hunting parties since. We hope that some may still be alive, perhaps imprisoned by the spiders.  Our numbers are few. Will you search for our people?\n", objectives = "Scout Navrin wants you to travel to the Netherweb Ridge and free 6 Webbed Sha'tar Warriors and then return to him at Sha'tari Base Camp.", completion = "You saved so many.  I didn't think we would ever see them again.  We cannot thank you enough, <name>." }
WordHunterWoW_QuestEN[10874] = { title = "Veil Shalas: Signal Fires", description = "Terokk's perch, Skettis, looms above the Bone Wastes to the east. At the base of Skettis lies Veil Shalas, the most formidable of Terokk's colonies. It is through the stronghold of Veil Shalas that Terokk's forward sages wage war against the Light.\n\nThe evil-doers of Shalas communicate with their master using a complex system of magical signal fires. Travel to the east, {race}, and extinguish the fires. Once Veil Shalas is silenced, we can begin to plot the fall of Skettis.\n\nBut I get ahead of myself.", objectives = "Kirrik the Awakened at the Refugee Caravan wants you to extinguish the four signal fires of Veil Shalas.", completion = "We witnessed the cursed smoke rise from here. You are most brave, <class>." }
WordHunterWoW_QuestEN[10875] = { title = "Report to Nazgrel", description = "{name}, during your foray with the Demoniac Scryer, I sent word of your exploits against the fel orcs.  Nazgrel, our illustrious leader in Thrallmar, wishes to speak with you.  I believe he has a bloody mission in mind...", objectives = "Speak with Nazgrel at Thrallmar in Hellfire Peninsula.", completion = "It is good to hear of all your moves against the fel orcs, <name>.  The apothecaries have spent much time and resources studying the cause of their corruption, and although such information is invaluable... my orc blood burns to strike a severe blow against these betrayers!\n\nListen close, and I will explain my task..." }
WordHunterWoW_QuestEN[10876] = { title = "The Foot of the Citadel", description = "Force-Commander Gorax is training Shattered Hand captains at the base of Hellfire Citadel, honing them to a bloody razor's edge.  You must kill him, {name}, for his loss would be a mighty blow to the fel orcs.\n\nHowever, that is not all you must do.\n\nTake this banner.  Place it atop Gorax's corpse.  Gorax's commander, the Hand of Kargath, must answer your challenge if he has even a drop of true orc blood within him!\n\nHis head, the head of the hand of Kargath, is what I seek.", objectives = "Kill Force-Commander Gorax, place the Challenge From the Horde upon his corpse, kill The Hand of Kargath, and then bring the Head of the Hand of Kargath to Nazgrel in Thrallmar.", progress = "Have you faced the Hand of Kargath, <name>?", completion = "You have done a great deed, <name>.  The fel orcs are a shame to all true orcs.  If we have one fear, it is the fear of  succumbing to demonic corruption once again.  So you see, our war against the fel orcs is more than merely a battle with fierce foes -- it is also a battle within ourselves.\n\nAnd with strength, strength you have shown time again, it is a battle we will win." }
WordHunterWoW_QuestEN[10877] = { title = "The Dread Relic", description = "Long ago a caravan went to Auchindoun with a mission to take a Dread Relic from the ancient tombs beneath the necropolis. They fled, but the relic was their undoing.  The relic is evil and it summons evil when touched.   Their caravan was destroyed somewhere to the east. \n\nThis dark artifact is the key to a terrible plan to defeat Teribus the Cursed, a creature that flies over the Bone Wastes.  Help me if you wish, but your life and even your soul will be at risk.", objectives = "Oakun wants you to travel east to the Derelict Caravan to recover the Dread Relic. Return to Oakun when the task is complete.", progress = "Do you have the Dread Relic?  We must have it.", completion = "It is incredible that you succeeded.  The Dread Relic is far more powerful than I feared. Only a mighty hero could have survived the long journey back carrying such blasphemous evil." }
WordHunterWoW_QuestEN[10878] = { title = "Before Darkness Falls", description = "After our caravan fell prey to an attack by Shadow Council cabal cultists, scouts were sent to Shattrath to call for help.  The guards think we're safe for now, but they underestimate these madmen.\n\nI, for one, am not looking forward to having my throat slit by some cabal initiate in the middle of the night.  Do us all a favor and take the fight to them, before they come to us.\n\nYou will find our attackers south of here, at Auchindoun's northern entrance.", objectives = "Mekeda at the Refugee Caravan wants you to kill 8 Cabal Skirmishers, 4 Cabal Spell-Weavers and 2 Cabal Initiates.", completion = "I can breathe a sigh of relief for now, <name>.  The Shadow Council will be held off for the time being.\n\nThey are murderers and cowards and your display of courage will keep them at bay." }
WordHunterWoW_QuestEN[10879] = { title = "The Skettis Offensive", description = "Skettis has waged war on us! Have you gathered enough strength to help with Shattrath's defense?\n\nHold off the attackers!", objectives = "Hold off the attackers and speak with Rilak the Redeemed.", progress = "This is no time for idle chatter, <name>. We're under attack! Hold off the invaders!", completion = "I applaud your prowess in combat, <class>. You have proven yourself to be a true defender of the Light. May A'dal's blessing shine upon your darkest hours.\n\nBut look far into the horizon. Dark skies loom above Skettis. Terokk is undoubtedly plotting his next move. Shattrath is safe for now. But only tomorrow knows what terror will descend upon us." }
WordHunterWoW_QuestEN[10880] = { title = "Cabal Orders", description = "This message bears a dark seal and though the language seems somewhat familiar, it appears to be encoded.\n\nPerhaps someone at the Refugee Caravan will know something about it.", objectives = "Bring the Cabal Orders to Mekeda at the Refugee Caravan in the Bone Wastes.", progress = "You wish to show me something, <name>?", completion = "Ah, yes... this was written in a basic form of the shadow cypher.  My knowledge of it is not perfect but it should suffice to translate this.\n\nYou learn much about unsavory subjects when you live among outcasts and refugees in the Lower City." }
WordHunterWoW_QuestEN[10881] = { title = "The Shadow Tomb", description = "Many believe it was the Shadow Council that caused the explosion that tore Auchindoun apart.  It is rumored they awoke a great evil inside.\n\nIf that is true, then that evil must have turned against them.  According to these orders, part of the Shadow Council is fleeing Auchindoun.  They are using the Shadow Tomb to store powerful artifacts from Auchindoun.\n\nThree of these are sacred, for they belonged to the powerful patriarchs Arunen, K'alen and Atalor.  I must ask you to retrieve them.", objectives = "Go into the Shadow Tomb, west of the Refugee Caravan and retrieve the Drape of Arunen, the Gavel of K'alen and the Scroll of Atalor. Return to Mekeda at the Refugee Caravan after you've completed this task.", progress = "Have you retrieved the relics, <name>?  We cannot allow the Shadow Council to use their power for dark purposes.", completion = "The Light might have forgotten me, but I have not forgotten the Light.  These relics were once very sacred to my people.\n\nAllowing the Shadow Council to use their power for evil is... unthinkable!" }
WordHunterWoW_QuestEN[10882] = { title = "Harbinger of Doom", description = "<A discordant note can be detected in A'dal's 'voice'.>\n\nPrince Kael'thas has chosen his warden poorly, and now the entities that we kept locked up within the Arcatraz are breaking free.\n\nOne in particular, a servant of the Old Gods known as Harbinger Skyriss, seeks to usher in his masters' vision of conquering all of the worlds in the universe.\n\n<name>, you must not allow him to escape.  Return to Tempest Keep, enter the Arcatraz, and slay Harbinger Skyriss before it is too late!", objectives = "You have been tasked to go to Tempest Keep's Arcatraz satellite and slay Harbinger Skyriss. Return to A'dal at the Terrace of Light in Shattrath City after you have done so.", completion = "<The crystalline timber of A'dal's voice carries a more tranquil melody within your mind than the last time the two of you spoke.>\n\nOnce again you have proven your mettle.  Had Harbinger Skyriss broken free, countless thousands would have perished in the ensuing conflict, just as happened with another servant of the Old Gods, Skeram, on your world of Azeroth.\n\n<name>, what I have to offer in return may seem a pittance in comparison, but know that it comes with the everlasting gratitude of the Sha'tar." }
WordHunterWoW_QuestEN[10883] = { title = "The Tempest Key", description = "You have proven yourself capable of great feats, {name}. Your discovery of the Cipher of Damnation and Kael'Thas' involvement is most important to our cause. Should Kael use the cipher, what little is left of this world may collapse.\n\nA'dal is convinced that Kael must be stopped and now seeks adventurers willing to undergo trials. Those that prove their strength will be granted favor by the naaru.\n\n<Khadgar nods.>\n\nA'dal awaits...\n", objectives = "Speak with A'dal in Shattrath City.", completion = "Tempest Keep is a naaru creation, mortal. Access to the vessel has always been within our power to grant. A return to Tempest Keep, though, had been deemed unnecessary. A point of pride for a mortal race, perhaps, but naaru invest little in such things.\n\nWe go now because we must. Kael'thas cannot be allowed to utter the words of damnation.\n\nWhile the way is open, only a fool would enter unproven. Do not underestimate the purpose of the trials, mortal." }
WordHunterWoW_QuestEN[10884] = { title = "Trial of the Naaru: Mercy", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nWithin the Shattered Halls of Hellfire Citadel are three of your people. They are held there by the merciless one, Kargath Bladefist. He seeks to execute them as a sign of his virility and power. You must save these prisoners before such an atrocity can come to pass. As proof of deed, bring me the unused axe of the executioner. It must not have a drop of blood on its blade!\n", objectives = "A'dal in Shattrath City wants you to recover the Unused Axe of the Executioner from the Shattered Halls of Hellfire Citadel.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "<A'dal greets you.>", completion = "Well done, <name>. You have passed the trial of mercy." }
WordHunterWoW_QuestEN[10885] = { title = "Trial of the Naaru: Strength", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nThe trial of strength is divided in two. You must destroy the leader of the Coilfang Steamvaults, Warlord Kalithresh, and bring me his trident. Slay the extra-planar being known as Murmur, in the Shadow Labyrinth of Auchindoun, and bring me his essence.\n\nDo this and you will have passed the trial of strength.", objectives = "A'dal in Shattrath City wants you to recover Kalithresh's Trident and Murmur's Essence.\n\nThis quest must be completed in Heroic dungeon difficulty.", progress = "<A'dal greets you.>", completion = "Well done, <name>. You have passed the trial of strength." }
WordHunterWoW_QuestEN[10886] = { title = "Trial of the Naaru: Tenacity", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nIn our travels we have encountered many dangerous beings. Some of these beings we incarcerated and placed in what is now known as the Arcatraz of Tempest Keep.\n\nThere is one prisoner, however, that is a victim of circumstance. A stowaway who was in the wrong naaru vessel at the wrong time.\n\nVenture to the Arcatraz and rescue the gnome, Millhouse Manastorm. Ensure his survival.", objectives = "A'dal in Shattrath City wants you to rescue Millhouse Manastorm from the Arcatraz of Tempest Keep.\n\nThis quest must be completed in Heroic dungeon difficulty.", completion = "Well done, <name>. You have passed the trial of tenacity." }
WordHunterWoW_QuestEN[10887] = { title = "Escaping the Tomb", description = "I appreciate your help, {name}.  I was certain I was going to be killed.\n\nLet's get out of here with a hurry.  It won't be long before more cultists come after us.", objectives = "Help Akuno find his way to the Refugee Caravan. Speak to Mekeda after you've completed this quest.", completion = "You rescued Akuno, a dear friend of mine.  For this I am in your debt, <name>." }
WordHunterWoW_QuestEN[10888] = { title = "Trial of the Naaru: Magtheridon", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", objectives = "A'dal in Shattrath City wants you to slay Magtheridon.", completion = "You have proven yourself as a being of great power. The naaru approve..." }
WordHunterWoW_QuestEN[10889] = { title = "Return to Shattrath", description = "Your actions, while brave, will surely rouse a vindictive response from Terokk.\n\nHurry to Shattrath. Send word to Rilak!", objectives = "Travel to Shattrath City and speak with Rilak the Redeemed in the Lower City.", completion = "The guardians of Skettis grow restless from their perch. Shattrath is in trouble. We will surely feel the brunt of Terokk's revenge.\n\nMuster a defense party quickly! Speak with Defender Grashna and let him know you are ready to bear arms against our attackers!" }
WordHunterWoW_QuestEN[10891] = { title = "Imperial Plate Armor", description = "There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?Upon completion of this quest you will gain:", objectives = "Speak with Derotain Mudsipper at Gadgetzan in Tanaris.There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10892] = { title = "Imperial Plate Armor", description = "There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?Upon completion of this quest you will gain:", objectives = "Speak with Derotain Mudsipper at Gadgetzan in Tanaris.There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10893] = { title = "Longtail is the Lynchpin", description = "With the Blackwing wyrmcultists massing in the tunnel, we're hard pressed to deal with the situation.  Quite frankly, they have the numbers.\n\nAnd while we've been able to take care of any of their people that get too close, the fact remains that if they attack in earnest, we're going to be overrun.\n\nThe situation calls for someone to get through to the other end of the tunnel, and take out their leader, Draaca Longtail.  Up for some fun?", objectives = "Slay Draaca Longtail, the leader of the wyrmcultists in the Wyrmskull Tunnel.", completion = "With Draaca out of the picture, we should be able to take advantage of the situation.  They'll be in-fighting over who should be in charge, and that will relieve some of the pressure.\n\nThat is, unless the overseer mentioned in that note you gave me comes to take her place.\n\nLet's see if you can do something to make sure that never happens!" }
WordHunterWoW_QuestEN[10894] = { title = "Wyrmskull Watcher", description = "Hmm, I'm not certain what we should do.  I'm not much of a military planner.\n\nWatcher Moonshade will know what to do.  He's heading up our defensive efforts at the Wyrmskull Tunnel to the west at the end of Wyrmskull Bridge.  We have a force out there just in case the cultists try anything funny.\n\nPlease, take the note to him with all due haste.", objectives = "Deliver the Meeting Note to Watcher Moonshade at the entrance of the Wyrmskull Tunnel in the Blade's Edge Mountains.", progress = "How can I help you?  You bring news from Evergrove?", completion = "It's as I thought, and that's not good!\n\nI've got an idea for how to help you, but first, I was wondering if you might help us out?\n\nYou scratch my back, I'll scratch yours." }
WordHunterWoW_QuestEN[10895] = { title = "Zeth'Gor Must Burn!", description = "It's time to strike Zeth'Gor from the air!  Our gryphon riders are ready for a sortie, {name}.  But they need someone on the ground to direct their fire.  Are you ready for a covert mission?\n\nTake these smoke beacons into Zeth'Gor, the Bleeding Hollow stronghold to the west.  They have four guard towers: one near their northern wall, one near their southern wall, one near their forge and another nestled in their foothills.  Place a beacon underneath each of the towers and we'll fly in and bomb them!", objectives = "Use the smoke beacon at each of Zeth'Gor's towers, and then return to Wing Commander Dabir'ee at Expedition Point.", progress = "Time is crucial, <name>.  We need those guard towers burned!", completion = "I could see the smoke and flames from here!  Good job, <name>!  You received more than a few words of praise from our gryphon riders -- what you just did took a lot of guts..." }
WordHunterWoW_QuestEN[10896] = { title = "The Infested Protectors", description = "The trees of this land are ravaged by the power that was unleashed from Auchindoun.  The foul magic that was unleashed blasted the land into the wastes you see all around.  The trees that survived are now infested with wretched wood mites that crawl under their bark and gnaw at their flesh.  \n\nRotting forest-ragers and infested root-walkers are breeding grounds for the mites.  They are found along the edge of the wood to the east.  Destroy these creatures and then kill the mites that flee their husks.", objectives = "Lakotae wants you to kill 25 Wood Mites and then return to him at the Refugee Caravan. The mites can be found living inside the bodies of Rotting Forest-Ragers and Infested Root-Walkers.", completion = "You have done much to help Terokkar Forest, <name>.  With the worst of the mite colonies destroyed we may yet be able to reclaim this wasted land." }
WordHunterWoW_QuestEN[10897] = { title = "Master of Potions", description = "As you know, plants have properties that allow alchemists to re-energize and reinvigorate others through potions.\n\nMy familiarity with the plants of Outland allows me to teach alchemists how to make the most out of them.  If you're interested in expanding your knowledge of potions, I have but one task to ask of you.\n\nHigh Botanist Freywinn in Tempest Keep is rumored to have written a comprehensive botany guide.  Bring it to me along with samples of your work and I'll teach you the knowledge you seek.", objectives = "Lauranna Thar'well wants you to go to the Botanica in Tempest Keep and retrieve the Botanist's Field Guide from High Botanist Freywinn. In addition she also wants you to bring her 5 Super Healing Potions, 5 Super Mana Potions and 5 Major Dreamless Sleep Potions.\n\n*WARNING!* You can only select one alchemy specialization.", progress = "Are you sure about this, <name>?  Specializing in potions will prevent you from pursuing other specializations.", completion = "Excellent!  It looks like you're eager to learn, so let's get to it.  I will teach you how to make the most out of the plants you use in your alchemical potions.\n\nYou will find that you can make herbs go a really long way if you know what you're doing.  Sometimes you will be able to make two potion with materials you initially judged necessary for just one." }
WordHunterWoW_QuestEN[10898] = { title = "Skywing", description = "Skywing flutters around you.\n\nYou get the feeling he wants you to follow him.", objectives = "Escort Skywing and report to Rilak the Redeemed in Shattrath City.", completion = "Alas, poor Skywing was under the dreaded curse of Luanga the Imprisoner!\n\nSkywing traveled to Veil Shalas to attempt to sway others in seeing the way of the Light. They didn't take lightly to his actions, especially sitting on the doorstep of Skettis.\n\nLuanga was one of Terokk's most feared agents. You have done well by freeing Skywing! I thank you." }
WordHunterWoW_QuestEN[10899] = { title = "Master of Transmutation", description = "Any alchemist will tell you that matter is malleable, any substance can be transformed into another - but nothing is really created or destroyed.\n\nA true master of transmutation can learn to overcome this limitation - and I can teach you how to obtain this mastery!\n\nAs a prospective transmuter you're undoubtedly familiar with primal might - the combination of the material representation of all primal forces.  Show me proof of your transmuting prowess and I will share my knowledge with you.", objectives = "Zarevhi at the Stormspire in Netherstorm wants you to bring him 4 Primal Mights.\n\n*WARNING!* You can only select one alchemy specialization.", progress = "Are you sure you want to become a master transmuter?  If you specialize in this field you will find it impossible to specialize in potions or elixirs.", completion = "Excellent work, <name>!  These transmutations are perfect in every way!\n\nI will now teach you the manner in which the alchemical transmutation process can conjure matter out of thin air!  Make good use of your knowledge, master transmuter.\n\nNow, if you'll excuse me, I have to go see a buyer interested in primal might." }
WordHunterWoW_QuestEN[10900] = { title = "The Mark of Vashj", description = "", objectives = "Burn it down, <race>. Burn it all down! They deserve nothing! Do you hear me! NOTHING! They must pay for what they have done. For what they continue to do.\n\nI would kill Vashj myself if I could break free of these damned bindings.\n\nOr maybe you seek to do the work of Neptulon? Her death serves both of us, soft-skin. Will you assist me in forming the sacred cudgel." }
WordHunterWoW_QuestEN[10901] = { title = "The Cudgel of Kar'desh", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!\n", objectives = "Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet.", progress = "With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!", completion = "At last!\n\nWith these bonds broken and the cudgel in my possession I shall send  the sea witch back to the icy depths..." }
WordHunterWoW_QuestEN[10902] = { title = "Master of Elixirs", description = "I've devoted my life to perfecting my elixirs.  Despite my success, I haven't been able to create an elixir of eternal life.\n\nI think I know the reagent I'm missing.  I've heard of a place called the Caverns of Time in Azeroth where intruders known as rift lords and rift keepers phase in and out of the timeline.\n\nThis intrusive time-shifting creates tears in time itself, twisting it infinitely into crystallized essences.  Bring these to me along with samples of your work and I'll teach you all I know.", objectives = "Go to the Black Morass in the Caverns of Time and obtain 10 Essences of Infinity from Rift Lords and Rift Keepers. Bring these along with  5 Elixirs of Major Defense, 5 Elixirs of Mastery and 5 Elixirs of Major Agility to Lorokeem in Shattrath's Lower City.\n\n*WARNING!* You can only select one alchemy specialization.", progress = "The essences!  Do you have them?", completion = "You are very good with elixirs, if these are any indication.  You will make a fine student.\n\nThese essences will provide me enough materials to formulate my recipe.  I will be known among all alchemists for this discovery!\n\nNow, if you're willing to learn, I am willing to teach." }
WordHunterWoW_QuestEN[10903] = { title = "Return to Honor Hold", description = "{name}, while you were on your mission in Zeth'Gor, I received news of my commanding officer, Colonel Jules.  He was stricken with a demonic corruption while fighting near the Gor'gaz Outpost, and his situation has grown very bad.\n\nYou have made such great gains for us against the fel orcs.  Your strength in battle is without question... is your spirit just as strong?\n\nPlease, return to Honor Hold and speak with Klatu, in an upper room at the Honor Hold inn.", objectives = "Speak with Assistant Klatu, at Honor Hold's inn.", completion = "Yes, it is true.  Colonel Jules' situation has grown much worse these past days.  Anchorite Barada is busy praying for him... let us hope he may be cured." }
WordHunterWoW_QuestEN[10904] = { title = "Harvesting the Fel Ammunition", description = "We must shut down the Burning Legion's access to Death's Door, but first you're going to destroy their two warp-gates!\n\nThe problem is, we can't even scratch one of those things, so you're going to need to use their own weapons against them.\n\nThe death's might, death's watch, deathforge over-smiths and deathforge technicians carry the ammunition for the fel cannons.\n\nNormally it wouldn't affect any of them, but if you bring the cannonballs to me, I will imbue them with Nature's unbridled wrath!", objectives = "Collect 5 Fel Cannonballs.", progress = "Do you have the cannonballs yet?", completion = "Those things stink more than I thought they would!\n\nQuickly, hand them over to me and I will imbue them with Nature's force such that they will prove extremely deadly to their fel masters and their unnatural creations." }
WordHunterWoW_QuestEN[10905] = { title = "Master of Potions", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in potion creation, I would recommend that you seek the help of Lauranna Thar'well of the Cenarion Expedition.\n\nHer knowledge of plants will allow you to make the most of your raw materials.  Look for her in Zangarmarsh and tell her I sent you to her.", objectives = "Speak to Lauranna Thar'well at Cenarion Refuge in Zangarmarsh.\n\n*WARNING!* You can only select one alchemy specialization.", completion = "You want me to help you with your study of potions?  Very well, <name>.  Let's see what we can do." }
WordHunterWoW_QuestEN[10906] = { title = "Master of Elixirs", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in elixir creation, I would recommend that you seek the help of the arakkoa known as Lorokeem.\n\nHis knowledge of elixirs is unmatched, yet he  squanders his skill pursuing an elixir of eternal life.  Find him and see what he can teach you.", objectives = "Speak to Lorokeem in Shattrath's Lower City.\n\n*WARNING!* You can only select one alchemy specialization.", completion = "You want to learn from me?  Hmmm, yes.  Perhaps you'll be a suitable student." }
WordHunterWoW_QuestEN[10907] = { title = "Master of Transmutation", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in transmutation, I would recommend that you seek the help of the ethereal known as Zarevhi.  He resides in the Stormspire in Netherstorm.\n\nHis mastery of transmutation is... well, outlandish!  See what you can learn from him, but beware - ethereals drive a hard bargain.", objectives = "Speak to Zarevhi at the Stormspire in Netherstorm.\n\n*WARNING!* You can only select one alchemy specialization.", completion = "You want me to help you with your study of transmutations?  Very well, <name>.  Let's see what we can do." }
WordHunterWoW_QuestEN[10908] = { title = "Speak with Rilak the Redeemed", description = "You look surprised to be talking to me. I do not blame you. My people, the arakkoa, deserve to be feared.\n\nSpeak with Rilak the Redeemed in Shattrath City if you wish to know more. He can be found in the northern part of the Lower City, with the other outcasts of Skettis.\n\nAnd, {name}, we will speak again.", objectives = "Kirrik the Awakened wants you to speak with Rilak the Redeemed in the Lower City section of Shattrath City.", completion = "So we meet, <name>. You must forgive the lack of formalities for time is of the essence." }
WordHunterWoW_QuestEN[10909] = { title = "Fel Spirits", description = "Colonel Jules was cursed in a battle near the Gor'gaz Outpost, a haunt for Shattered Hand fel orcs.  My master, Barada, works feverishly to cure the poor human, but he needs help.  The Colonel's tormented spirit seeks peace, and his path to peace is, I fear, a path of vengeance.\n\nTake this anchorite relic to Gor'gaz Outpost.  Place it upon the ground near Shattered Hand orcs and defeat them.  This will release their fel spirits -- you must slay those fel spirits for Jules' own spirit's recovery.", objectives = "Klatu in Honor Hold wants you to use the Anchorite Relic at Gor'gaz Outpost southwest of Honor Hold, slay Shattered Hand Berserkers near the relic, and then slay 10 released Fel Spirits to avenge Colonel Jules.", progress = "The fel spirits of the Shattered Hand orcs are a blight to poor Jules' soul.  Tell me, <name>... has he been appeased?", completion = "The Shattered Hand orcs are foul and beyond hope, but my heart is saddened that the road to salvation for Colonel Jules holds such bloodshed." }
WordHunterWoW_QuestEN[10910] = { title = "Death's Door", description = "Now there is an even greater threat from the Burning Legion.  To the south is a portal known as Death's Door, which opens upon the horrific world where the Legion breeds its deadly hounds.\n\nTo get there, exit Evergrove by heading east up the ramp.  Follow the path south, through the Bladed Gulch, Razaan's Landing, Razor Ridge and the Scalewing Shelf.  Then, take the ramp down into the Vekhaar Stand and enter Death's Door through the tunnel, south of Mok'Nathal.\n\nOnce there, use this druid signal.", objectives = "Use the Druid Signal at Death's Door to call down and speak with an Evergrove Druid.\n\nProvided item:", completion = "It is a relief that Wildlord Antelarion has sent you to us.  The problem is much worse than first we feared!" }
WordHunterWoW_QuestEN[10911] = { title = "Fire At Will!", description = "Now that the ammunition can affect the Burning Legion, it's time for you to use it.\n\nThere are two warp-gates, which are used for teleportation and enhancement of the void terrors.  One is in the south and the other in the north, and each is within range of a fel cannon.\n\nUse the naturalized ammunition to take control of each fel cannon and destroy the warp-gates.\n\nAttack the gate with artillery to begin, and be prepared to kill its defenders to keep the cannon alive if necessary.", objectives = "Use the Naturalized Ammunition to take control of the Death's Door Fel Cannons. Use the cannons to destroy both the South Warp-Gate and the North Warp-Gate.", progress = "Have you destroyed both of the warp-gates yet?", completion = "Your prowess is staggering!\n\nVery well, with the warp-gates out of the picture, there's only one thing left to do." }
